[65132] = {id=65132,name="Friend of a Friend: Choofa",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13329,mapID=1525,starts={{npcID=168449,x=0.462,y=0.398,mapID=1525},{npcID=168449,x=0.472,y=0.41,mapID=1525}},ends={{npcID=168449,x=0.462,y=0.398,mapID=1525},{npcID=168449,x=0.472,y=0.41,mapID=1525}},coords={x=0.462,y=0.398,source="quest_giver",mapID=1525},questType="standard"},
[65133] = {id=65133,name="How to Use Momentum with Your Dragon",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14795,description="Now what if there is an obstacle in your way? As long as you fly well, you can conserve your momentum and gain some height after a dive. When you dive this time you will find your flight path takes you below the landing area. By using your momentum you can regain lost height at the end of the course to still land in the target area. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.",starts={{npcID=193287,x=0.576,y=0.668,zoneID=13644}},ends={{npcID=183141,x=0.574,y=0.59,zoneID=13644}},coords={x=0.576,y=0.668,source="quest_giver",zoneID=13644},questType="standard"},
[65134] = {id=65134,name="Friend of a Friend: Cryptkeeper Kassir",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13329,mapID=1525,starts={{npcID=168450,x=0.44,y=0.282,mapID=1525},{npcID=168450,x=0.44,y=0.288,mapID=1525}},ends={{npcID=168450,x=0.44,y=0.282,mapID=1525},{npcID=168450,x=0.44,y=0.288,mapID=1525}},coords={x=0.44,y=0.282,source="quest_giver",mapID=1525},questType="standard"},
