[65146] = {id=65146,name="Relic Hunter",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13570,mapID=1961,starts={{npcID=178257,x=0.626,y=0.224,mapID=1961}},ends={{npcID=178257,x=0.626,y=0.224,mapID=1961}},coords={x=0.626,y=0.224,source="quest_giver",mapID=1961},questType="standard"},
[65147] = {id=65147,name="No Ordinary Steward",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=11012,mapID=1533,questType="standard"},
[65149] = {id=65149,name="Surveying Cyphers",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="There are many consoles such as that one scattered throughout Zereth Mortis . They have all been beyond my understanding, but perhaps that creature intends to reveal their meaning to us? Fortunately, I know where there are more. I will mark them on your map, and accompany you... for research, of course. Let us see what this creature's purpose is.",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="standard"},
[65157] = {id=65157,name="A Hardened Bond",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12876,mapID=1698,starts={{npcID=161905,x=0.424,y=0.324,mapID=1698}},ends={{npcID=161905,x=0.424,y=0.324,mapID=1698}},coords={x=0.424,y=0.324,source="quest_giver",mapID=1698},questType="standard"},
[65165] = {id=65165,name="Soul Support",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12876,mapID=1698,starts={{npcID=183248,x=0.382,y=0.358,mapID=1698}},ends={{npcID=183248,x=0.382,y=0.358,mapID=1698}},coords={x=0.382,y=0.358,source="quest_giver",mapID=1698},questType="standard"},
[65168] = {id=65168,name="My Wings Are Yours",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=11012,mapID=1533,questType="standard"},
[65169] = {id=65169,name="A Stalwart Ally",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=10986,mapID=1525,starts={{npcID=161977,x=0.464,y=0.16,mapID=1525}},ends={{npcID=161977,x=0.464,y=0.16,mapID=1525}},coords={x=0.464,y=0.16,source="quest_giver",mapID=1525},questType="standard"},
[65170] = {id=65170,name="Kindred Spirits",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=10986,mapID=1525,starts={{npcID=161979,x=0.5,y=0.19,mapID=1525}},ends={{npcID=161979,x=0.5,y=0.19,mapID=1525}},coords={x=0.5,y=0.19,source="quest_giver",mapID=1525},questType="standard"},
[65219] = {id=65219,name="Jiro to Hero",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="I have spoken to other jiro. Our orb can create a dampening field. It should close the rifts and stop new ones from forming. It must be done where the Maw magic is strongest. Between the giant chains. The power released by the orb will draw devourers. You and I must defend the orb until the field is set. I will escort the others. Meet us at the rift when you are ready.",starts={{npcID=180989,x=0.426,y=0.314,zoneID=13536}},ends={{npcID=180989,x=0.426,y=0.314,zoneID=13536}},coords={x=0.426,y=0.314,source="quest_giver",zoneID=13536},questType="standard"},
[65237] = {id=65237,name="Oracle, Heal Thyself",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="The vessel, snatched from peril. This automa, a steadfast servant. Its energy, the key to my restoration. Pocopoc , it calls itself. A name that shall return to it. My name will be mine again. Saezurah , among the last of the oracles. Guide to those who would save Zereth Mortis . Bring Pocopoc . Its time as proxy has ended. The time of my awakening has arrived.",starts={{npcID=181706,x=0.34,y=0.474,zoneID=13536}},ends={{npcID=184938,x=0.34,y=0.486,zoneID=13536}},coords={x=0.34,y=0.474,source="quest_giver",zoneID=13536},questType="standard"},
[65238] = {id=65238,name="Souls Entwined",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=10565,description="I must confess, at first I thought Pelagos was making a horrible sacrifice. But now I see--he was giving the Shadowlands all the hope and compassion he holds in his heart. We should go and see him. Speak with Tal-Inara when you reach Oribos. I will meet you there, my friend.",starts={{npcID=181545,x=0.342,y=0.484,zoneID=13536}},coords={x=0.342,y=0.484,source="quest_giver",zoneID=13536},questType="standard"},
[65245] = {id=65245,name="Pop Goes the Devourer!",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Once... they had purpose. Made for balance. But now... shifted, altered. Disharmonious. They rend the pattern. It cannot continue. Elimination is the only recourse.",starts={{npcID=181706,x=0.34,y=0.474,zoneID=13536}},coords={x=0.34,y=0.474,source="quest_giver",zoneID=13536},questType="standard"},
[65250] = {id=65250,name="Prisoner of Interest",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=10565,description="With the Jailer defeated, we must now turn our attention to healing the wounds he inflicted upon the Shadowlands. That process begins with Sylvanas Windrunner. Though she proved instrumental to our victory, the terrible atrocities she committed have been neither forgotten nor forgiven. She is to face the new Arbiter's judgment in Oribos. Uther awaits you in the Ring of Fates. Together, you will escort Sylvanas to the Crucible.",starts={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[65259] = {id=65259,name="Heart of the Sepulcher",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Soon after we stepped forth into the realms of Death, a message left behind by the Primus gave warning that the Jailer must not be allowed to reach the Sepulcher. Despite all our efforts, he has done so. Within the heart of that ancient place lie secrets the Jailer could use to dominate the entire cosmos. If he succeeds, everything we hold dear will be lost. Gather your allies, . Claim victory for the Shadowlands... and for Azeroth.",starts={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},ends={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="raid"},
[65260] = {id=65260,name="A Long Walk",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=10565,description="The Arbiter awaits us. Though few are allowed within the Crucible, several who hail from Azeroth have been granted permission to bear witness as he passes judgment on Sylvanas. Yet we are far from the only ones affected by all the carnage Sylvanas has wrought. Her actions have brought pain and suffering to a great many. Screaming back at the Banshee as she passes might be their only chance to speak their mind. Let them be heard.",questType="standard"},
[65263] = {id=65263,name="The Fate of Sylvanas",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=10565,description="The time has come. Let this bring the dark saga of Sylvanas Windrunner to a close and herald a new dawn for the Shadowlands. Speak to me, and we will begin.",questType="standard"},
[65266] = {id=65266,name="Lost Research",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13570,description="We have uncovered a promising source of Korthian research. Previous Archivists hid knowledge within repositories that were then placed within the rift. I fear that the repositories are no longer safe and that shades of that realm will consume them. It is imperative that we secure this research before it is lost forever. Use a Repaired Riftkey to enter the Korthia Rift. Recover the Korthian Repositories.",starts={{npcID=178257,x=0.626,y=0.224,zoneID=13570}},ends={{npcID=178257,x=0.626,y=0.224,zoneID=13570}},coords={x=0.626,y=0.224,source="quest_giver",zoneID=13570},questType="standard"},
[65267] = {id=65267,name="Smash 'Em to Feathereens",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="I was curious about these strange, winged creatures and attempted to introduce myself. I would have been eaten if not for Professor Chirpsnide and her large mechanical fowl! Could you help us deal with these \"Screechflight\"? The native bluefeather rocs are having a difficult time defending their nests from them. Also, I'd hate for any more introductions to go the way mine did with them...",starts={{npcID=184591,x=0.5,y=0.698,zoneID=13647}},ends={{npcID=184591,x=0.5,y=0.698,zoneID=13647}},coords={x=0.5,y=0.698,source="quest_giver",zoneID=13647},questType="standard"},
[65271] = {id=65271,name="Forging Connections",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Firim described these Enlightened brokers unfavorably. Then again, he does seem a bit... eccentric. Regardless, if we are to restore contact with our comrades in Oribos and defeat the Jailer, we will need allies in Zereth Mortis . The Mawsworn look to be gathering outside the gates of Haven. We must not let any more innocents fall prey to the Jailer's villainy. Hopefully the Enlightened will welcome our aid. After you, my friend.",starts={{npcID=181931,x=0.34,y=0.608,zoneID=13536}},ends={{npcID=177486,x=0.348,y=0.648,zoneID=13536}},coords={x=0.34,y=0.608,source="quest_giver",zoneID=13536},questType="standard"},
[65279] = {id=65279,name="By Royal Decree",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Idiot gnoll not understand crown. Only understand violence. Beat them up or I eat you.",starts={{npcID=183997,x=0.128,y=0.22,zoneID=13646}},coords={x=0.128,y=0.22,source="quest_giver",zoneID=13646},questType="standard"},
[65287] = {id=65287,name="Separating the Yolk",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="I've deciphered the scroll and, surprise, it's bad news! The Screechflight aren't just eating the bluefeathers for sustenance. Turns out they've found a spell or two that transfers the rocs' innate strength to themselves upon consumption. Especially the eggs! Save as many of those roc eggs as you can down the cliffs from here. It'll stall the harpies long enough to put my plan into motion. And watch out for rogue elementals. The Cursewives' spell work has stirred them up!",starts={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},ends={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},coords={x=0.5,y=0.698,source="quest_giver",zoneID=13647},questType="standard"},
[65297] = {id=65297,name="Penance and Renewal",level=60,requiredLevel=60,faction="alliance",expansion=9,zoneID=10565,description="When I became the new Arbiter, I vowed to myself that I would listen to those around me, to take their counsel into consideration before passing eternal judgment. I have an inkling of what Tyrande intends for Sylvanas. Her fury is tempered by wisdom, and I trust in the decision she has made. Meet her in the Ring of Transference and see her judgment come to pass.",questType="standard"},
[65302] = {id=65302,name="Keys to the Kingdom",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Need weapons for plan. Have good weapons, but locked up. Gnolls leave key in camp--protect weapon cache. Get pointiest sticks. They have most blood stains.",ends={{npcID=183997,x=0.128,y=0.22,zoneID=13646}},questType="standard"},
[65305] = {id=65305,name="The Way Forward",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="I see you have a new friend, Maw Walker! With Pocopoc at your side, I wonder what else you will discover about Zereth Mortis ? The secrets we uncover here will be of great help against the Jailer. Perhaps they can teach us how to awaken this oracle. Highlord Bolvar will surely want to hear of them. Please go to Haven and inform him. There is a transporter just outside the cave you may want to use. I will remain here and keep watch over the oracle.",starts={{npcID=179611,x=0.34,y=0.48,zoneID=13536}},ends={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},coords={x=0.34,y=0.48,source="quest_giver",zoneID=13536},questType="standard"},
[65306] = {id=65306,name="Rot Rancher",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Decay gross, smelly, and painful. Have idea but need ooze. GET OOZE!",starts={{npcID=183997,x=0.128,y=0.22,zoneID=13646}},coords={x=0.128,y=0.22,source="quest_giver",zoneID=13646},questType="standard"},
[65307] = {id=65307,name="Mercy First",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="The toxicity in the creche nearly claimed us all. While the antidote is being prepared, I need you to seek out the wounded and heal them. Yes, even the blue drakonid. The Healing Wings do not stand idly by while others suffer.",starts={{npcID=184163,x=0.202,y=0.19,mapID=85}},ends={{npcID=184163,x=0.202,y=0.19,mapID=85}},coords={x=0.202,y=0.19,source="quest_giver",mapID=85},questType="standard"},
[65313] = {id=65313,name="A Roc-ing Appetite",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Segallia seems like a good egg, good with gadgets, but she panics easily. For example: When I sent her into the caves directly south of here, she was promptly run out of them by an unusually large harpy. Seems it was giving orders to the others as well. Could it be the matriarch of this brood? Perhaps a commander of some kind? Get in there and find out, . And don't be afraid to ruffle a few feathers, if you know what I mean.",starts={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},ends={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},coords={x=0.5,y=0.698,source="quest_giver",zoneID=13647},questType="standard"},
[65327] = {id=65327,name="Schematic Reassimilation: Ambystan Darter",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65328] = {id=65328,name="Arbiter in the Making",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Maw Walker, I ... I do not know what to say. I did not expect this. She speaks of preparations and a new Arbiter. We must tell our friends in Haven.",starts={{npcID=181090,x=0.342,y=0.484,zoneID=13536}},ends={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},coords={x=0.342,y=0.484,source="quest_giver",zoneID=13536},questType="standard"},
[65329] = {id=65329,name="Safe Haven",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Let us return to Zereth Mortis . You should report back to Bolvar and tell him of what we have accomplished. We may have achieved this victory, but there is still much to be done.",ends={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},questType="standard"},
[65331] = {id=65331,name="Herbal Remedies",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Using the roots you collected, I have crafted a concoction that, in theory, will cause the plants to revert to their natural state. Hurl vials of this remedy at the lashers of the Catalyst Gardens. If it works, wonderful! If not, you will need to deal with them more directly, by killing them.",starts={{npcID=184323,x=0.476,y=0.798,zoneID=13536}},ends={{npcID=184323,x=0.476,y=0.798,zoneID=13536}},coords={x=0.476,y=0.798,source="quest_giver",zoneID=13536},questType="standard"},
[65332] = {id=65332,name="Schematic Reassimilation: Fierce Scarabid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65333] = {id=65333,name="Schematic Reassimilation: Multichicken",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65334] = {id=65334,name="Schematic Reassimilation: Violent Poultrid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65335] = {id=65335,name="News from Oribos",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="I bear important news that will grant us insight into the Jailer's methods. With faith and understanding, we may also execute true justice. There is much we should discuss, Hero.",starts={{npcID=183677,x=0.35,y=0.646,zoneID=13536}},ends={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},coords={x=0.35,y=0.646,source="quest_giver",zoneID=13536},questType="standard"},
[65336] = {id=65336,name="Schematic Reassimilation: Stabilized Geomental",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65348] = {id=65348,name="Schematic Reassimilation: Omnipotential Core",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65349] = {id=65349,name="Lost Grace",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="The waters of the Wellspring no longer flow. The designs of the First Ones have never before failed us. The pilgrims are beginning to wonder... are the First Ones displeased? Certainly they may question, but MY faith remains steadfast. And as I expected, it seems the First Ones have sent us a solution. You, of course. Ancient research and texts indicate that the source of the wellspring is in an underground temple in Provis Esper. Go, I have faith that you will restore the Wellspring.",starts={{npcID=182146,x=0.618,y=0.534,zoneID=13536}},ends={{npcID=184421,x=0.55,y=0.502,zoneID=13536}},coords={x=0.618,y=0.534,source="quest_giver",zoneID=13536},questType="standard"},
[65350] = {id=65350,name="Restore the Flow",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13952,description="Look! Devourers have penetrated the temple's defenses. Those ravenous menaces feed on any energy that they can find. They must have been drawn to the wellspring's power. With that kind of interference, no wonder the waters have been stalled! The solution must be inside Locrian Esper. Once there, see if you can find a way to reverse the damage that has been done.",starts={{npcID=184537,x=0.55,y=0.502,zoneID=13536}},ends={{npcID=375283,x=0.525,y=0.687,zoneID=13952}},coords={x=0.55,y=0.502,source="quest_giver",zoneID=13536},questType="standard"},
[65351] = {id=65351,name="Schematic Reassimilation: Resonant Echo",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65353] = {id=65353,name="An Automa-free Diet",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13952,description="These devourers are relentless! They feed on any energy they can find. If left unchecked, they would surely devour the whole of Zereth Mortis . We cannot allow the creations of the First Ones to be sullied by these invaders! I am no fighter. But you... perhaps the First Ones delivered you to us after all. Will you help?",starts={{npcID=184537,x=0.55,y=0.502,zoneID=13536}},ends={{npcID=182458,x=0.618,y=0.534,zoneID=13536}},coords={x=0.55,y=0.502,source="quest_giver",zoneID=13536},questType="standard"},
[65354] = {id=65354,name="Schematic Reassimilation: Prototickles",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65355] = {id=65355,name="Schematic Reassimilation: Terror Jelly",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65357] = {id=65357,name="Schematic Reassimilation: Leaping Leporid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65358] = {id=65358,name="Schematic Reassimilation: Microlicid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65359] = {id=65359,name="Schematic Reassimilation: Shelly",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65360] = {id=65360,name="Schematic Reassimilation: Viperid Menace",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65361] = {id=65361,name="Schematic Reassimilation: Tunneling Vombata",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=184172,x=0.606,y=0.594,zoneID=13536}},questType="standard"},
[65370] = {id=65370,name="Gut Check",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="The crescendal is a powerful tool created by automa. They are given to jiro when work is hard or important. When the devourers attacked, crescendals were likely... eaten. crescendals are strong. They do not easily damage. Check the stomachs of bigger devourers. Perhaps find one intact?",starts={{npcID=181102,x=0.382,y=0.354,zoneID=13536}},ends={{npcID=181102,x=0.382,y=0.354,zoneID=13536}},coords={x=0.382,y=0.354,source="quest_giver",zoneID=13536},questType="standard"},
[65371] = {id=65371,name="A Nest of Our Own",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The scroll you found is a command that all bluefeather eggs are to be brought to the harpy chef, Fry-Aerie. Apparently, the Screechflight's matriarch won't eat anything that hasn't been properly prepared and seasoned. So we'll bring her a special egg of our own. One that's EXPLOSIVELY delicious... and will explode when she eats it. Of course. How will you deliver it? In disguise! Slay the creatures on the lower cliffs, collect up this list of parts, and I'll whip you up a full-feathered outfit.",starts={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},ends={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},coords={x=0.5,y=0.698,source="quest_giver",zoneID=13647},questType="standard"},
[65373] = {id=65373,name="Plucking Parts",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Oh, no... I've made a huge mistake. Harleen entrusted me with the famed Feather-Plucker 3300, a phenomenal invention of her very own! I was planning to pluck roc feathers in the cave south of here for her research, but the harpies ambushed me and it broke into pieces as I was running out. Please retrieve the parts! They're probably strewn about like shed scales on the cave floor. I can put it back together. Definitely. Well, probably.",starts={{npcID=184591,x=0.5,y=0.698,zoneID=13647}},ends={{npcID=184591,x=0.5,y=0.698,zoneID=13647}},coords={x=0.5,y=0.698,source="quest_giver",zoneID=13647},questType="standard"},
[65374] = {id=65374,name="It's Plucking Time",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Harleen told me she's making a disguise for you! How exciting! But she'll need some feathers from the roc hatchlings to complete the outfit. Luckily, I've just finished fixing up the Feather-Plucker 3300 ! The Screechflight are capturing roc hatchlings on the lower cliffs to raise and breed for themselves. Use the Plucker to yank the hatchlings out of danger. It'll automatically pluck some of their feathers for you as well! Two birds with one Plucker? I should say so!",starts={{npcID=184591,x=0.5,y=0.698,zoneID=13647}},ends={{npcID=184591,x=0.5,y=0.698,zoneID=13647}},coords={x=0.5,y=0.698,source="quest_giver",zoneID=13647},questType="standard"},
[65375] = {id=65375,name="Schematic Reassimilation: Pale Regal Cervid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,mapID=1970,ends={{npcID=181135,x=0.702,y=0.285,mapID=1970}},questType="standard"},
