[65399] = {id=65399,name="Schematic Reassimilation: Curious Crystalsniffer",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,mapID=1970,ends={{npcID=181135,x=0.702,y=0.285,mapID=1970}},questType="standard"},
[65400] = {id=65400,name="Schematic Reassimilation: Darkened Vombata",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=181135,x=0.702,y=0.285,zoneID=13536}},questType="standard"},
[65401] = {id=65401,name="Schematic Reassimilation: Adorned Vombata",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=181135,x=0.702,y=0.285,zoneID=13536}},questType="standard"},
[65419] = {id=65419,name="Protoform Synthesis",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Pocopoc jumps around anxiously. When you completed your research into the basics of Dealic, it got very excited and it is urging you to follow it somewhere else in this realm.>",starts={{npcID=181059,x=0.486,y=0.056,zoneID=13536}},ends={{npcID=181059,x=0.486,y=0.056,zoneID=13536}},coords={x=0.486,y=0.056,source="quest_giver",zoneID=13536},questType="standard"},
[65420] = {id=65420,name="Judgment Call",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Oh no... No no no... What have I done? The elders will never take me back. They shall cast me out as they did Firim. Please, outsider, speak to Elder Amir in Pilgrim's Grace. Give him my thanks for sending you, and tell him all that has happened here. He will understand why I must never return.",starts={{npcID=181273,x=0.614,y=0.514,zoneID=13536}},ends={{npcID=180630,x=0.614,y=0.514,zoneID=13536}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="standard"},
[65421] = {id=65421,name="Climb Every Mountain",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Hope ye are a quick study, . 'Cause I got no time for a lesson! Grab a pack and find a path tae the top o' that peak. Once yer up there, toss this parachute to our pal Yips. Poor kid got stuck on some vines when these air elementals crashed our plane! Quickly now, so we can get outta here!",starts={{npcID=181039,x=0.624,y=0.504,zoneID=13644}},ends={{npcID=181039,x=0.624,y=0.504,zoneID=13644}},coords={x=0.624,y=0.504,source="quest_giver",zoneID=13644},questType="standard"},
[65422] = {id=65422,name="Treasure Hunting Ain't Easy",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[65426] = {id=65426,name="The Lost Component",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Maw Walker! Look. We have been studying this automa component for some time. Its cyphers are similar to those of the components near and within the Protoform Repository. Kodah's last effort should not be in vain. Please return this component to the repository that our friend restored.",starts={{npcID=181273,x=0.614,y=0.514,zoneID=13536}},ends={{npcID=181135,x=0.702,y=0.285,zoneID=13536}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="standard"},
[65427] = {id=65427,name="A New Architect",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="The architects prototype designs to fulfill the purposes of the First Ones. This archive contained many such designs. A number of design entries are lost or corrupted due to the Maw invasion. An untouched design lattice and tools are detected nearby. The mortal will retrieve them to begin the synthesis process.",starts={{npcID=181135,x=0.702,y=0.285,zoneID=13536}},ends={{npcID=181135,x=0.702,y=0.285,zoneID=13536}},coords={x=0.702,y=0.285,source="quest_giver",zoneID=13536},questType="standard"},
[65431] = {id=65431,name="Further Research: Aealic",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Maw Walker, you have made some wondrous discoveries, but there are still secrets to uncover. You have taken the first step, in unlocking the console and I believe that you are ready to take another. Please go investigate the console and see what new piece of the pattern unfolds itself to you.",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="standard"},
[65435] = {id=65435,name="The Dragon Isles Await",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=1637,description="Heroes of the Horde, I bring news. The Dragon Isles are awakening! The Isles went dormant in the wake of the Sundering. But now, at long last, they have called my kin and me home. While the Isles hold many wonders, it is also a perilous land. We will require the aid of our mortal allies to reclaim our legacy. I am about to present the Aspects' invitation to the Horde Council in Orgrimmar. Meet me there and we shall see what they have to say.",starts={{npcID=190239,x=0.558,y=0.126,zoneID=14},{npcID=190239,x=0.442,y=0.382,zoneID=1637}},ends={{npcID=190239,x=0.558,y=0.126,zoneID=14},{npcID=190239,x=0.442,y=0.382,zoneID=1637}},coords={x=0.558,y=0.126,source="quest_giver",zoneID=14},questType="standard"},
[65436] = {id=65436,name="The Dragon Isles Await",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,description="Wondrous news, my friend! The Dragon Isles are awakening! My people left our lands dormant in the wake of the Sundering. But now, at long last, we feel the call to home. While the Isles hold many wonders, there are perils as well. We will require the aid of our mortal allies in order to reclaim our legacy. Meet me in Stormwind. I must present the Aspects' invitation to the Alliance.",starts={{npcID=189569,x=0.798,y=0.272,zoneID=1519}},ends={{npcID=189569,x=0.798,y=0.272,zoneID=1519}},coords={x=0.798,y=0.272,source="quest_giver",zoneID=1519},questType="standard"},
[65437] = {id=65437,name="Aspectral Invitation",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=1637,mapID=85,description="Your arrival is well timed, $p. I have just met with the Horde Council, and they have accepted the Aspects' invitation to the Dragon Isles . The same invitation extends to you, as well. You may also notice some unfamiliar faces here in Orgrimmar. The dracthyr are new arrivals you will learn about on the journey ahead. Let us speak more.",starts={{npcID=190239,x=0.558,y=0.126,mapID=1},{npcID=190239,x=0.442,y=0.382,mapID=85}},ends={{npcID=190239,x=0.558,y=0.126,mapID=1},{npcID=190239,x=0.442,y=0.382,mapID=85}},coords={x=0.558,y=0.126,source="quest_giver",mapID=85},questType="standard"},
[65439] = {id=65439,name="Whispers on the Winds",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=1637,description="Hello, $p. It's been a while, and I wish we had more time to catch up. But you see, I've just had a rather enlightening... no, make that foreboding... yes, a foreboding conversation with an old friend. Sometimes a revelation can be both, after all. I really must tell you of what I've learned.",starts={{npcID=193450,x=0.558,y=0.126,zoneID=14},{npcID=193450,x=0.23,y=0.558,zoneID=1519}},ends={{npcID=190239,x=0.558,y=0.126,zoneID=14},{npcID=190239,x=0.442,y=0.382,zoneID=1637}},coords={x=0.558,y=0.126,source="quest_giver",zoneID=14},questType="standard"},
[65443] = {id=65443,name="Expeditionary Coordination",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=14,mapID=1,description="Pleasure to meet you, I am Naleidea Rivergleam . The invitation to visit the Dragon Isles is quite an exciting prospect. Don't you agree? The Reliquary has combined forces with our expeditionary counterparts to help coordinate our efforts. As a member of the Dragonscale Expedition, it is my honor to welcome you. Though first we must gather a few more members for our journey. Shall we begin?",starts={{npcID=184793,x=0.442,y=0.38,mapID=85}},ends={{npcID=197279,x=0.558,y=0.126,mapID=1}},coords={x=0.442,y=0.38,source="quest_giver",mapID=1},questType="standard"},
[65444] = {id=65444,name="To the Dragon Isles!",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=13644,description="Our preliminary expedition has made landfall in the Dragon Isles . Thanks to the efforts of those brave Dragonscale Expedition members, we've established a protected landing site in the Dragon Isles and made contact with the dragonflight's embassy. Are you prepared to accompany us on our next voyage to the Dragon Isles ?",starts={{npcID=197279,x=0.558,y=0.126,zoneID=14}},ends={{npcID=184841,x=0.806,y=0.276,zoneID=13644}},coords={x=0.558,y=0.126,source="quest_giver",zoneID=14},questType="standard"},
[65448] = {id=65448,name="A Return to Grace",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Olem will want to know what you've done here.>",starts={{npcID=375283,x=0.525,y=0.687,zoneID=13952}},ends={{npcID=182146,x=0.618,y=0.534,zoneID=13536}},coords={x=0.525,y=0.687,source="quest_giver",zoneID=13952},questType="standard"},
[65451] = {id=65451,name="Practice Materials",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=13644,description="These proto-drakes are unlike any I've seen before on Azeroth. Their scales appear to be naturally flame-resistant, stronger than steel, and don't lose flexibility in the process. Incredible. My artisans--all of them--are clamoring to get their hands on some of those scales to work with. Start with the whelps. The smaller scales should be more pliable until we've mastered our techniques with them.",starts={{npcID=184844,x=0.806,y=0.276,zoneID=13644}},ends={{npcID=187236,x=0.76,y=0.332,zoneID=13644}},coords={x=0.806,y=0.276,source="quest_giver",zoneID=13644},questType="standard"},
[65452] = {id=65452,name="Explorers in Peril",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=13644,description="Don't mistake the expedition's scholarly pursuits as timidness, $p. We are not recluses studying books in far-off towers. We are adventurers, hunting down knowledge first-hand in every corner of Azeroth! That passion for adventure often leads us onto the path of perils and hazards, and a few expedition members have bitten off a little more than they could chew...",starts={{npcID=184841,x=0.806,y=0.276,zoneID=13644}},ends={{npcID=184841,x=0.806,y=0.276,zoneID=13644},{npcID=184870,x=0.766,y=0.336,zoneID=13644}},coords={x=0.806,y=0.276,source="quest_giver",zoneID=13644},questType="standard"},
[65453] = {id=65453,name="Primal Pests",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=13644,description="I'd swear that those proto-dragons edge closer to camp every time I turn my back... Those are not the dragons Ebyssian invited us here to meet. Proto-dragons are ruthless predators who cannot be reasoned with. We must be ruthless in return. Cull their numbers to keep their ambitions in check, or this expedition will be over before it begins.",starts={{npcID=184859,x=0.806,y=0.276,zoneID=13644}},ends={{npcID=187235,x=0.762,y=0.33,zoneID=13644}},coords={x=0.806,y=0.276,source="quest_giver",zoneID=13644},questType="standard"},
[65456] = {id=65456,name="Long Lost Firim",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="I was gathering data here when your portal opened. The disruption activated these gate-locking mechanisms. It is only fair for you to gather the gate keys, yes? We shall speak while you search.",starts={{npcID=181561,x=0.34,y=0.608,zoneID=13536}},ends={{npcID=181561,x=0.34,y=0.608,zoneID=13536}},coords={x=0.34,y=0.608,source="quest_giver",zoneID=13536},questType="standard"},
[65460] = {id=65460,name="Your First Cantaric Protolock",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Maw Walker, it appears that Pocopoc has learned the Cachial skill. This grants you access to the Caches of Creation. You will find several types of these caches all throughout Zereth Mortis . In order to aid me with my research, you will need to be able to decode various cyphers such as the Cantaric Protolock. Now, let me show you what you need to do to assist me.",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="standard"},
[65461] = {id=65461,name="Your First Mezzonic Protolock",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="In order to aid me in my research, you will need to decode various Progenitor cyphers like the Mezzonic Protolock. Now, I will show you what you need to do.",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="standard"},
[65463] = {id=65463,name="The Wellspring of the First Ones",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="A mortal, here? How unusual! Welcome to Pilgrim's Grace. Would that you had arrived under better circumstances. Pilgrims usually travel here to visit the sacred Wellspring of the First Ones. Unfortunately, the wellspring has gone dry. I do not understand it. The creations of the First Ones should be infallible! This situation is as unusual as your arrival--perhaps you can lend your aid? Travel to the wellspring and speak to Conservator Olem .",starts={{npcID=181084,x=0.614,y=0.492,zoneID=13536}},ends={{npcID=182146,x=0.618,y=0.534,zoneID=13536}},coords={x=0.614,y=0.492,source="quest_giver",zoneID=13536},questType="standard"},
[65466] = {id=65466,name="Your First Fugueal Protolock",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="In order to aid my research you will need to decode various Progenitor cyphers like the Fugueal Protolock. This is a most difficult cypher, I will show you what you need to do.",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="standard"},
[65467] = {id=65467,name="Turkey Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Turkey Soul is bold and fierce. The shape of the turkey will be yours to call upon.>",questType="standard"},
[65475] = {id=65475,name="Rolling in the Screech",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Harleen Chirpsnide .>",ends={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},questType="standard"},
[65486] = {id=65486,name="Picture Perfect",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Sorry if ya be waitin' long. Sometimes I get lost in de telescope. Do ya ever find da world be easier understood from a distance? No interference, just nature goin' about its business without us... Akunda the Cataloger sighs.> I see Coralie gave ya a camera. Good. Take a ride down the river with Fren, and take photographs of some wildlife in dey natural habitats for me to study.",starts={{npcID=185651,x=0.498,y=0.684,zoneID=13644}},ends={{npcID=185651,x=0.498,y=0.684,zoneID=13644}},coords={x=0.498,y=0.684,source="quest_giver",zoneID=13644},questType="standard"},
[65490] = {id=65490,name="Explosive Excrement",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The harpies are a nice surprise and all, but I came to these mountains for one reason and one reason only: EXCREMENT! Specifically, the excrement of bluefeather rocs that's then been eaten and digested by bugs. Scarab stomach juices enhance the explosive nitrogen content by tenfold! At least! Here, take this Chirpsnide Auto-Excre-Collector. Stomp on the scarabs crawling around the cave floor, and use the Collector to reap the rewards. Bring it back full and we can start the real fun: EXPLOSIONS!!",starts={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},ends={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},coords={x=0.5,y=0.698,source="quest_giver",zoneID=13647},questType="standard"},
[65504] = {id=65504,name="Dragonhawk Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Dragonhawk Soul is nimble and resilient. The shape of the dragonhawk will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65505] = {id=65505,name="Scorpid Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Scorpid Soul is fierce and voracious. The shape of the scorpid will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65506] = {id=65506,name="Ray Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Ray Soul is clever and swift. The shape of the ray will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65507] = {id=65507,name="Elekk Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Elekk Soul is clever and mighty. The shape of the elekk will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65508] = {id=65508,name="Tallstrider Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Tallstrider Soul is agile and curious. The shape of the tallstrider will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65509] = {id=65509,name="Bat Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Bat Soul is cunning and swift. The shape of the bat will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65510] = {id=65510,name="Brutosaur Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Brutosaur Soul is loyal and valiant. The shape of the brutosaur will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65512] = {id=65512,name="Silithid Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Silithid Soul is brutal and quick. The shape of the silithid will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65513] = {id=65513,name="Gromit Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Gromit Soul is exuberant and inquisitive. The shape of the gromit will be yours to call upon.>",questType="standard"},
[65514] = {id=65514,name="Armadillo Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Armadillo Soul is cautious and resilient. The shape of the armadillo will be yours to call upon.>",questType="standard"},
[65515] = {id=65515,name="Pig Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Pig Soul is curious and tenacious. The shape of the pig will be yours to call upon.>",questType="standard"},
[65516] = {id=65516,name="Sheep Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Sheep Soul is calm and stalwart. The shape of the sheep will be yours to call upon.>",questType="standard"},
[65517] = {id=65517,name="Penguin Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Penguin Soul is playful and sociable. The shape of the penguin will be yours to call upon.>",questType="standard"},
[65518] = {id=65518,name="Bee Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Bee Soul is protective and spry. The shape of the bee will be yours to call upon.>",questType="standard"},
[65519] = {id=65519,name="Snail Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Snail Soul is cautious and patient. The shape of the snail will be yours to call upon.>",questType="standard"},
[65594] = {id=65594,name="Making a Mountain Out of a Gnoll Hill",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Stupid decay thinks it in charge, but me in charge. We kill it now. Me turned ooze into friends.",starts={{npcID=183997,x=0.128,y=0.22,zoneID=13646}},ends={{npcID=183997,x=0.128,y=0.22,zoneID=13646}},coords={x=0.128,y=0.22,source="quest_giver",zoneID=13646},questType="standard"},
[65595] = {id=65595,name="One Bad Apple",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Rot starve gnolls. Rot hurt friends. We kill rot now. Is what Mon-Arks do.",starts={{npcID=183997,x=0.128,y=0.22,zoneID=13646}},coords={x=0.128,y=0.22,source="quest_giver",zoneID=13646},questType="standard"},
[65606] = {id=65606,name="Renowned with the Maruuk",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13645,description="Your deeds to further the interests of the clan have not gone unnoticed. Return to Maruukai, I have prepared some supplies to further assist you in your work with us.",ends={{npcID=185179,x=0.604,y=0.376,zoneID=13645}},questType="standard"},
[65613] = {id=65613,name="An Iconic, Draconic Look",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=1637,mapID=85,description="I am sure your arrival in Orgrimmar drew the attention of its citizens. No doubt some were more comfortable in your presence than others. When I was a young dragon, I took on the mortal visage you now see. It allowed me to live among the tauren of Highmountain as an ally. Though your path differs from mine, the essence of dragonkind flows through you as well, $p. Perhaps that will allow you to assume a visage of your own. Let us walk together.",starts={{npcID=190239,x=0.558,y=0.126,mapID=1},{npcID=190239,x=0.442,y=0.382,mapID=85}},ends={{npcID=190239,x=0.558,y=0.126,mapID=1},{npcID=190239,x=0.442,y=0.382,mapID=85}},coords={x=0.558,y=0.126,source="quest_giver",mapID=85},questType="standard"},
[65615] = {id=65615,name="Arcane Intrusion",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="That beacon ahead--I am certain it was not there before we were imprisoned. Spellcraft is not my forte, but I know arcane magic when I see it. The same magic used by the blue dragon in the creche. He said a name... Malygos. It sounds so familiar, but the Earth-Warder's teachings feel distant. Fragmented. If this Malygos put us into stasis, perhaps the arcane beacon was placed on his orders. Investigate the area and report back. Ensure the beacon cannot be used to call in enemy reinforcements.",starts={{npcID=182251,x=0.442,y=0.614,mapID=85}},ends={{npcID=182251,x=0.442,y=0.614,mapID=85}},coords={x=0.442,y=0.614,source="quest_giver",mapID=85},questType="standard"},
[65625] = {id=65625,name="The Jailer's Gauntlet",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=10565,description="Maw Walker! I have been looking for you. Word is there is a new gathering of the Jailer's forces in Torghast. I'm not sure what they are doing, but it can't be good. Perhaps you should put an end to their plans?",questType="standard"},
[65640] = {id=65640,name="Cervid Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Cervid Soul is noble and wise. The shape of the cervid will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65652] = {id=65652,name="Summons from the Matriarch",level=60,requiredLevel=60,faction="horde",expansion=9,zoneID=3487,description="Greetings, . Let us not mince words--you are urgently needed in Silvermoon. We're experiencing a resurgence of Scourge in Quel'Thalas. With nothing to hold the Scourge in check, we'll soon be overrun. We must hold the line! Meet me in the Hall of Blood, and we will get you a full briefing.",ends={{npcID=176796,x=0.898,y=0.374,zoneID=3487}},questType="standard"},
[65655] = {id=65655,name="Eyes of the Wolf",level=50,requiredLevel=50,faction="alliance",expansion=9,zoneID=13983,description="An alarming rumor has reached me, thanks to our spies. The Forsaken are mustering in Tirisfal Glades. For what purpose, I do not know. Notably, Calia Menethil has gone there as well. We must know more of what they are up to, now that the accursed Banshee Queen no longer unites them. Go, don a disguise and see what you can discover. Observe everything. And if there is opportunity to gain their trust and learn more, do as they ask. I eagerly await your report.",ends={{npcID=185512,x=0.608,y=0.514,zoneID=13983}},questType="standard"},
[65656] = {id=65656,name="Call to Lordaeron",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=13983,mapID=2070,description="With the Shadowlands healing, it is time to turn our attention to matters close to home again, on Azeroth. The Forsaken are mustering in the ruins of the kingdom of Lordaeron. They seek to reclaim as much as they can of the Tirisfal Glades, to finally put the destruction left by the Fourth War behind them. And I intend to assist them in any way I can. I also know that for the Horde, I have much to prove. Come, join me in Brill and we can help the Forsaken together.",starts={{npcID=173386,x=0.506,y=0.758,mapID=85}},ends={{npcID=185512,x=0.608,y=0.514,mapID=2070}},coords={x=0.506,y=0.758,source="quest_giver",mapID=2070},questType="standard"},
[65657] = {id=65657,name="Assemble the Forsaken",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=13983,description="It's heartening to see progress has been made in rebuilding Brill, but this is only a first step. The ruins of the capital remain inaccessible because of the blight. And here is where I hope you will aid the cause. Restoring as much of the land as possible will require a gathering of minds all working toward a singular purpose. A number of influential figures have risen to prominence among the Forsaken. Please help bring them together so we can meet and discuss the path forward.",starts={{npcID=185512,x=0.608,y=0.514,zoneID=13983}},ends={{npcID=185513,x=0.608,y=0.514,zoneID=13983}},coords={x=0.608,y=0.514,source="quest_giver",zoneID=13983},questType="standard"},
[65658] = {id=65658,name="This Land is Ours",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=13983,description="The plague unleashed during the war has tainted the land and disturbed the dead. That is to say, more so than they already were. We have worked hard to rebuild, but our people cannot complete their efforts while under threat. My first duty is to ensure the safety of the Forsaken. I will meet with the others as Calia requests, but first you must help me eradicate some of these Blighted.",starts={{npcID=185514,x=0.62,y=0.506,zoneID=13983}},ends={{npcID=185792,x=0.608,y=0.516,zoneID=13983}},coords={x=0.62,y=0.506,source="quest_giver",zoneID=13983},questType="standard"},
[65659] = {id=65659,name="The Blight Congress",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=13983,description="We, the Forsaken, have been through a lot since the destruction of Lordaeron. But we're determined to keep our home. Why should we give up what we've fought so hard to carve out for ourselves? Calia is still a relative newcomer in some ways, but obviously she's known to our people. How could she not be, as the sister of Arthas himself? I hope we can move forward, and that she can really help. Her voice could be a powerful one, if she is really truly committed to the people.",starts={{npcID=185513,x=0.608,y=0.514,zoneID=13983}},ends={{npcID=185797,x=0.62,y=0.556,zoneID=13983}},coords={x=0.608,y=0.514,source="quest_giver",zoneID=13983},questType="standard"},
[65660] = {id=65660,name="Walk of Faith",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=13983,description="I promised that I would help, and I shall. We need that pure sample of the plague afflicting Lordaeron, but we cannot put anyone else at risk. Come with me. I will call forth a shield of Holy Light to safeguard us deep into the blighted area so that we can collect that sample. This spell will require my full focus. I'll trust you to protect us from anything that might try to stop us. Are you with me?",starts={{npcID=185797,x=0.62,y=0.556,zoneID=13983}},ends={{npcID=185513,x=0.608,y=0.514,zoneID=13983}},coords={x=0.62,y=0.556,source="quest_giver",zoneID=13983},questType="standard"},
[65661] = {id=65661,name="Consulting Our Allies",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=11462,description="I hope Calia is right about these lords of Maldraxxus. That they know how to deal with this sort of powerful plague. We've only got one plague eater left, too, but Faranell says he can replicate more of them as long as they're strong enough to survive. Let's get to the Shadowlands.",starts={{npcID=185513,x=0.608,y=0.514,zoneID=13983}},ends={{npcID=177782,x=0.746,y=0.336,zoneID=11462}},coords={x=0.608,y=0.514,source="quest_giver",zoneID=13983},questType="standard"},
[65662] = {id=65662,name="House of Plagues",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=11462,description="The one with the knowledge you seek is a survivor of the House of Plagues. You already know him. Plague Deviser Marileth may not be the most lucid of conversationalists, but he will know what to do with your plague. Find him near the ruins of that fallen house. But be wary! Many things lurking there could end your existence without a hint of concern.",starts={{npcID=177782,x=0.746,y=0.336,zoneID=11462}},ends={{npcID=185517,x=0.71,y=0.714,zoneID=11462}},coords={x=0.746,y=0.336,source="quest_giver",zoneID=11462},questType="standard"},
[65663] = {id=65663,name="Feed the Eater",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=11462,description="The House of Plagues has suffered calamity, much like Lordaeron. I hope that our work and effort here will reverse some of that destruction. But first, we must reach farther into the House of Plagues so we can strengthen the capabilities of Faranell's plague eater. Any slime or creature you slay will surely help it gain fortitude.",starts={{npcID=185803,x=0.71,y=0.714,zoneID=11462}},ends={{npcID=185826,x=0.686,y=0.816,zoneID=11462}},coords={x=0.71,y=0.714,source="quest_giver",zoneID=11462},questType="standard"},
[65664] = {id=65664,name="Essence of Plague",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=11462,description="Your little friend there looks hungry! Not to worry, I know just what to feed it. Soon it will grow big and strong and be able to eat all the plague it can. There are various concoctions nearby that will give it bolstering properties. And every color is a different flavor! I will take the plague sample you brought me deeper into the House of Plagues, to see what else we can learn. Meet me there, and let your plague eater dine in style!",starts={{npcID=185517,x=0.71,y=0.714,zoneID=11462}},ends={{npcID=185825,x=0.686,y=0.816,zoneID=11462}},coords={x=0.71,y=0.714,source="quest_giver",zoneID=11462},questType="standard"},
[65665] = {id=65665,name="Embodiment",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=11462,description="What a nasty little plague you've brought me, apprentice. Must've been concocted by a true sadist. To study the sample, I gave it form. But the ungrateful thing turned on me and attacked, completely unprovoked! It's shuffled a bit further on into the House. I hate to say it, but I believe this one must be put down before it is allowed to grow any stronger... or larger. Look on the bright side. If your plague eater manages to survive, it'll be attuned to your particularly terrible form of blight.",starts={{npcID=185825,x=0.686,y=0.816,zoneID=11462}},ends={{npcID=185829,x=0.686,y=0.818,zoneID=11462}},coords={x=0.686,y=0.816,source="quest_giver",zoneID=11462},questType="standard"},
[65666] = {id=65666,name="Return to Brill",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=13983,description="We've strengthened our plague eater, and now it looks ready to take on a much, much bigger meal. Let's get it back to Faranell. He said he can replicate its properties and disperse plague eaters all across the ruins. Then maybe, just maybe, we can set foot in our home again. Here, take my hearthstone. It'll bring you back to Brill.",starts={{npcID=185829,x=0.686,y=0.818,zoneID=11462}},ends={{npcID=185831,x=0.658,y=0.6,zoneID=13983}},coords={x=0.686,y=0.818,source="quest_giver",zoneID=11462},questType="standard"},
[65667] = {id=65667,name="The Remedy of Lordaeron",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=13983,description="The time has come. By the Light, I pray our plan works. Master Apothecary Faranell's wagons have reproduced the plague eater many times over, and the bats are ready to deploy them. If you see a place where our forces could spread even more of the remedy, you can signal them with a flare. Take to the skies, and let's put an end to this blight. For Lordaeron, and for the Forsaken.",starts={{npcID=185839,x=0.658,y=0.602,zoneID=13983}},ends={{npcID=185852,x=0.618,y=0.678,zoneID=13983}},coords={x=0.658,y=0.602,source="quest_giver",zoneID=13983},questType="standard"},
[65668] = {id=65668,name="The Desolate Council",level=50,requiredLevel=50,faction="both",expansion=9,zoneID=13983,description="By combining our knowledge and expertise, we've restored the surface of the Undercity to the Forsaken. It was only possible by setting aside our distrust and acting for the good of our people. Now it's time to make this council official. We are no longer the same undead that followed and served Sylvanas Windrunner. From here on, we lead ourselves, with the same spirit of independence and pride we've had since we reclaimed our free will. It's time for a new future, with new leadership.",starts={{npcID=185852,x=0.618,y=0.678,zoneID=13983}},ends={{npcID=185848,x=0.618,y=0.678,zoneID=13983}},coords={x=0.618,y=0.678,source="quest_giver",zoneID=13983},questType="standard"},
[65669] = {id=65669,name="Report to Greymane",level=50,requiredLevel=50,faction="alliance",expansion=9,zoneID=10565,description="Thank you for all of your assistance, leading to this historic moment. I believe there may be others who are interested in what happened here. Please, carry this letter, and my well wishes, when you return to them.",starts={{npcID=185848,x=0.618,y=0.678,zoneID=13983}},coords={x=0.618,y=0.678,source="quest_giver",zoneID=13983},questType="standard"},
[65674] = {id=65674,name="What Is This Thing?",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Firim may have some answers about this.>",ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},questType="standard"},
[65680] = {id=65680,name="Schematic Reassimilation: Heartbond Lupine",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,ends={{npcID=181135,x=0.702,y=0.285,zoneID=13536}},questType="standard"},
[65686] = {id=65686,name="To the Azure Span",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Greetings, ! Pakina and I are here on behalf of the Kirin Tor looking for aid. The Kirin Tor are working to safeguard the wild arcane magic located all throughout the Azure Span . Kalecgos, the Aspect of the blue dragonflight and one of our leaders, needs aid in reclaiming the Azure Oathstone there as well. If you're willing to help, keep traveling along the road to find Glania of the Blessed Ones . She can direct you to where you can help the most.",starts={{npcID=185599,x=0.716,y=0.806,zoneID=13645}},ends={{npcID=185603,x=0.414,y=0.356,zoneID=13646}},coords={x=0.716,y=0.806,source="quest_giver",zoneID=13645},questType="standard"},
[65687] = {id=65687,name="Punching Up",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Some of the other disciples are... very mean. Ingot rubs a fresh wound on his snout.> It used to not be like that, but when Cygenoth came, he said \"We should value strength above all else\". Now everybody fights all the time. I try to fight back, but their hides are too thick... and I'm too small. But not you! You must fight bullies all the time. Maybe you can help?",starts={{npcID=185627,x=0.394,y=0.482,zoneID=13644}},ends={{npcID=185627,x=0.394,y=0.482,zoneID=13644}},coords={x=0.394,y=0.482,source="quest_giver",zoneID=13644},questType="standard"},
[65688] = {id=65688,name="Meeting Kalecgos",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I fear we will have to split our attention. The Primalist threat to the east must be handled. I must ask you travel to the Azure Archives in my stead to aid Kalecgos in reclaiming the Azure Oathstone. You'll need to pick up a few supplies to help you with whatever is happening there. Speak with our portal quartermaster, they ought to have something that can aid you along the way. Good luck, . Kalecgos will appreciate the aid.",starts={{npcID=192091,x=0.466,y=0.402,zoneID=13646}},ends={{npcID=185615,x=0.408,y=0.55,zoneID=13646}},coords={x=0.466,y=0.402,source="quest_giver",zoneID=13646},questType="standard"},
[65689] = {id=65689,name="The Many Images of Kalecgos",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Good to formally meet you, . My name is Kalecgos , Archmage of the Kirin Tor and Aspect of the blue dragonflight. I'm having difficulty repairing the Azure Archives to reclaim the Azure Oathstone. I could use an extra pair of physical hands. I'm currently up in the archives themselves. I was able to reactivate the pylon outside, which should allow you to traverse up here.",starts={{npcID=185615,x=0.408,y=0.55,zoneID=13646}},ends={{npcID=185622,x=0.408,y=0.59,zoneID=13646}},coords={x=0.408,y=0.55,source="quest_giver",zoneID=13646},questType="standard"},
[65690] = {id=65690,name="A Cultist's Misgivings",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Another outsider arrived yesterday. She called herself an \"emissary\" for the red dragonflight and asked for an audience with our leader, the Voice of Neltharion. But the Voice got terribly mad. He said that the Earth-Warder was testing us, and that we had to execute her! I know we're not supposed to trust outsiders, but we don't have to kill them! Please, help me save her.",starts={{npcID=185627,x=0.394,y=0.482,zoneID=13644}},ends={{npcID=185628,x=0.374,y=0.466,zoneID=13644}},coords={x=0.394,y=0.482,source="quest_giver",zoneID=13644},questType="standard"},
[65691] = {id=65691,name="The Shadow of His Wings",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The Voice of Neltharion resides below, spreading lies amongst his followers. He appears to be dragonspawn like me. but his Draconic is clumsy--fit for the unscaled. I suspect duplicity: an illusion, perhaps. If we can subdue him, I'm certain the truth will out.",starts={{npcID=185628,x=0.374,y=0.466,zoneID=13644}},ends={{npcID=185628,x=0.374,y=0.466,zoneID=13644}},coords={x=0.374,y=0.466,source="quest_giver",zoneID=13644},questType="standard"},
[65700] = {id=65700,name="Core Control",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Your timing is most excellent. It appears one of my traps captured a rather curious creature moments ago. I dare not investigate, but you... you can do this for me. Take Pocopoc along with you. Perhaps there are secrets yet to be discovered.",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="standard"},
[65701] = {id=65701,name="Preservation, Augmentation, or Devastation",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="If what these dragons say is true, then a great battle is upon us. We need you focused and strong, evoker. Time to choose your battle specialization. Will you preserve your allies, or devastate your enemies? To hone your combat skills to their sharpest, choose Devastation. To maximize your healing potential, take the path of Preservation. To enhance your wingmates, embrace Augmentation. Each specialization should serve you well. And remember, you can change or adapt it later.",starts={{npcID=182258,x=0.448,y=0.578,mapID=85}},ends={{npcID=182258,x=0.448,y=0.578,mapID=85}},coords={x=0.448,y=0.578,source="quest_giver",mapID=85},questType="standard"},
[65702] = {id=65702,name="Driven Mad",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The Azure Archives was once a place where the blue dragons would gather to discuss magic. Now I am the only one of my kind here. This place controls the ley lines beneath the Azure Span , but it and its servants have gone out of control. I believe if we bring order to this place that I can then reclaim the Azure Oathstone. The various constructs and elements are brimming with unstable arcane energy that needs to be redirected. Destroy them and collect what you can.",starts={{npcID=185622,x=0.408,y=0.59,zoneID=13646}},ends={{npcID=185622,x=0.408,y=0.59,zoneID=13646}},coords={x=0.408,y=0.59,source="quest_giver",zoneID=13646},questType="standard"},
[65703] = {id=65703,name="Shadowlands (60) E",level=60,requiredLevel=60,faction="none",expansion=9,questType="standard"},
[65704] = {id=65704,name="Shadowlands (60) E",level=60,requiredLevel=60,faction="none",expansion=9,questType="standard"},
[65705] = {id=65705,name="Shadowlands (60) E",level=60,requiredLevel=60,faction="none",expansion=9,questType="standard"},
[65709] = {id=65709,name="Arcane Pruning",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We cannot activate the oathstone in the Azure Archives until we fix the issue with the out of control ley energy here. Two out of the three draconic runes that are meant to control it are being choked by unstable arcana. I apologize that this falls to you, given Khadgar's responsibilities and the lack of my brethren appearing. There should be a ley scepter within that bag of helpful goods you have. Use it to help repair the runes nearby.",starts={{npcID=185623,x=0.406,y=0.59,zoneID=13646}},ends={{npcID=185623,x=0.406,y=0.59,zoneID=13646}},coords={x=0.406,y=0.59,source="quest_giver",zoneID=13646},questType="standard"},
[65711] = {id=65711,name="Stealing Its Thunder",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="It's you! Thank Ohn'ahra. I was pretending to be hurt to fool the next brute who dared come in here. Ugh--the hoof lickers put some binding spell on me. I'll figure it out. They've got Lizi in the cave. Please save her. I'll figure out how to free myself. Do what you have to do.",starts={{npcID=190014,x=0.562,y=0.77,zoneID=13645}},ends={{npcID=190014,x=0.562,y=0.77,zoneID=13645}},coords={x=0.562,y=0.77,source="quest_giver",zoneID=13645},questType="standard"},
[65717] = {id=65717,name="Leading Motives",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Firim would be very interested in this.>",ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},questType="standard"},
[65725] = {id=65725,name="The Burrowed Bufonid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,starts={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},ends={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},coords={x=0.344,y=0.658,source="quest_giver",zoneID=13536},questType="standard"},
[65726] = {id=65726,name="The Burrowed Bufonid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,starts={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},ends={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},coords={x=0.344,y=0.658,source="quest_giver",zoneID=13536},questType="standard"},
[65727] = {id=65727,name="The Burrowed Bufonid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Have you stopped to watch the bufonids? A lovely one lurks underwater. Still, patient, unmoving. Wise Bud takes after him. They are much alike. I sense Bud desires to see this large bufonid up close. Perhaps the creature can be lured out with some honey from the vespoids here in Zereth Mortis . Would you please gather some?",starts={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},ends={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},coords={x=0.344,y=0.658,source="quest_giver",zoneID=13536},questType="standard"},
[65728] = {id=65728,name="The Burrowed Bufonid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,starts={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},ends={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},coords={x=0.344,y=0.658,source="quest_giver",zoneID=13536},questType="standard"},
[65729] = {id=65729,name="The Burrowed Bufonid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,starts={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},ends={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},coords={x=0.344,y=0.658,source="quest_giver",zoneID=13536},questType="standard"},
[65730] = {id=65730,name="The Burrowed Bufonid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,starts={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},ends={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},coords={x=0.344,y=0.658,source="quest_giver",zoneID=13536},questType="standard"},
[65731] = {id=65731,name="The Burrowed Bufonid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,starts={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},ends={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},coords={x=0.344,y=0.658,source="quest_giver",zoneID=13536},questType="standard"},
[65732] = {id=65732,name="The Patient Bufonid",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Look, another magnificent creature of Zereth Mortis ! By the glint in its eye, I would say it was playing along the whole time. Patience delights. Bud is pleased. Excellent work, Maw Walker.",starts={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},ends={{npcID=180950,x=0.344,y=0.658,zoneID=13536}},coords={x=0.344,y=0.658,source="quest_giver",zoneID=13536},questType="standard"},
[65750] = {id=65750,name="Eight-Legged Menace",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="! I require your aid if you're willing... This joint expedition was intended to study the unique arachnids inhabiting the area, but, as you can see, our plan has gone awry. What we originally assumed was an evolutionary adaptation is instead a Primalist perversion of the natural order! I take my responsibilities as a conservationist seriously, but the time for studying live specimens has passed. We can't let their perversion spread. We can study their corpses instead. Will you help us?",starts={{npcID=185778,x=0.516,y=0.62,zoneID=13646}},ends={{npcID=185778,x=0.516,y=0.62,zoneID=13646}},coords={x=0.516,y=0.62,source="quest_giver",zoneID=13646},questType="standard"},
[65751] = {id=65751,name="Platform Adjustments",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="It seems the last of the arcane disruption is up here. I'll continue adjusting the ley energies. Use some of the arcana you recovered to dispel the disruptions here.",starts={{npcID=186184,x=0.4,y=0.614,zoneID=13646}},ends={{npcID=186184,x=0.4,y=0.614,zoneID=13646}},coords={x=0.4,y=0.614,source="quest_giver",zoneID=13646},questType="standard"},
[65752] = {id=65752,name="Arcane Annoyances",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="A large number of mana wyrms are absorbing the wild arcane magic coming out from the archives. The rate that they're doing it is causing the ley lines to be thrown off balance... which is preventing the Azure Oathstone from being reclaimed. I will use some of the unstable arcana you collected to form a hook of sorts. Use it to slay several of the wyrms. The brief delay will be enough for me to adjust the energies below.",starts={{npcID=186184,x=0.4,y=0.614,zoneID=13646}},ends={{npcID=186184,x=0.4,y=0.614,zoneID=13646}},coords={x=0.4,y=0.614,source="quest_giver",zoneID=13646},questType="standard"},
[65758] = {id=65758,name="Grungir the Explorer",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="! My Explorers' League counterpart, Grungir Ironspout , wasn't among those you rescued. He had fought his way free originally, but once he saw how few of us made it out, he turned around and headed right back in! Alone! The oaf is as brave as he is impulsive and does not deserve whatever fate has befallen him. Please... find him.",starts={{npcID=185778,x=0.516,y=0.62,zoneID=13646}},ends={{npcID=185806,x=0.49,y=0.642,zoneID=13646}},coords={x=0.516,y=0.62,source="quest_giver",zoneID=13646},questType="standard"},
[65760] = {id=65760,name="Reporting for Duty",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I've only read of the djaradin in books. Ancient rivals to the dragons, powerful giants with mastery over earth and lava... dedicated wholly to hunting dragons to extinction. Sendrax furrows her brow at the distant volcano.> My instructor said that they hadn't been seen since the dragons left as they slumbered deep in the earth. If they've awoken, every whelpling on the isles is in danger! We should hurry to Commander Lethanak at the Dragonheart Outpost.",starts={{npcID=193363,x=0.762,y=0.344,zoneID=13644}},ends={{npcID=186584,x=0.712,y=0.408,zoneID=13644}},coords={x=0.762,y=0.344,source="quest_giver",zoneID=13644},questType="standard"},
[65761] = {id=65761,name="More Adventure Than Expected",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Godoloto 's stare is beady and accusatory. She huffs.>",starts={{npcID=190022,x=0.51,y=0.622,zoneID=13645}},ends={{npcID=190014,x=0.562,y=0.77,zoneID=13645}},coords={x=0.51,y=0.622,source="quest_giver",zoneID=13645},questType="standard"},
[65762] = {id=65762,name="Sepulcher of the First Ones - Heavy is the Crown",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13742,description="Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king. Four fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.",questType="raid"},
[65763] = {id=65763,name="Sepulcher of the First Ones - Heavy is the Crown",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13742,description="Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king. Four fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.",questType="raid"},
[65764] = {id=65764,name="Sepulcher of the First Ones - Heavy is the Crown",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13742,description="Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king. Four fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.",questType="raid"},
[65768] = {id=65768,name="Our Forward Scouts",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="The Jailer's forces control much of Zereth Mortis , but there are other dangers out there as well. I have dispatched scouts to survey the surrounding area and pinpoint any potential threats. Speak with each scout. They should have a report of their surveys. Gather this information and then return to me.",starts={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},ends={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[65769] = {id=65769,name="Icy Webs",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Many of my friends and colleagues were captured when the arachnids and their Primalist masters attacked. I saw them being bound in frozen webbing and dragged away to a fate I dare not consider. Please free any of them that you can!",starts={{npcID=185778,x=0.516,y=0.62,zoneID=13646}},ends={{npcID=185778,x=0.516,y=0.62,zoneID=13646}},coords={x=0.516,y=0.62,source="quest_giver",zoneID=13646},questType="standard"},
[65770] = {id=65770,name="A Promise Is A Promise",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The animals are comfortable around you. That's a good indicator of your spirit. Actually... can you keep a secret? I want to introduce you to my friend. Nobody else knows about her. You have to promise me first that you'll keep this between us. My Ohn would exile me from the plains if she found out.",starts={{npcID=190014,x=0.562,y=0.77,zoneID=13645}},ends={{npcID=190022,x=0.51,y=0.622,zoneID=13645}},coords={x=0.562,y=0.77,source="quest_giver",zoneID=13645},questType="standard"},
[65771] = {id=65771,name="Favor of the First Ones",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,mapID=1970,description="The attack from the Jailer's forces is a sign! In the past, there was one among us who sought the forbidden knowledge of the First Ones. For that, we must have earned their ire and lost the protections we once had. We must atone for the trespasses of our kin. Take this incense. Go out into the veldt and burn it as offerings to the First Ones. I hope they will offer us forgiveness.",starts={{npcID=178015,x=0.348,y=0.648,mapID=1970}},ends={{npcID=178015,x=0.348,y=0.648,mapID=1970}},coords={x=0.348,y=0.648,source="quest_giver",mapID=1970},questType="standard"},
[65772] = {id=65772,name="Necessary Harvest",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Between the Mawsworn attacks and your presence here, our supplies are dwindling. It pains me to say it, but the most immediate solution for replenishing our resources is the local wildlife. It is unfortunate that it has come to this, but it is what must be done. Cull some of the local wildlife, and help us replenish our supplies.",starts={{npcID=178016,x=0.348,y=0.648,zoneID=13536}},ends={{npcID=178016,x=0.348,y=0.648,zoneID=13536}},coords={x=0.348,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[65774] = {id=65774,name="The Catalyst Awakens",level=61,requiredLevel=61,faction="both",expansion=9,zoneID=13536,description="Adventurer, can you feel it? High above the Catalyst Gardens, the Creation Catalyst hums with new power. This power will change the world itself. You must harness it at once.",starts={{npcID=182257,x=0.348,y=0.642,zoneID=13536}},ends={{npcID=182257,x=0.348,y=0.642,zoneID=13536}},coords={x=0.348,y=0.642,source="quest_giver",zoneID=13536},questType="standard"},
[65777] = {id=65777,name="Mudcaked Necklace",level=50,requiredLevel=50,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[65778] = {id=65778,name="Screechflight Potluck",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Are you ready to put those acting chops of yours to good use, ? What? You don't have any chops? Then it's a good thing I've made you an im-PECK-able Screechflight disguise out of all the materials you just gathered! Segallia and I still need time to finish building the final \"egg\" that will take out the matriarch, but I've made a smaller, prototype version for you to try out on the chef. And don't worry! You'll be 12% safer from these explosions under all the feathers!",starts={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},ends={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},coords={x=0.5,y=0.698,source="quest_giver",zoneID=13647},questType="standard"},
[65779] = {id=65779,name="Into the Plains",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The green dragonflight has returned to their gardens in the nearby plains. Queen Alexstrasza wishes for you to make contact with Merithra of the Dream. The centaur of those plains are fierce hunters. To reach the Emerald Gardens, you will need to establish diplomacy with them first. Be respectful, but show no weakness.",starts={{npcID=185878,x=0.482,y=0.886,zoneID=13644}},ends={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},coords={x=0.482,y=0.886,source="quest_giver",zoneID=13644},questType="standard"},
[65780] = {id=65780,name="Proving Oneself",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="A gift from dragons may impress some centaur, but Clan Shikaar must see how well you hunt. One of our hunting parties just brought down a proto-dragon infused with the power of flame. Prove your worth by aiding in the kill.",starts={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},ends={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},coords={x=0.756,y=0.316,source="quest_giver",zoneID=13645},questType="standard"},
[65782] = {id=65782,name="Under Lock and Key",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="When we heard rumors of a Deathwing cult, Majordomo Selistra ordered me to bring these erstwhile scaleborn back into the fold. We'd hoped it was a simple misunderstanding. Clearly, we were wrong. Their leader must be dealt with--but first I need out of this cage. Find the key and bring it to me.",starts={{npcID=185628,x=0.374,y=0.466,zoneID=13644}},ends={{npcID=185628,x=0.374,y=0.466,zoneID=13644}},coords={x=0.374,y=0.466,source="quest_giver",zoneID=13644},questType="standard"},
[65783] = {id=65783,name="Welcome at Our Fire",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="You have fought alongside our hunters and earned a place at our fire. Our khan is at our hunting post in the swamp, readying our upcoming caravan. I will notify her of your arrival and purpose. Surely you can find your way on your own.",starts={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},ends={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},coords={x=0.756,y=0.316,source="quest_giver",zoneID=13645},questType="standard"},
[65784] = {id=65784,name="The Otter Side",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="To the northeast, there are a system of otter burrows along the bank. Some of the otters there are blessed by the river to grow to magnificent sizes. I will not have you hunting these blessings out of respect. Instead you will bring them back here, alive, so that we may treat them with the reverence they deserve.",starts={{npcID=185870,x=0.556,y=0.524,zoneID=13645}},ends={{npcID=185870,x=0.556,y=0.524,zoneID=13645}},coords={x=0.556,y=0.524,source="quest_giver",zoneID=13645},questType="standard"},
[65788] = {id=65788,name="A Walk with Ghosts",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=13983,description="Reclaiming these ruins means a lot to the Forsaken. Especially since the war ended, our people have needed something to hold onto, to give us purpose in the wake of everything that's happened to us. I saw Calia walk toward the throne room. That place holds many memories for her. Many ghosts. We should check on her.",starts={{npcID=185852,x=0.618,y=0.678,zoneID=13983}},ends={{npcID=185893,x=0.618,y=0.678,zoneID=13983}},coords={x=0.618,y=0.678,source="quest_giver",zoneID=13983},questType="standard"},
[65789] = {id=65789,name="Where Rivers Sleep",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Mirewood contains key reagents often used to converse with the ancestors. Unfortunately, the Mudfin tribe swarms the area, making it difficult for us to forage the area. If you could gather some of the blooms within the marsh, along with some of the Mudfin's own resources, I would appreciate it.",starts={{npcID=185867,x=0.558,y=0.518,zoneID=13645}},ends={{npcID=185867,x=0.558,y=0.518,zoneID=13645}},coords={x=0.558,y=0.518,source="quest_giver",zoneID=13645},questType="standard"},
[65791] = {id=65791,name="Life-Binder on Duty",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Soon the Life Pools will be full once again. Thank you for your part in this, , it means more than I can ever hope to express. Go, find the Life-Binder by the oathstone. Tell her that we are ready for the eggs.",starts={{npcID=185904,x=0.616,y=0.686,zoneID=13644}},ends={{npcID=185905,x=0.622,y=0.73,zoneID=13644}},coords={x=0.616,y=0.686,source="quest_giver",zoneID=13644},questType="standard"},
[65792] = {id=65792,name="Teeth for a Tooth",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Toliqui has been claiming that just the other day she killed a rockfang without any assistance. Given our connected souls, I don't want to call her as a liar. So instead... I want to prove to her, and everyone else, that I'm the better half of our soul! The nearest rockfang quest is to the northeast - meet me there!",starts={{npcID=185880,x=0.704,y=0.628,zoneID=13645}},ends={{npcID=185880,x=0.704,y=0.628,zoneID=13645}},coords={x=0.704,y=0.628,source="quest_giver",zoneID=13645},questType="standard"},
[65793] = {id=65793,name="Black Wagon Flight",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14795,description="With the oathstone empowered once more, we must now transport the future of our kind to the Life Pools. It is the right of every true dragonflight to have their eggs nurtured by its waters. Unfortunately, our enemies will be watching the skies, now that we have revealed ourselves. We will make the final leg of the journey on foot to avoid their scrutiny. Meet me near the Obsidian Bulwark, . As the Life-Binder's champion, you are welcome to join me in this.",starts={{npcID=185894,x=0.242,y=0.558,zoneID=13644}},ends={{npcID=190740,x=0.578,y=0.672,zoneID=13644}},coords={x=0.242,y=0.558,source="quest_giver",zoneID=13644},questType="standard"},
[65794] = {id=65794,name="A Charge of Care",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="You have my thanks, , and my condolences for having to deal with those two for as long as you did. The red dragonflight is charged with the preservation and nurturing of all dragons, even those we may tire of at times. With the return of the Black Dragonflight's eggs, dragonkind is united as it has not been in thousands of years. I believe this is what will restore our ruby oathstone. Speak with me when you are ready to bring the eggs to the Obsidian Lifepool.",starts={{npcID=185905,x=0.622,y=0.73,zoneID=13644}},ends={{npcID=193377,x=0.614,y=0.686,zoneID=13644}},coords={x=0.622,y=0.73,source="quest_giver",zoneID=13644},questType="standard"},
[65795] = {id=65795,name="Next Steppes",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The green dragonflight requires your aid now, hero. My sister's daughter and her flight have entered the Emerald Dream in an attempt to empower their own oathstone, but we have heard nothing since their slumber began. Seek out the centaur that rule over the Ohn'ahran Plains. You may well need their connection to the land and its spirits if you are to rouse the greens. They are a proud and territorial people who do not suffer insult lightly. Speak with our ambassador and he will prepare you.",starts={{npcID=193377,x=0.614,y=0.686,zoneID=13644}},ends={{npcID=185878,x=0.482,y=0.886,zoneID=13644}},coords={x=0.614,y=0.686,source="quest_giver",zoneID=13644},questType="standard"},
[65796] = {id=65796,name="The Best Defense...",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Our next path is through Nokhud territory. Historically, we have been at a tentative peace with their clan, but times have changed. If we do not act first, we leave ourselves open while we're vulnerable. My scouts have reported that one of their war leaders has been spotted near Dragonsmeet. Take the fight to her directly - do not let her gather the forces to assault us on the move.",starts={{npcID=185853,x=0.714,y=0.31,zoneID=13645}},ends={{npcID=185853,x=0.714,y=0.31,zoneID=13645}},coords={x=0.714,y=0.31,source="quest_giver",zoneID=13645},questType="group"},
[65798] = {id=65798,name="An Opportunistic Approach",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Shikaar have formed an offensive line against the Nokhud to the north. While I do not like stooping to scavenging, it is unfortunately a necessary evil for our supplies. Brave the battlefield and return with weapons, and I will reward your efforts. If you could focus said efforts on the Nokhud side of the line, perhaps the ancestors will judge me less harshly.",starts={{npcID=185853,x=0.714,y=0.31,zoneID=13645}},ends={{npcID=185853,x=0.714,y=0.31,zoneID=13645}},coords={x=0.714,y=0.31,source="quest_giver",zoneID=13645},questType="standard"},
[65801] = {id=65801,name="Making Introductions",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Sansok Khan signs, Okir vocalizes for her.> It has been countless generations since an outsider like you reached our lands. With Primalists treading on our lands and peddling forbidden magics, my people are understandably wary. If you are to travel with us, you must make yourself known. Introduce yourself to the members of my clan.",starts={{npcID=181217,x=0.856,y=0.252,mapID=2023}},ends={{npcID=185882,x=0.756,y=0.316,mapID=2023}},coords={x=0.856,y=0.252,source="quest_giver",mapID=2023},questType="standard"},
[65802] = {id=65802,name="Supplies for the Journey",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Sansok Khan signs, Okir vocalizes for her.> While you travel with us, you must pull your weight. Unruly gorlocs have been raiding our medical supplies recently, and we must restock. Gather the orange blooms around the outpost so we can create more poultices. There are supplies around the outpost that need to be brought to the caravan as well. I would like you to gather them while you are out. Once you have everything, bring it to Tomul.",starts={{npcID=181217,x=0.856,y=0.252,zoneID=13645}},ends={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},coords={x=0.856,y=0.252,source="quest_giver",zoneID=13645},questType="standard"},
[65803] = {id=65803,name="Toward the City",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Khural is a time of discussion amongst clans. Stories are shared. While there are many centaur clans across the plains, we are all Maruuk. The caravan is ready to go. As Maruukai is some distance away, we will make stops. When you are ready to leave, find me at the caravan. Don't keep us waiting.",starts={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},ends={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},coords={x=0.756,y=0.316,source="quest_giver",zoneID=13645},questType="standard"},
[65804] = {id=65804,name="For Food and Rivalry",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Maruuk travel from all across the plains to attend the Khural, and the gathering lasts many days. Feeding that many centaur is no simple feat. Clan Shikaar's hunters provide meat for all of the shared meals. It is our tradition to hunt on our way to Maruukai. You must pull your weight as well.",starts={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},ends={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},coords={x=0.756,y=0.316,source="quest_giver",zoneID=13645},questType="standard"},
[65805] = {id=65805,name="Connection to Ohn'ahra",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The wind is restless here, . Ohn'ahra is reaching out. I must answer her call. I need reagents for my ritual: reeds from the riverbanks, feathers from the tails of mallards, and the heart of a salamanther. Gather these materials from the river so that I may heed her voice.",starts={{npcID=184595,x=0.856,y=0.208,zoneID=13645}},ends={{npcID=184595,x=0.856,y=0.208,zoneID=13645}},coords={x=0.856,y=0.208,source="quest_giver",zoneID=13645},questType="standard"},
[65806] = {id=65806,name="Maruukai",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Sansok Khan signs.> Maruukai rests beside a mountain near this grove. Our journey is almost over. The Khural is a time of truce amongst the Maruuk, but Ohn Seshteng's omen is troubling. We must stay on our guard.",starts={{npcID=181217,x=0.856,y=0.252,zoneID=13645}},ends={{npcID=191283,x=0.614,y=0.396,zoneID=13645}},coords={x=0.856,y=0.252,source="quest_giver",zoneID=13645},questType="standard"},
[65832] = {id=65832,name="Dwarven Antifreeze",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I'm in a wee bit of a pickle, $Uladdie:lassie;. The Primalist frost lickers stuck me in this overgrown ice cube and the only reason I'm nae frozen solid yet is me secret stash o' the good stuff. Sadly, me less secret stashes got nicked when tae thieving scum jumped me. I'm runnin' low! Would ye do a dwarf a kindness and fetch me flasks afore me blood turns tae ice? Oh, and $Uladdie:lassie;, if ye do haftae pull one out o' some spider's unmentionables, dinnae tell me. I'd rather nae know.",starts={{npcID=185806,x=0.49,y=0.642,zoneID=13646}},ends={{npcID=185806,x=0.49,y=0.642,zoneID=13646}},coords={x=0.49,y=0.642,source="quest_giver",zoneID=13646},questType="standard"},
[65833] = {id=65833,name="Primalist Tampering",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The Primalists are infusin' spiders with elemental ice and are fixin' to use 'em as shock troops tae overrun the dragons' defenses in the Span. We cannae let that happen. The three frosty lookin' ones are in charge. Take 'em out and bring me the runestones they're using tae focus the primal magic and we can see about cuttin' off the flow.",starts={{npcID=185806,x=0.49,y=0.642,zoneID=13646}},ends={{npcID=185806,x=0.49,y=0.642,zoneID=13646}},coords={x=0.49,y=0.642,source="quest_giver",zoneID=13646},questType="standard"},
[65834] = {id=65834,name="Kill the Queen",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Here we go! A lil' formal education, a lil' educated guessin', a touch o' re-chiselin' runes, and we got ourselves a magic un-infuser! Defuser? Out-fuser? Whatever! It'll do somethin' unpleasant tae the queen, o' that I'm pretty sure. And she's got tae go if we're aimin' tae stop the threat. Squashin' the lil' ones will only slow 'em down. Ye got tae cut 'em off at the source.",starts={{npcID=185806,x=0.49,y=0.642,zoneID=13646}},ends={{npcID=185806,x=0.49,y=0.642,zoneID=13646}},coords={x=0.49,y=0.642,source="quest_giver",zoneID=13646},questType="standard"},
[65836] = {id=65836,name="Show of Storm",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I--I--I stuck the shard into myself. Nothing hurts anymore. I feel good. Great. Immense. Olekk still isn't back. Something must have gone awry. He should have never gone without me!",starts={{npcID=190025,x=0.81,y=0.59,zoneID=13645}},ends={{npcID=190025,x=0.81,y=0.59,zoneID=13645}},coords={x=0.81,y=0.59,source="quest_giver",zoneID=13645},questType="standard"},
[65837] = {id=65837,name="Trouble In The Pines",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="There's been a primalist attack in the Shikaar Highlands. If you have information or think you can help, head over to Pinewood Post and look for Olekk. Tell him I sent you. I sure hope the dusty hoofer remembers me. Keep to the roads, $p. The plains are not as peaceful since all this change arrived.",starts={{npcID=195524,x=0.62,y=0.418,zoneID=13645}},ends={{npcID=190024,x=0.81,y=0.588,zoneID=13645}},coords={x=0.62,y=0.418,source="quest_giver",zoneID=13645},questType="standard"},
[65838] = {id=65838,name="Breaching the Brackenhide",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="If the gnolls here have discovered decay magic, the ley line and even the land itself are in grave danger. My mirror images are spread too thin to withstand elemental disruption of this scale. Please enter the forest and investigate the decay. I'll work with our new tuskarr friends to find a place I can maintain my image. Then, I will meet you deeper in the forest. We must put a stop to this!",starts={{npcID=187873,x=0.152,y=0.394,zoneID=13646}},ends={{npcID=187873,x=0.152,y=0.394,zoneID=13646}},coords={x=0.152,y=0.394,source="quest_giver",zoneID=13646},questType="standard"},
[65840] = {id=65840,name="Same as the Old Boss",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,description="The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing. However, Deathwing has not returned, and still there is no Twilight. It is time for a new leader. You can help bring about the change.",starts={{npcID=191304,x=0.32,y=0.522,zoneID=13644}},ends={{npcID=191304,x=0.32,y=0.522,zoneID=13644}},coords={x=0.32,y=0.522,source="quest_giver",zoneID=13644},questType="standard"},
[65842] = {id=65842,name="Disarming Behavior",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I have little love for the Worldbeaker dragonkin. They follow a misplaced belief that Deathwing himself will return one day, and they will not help us with the Obsidian Throne. Weaponmaster Vordak , who once swore loyalty to the Black Prince, has stolen many weapons crafted here in the Citadel and given them to the Worldbreakers. I will not allow such theft. Or such betrayal. Go to Smoldering Peak and recover the weapons... by force if necessary.",starts={{npcID=190899,x=0.266,y=0.624,zoneID=13644}},ends={{npcID=190899,x=0.266,y=0.624,zoneID=13644}},coords={x=0.266,y=0.624,source="quest_giver",zoneID=13644},questType="standard"},
[65844] = {id=65844,name="Cut Out the Rot",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="This decay must have rotted these gnolls' brains as well as their bodies! Destructive as they are, gnolls are native to this land--just like us. But we already saw them spreading decay to the Big Tree Tribe. At this rate, they'll consume the Span and destroy themselves. We can't let this happen. It's a shame... but put an end to them.",starts={{npcID=186181,x=0.168,y=0.372,zoneID=13646}},ends={{npcID=186181,x=0.168,y=0.372,zoneID=13646}},coords={x=0.168,y=0.372,source="quest_giver",zoneID=13646},questType="standard"},
[65845] = {id=65845,name="Echoes of the Fallen",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="There are tuskarr here! My friends, my people--my family. They left for a hunt not a week ago. Already they're too decayed to recover. Their spirits are here still. They linger in rage and regret. Kaqiata , Lutokk , Tuyuki ... Please, , take this totem and place it near their remains. It'll contact their spirits... and help them find peace.",starts={{npcID=186179,x=0.206,y=0.356,zoneID=13646}},ends={{npcID=186179,x=0.206,y=0.356,zoneID=13646}},coords={x=0.206,y=0.356,source="quest_giver",zoneID=13646},questType="standard"},
[65846] = {id=65846,name="Ley Litter",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The ley line is here--I can feel it! But first, we must stop the gnolls. That ancient will be their greatest weapon. There are some ley crystals the gnolls have gathered. Thankfully, they don't seem to understand the power that the crystals hold. Bring me as many as you can. They'll empower my mirror image and help me summon something useful from the Archives to take that monster down!",starts={{npcID=187873,x=0.152,y=0.394,zoneID=13646}},ends={{npcID=187873,x=0.152,y=0.394,zoneID=13646}},coords={x=0.152,y=0.394,source="quest_giver",zoneID=13646},questType="standard"},
[65847] = {id=65847,name="Realignment",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Now for this ley line. It looks like my fears were correct -- the decay has spread into the line itself. We'll need to purge the decay and speed along the healing process, but I can't channel enough energy with my mirror image alone. Focus yourself on this ley crystal here. My connection with you will help me teleport here physically. Then, I will be strong enough.",starts={{npcID=187873,x=0.152,y=0.394,zoneID=13646}},ends={{npcID=186177,x=0.16,y=0.414,zoneID=13646}},coords={x=0.152,y=0.394,source="quest_giver",zoneID=13646},questType="standard"},
[65848] = {id=65848,name="Tome-ward Bound",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We must stop that tree! With these ley crystals, I can finally help. Speak with me when you are ready. I'll open a portal into the Azure Archives and try to bring out something useful. Stand back, it may be rather unstable.",starts={{npcID=187873,x=0.152,y=0.394,zoneID=13646}},ends={{npcID=187873,x=0.152,y=0.394,zoneID=13646}},coords={x=0.152,y=0.394,source="quest_giver",zoneID=13646},questType="standard"},
[65849] = {id=65849,name="To Iskaara",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Thank you, , for all your help. My family is safe because of you. Now, we can finally return to Iskaara and see old Ponoliak taken back to the sea. He was my mentor, and a fine chieftain. Please, you must join us! A celebration of the Cycle of the Sea is something all can share in.",starts={{npcID=186179,x=0.206,y=0.356,zoneID=13646}},ends={{npcID=186480,x=0.132,y=0.494,zoneID=13646}},coords={x=0.206,y=0.356,source="quest_giver",zoneID=13646},questType="standard"},
[65850] = {id=65850,name="The Cycle of the Sea",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Thank you, . I have learned what I need for now from our new friends. The funeral ceremony for their former chieftain is about to start. Given how kind and hospitable the Iskaarans have been to us, it seems only right that we join them before departing back to the Archives. Speak with Brena and let her know we are ready when they are.",starts={{npcID=189793,x=0.132,y=0.494,zoneID=13646}},ends={{npcID=186177,x=0.16,y=0.414,zoneID=13646}},coords={x=0.132,y=0.494,source="quest_giver",zoneID=13646},questType="standard"},
[65852] = {id=65852,name="Straight to the Top",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="There appears to be something sapping the arcane energies at the apex of the tower. Now that you've stabilized the energies down here, you should be able to \"ride\" the arcane magics in the area. Look in that bag of yours for something called an arcane stepping stone , and use it to meet me at the top.",starts={{npcID=185622,x=0.408,y=0.59,zoneID=13646}},ends={{npcID=186184,x=0.4,y=0.614,zoneID=13646}},coords={x=0.408,y=0.59,source="quest_giver",zoneID=13646},questType="standard"},
[65854] = {id=65854,name="Reclaiming the Oathstone",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Fine work, friend. It seems we've managed to repair the leylines within the Azure Archives. Back when the blue dragonflight was united, I would tell my brothers and sisters to never doubt the strength of mortals. Meet me at the oathstone to the south of here. I will reclaim it, and then be on my way to Thaldraszus.",starts={{npcID=186184,x=0.4,y=0.614,zoneID=13646}},ends={{npcID=186188,x=0.394,y=0.63,zoneID=13646}},coords={x=0.4,y=0.614,source="quest_giver",zoneID=13646},questType="standard"},
[65855] = {id=65855,name="Aiding Azure Span",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The oathstone's energy cannot be reclaimed until the ley lines within the Azure Span are repaired. Some ley lines may only be reachable by those of Kalecgos's skills... but you may still be of aid. If they still yet survive, seek out the tuskarr. They lived here in my times and have a deep knowledge of the land. Speak with one of our arcane aids to return to your allies.",starts={{npcID=186188,x=0.394,y=0.63,zoneID=13646}},ends={{npcID=183543,x=0.466,y=0.4,zoneID=13646}},coords={x=0.394,y=0.63,source="quest_giver",zoneID=13646},questType="standard"},
[65864] = {id=65864,name="Catch the Caravan",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="You should catch up with Brena . Her caravan passed through no more than a few hours ago. They were collecting our late chieftain's most prized possessions for a funeral to honor him. Given that the caravan was heavily burdened, she can't be far ahead.",starts={{npcID=190225,x=0.456,y=0.388,zoneID=13646}},ends={{npcID=186224,x=0.352,y=0.37,zoneID=13646}},coords={x=0.456,y=0.388,source="quest_giver",zoneID=13646},questType="standard"},
[65865] = {id=65865,name="They've Got Us Pinned Down!",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[65866] = {id=65866,name="Snap the Traps",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The hills ahead are littered with insidious bladejaw traps. With a keen eye, you should be able to locate them. Very carefully spring the traps using this old tuskarr trick: a long stick. Note that while stepping on them is another way to set the traps off, I wouldn't recommend it. Once enough have been removed, find Hanu . Elder Poa and I will catch up when we can.",starts={{npcID=191810,x=0.352,y=0.37,zoneID=13646}},ends={{npcID=186618,x=0.342,y=0.312,zoneID=13646}},coords={x=0.352,y=0.37,source="quest_giver",zoneID=13646},questType="standard"},
[65867] = {id=65867,name="Howling in the Big Tree Hills",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The gnolls that attacked our caravan were led by three lieutenants. Durgun was flanked by a dozen hyenas. Kerwal cackled maniacally each time we tried to pursue him and fell for one of his steel-jawed traps. Bakra taunted us, mercilessly. To have a hope in recovering what was stolen, they must be slain.",starts={{npcID=191810,x=0.352,y=0.37,zoneID=13646}},ends={{npcID=186618,x=0.342,y=0.312,zoneID=13646}},coords={x=0.352,y=0.37,source="quest_giver",zoneID=13646},questType="standard"},
[65868] = {id=65868,name="Those Aren't for Chewing",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I found one of Ponoliak's funerary offerings , mishandled and then discarded by these Shadepaw gnolls... It has bite marks all over it! This offering, and others like it, are needed for the memorial ceremony for the recently deceased Iskaara chieftain. It's a travesty that something so sacred should be employed as a chew toy. Please keep an eye out for more offerings.",starts={{npcID=188809,x=0.352,y=0.37,zoneID=13646}},ends={{npcID=186618,x=0.342,y=0.312,zoneID=13646}},coords={x=0.352,y=0.37,source="quest_giver",zoneID=13646},questType="standard"},
[65869] = {id=65869,name="Another Ambush",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="A tragedy. And potentially the first of many more. Find out what Akiun knows, then examine anyone who fell in the attack. I have my hunches about what happened here. Let's see if the clues support my theory. Meanwhile, I'll try to reassure my rattled friends.",starts={{npcID=187721,x=0.286,y=0.348,zoneID=13646}},ends={{npcID=189708,x=0.288,y=0.346,zoneID=13646}},coords={x=0.286,y=0.348,source="quest_giver",zoneID=13646},questType="standard"},
[65870] = {id=65870,name="Supplies!",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="There was no sign of our stolen hunting supplies in the Big Tree Hills. They must be in that cave. Keep an eye out for the supply containers, and be prepared for anything. I would not trust the gnolls to leave the goods unprotected.",starts={{npcID=189662,x=0.344,y=0.31,zoneID=13646}},ends={{npcID=189662,x=0.344,y=0.31,zoneID=13646}},coords={x=0.344,y=0.31,source="quest_giver",zoneID=13646},questType="standard"},
[65871] = {id=65871,name="Gnoll Way Out",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I've tracked the captured tuskarr, including my husband Norukk , to this cave. Norukk doesn't always look out for his own hide, so that responsibility falls to me. But I'm not too proud to ask for help. Please rescue them!",starts={{npcID=189642,x=0.344,y=0.312,zoneID=13646}},ends={{npcID=189642,x=0.344,y=0.312,zoneID=13646}},coords={x=0.344,y=0.312,source="quest_giver",zoneID=13646},questType="standard"},
[65872] = {id=65872,name="Ill Gnolls with Ill Intent",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I'm catching a strange scent on the wind. Something here isn't right... Hanu described the gnolls in this cave as strange... and sickly. We should learn more about what is causing this. Don't let your guard down. Despite their sickly appearance, expect them to be just as devious and dangerous.",starts={{npcID=186228,x=0.344,y=0.31,zoneID=13646}},ends={{npcID=186228,x=0.344,y=0.31,zoneID=13646}},coords={x=0.344,y=0.31,source="quest_giver",zoneID=13646},questType="standard"},
[65873] = {id=65873,name="Leader of the Shadepaw Pack",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Kargpaw is the true leader of the gnolls in this part of the forest. We've had... unpleasant encounters with him in the past. This time was different. He carried a strange totem that seemed to twist his very essence. Kargpaw must be stopped and this totem recovered. I fear the gnolls are meddling in something darker than we can imagine.",starts={{npcID=186228,x=0.344,y=0.31,zoneID=13646}},ends={{npcID=186228,x=0.344,y=0.31,zoneID=13646}},coords={x=0.344,y=0.31,source="quest_giver",zoneID=13646},questType="standard"},
[65874] = {id=65874,name="A Rotten Revelation",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="Hmm... We've got to put our whiskers together and determine what this means.",questType="standard"},
[65875] = {id=65875,name="A Dragon's Day Off",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="A lifetime spent in Outland... always fighting. So little time to relax! Sometimes a dragon just needs a day off by the sea with a cold, cold drink in their claws. Hey, maybe you can help me relax! Do me a favor and see if you can find a few of these drinks to refresh our supply here.",starts={{npcID=192662,x=0.202,y=0.396,zoneID=13644}},ends={{npcID=192662,x=0.202,y=0.396,zoneID=13644}},coords={x=0.202,y=0.396,source="quest_giver",zoneID=13644},questType="standard"},
[65886] = {id=65886,name="To Rhonin's Shield",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Raszageth and the Primalists are launching an all out assault on Vakthros. We cannot let her succeed! Khadgar and I will go ahead to handle the situation there from the sky. In the meantime, make your way to the Rhonin's Shield, one of the last Kirin Tor camps in the area. You may be able to get there faster by riding that drake of yours from the top of the archives. See that the Kirin Tor there are all right, then make your way to Vakthros. We'll be counting on your help from the ground.",starts={{npcID=186280,x=0.394,y=0.63,zoneID=13646}},ends={{npcID=189751,x=0.658,y=0.254,zoneID=13646}},coords={x=0.394,y=0.63,source="quest_giver",zoneID=13646},questType="standard"},
[65887] = {id=65887,name="To the Mountain",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="It's a sight to behold up there, Khadgar and Kalecgos fighting the Primalists in the sky! They've summoned several mirror images of themselves to help you through the monstrous hole the Primalists have created. One pair is at the base of the mountains right now. If things start to look bad... well I'll get the word out to the rest of us in the Azure Span .",starts={{npcID=189751,x=0.658,y=0.254,zoneID=13646}},ends={{npcID=186304,x=0.7,y=0.352,zoneID=13646}},coords={x=0.658,y=0.254,source="quest_giver",zoneID=13646},questType="standard"},
[65890] = {id=65890,name="The Nelthazan Ruins",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Dragonscale Expedition requires your assistance. A skyscribe was sent to the ruins to gather information. They should be uninhabited, but I can hear his shouting from over here. He must be in dire circumstances for it to be audible at this distance. On this expedition, we take care of our own. Even the insufferable ones. Seek him out and protect him from whatever danger he has found.",starts={{npcID=190089,x=0.66,y=0.25,zoneID=13645}},ends={{npcID=186300,x=0.64,y=0.182,zoneID=13645}},coords={x=0.66,y=0.25,source="quest_giver",zoneID=13645},questType="standard"},
[65891] = {id=65891,name="Tools of the Tirade",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Good. I was just thinking that I am in need of an adventurer like you. Strong. Sturdy. Willing to work for a trivial sum. It is as if I willed you into existence. Well done, me. These ruins seem to have brought the attention of others. We cannot rely on them to excavate it properly. They will taint the samples! Take this. Deploy it around artifacts of interest around the ruins. It is enchanted to perform any necessary duty.",starts={{npcID=186300,x=0.64,y=0.182,zoneID=13645}},ends={{npcID=186300,x=0.64,y=0.182,zoneID=13645}},coords={x=0.64,y=0.182,source="quest_giver",zoneID=13645},questType="standard"},
[65893] = {id=65893,name="The Relic Inquiry",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Sundered Flame are here. Would you trust anyone claiming to be sundered with precious artifacts? I did not think so. Regardless, we need to know what they are here for if we are to proceed. Gather what you can recover from them and report back to me with your findings. There are more pieces to this puzzle than what we will find in the ground.",starts={{npcID=186300,x=0.64,y=0.182,zoneID=13645}},ends={{npcID=186300,x=0.64,y=0.182,zoneID=13645}},coords={x=0.64,y=0.182,source="quest_giver",zoneID=13645},questType="standard"},
[65895] = {id=65895,name="Competing Company",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Bah! We will learn nothing from the slaughter of laborers. Seek out their leaders. One of them will know what we need. Oh, and . Listen to them before you kill them this time. You may learn something useful.",starts={{npcID=186300,x=0.64,y=0.182,zoneID=13645}},ends={{npcID=186300,x=0.64,y=0.182,zoneID=13645}},coords={x=0.64,y=0.182,source="quest_giver",zoneID=13645},questType="standard"},
[65896] = {id=65896,name="Let the Healing Begin",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,description="Do you think you would be able to step into this city without me noticing? No! I was right about your kind before and I'll be damned before I let dragons destroy my home again. This once was a park filled with joy and peace. Then your progenitor, Deathwing, came. Oh yes, I know all about him. See for yourself the legacy of destruction that was left behind. The pain that walks these streets still.",starts={{npcID=190830,x=0.442,y=0.57,zoneID=1519}},ends={{npcID=194554,x=0.448,y=0.698,zoneID=1519}},coords={x=0.442,y=0.57,source="quest_giver",zoneID=1519},questType="standard"},
[65898] = {id=65898,name="Proto Problems",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I hold no love for the Sundered Flame, but even I cannot stand idle while they rip themselves apart like this. It is all too familiar. Whatever this Locus is, it is safer in our hands than in their clutches. Follow the trail of bodies and I suspect we will find it. Do be careful, $p. I worry we will find that the nest is not quite as abandoned as it appears.",starts={{npcID=186300,x=0.64,y=0.182,zoneID=13645}},ends={{npcID=191154,x=0.662,y=0.242,zoneID=13645}},coords={x=0.64,y=0.182,source="quest_giver",zoneID=13645},questType="standard"},
[65899] = {id=65899,name="Find Theramus",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="! Are you here to visit the beautiful Lilac Ramble? I'm so sorry about its current state. I promise it's not usually this untended! Theramus, the garden's keeper, was supposed to meet us today and tackle the issues together. He's been struggling with the upkeep lately, so Felina and I are helping out. But we can't do it all. Would you help us look around for him? Maybe he did forget.",starts={{npcID=186303,x=0.244,y=0.63,zoneID=13645}},ends={{npcID=186303,x=0.244,y=0.63,zoneID=13645}},coords={x=0.244,y=0.63,source="quest_giver",zoneID=13645},questType="standard"},
[65900] = {id=65900,name="Suspiciously Spiced Steak",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="My sister's idea is charming, but Theramus needs a real pick-me-up. That would be a generous serving of sourbloom . We can make it into a paste to slather onto his favorite food: turtle meat! Will you help me collect the ingredients?",starts={{npcID=185726,x=0.244,y=0.63,zoneID=13645}},ends={{npcID=185726,x=0.244,y=0.63,zoneID=13645}},coords={x=0.244,y=0.63,source="quest_giver",zoneID=13645},questType="standard"},
[65901] = {id=65901,name="Sneaking Out",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I'm grounded indefinitely! Doesn't my Ohn know I'm turning sixteen next spring? I should be able to leave when I want to. You look like you could help me out. I do have an escape plan: by channeling these totems, I'll concentrate the air and create quite a stir. But I can't go around placing them, because I'm under maximum wind watch. Even Togo won't help me. But with your help... Please! I promise I'll show you something cool.",starts={{npcID=190014,x=0.562,y=0.77,zoneID=13645}},ends={{npcID=190014,x=0.562,y=0.77,zoneID=13645}},coords={x=0.562,y=0.77,source="quest_giver",zoneID=13645},questType="standard"},
[65902] = {id=65902,name="Food or Floof",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Look at this juicy and delectable herbed turtle meat ! I speak objectively, of course. I'm a vegetarian. Go on! He probably hasn't had a meal all day.",starts={{npcID=185726,x=0.244,y=0.63,zoneID=13645}},ends={{npcID=185726,x=0.244,y=0.63,zoneID=13645}},coords={x=0.244,y=0.63,source="quest_giver",zoneID=13645},questType="standard"},
[65903] = {id=65903,name="Can't Beat Fluffy",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Poor Theramus. I have an idea to cheer him up! Take this net to catch some of the native hoppers, which are docile but quick. They've made quite a home by the coast. We'll bring them to Theramus. He'll literally be overrun with fluffy goodness!",starts={{npcID=186303,x=0.244,y=0.63,zoneID=13645}},ends={{npcID=186303,x=0.244,y=0.63,zoneID=13645}},coords={x=0.244,y=0.63,source="quest_giver",zoneID=13645},questType="standard"},
[65904] = {id=65904,name="Enough Is Enough",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Grumpy or not, Theramus has a job to do. While he hides inside, he can't see the consequences of his absence. Let's go together. We'll show him the evidence.",starts={{npcID=186303,x=0.244,y=0.63,zoneID=13645}},ends={{npcID=186303,x=0.244,y=0.63,zoneID=13645}},coords={x=0.244,y=0.63,source="quest_giver",zoneID=13645},questType="standard"},
[65905] = {id=65905,name="More Than Weeds",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Perhaps it's best we give Theramus some space. But we can't be idle. The grove is destroying itself at a rapid rate! Please help us out.",starts={{npcID=185726,x=0.244,y=0.63,zoneID=13645}},ends={{npcID=185726,x=0.244,y=0.63,zoneID=13645}},coords={x=0.244,y=0.63,source="quest_giver",zoneID=13645},questType="standard"},
[65906] = {id=65906,name="A Disgruntled Initiate",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I received an interesting letter from Ohn'iri Springs. As for the letter's contents, it details, quote, horrid imprisonment, controlling mentors, and extreme boredom. It is formally signed by Initiate Radiya . There's also a sketch of an eagle... kicking a centaur named Meluun off a cliff. Well. I suppose this is a call for help, if you are so inclined to see for yourself. To be frank, I think Radiya is probably okay. She sends me such letters often.",starts={{npcID=195302,x=0.63,y=0.34,zoneID=13645}},ends={{npcID=190014,x=0.562,y=0.77,zoneID=13645}},coords={x=0.63,y=0.34,source="quest_giver",zoneID=13645},questType="standard"},
[65907] = {id=65907,name="Favorite Fruit",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Mystic training is so boring. I'm watching water be wet half of my days. My brothers are already out in the wild hunting drakes and primalists, and making a difference in the world. Anyway, I promised I'd show you something cool! Did you know mudstompers love bushfruit? It grows nearby, among the geysers. Go pick some and we can feed them together.",starts={{npcID=190014,x=0.562,y=0.77,zoneID=13645}},ends={{npcID=190014,x=0.562,y=0.77,zoneID=13645}},coords={x=0.562,y=0.77,source="quest_giver",zoneID=13645},questType="standard"},
[65911] = {id=65911,name="Azure Alignment",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The bonds of this community... the friendship and family they share. I... never had that. The blue dragonflight never had that. And maybe that's because we haven't had a chance to. Now is the time. I must gather my kind. Meet me at the Azure Archives. There is much to be done.",starts={{npcID=186177,x=0.16,y=0.414,zoneID=13646}},ends={{npcID=186280,x=0.394,y=0.63,zoneID=13646}},coords={x=0.16,y=0.414,source="quest_giver",zoneID=13646},questType="standard"},
[65913] = {id=65913,name="Wotcher, Watcher?",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13802,description="Thank the Titans! , we need your help! Primalists attacked only moments ago. My sisters and I were able to defend, but at a severe loss... There will be time to mourn after my watcher is safe! A group of Primalists broke away while we were fighting and I swear if they hurt our Watcher-- You must help her before it's too late!",starts={{npcID=190527,x=0.496,y=0.588,zoneID=13647},{npcID=190527,x=0.528,y=0.532,zoneID=13802}},ends={{npcID=189045,x=0.496,y=0.588,zoneID=13647}},coords={x=0.496,y=0.588,source="quest_giver",zoneID=13647},questType="standard"},
[65914] = {id=65914,name="Mammoths Matter",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Our tribe has proudly nurtured the On'tuq mammoth herd for generations. Now they're... gone. Their souls will linger in rage, after such a massacre. We must honor their lives by making good use of their remains. There's too many for us to gather alone. Please, gather what materials you can from the youngsters and matriarchs, then meet me in the Kauriq Gleamlet.",starts={{npcID=186157,x=0.448,y=0.506,zoneID=13646}},ends={{npcID=186157,x=0.448,y=0.506,zoneID=13646}},coords={x=0.448,y=0.506,source="quest_giver",zoneID=13646},questType="standard"},
[65916] = {id=65916,name="We Don't Negotiate with Primalists",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The Primalists thought they were able to overcome the might of Tyr. They were wrong. My refti were able to track down the Primalists to a cave not far from here. As I thought, they have the missing keystones. Champion, if we are to restore the reservoir, we must get those keystones back. Furthermore, their leader must be slain so that they won't attempt a second assault.",starts={{npcID=189045,x=0.496,y=0.588,zoneID=13647}},ends={{npcID=189045,x=0.496,y=0.588,zoneID=13647}},coords={x=0.496,y=0.588,source="quest_giver",zoneID=13647},questType="standard"},
[65918] = {id=65918,name="Preventative Maintenance",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13802,description="The Primal Elementals are reproducing unchecked. Ordinarily, my sisters and I would take care of them, but we're in no condition to fight them. We've had so many of our soldiers eliminated. Besides, we few that remain have other matters we must look into. Zuttiki winces in pain.> That's where you come in, $p. Could you take care of the elementals?",starts={{npcID=190527,x=0.496,y=0.588,zoneID=13647},{npcID=190527,x=0.528,y=0.532,zoneID=13802}},ends={{npcID=190527,x=0.496,y=0.588,zoneID=13647},{npcID=190527,x=0.528,y=0.532,zoneID=13802}},coords={x=0.496,y=0.588,source="quest_giver",zoneID=13647},questType="standard"},
[65920] = {id=65920,name="For the Ward!",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13802,description="We can finally restore the wards. We have suffered great losses, but our work must be completed. $p, we need your help once more. Bring each keystone to its rightful place in order to make the wards whole again. Once that is done, come back, so we can activate the console and restore order in the reservoir.",starts={{npcID=189045,x=0.496,y=0.588,zoneID=13647}},ends={{npcID=189045,x=0.496,y=0.588,zoneID=13647}},coords={x=0.496,y=0.588,source="quest_giver",zoneID=13647},questType="standard"},
[65921] = {id=65921,name="Refti Retribution",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13802,description="I cannot get it out of my head, $p. So many of my sisters massacred! Lives tossed away... Their sacrifices will not go unanswered! My soldiers have tracked down the Primalists, and they say some of our sisters are still alive. We must rescue them, and ensure every Primalist knows my anger!",starts={{npcID=190527,x=0.496,y=0.588,zoneID=13647},{npcID=190527,x=0.528,y=0.532,zoneID=13802}},ends={{npcID=190527,x=0.496,y=0.588,zoneID=13647},{npcID=190527,x=0.528,y=0.532,zoneID=13802}},coords={x=0.496,y=0.588,source="quest_giver",zoneID=13647},questType="standard"},
[65925] = {id=65925,name="Culling the Cullers",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="These wyrms don't belong here. I don't know what's driven them from their underground lairs, but there's no way to help them, now. We can't allow them to destroy the native life here. Slay the wyrms, . Keep their parts, if you must, and find me in the Gleamlet when you're done.",starts={{npcID=186157,x=0.448,y=0.506,zoneID=13646}},ends={{npcID=186157,x=0.448,y=0.506,zoneID=13646}},coords={x=0.448,y=0.506,source="quest_giver",zoneID=13646},questType="standard"},
[65926] = {id=65926,name="Tackling the Falls",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Have you heard the tale of the Gleamfisher? She built a boat strong enough to pass down waterfalls! Elder Nava loves to tell the story. I think the noble spirits of the On'tuq mammoths would be honored if we used their remains to craft such a boat again. My brother says no. But if we succeed, we can help bring fish to our struggling sister tribes. You've proven your skill and passion! Together, I'm sure we can build something great.",starts={{npcID=186157,x=0.448,y=0.506,zoneID=13646}},ends={{npcID=186386,x=0.454,y=0.542,zoneID=13646}},coords={x=0.448,y=0.506,source="quest_giver",zoneID=13646},questType="standard"},
[65928] = {id=65928,name="Wayward Winds",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Bah! Work together, she says? But... if the Gleamfisher believes there is a chance we can help the other tribes... we must try. For the wind spirit Kraunot to acknowledge us, we will first have to tend to his element. The nearby wind elementals have been agitated ever since the land began to awaken. While I inspect this boat you two made, you go and fight to dismantle them, then bring me their restless motes . That should bring some calm back to the area.",starts={{npcID=186386,x=0.454,y=0.542,zoneID=13646}},ends={{npcID=186386,x=0.454,y=0.542,zoneID=13646}},coords={x=0.454,y=0.542,source="quest_giver",zoneID=13646},questType="standard"},
[65929] = {id=65929,name="Ice Breakers",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I knew the ancestor would approve! I don't know much about spirits -- Kauj is the shaman. But we will need to appease the great Spirits of Air and Water before they will appear to us. Anyone could see water elementals up the mountain slowly freezing. It is not a natural freeze. Cold has been coming down the mountains more than usual, lately. Left be, our entire river could ice over. Release them from their icy prisons!",starts={{npcID=186157,x=0.448,y=0.506,zoneID=13646}},ends={{npcID=186157,x=0.448,y=0.506,zoneID=13646}},coords={x=0.448,y=0.506,source="quest_giver",zoneID=13646},questType="standard"},
[65930] = {id=65930,name="A Wrestle of Wind and Water",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Now we should be able to face the Spirits. Did Ruriq fail to mention it? By our tribe's traditions, we must face the Spirits in combat before asking a boon of them. The strength of their blessing is dependent on how well you impress them. Perhaps that is why the Gleamfisher insisted we all work together. If you take on Kraunot, the Spirit of Air, Ruriq and I will tackle Otu'rorq, the Spirit of Water. They dwell in the cave behind the nearby waterfall. We will meet you there, adventurer.",starts={{npcID=186386,x=0.454,y=0.542,zoneID=13646}},ends={{npcID=186157,x=0.448,y=0.506,zoneID=13646}},coords={x=0.454,y=0.542,source="quest_giver",zoneID=13646},questType="standard"},
[65935] = {id=65935,name="Catching Up to Chromie",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="You have helped us regain our hold on the sands, but I can sense something greater happening up on the temple platforms. Let us take to the skies and regroup with Ambassador Chronormu there. As always, time is of the essence.",starts={{npcID=187877,x=0.574,y=0.788,zoneID=13647}},ends={{npcID=186711,x=0.596,y=0.816,zoneID=13647}},coords={x=0.574,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[65937] = {id=65937,name="Proof of Negligence",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="We can't give up. He must understand what's happening out here! If he won't leave the cave, we'll show him directly. Anything will do, I'm sure. There's so much going wrong, from the corrupted flora to the antagonized wildlife!",starts={{npcID=186303,x=0.244,y=0.63,zoneID=13645}},ends={{npcID=186303,x=0.244,y=0.63,zoneID=13645}},coords={x=0.244,y=0.63,source="quest_giver",zoneID=13645},questType="standard"},
[65938] = {id=65938,name="The Once and Future Team",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="All right! Let's pop that stasis bubble around the temple doors and release our Wardens! Are you ready for a huge tug-of-war match with time itself? Yank at the door's bubble like you did with the crystals earlier. But be careful, all the time energy released is sure to collect and attack you. I'm not sure what will be there, but at least you'll have the freed Wardens on your side no matter what happens. Good luck, !",starts={{npcID=186711,x=0.596,y=0.816,zoneID=13647}},ends={{npcID=186711,x=0.596,y=0.816,zoneID=13647}},coords={x=0.596,y=0.816,source="quest_giver",zoneID=13647},questType="standard"},
[65939] = {id=65939,name="The Courage of One's Convictions",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The next battle will no doubt be fierce, but our courage and determination will overcome their greater numbers. I am counting on your exceptional skills to help lead the troops to victory. We shall begin the assault when you are ready.",starts={{npcID=186681,x=0.34,y=0.612,zoneID=13644}},ends={{npcID=186933,x=0.29,y=0.588,zoneID=13644},{npcID=187045,x=0.272,y=0.626,zoneID=13644},{npcID=196265,x=0.264,y=0.586,zoneID=13644}},coords={x=0.34,y=0.612,source="quest_giver",zoneID=13644},questType="standard"},
[65940] = {id=65940,name="By Broken Road",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I hope you don't mind getting your feet wet. The next leg of our journey will take us across two rivers. Ohn Seshteng would like to share a story with you about our blessed watcher, Ohn'ahra. I happily leave you under her watch.",starts={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},ends={{npcID=184595,x=0.856,y=0.208,zoneID=13645}},coords={x=0.756,y=0.316,source="quest_giver",zoneID=13645},questType="standard"},
[65943] = {id=65943,name="Primal Offensive",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Khadgar and I are doing our best to hold off the Primalists in the sky, but we can't push further towards the tower. We need you to weaken their ground forces so we can get closer to Raszageth and stop her before it's too late. Make your way through the Primalists ahead. If I can maintain my concentration, there'll be another mirror image waiting.",starts={{npcID=186304,x=0.7,y=0.352,zoneID=13646}},ends={{npcID=186686,x=0.744,y=0.378,zoneID=13646}},coords={x=0.7,y=0.352,source="quest_giver",zoneID=13646},questType="standard"},
[65944] = {id=65944,name="Lava Burst",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The Primalists have torn apart the mountain to send their forces streaming to Vakthros! I spied some lava orbs in the initial corridor that they're using to spread more of their elemental chaos. Destroy them to help slow their advance. I'll do what I can from up here to help Kalecgos.",starts={{npcID=186305,x=0.7,y=0.352,zoneID=13646}},ends={{npcID=186688,x=0.744,y=0.378,zoneID=13646}},coords={x=0.7,y=0.352,source="quest_giver",zoneID=13646},questType="standard"},
[65947] = {id=65947,name="Time-Locked Timewalkers",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="I'm so glad you're here! I need you to stabilize the situation here on the platforms while Dante and Zera help me hold our infinite dragon friend in place. The temple's security measures locked Eternus in a stasis bubble when she tried to take control of our Oathstone. Unfortunately, the other Timewalkers were also caught in those security measures. Your Timewalker staff should free them, no problem. Just make sure to deal with any angry timelings that pop up!",starts={{npcID=186711,x=0.596,y=0.816,zoneID=13647}},ends={{npcID=186711,x=0.596,y=0.816,zoneID=13647}},coords={x=0.596,y=0.816,source="quest_giver",zoneID=13647},questType="standard"},
[65948] = {id=65948,name="Cracks in Time",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="When the temple locked down, the Wardens got sealed up with the temple doors. We need to pop that stasis bubble to get them out! Unfortunately, that'll need a fully empowered Timewalker staff... I know! You can drain the crystals here on the platforms! That should power up your staff enough. They have their own stasis fields, so just yank them out and absorb their energy with your staff. And don't feel bad if they shatter--the power is still there, even if it's in pieces!",starts={{npcID=186711,x=0.596,y=0.816,zoneID=13647}},ends={{npcID=186711,x=0.596,y=0.816,zoneID=13647}},coords={x=0.596,y=0.816,source="quest_giver",zoneID=13647},questType="standard"},
[65949] = {id=65949,name="The Sole Mender",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="When we join Ohn'ahra in the wind, we leave these medallions behind. Although I helped craft this medallion, I am not its rightful owner. It should be returned to Roscha. It is the last memory of her betrothed. Take it to her so she may mourn and be at peace.",starts={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},ends={{npcID=186650,x=0.844,y=0.25,zoneID=13645}},coords={x=0.806,y=0.308,source="quest_giver",zoneID=13645},questType="standard"},
[65950] = {id=65950,name="Thieving Gorlocs",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Is Farrier Roscha invited to the caravan? No! But who must provide shoes for the caravan? Farrier Roscha . And from whom do the Mudfins steal? Of course, Farrier Roscha . Pah. I would send Khasar , but who knows where he has wandered this time? Find my supplies. Teach those thieving creatures not to steal from Farrier Roscha . Go!",starts={{npcID=186650,x=0.844,y=0.25,zoneID=13645}},ends={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},coords={x=0.844,y=0.25,source="quest_giver",zoneID=13645},questType="standard"},
[65951] = {id=65951,name="Sole Supplier",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Poor Roscha! She has toiled endlessly to prepare for the caravan, only for her supplies to be stolen by nasty gorlocs. She has lost so much already. I am doing my best to assist her. Khasar likely went after her supplies alone, telling no one. It is his way. But he has been gone too long. Many dogs are missing as well. Would you please check on Khasar and the dogs, $p?",starts={{npcID=186653,x=0.844,y=0.25,zoneID=13645}},ends={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},coords={x=0.844,y=0.25,source="quest_giver",zoneID=13645},questType="standard"},
[65952] = {id=65952,name="A Chief of Legends",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The gorlocs of this swamp were once simple creatures. Pests, perhaps, but never raiders, thieves, or dog-eaters. It is their chief, Grrlgllmesh, who has led them away from their nature. Put an end to him, and the gorlocs will threaten us no more.",starts={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},ends={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},coords={x=0.806,y=0.308,source="quest_giver",zoneID=13645},questType="standard"},
[65953] = {id=65953,name="The Ora-cull",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Of all the madness in this gorloc village, I have discovered none so troubling as the gorloc shamans. They are particularly vicious and play recklessly with storm magic with no regard for the consequences. This must be put to an end. Slay them, and bring me their totems. Our mystics will be interested in them.",starts={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},ends={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},coords={x=0.806,y=0.308,source="quest_giver",zoneID=13645},questType="standard"},
[65954] = {id=65954,name="Release the Hounds",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I have heard the familiar howls and barks of bakar that are missing from camp. Our beloved dogs are trapped in cages, waiting to be ripped apart by those... those things. We have a duty to our companions. Free them and witness the true might of a Shikaar bakar!",starts={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},ends={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},coords={x=0.806,y=0.308,source="quest_giver",zoneID=13645},questType="standard"},
[65955] = {id=65955,name="A Centaur's Best Friend",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="It isn't safe for us to remain in the open, $p. The gorlocs forced my hunting companion, Baba, into a cave to the east. Set me free, then we shall rescue Baba. I will meet you in the cave when the path is clear.",starts={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},ends={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},coords={x=0.806,y=0.308,source="quest_giver",zoneID=13645},questType="standard"},
[65956] = {id=65956,name="Talon Strike",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="With your help, my Blacktalon assassins will cut down the djaradin defending the outer perimeter. Mark any targets with a small stun bomb, and they will come to your aid. Proceed quickly and eliminate anything that may hinder our advance.",starts={{npcID=186274,x=0.424,y=0.668,zoneID=13644}},ends={{npcID=186681,x=0.34,y=0.612,zoneID=13644}},coords={x=0.424,y=0.668,source="quest_giver",zoneID=13644},questType="standard"},
[65957] = {id=65957,name="No Time for Heroes",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="From what we have observed, djaradin society is built on strength. The strongest serve as examples for others to fight all the harder. Among the forces below are three examples of the mightiest djaradin... and your targets. You, , will personally eliminate them. This should deal a devastating blow to their morale.",starts={{npcID=186274,x=0.424,y=0.668,zoneID=13644}},ends={{npcID=186681,x=0.34,y=0.612,zoneID=13644}},coords={x=0.424,y=0.668,source="quest_giver",zoneID=13644},questType="standard"},
[65958] = {id=65958,name="Primal Power",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I'm afraid it's becoming harder to maintain my mirror images. The Primalists are focusing their efforts to tearing me out from the sky. Not to worry... I have a plan. I need you to take the orb you recovered and gather elemental magic from slain Primalists. We'll need that elemental power up ahead to divert their forces away from me.",starts={{npcID=186686,x=0.744,y=0.378,zoneID=13646}},ends={{npcID=186779,x=0.768,y=0.394,zoneID=13646}},coords={x=0.744,y=0.378,source="quest_giver",zoneID=13646},questType="standard"},
[65962] = {id=65962,name="The Never-Final Countdown",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="I never thought I'd save our temple by dismantling the very security we set up to protect it, but here we are! With the time elementals purged, our Timewalkers free, and our Wardens at the ready, it's finally time to let this last stasis bubble down and deal with Eternus. Let me know when you're ready. I know with you by my side nothing can go wrong.",starts={{npcID=186711,x=0.596,y=0.816,zoneID=13647}},ends={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},coords={x=0.596,y=0.816,source="quest_giver",zoneID=13647},questType="standard"},
[65977] = {id=65977,name="Kirin Tor Recovery",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="When the Primalists attacked our expedition, I feared many of our mages were lost to us. It seems they were taken by the Primalists and are being tortured as we speak! Please, you must rescue the mages left here. They may not be able to help in this fight, but we cannot leave them behind!",starts={{npcID=186688,x=0.744,y=0.378,zoneID=13646}},ends={{npcID=186779,x=0.768,y=0.394,zoneID=13646}},coords={x=0.744,y=0.378,source="quest_giver",zoneID=13646},questType="standard"},
[65989] = {id=65989,name="Invader Djaradin",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="We may not have the power to take back our outpost, but we do not have to surrender without a fight. Show them we still have teeth.",starts={{npcID=186584,x=0.712,y=0.408,zoneID=13644}},ends={{npcID=186584,x=0.712,y=0.408,zoneID=13644}},coords={x=0.712,y=0.408,source="quest_giver",zoneID=13644},questType="standard"},
[65990] = {id=65990,name="Deliver Whelps From Evil",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="They descended upon us before we could even respond. My guards held as long as they could as we evacuated the young and helpless, but I fear that there are more within the outpost. Cross that bridge and search for survivors.",starts={{npcID=186584,x=0.712,y=0.408,zoneID=13644}},ends={{npcID=186584,x=0.712,y=0.408,zoneID=13644}},coords={x=0.712,y=0.408,source="quest_giver",zoneID=13644},questType="standard"},
[65991] = {id=65991,name="Time for a Reckoning",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Cadet Sendrax has informed me of our majordomo's plans. Thank the Life-Binder that we have their help. Their interference gives us the reprieve we need to get our wounded back to the Life Pools to be treated. I wish I could reinforce Selistra but I must keep my guards near the wounded. Go to the enemy stronghold to meet them. If there were another way of handling the djaradin, I would ask it. But, as it were... You must do what you must.",starts={{npcID=186584,x=0.712,y=0.408,zoneID=13644}},ends={{npcID=186640,x=0.664,y=0.348,zoneID=13644}},coords={x=0.712,y=0.408,source="quest_giver",zoneID=13644},questType="standard"},
[65992] = {id=65992,name="Blacktalon Intel",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="While Selistra and I attracted their eyes above, shadows crept in through their defenses. My agents, the Blacktalon, are keeping an eye and an ear throughout the keep. Meet them and let them know you're on our side. They'll give you some valuable information on our enemies.",starts={{npcID=186640,x=0.664,y=0.348,zoneID=13644}},ends={{npcID=194772,x=0.626,y=0.33,zoneID=13644}},coords={x=0.664,y=0.348,source="quest_giver",zoneID=13644},questType="standard"},
[65993] = {id=65993,name="Killjoy",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Ah, yes. I saw the leader of these giants headed back from the raid shortly after I arrived. She's celebrating their victory somewhere within the camp. It would be a shame if someone interrupted her revelries, don't you think?",starts={{npcID=186640,x=0.664,y=0.348,zoneID=13644}},ends={{npcID=194772,x=0.626,y=0.33,zoneID=13644}},coords={x=0.664,y=0.348,source="quest_giver",zoneID=13644},questType="standard"},
[65995] = {id=65995,name="The Obsidian Citadel",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Wrathion would be interested in seeing this.>",ends={{npcID=194772,x=0.626,y=0.33,zoneID=13644}},questType="standard"},
[65996] = {id=65996,name="Veteran Reinforcements",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Commander Lethanak was insightful, as always. We will need the help of our most veteran guards to stop their threat. Rallying them was the perfect task for a young cadet like Sendrax, but she may need support. Sendrax's path will take her towards the west, which may have been overwhelmed by this rising threat. They will need aid as well. Take this concoction and give them your support.",starts={{npcID=186767,x=0.626,y=0.33,zoneID=13644}},ends={{npcID=190155,x=0.55,y=0.308,zoneID=13644}},coords={x=0.626,y=0.33,source="quest_giver",zoneID=13644},questType="standard"},
[65997] = {id=65997,name="Chasing Sendrax",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Cadet Sendrax came through here not long ago. She relayed Commander Lethanak's orders for all drakonid to rally back at the Life Pools. Our whole defensive regiment set off in that direction not long after. But our scouts were out on patrol in the old ruins, so she headed in there to rally them too.",starts={{npcID=190155,x=0.55,y=0.308,zoneID=13644}},ends={{npcID=187406,x=0.552,y=0.248,zoneID=13644}},coords={x=0.55,y=0.308,source="quest_giver",zoneID=13644},questType="standard"},
[65998] = {id=65998,name="Future of the Flights",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="There is no higher charge given to a drakonid upon their graduation than to defend every single dragon egg with their lives. It's why we train. Why we exist. I can no longer hide and observe, $p. By stealing and infusing these eggs, the Primalists threaten the entire future of the dragonflights! We are vastly outnumbered, but will you stand by my side? Will you fight to save the dragonflights?",starts={{npcID=187406,x=0.552,y=0.248,zoneID=13644}},ends={{npcID=190171,x=0.552,y=0.218,zoneID=13644}},coords={x=0.552,y=0.248,source="quest_giver",zoneID=13644},questType="standard"},
[65999] = {id=65999,name="Red in Tooth and Claw",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Commander Lethanak warned us recruits that he had received reports of the Storm-Eater, Raszageth, escaping her prison. It seems her servants have followed in her wake, threatening all we hold dear. They move quickly. These ruins were reported to be abandoned during the last patrol. We must stop the Primalists here. For the Life-Binder, and for all of the dragonflights!",starts={{npcID=187406,x=0.552,y=0.248,zoneID=13644}},ends={{npcID=190171,x=0.552,y=0.218,zoneID=13644}},coords={x=0.552,y=0.248,source="quest_giver",zoneID=13644},questType="standard"},
[66000] = {id=66000,name="Library of Alexstrasza",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,starts={{npcID=377499,x=0.552,y=0.247,zoneID=13644}},ends={{npcID=190171,x=0.552,y=0.218,zoneID=13644}},coords={x=0.552,y=0.247,source="quest_giver",zoneID=13644},questType="standard"},
[66001] = {id=66001,name="A Last Hope",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="A whole brood of whelplings, lost... Sendrax straightens her back and sticks her chin up.> There is one more location we have not checked yet. The large ritual site where that proto-dragon dropped off the eggs. Let us charge their cruel defenses together, $p, and save what we can.",starts={{npcID=190171,x=0.552,y=0.218,zoneID=13644}},ends={{npcID=186795,x=0.55,y=0.31,zoneID=13644}},coords={x=0.552,y=0.218,source="quest_giver",zoneID=13644},questType="standard"},
[66003] = {id=66003,name="Rings To Bind Them",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The djaradin here have become bold, binding flame elementals and letting them rampage through the area. The wildlife has fled, and the elementals are dangerously close to our camps. Luckily, I have been able to construct a small bastion of stone to stand against this fiery tide the djaradin have unleashed... and we will not fall! Gather the magical rings that bind these flame elementals. We shall use them to bolster our defenses against the flame elementals.",starts={{npcID=187609,x=0.374,y=0.718,zoneID=13644}},ends={{npcID=187609,x=0.374,y=0.718,zoneID=13644}},coords={x=0.374,y=0.718,source="quest_giver",zoneID=13644},questType="standard"},
[66004] = {id=66004,name="Galgresh",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[66005] = {id=66005,name="Medallion of a Fallen Friend",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Khasar may know more about the owner.>",ends={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},questType="standard"},
[66006] = {id=66006,name="Return to Roscha",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Baba is rested, and Roscha's supplies are recovered. We can return without upsetting her further. Take some boxes when you go. I will send warriors for the rest.",starts={{npcID=186649,x=0.806,y=0.308,zoneID=13645}},ends={{npcID=186650,x=0.844,y=0.25,zoneID=13645}},coords={x=0.806,y=0.308,source="quest_giver",zoneID=13645},questType="standard"},
[66007] = {id=66007,name="Free Air",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The Primalists are using these massive orbs here to hold off Kalecgos . At this rate, Kalecgos will be too injured to continue the fight. If he falls, I won't be able to fend off Raszageth. The empowered gem you hold should allow you to disguise yourself as an elemental to sneak ahead. Use the gem to destroy the orbs. That should give Kalecgos room to unleash his power. I will focus my attention on shielding the tower from Raszageth.",starts={{npcID=186779,x=0.768,y=0.394,zoneID=13646}},ends={{npcID=186862,x=0.784,y=0.4,zoneID=13646}},coords={x=0.768,y=0.394,source="quest_giver",zoneID=13646},questType="standard"},
[66009] = {id=66009,name="In Defense of Vakthros",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="It's time, . The Primalist forces in the air are dwindling now that you've handled things on the ground. Raszageth is calling in one of her lieutenants to reinforce the Primalist forces, thanks to your efforts. I need you to handle this monster while I push forward to fight Raszageth and help Khadgar. Look for my magic during your fight. I will do what I can to aid you. It is time for Raszageth to face the fury of the Aspect of magic!",starts={{npcID=186862,x=0.784,y=0.4,zoneID=13646}},ends={{npcID=193837,x=0.78,y=0.324,zoneID=13646}},coords={x=0.784,y=0.4,source="quest_giver",zoneID=13646},questType="standard"},
[66011] = {id=66011,name="In Memory of Ysera",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Oh, no! Now I think I understand. Theramus ...he misses Ysera, and she can't come back. Come! I suspect I know where he went. We won't bother him further, but it'll be good to tell him that we're sorry, and that we'll give him the space he wants. We are here for each other, within the nature all around us.",starts={{npcID=185726,x=0.244,y=0.63,zoneID=13645}},ends={{npcID=187270,x=0.248,y=0.658,zoneID=13645}},coords={x=0.244,y=0.63,source="quest_giver",zoneID=13645},questType="standard"},
[66012] = {id=66012,name="The Sealed Door",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="Our scouts have been combing the Dragon Isles for anything of interest. They've returned much of note, but one discovery stands out amongst the rest--a door. A door forged by the titans, and sealed against the world. No one has yet managed to find their way through to the artifacts that surely lie within. But then, no mystery has endured under the discerning gaze of the Reliquary. With the help of the Explorers' League, this challenge will be simple, I am certain.",starts={{npcID=186869,x=0.478,y=0.824,zoneID=13644}},ends={{npcID=186870,x=0.544,y=0.556,zoneID=13647}},coords={x=0.478,y=0.824,source="quest_giver",zoneID=13644},questType="standard"},
[66013] = {id=66013,name="Investigate the Door",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="Here we are. If we're going to get past this door, we need to understand who locked it, and how. Take a look around and see if you can find anything that might give us the answers we seek.",starts={{npcID=186870,x=0.544,y=0.556,zoneID=13647}},ends={{npcID=186870,x=0.544,y=0.556,zoneID=13647}},coords={x=0.544,y=0.556,source="quest_giver",zoneID=13647},questType="standard"},
[66015] = {id=66015,name="The Blue Dragon Oathstone",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The Azure Span has stabilized for now and more blue dragons have arrived... just in time. It's time to return to the Azure Archives and reclaim the oathstone. I would request your presence there, . You've been a great boon throughout this ordeal.",starts={{npcID=187034,x=0.782,y=0.332,zoneID=13646}},ends={{npcID=186188,x=0.394,y=0.63,zoneID=13646}},coords={x=0.782,y=0.332,source="quest_giver",zoneID=13646},questType="standard"},
[66016] = {id=66016,name="Clan Teerai",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Sansok Khan signs, Okir vocalizes for her.> Clan Teerai is the clan of our Khanam Matra, our direct connection to the Maruuk ancestors. They are the holders of our traditions, and our storytellers. To understand the Maruuk, you must understand Clan Teerai. One of the Khanam Matra's daughters, Qariin Dotur , is preparing a meal for our ancestors. Aid her. She will teach you about our people.",starts={{npcID=191283,x=0.614,y=0.396,zoneID=13645}},ends={{npcID=186941,x=0.592,y=0.376,zoneID=13645}},coords={x=0.614,y=0.396,source="quest_giver",zoneID=13645},questType="standard"},
[66017] = {id=66017,name="Clan Ohn'ir",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Sansok Khan signs, Okir vocalizes for her.> The mystics of our lands, like Ohn Seshteng , belong to Clan Ohn'ir. The clan is not made up of families, but rather of centaur from across the plains with an innate connection to Ohn'ahra. They spend their lives building that connection and honing their skills. Eventually, they receive assignments to advise different clans and protect our lands. Ohn Seshteng went to speak with her khan about the omen she received. Join her to learn about the Ohn'ir.",starts={{npcID=191283,x=0.614,y=0.396,zoneID=13645}},ends={{npcID=191595,x=0.63,y=0.336,zoneID=13645}},coords={x=0.614,y=0.396,source="quest_giver",zoneID=13645},questType="standard"},
[66018] = {id=66018,name="Clan Nokhud",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Sansok Khan signs, Okir vocalizes for her.> Clan Nokhud is the newest to rise to power. Their late khan, Jhakan, raised a mighty army to seize territory from their predecessors. Such is the way of our people. While Jhakan had earned his respect, his son has not. Balakar killed his father and took control of the clan. They have grown ever more insular since. But to know the Maruuk, you must know them.",starts={{npcID=191283,x=0.614,y=0.396,zoneID=13645}},ends={{npcID=191485,x=0.624,y=0.416,zoneID=13645}},coords={x=0.614,y=0.396,source="quest_giver",zoneID=13645},questType="standard"},
[66019] = {id=66019,name="Honoring Our Ancestors",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Our ancestors walk beside us upon the winds of Ohn'ahra, guiding and protecting us. All Maruuk, dead and living, gather under truce at the Khural. The scent of this meal calls the ancestors to our fire. When they arrive, the Khural begins.",starts={{npcID=186941,x=0.592,y=0.376,zoneID=13645}},ends={{npcID=186941,x=0.592,y=0.376,zoneID=13645}},coords={x=0.592,y=0.376,source="quest_giver",zoneID=13645},questType="standard"},
[66020] = {id=66020,name="Omens and Incense",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I shared with Tigari Khan the omen we received before entering Maruukai. She expressed her concern, as the wind felt cold to her as well. We cultivate certain flowers here, blooms that can be ground and burned to elicit a trancelike effect. They are used to deepen our connection to an omen. I request that you collect some so that we may make an incense to burn. With my khan's help, perhaps we can learn more of Ohn'ahra's plight.",starts={{npcID=191595,x=0.63,y=0.336,zoneID=13645}},ends={{npcID=191595,x=0.63,y=0.336,zoneID=13645}},coords={x=0.63,y=0.336,source="quest_giver",zoneID=13645},questType="standard"},
[66021] = {id=66021,name="Unwelcome Outsider",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Hah! Look at you. Weak. Just like those puny hunters that brought you here. You want to know the Nokhud? We speak through battle. Our battle ritual is called \"the tabarr\". We train. We spar. And it hardens us. Now there is no weakness in our clan. Enough talk. Go spar.",starts={{npcID=186940,x=0.604,y=0.406,zoneID=13645}},ends={{npcID=191485,x=0.624,y=0.416,zoneID=13645}},coords={x=0.604,y=0.406,source="quest_giver",zoneID=13645},questType="standard"},
[66022] = {id=66022,name="The Khanam Matra",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I cannot linger in centaur lands; I must return to the gardens as soon as I am able. The Khanam Matra has agreed to hear our plea for aid. She awaits my arrival at the top of the krutal, the central building of Maruukai. Though I must speak with her on my own at first, you are more than welcome to join us.",starts={{npcID=194927,x=0.61,y=0.404,zoneID=13645}},ends={{npcID=186942,x=0.602,y=0.38,zoneID=13645}},coords={x=0.61,y=0.404,source="quest_giver",zoneID=13645},questType="standard"},
[66023] = {id=66023,name="Trucebreakers",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Balakar disgraces his clan. He leads them into the storm, blinded by his lust for power. Their betrayal reveals their fragility. Cut them down.",starts={{npcID=186942,x=0.602,y=0.38,zoneID=13645}},ends={{npcID=186942,x=0.602,y=0.38,zoneID=13645}},coords={x=0.602,y=0.38,source="quest_giver",zoneID=13645},questType="standard"},
[66024] = {id=66024,name="Covering Their Tails",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Nokhud drool over war stories of our kind's ancient past. In truth they are weak, playacting children. And with one strike of lightning, they have severed their connection to Ohn'ahra. Well! If they will walk the path of corruption to seek war, then we will indulge them. Of course, Bahir was left in command to cover his escape. Her blood will soon stain the ground.",starts={{npcID=191485,x=0.624,y=0.416,zoneID=13645}},ends={{npcID=181198,x=0.6,y=0.374,zoneID=13645}},coords={x=0.624,y=0.416,source="quest_giver",zoneID=13645},questType="standard"},
[66025] = {id=66025,name="The Nokhud Threat",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Clan Nokhud's army is taking Maruukai. Let us discuss our next moves in the khan chambers. We must keep the Maruuk safe.",starts={{npcID=181198,x=0.6,y=0.374,zoneID=13645}},ends={{npcID=181198,x=0.6,y=0.374,zoneID=13645}},coords={x=0.6,y=0.374,source="quest_giver",zoneID=13645},questType="standard"},
[66026] = {id=66026,name="Urgent Action Required",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The source of these attacks must be the Brackenhide. We've fought with the Brackenhide gnolls for generations, but until now they've been nothing more than a nuisance. We have no choice but to take urgent action against the gnolls. Their foul decay will destroy the Azure Span , including whatever you're searching for. Meet us outside Brackenhide. We will need all the help we can get.",starts={{npcID=189708,x=0.288,y=0.346,zoneID=13646}},ends={{npcID=186179,x=0.206,y=0.356,zoneID=13646}},coords={x=0.288,y=0.346,source="quest_giver",zoneID=13646},questType="standard"},
[66027] = {id=66027,name="Calling the Blue Dragons",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I can no longer be afraid of reuniting the blue dragons, . It is better for us to be a family... than a fragment of our former selves. Even if I cannot reclaim the oathstone, I can still use its power to send a message to all of the blue dragons. It is time they received word... from their Aspect.",starts={{npcID=186280,x=0.394,y=0.63,zoneID=13646}},ends={{npcID=186280,x=0.394,y=0.63,zoneID=13646}},coords={x=0.394,y=0.63,source="quest_giver",zoneID=13646},questType="standard"},
[66028] = {id=66028,name="To the Future!",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13992,description="I have tracked Chronormu and Eternus to a potential future. I know not what you will find there, only that it is dark and chaotic. Soridormi has taken some of our timewalkers ahead to that future in order to hold our connection to that time stable. Her considerable power will be needed to keep the portal open, so she must rely on your talents. Soridormi will be able to direct you further once you meet her there. Hurry, . Find Chronormu.",starts={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},ends={{npcID=183860,x=0.61,y=0.508,zoneID=13992}},coords={x=0.6,y=0.824,source="quest_giver",zoneID=13647},questType="standard"},
[66029] = {id=66029,name="Temporal Tuning",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13996,description="Chronormu and Eternus are falling though time, but I sense them stop every so often. These brief moments are our opportunity to find them. Nozdormu conjures a small chrono crystal .> I have imbued this crystal with power as well as my own temporal resonance. They have gone to a... troubling possible future. Find them and use it. Hopefully you can fix their position in time before they slip away again.",starts={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},ends={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},coords={x=0.6,y=0.824,source="quest_giver",zoneID=13647},questType="standard"},
[66030] = {id=66030,name="Resistance Isn't Futile",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13992,description="The temporal ripples have caused trouble for the people here. Enemies appear where they were not, or are far stronger than they should be. These changes are small, but they are disastrous. I ask you to help the resistance fighters here. Heal their wounds so that they may fight once more. Set their timeline back on its correct course, as if it had never interacted with our own. It is not much, but it is what we can do for them.",starts={{npcID=183860,x=0.61,y=0.508,zoneID=13992}},ends={{npcID=183860,x=0.61,y=0.508,zoneID=13992}},coords={x=0.61,y=0.508,source="quest_giver",zoneID=13992},questType="standard"},
[66031] = {id=66031,name="Making Time",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="I guess I shouldn't be surprised to find myself here. This is not the Azeroth I wanted, but it's the one I have. We're fighting to preserve what's left and take the world back, but your arrival has caused some trouble. We use the essence of those elementals out there to fuel our protections and keep ourselves safe. See that shield? That's the only thing keeping us from discovery and annihilation and you drained our resources. Bring back some of that essence and we may survive another day.",questType="standard"},
[66032] = {id=66032,name="Return to the Present",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="This timeline is dark and chaotic. The disruption here has been severe. I shall remain in this timeline a moment more to help sort out what remaining ripples may appear. Return to Nozdormu . He will want to know of our success, even if it was less complete than we would like.",starts={{npcID=183860,x=0.61,y=0.508,zoneID=13992}},ends={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},coords={x=0.61,y=0.508,source="quest_giver",zoneID=13992},questType="standard"},
[66033] = {id=66033,name="To the... Past?",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=14092,mapID=2092,description="It is regrettable that we could not stabilize Chronormu, but there is another potential location where we may be able to catch her and bring an end to her fall through time. Nozdormu frowns.> The glimpses of this timeline past are... strange. Even among some of the visions I have witnessed in my life. Be on your guard, . I am uncertain what you will face, but it is powerful and... oddly familiar.",starts={{npcID=186931,x=0.6,y=0.824,mapID=2025}},ends={{npcID=187344,x=0.598,y=0.662,mapID=2092}},coords={x=0.6,y=0.824,source="quest_giver",mapID=2092},questType="standard"},
[66035] = {id=66035,name="Murloc Motes",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=14092,description="An alternate timeline born from murlocs??! Forgive my selfishness, but would you obtain a few stray motes of temporal energy while you locate Ambassador Chronomu? Just walk into them and your staff should do the rest. I will examine the data later. When we are not in the middle of venturing through rips in Azeroth's varied realities.",starts={{npcID=187344,x=0.598,y=0.662,zoneID=14092}},ends={{npcID=187344,x=0.598,y=0.662,zoneID=14092}},coords={x=0.598,y=0.662,source="quest_giver",zoneID=14092},questType="standard"},
[66036] = {id=66036,name="Mugurlglrlgl!",level=40,requiredLevel=40,faction="alliance",expansion=9,zoneID=14092,description="Mrglgulglrrlglgul! Grurguglullgurl! Gruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl. Mgrgulllglll gurl gugll.",starts={{npcID=183854,x=0.598,y=0.66,zoneID=14092}},ends={{npcID=183854,x=0.598,y=0.66,zoneID=14092}},coords={x=0.598,y=0.66,source="quest_giver",zoneID=14092},questType="standard"},
[66037] = {id=66037,name="Back to Reality",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="We were able to increase Ambassador Chronormu's connection to our time. I am certain when we find her again, we will be able to finish the ritual. For now, let us return to our present and a world with... significantly fewer murlocs.",starts={{npcID=187344,x=0.598,y=0.662,zoneID=14092}},ends={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},coords={x=0.598,y=0.662,source="quest_giver",zoneID=14092},questType="standard"},
[66038] = {id=66038,name="Race Through Time!",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13996,description=", we must act quickly to catch up to Ambassador Chronormu, and I mean that quite literally. Zera and I will do what we can to speed our progress, but it is imperative we avoid entangling with this time period as much as possible. To do so will slow us down and we may not be able to catch the Ambassador before she is lost to even Nozdormu's magic. We haven't a moment to lose! (Accepting this quest will begin a timer)",starts={{npcID=187435,x=0.434,y=0.692,zoneID=13993},{npcID=187435,x=0.524,y=0.74,zoneID=13996}},ends={{npcID=187435,x=0.434,y=0.692,zoneID=13993},{npcID=187435,x=0.524,y=0.74,zoneID=13996}},coords={x=0.434,y=0.692,source="quest_giver",zoneID=13993},questType="standard"},
[66039] = {id=66039,name="Chromie Time",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13996,description="This... This is the Black Empire. We have traveled very far into the past, indeed. Look! I see Ambassador Chronormu and Eternus! We need to hurry and complete the ritual. Even my curiosity is not enough to wish to see where they might travel to next.",starts={{npcID=187435,x=0.434,y=0.692,zoneID=13993},{npcID=187435,x=0.524,y=0.74,zoneID=13996}},ends={{npcID=186499,x=0.532,y=0.442,zoneID=13996}},coords={x=0.434,y=0.692,source="quest_giver",zoneID=13993},questType="standard"},
[66040] = {id=66040,name="Back to the Future",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="We're not going to fall through time anymore but we're far in the past. Waaaaay far in the past. \"The Titans Haven't Visited Azeroth Yet\" far in the past. Getting home is going to be... tricky. But we dragons can do it! We're going to need you to keep those Black Empire minions off our backs though. It shouldn't take too long! I think. Probably. Don't worry about it! Just keep those creepy monsters away and we'll handle the rest! Easy!",starts={{npcID=186499,x=0.532,y=0.442,zoneID=13996}},ends={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},coords={x=0.532,y=0.442,source="quest_giver",zoneID=13996},questType="standard"},
[66044] = {id=66044,name="Taking the Walls",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Sabellian and the other dragons are holding back the djaradin for now. We must act quickly to secure the high towers and ensure our victory. You and I shall clear the siege arbalests that threaten us from above. Let me know when you are ready.",starts={{npcID=186933,x=0.29,y=0.588,zoneID=13644}},ends={{npcID=196265,x=0.264,y=0.586,zoneID=13644}},coords={x=0.29,y=0.588,source="quest_giver",zoneID=13644},questType="standard"},
[66048] = {id=66048,name="Best Plans and Intentions",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Attacking the djaradin controlling the Obsidian Citadel will be no easy task. Even with Wrathion and his Blacktalon forces, this will be a fierce battle. Wrathion may be confident, but... I am not so certain. Perhaps we can speak to those helping to plan the strategy, and see if we can find any room for improvement.",starts={{npcID=192795,x=0.424,y=0.668,zoneID=13644}},ends={{npcID=186274,x=0.424,y=0.668,zoneID=13644}},coords={x=0.424,y=0.668,source="quest_giver",zoneID=13644},questType="standard"},
[66049] = {id=66049,name="Obsidian Oathstone",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="When Neltharion became the Earth-Warder, he swore an oath to protect this world, . To safeguard the deep places of the earth and, with his flight, to serve as Azeroth's defenders. The Obsidian Oathstone represents that promise. We must activate the stone and let the Dragon Isles know that the black dragonflight has returned! Follow me, .",starts={{npcID=196265,x=0.264,y=0.586,zoneID=13644}},ends={{npcID=187045,x=0.272,y=0.626,zoneID=13644}},coords={x=0.264,y=0.586,source="quest_giver",zoneID=13644},questType="standard"},
[66055] = {id=66055,name="A Shattered Past",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The Oathstone is damaged! There are pieces missing. Do what you can to recover the fragments... maybe there is a way to fix the stone!",starts={{npcID=186493,x=0.246,y=0.61,zoneID=13644}},ends={{npcID=186493,x=0.246,y=0.61,zoneID=13644}},coords={x=0.246,y=0.61,source="quest_giver",zoneID=13644},questType="standard"},
[66056] = {id=66056,name="Forging a New Future",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The forge of the Earth-Warder is the most powerful of all the dragon forges in existence. Our ancestors used it to create the strongest weapons and armor to defend Azeroth. Within the hearth of that forge is the power necessary to reform the shattered fragments of the Oathstone. Let us go and prepare the forge for the work to be done.",starts={{npcID=186493,x=0.246,y=0.61,zoneID=13644}},ends={{npcID=186493,x=0.246,y=0.61,zoneID=13644}},coords={x=0.246,y=0.61,source="quest_giver",zoneID=13644},questType="standard"},
[66057] = {id=66057,name="Restoring the Faith",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The shattered fragments have been reformed. We are ready to repair the Oathstone. Go now and help Wrathion complete the repairs.",starts={{npcID=186493,x=0.246,y=0.61,zoneID=13644}},ends={{npcID=187495,x=0.244,y=0.556,zoneID=13644}},coords={x=0.246,y=0.61,source="quest_giver",zoneID=13644},questType="standard"},
[66071] = {id=66071,name="Flying Rocs",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The name is Professor Harleen Chirpsnide , infamous ornithologist extraordinaire! I came here to study the mythical bluefeather rocs of the Dragon Isles, but I suppose we've got bigger fowl to fry. I bet these harpies flew in from Kalimdor when the Isles opened up. They're highly invasive and feasting like a pack of ogres at the Bilgewater Casino buffet. Let's give the native rocs here a fighting chance. Take this medical kit and use it to get the injured ones back on their feet.",starts={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},ends={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},coords={x=0.5,y=0.698,source="quest_giver",zoneID=13647},questType="standard"},
[66074] = {id=66074,name="Primal Scythid Queen",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66078] = {id=66078,name="Sharp Practice",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="For years I have fostered the Blacktalon, teaching and encouraging them to pursue the same heights you have reached. They may not have achieved the same lofty goals as yourself, but they are accomplished in their own right. They've made me proud. Each would be honored if you test their skills. I think you will see some of yourself in them.",starts={{npcID=186274,x=0.424,y=0.668,zoneID=13644}},ends={{npcID=186274,x=0.424,y=0.668,zoneID=13644}},coords={x=0.424,y=0.668,source="quest_giver",zoneID=13644},questType="standard"},
[66079] = {id=66079,name="Wrathion Awaits",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="These eggs represent a new generation of dragonkind. They must be protected and fostered. Yet... my heart aches, and I worry for Wrathion . I fear his stubborn determination will lead to folly. You have been a trusted friend over the years, . Perhaps you can go in my place, and help him. Seek him out at the Obsidian Bulwark. And please, watch over him. There are so few of his flight left.",starts={{npcID=187115,x=0.46,y=0.782,zoneID=13644}},ends={{npcID=186274,x=0.424,y=0.668,zoneID=13644}},coords={x=0.46,y=0.782,source="quest_giver",zoneID=13644},questType="standard"},
[66080] = {id=66080,name="Temporal Difficulties",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Hello, . You're right on time! Some trouble up at the temple is causing the timeways to destabilize and spill out into the valley. Not only that, but a bunch of Timewalkers are missing! We've asked for extra help, but one of the new recruits hasn't arrived yet. Can you look for her? Be careful though, time's in a massive state of flux around the valley. There's no knowing what dangers are around!",starts={{npcID=187877,x=0.574,y=0.788,zoneID=13647}},ends={{npcID=187098,x=0.574,y=0.788,zoneID=13647}},coords={x=0.574,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[66081] = {id=66081,name="Time is Running Out",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="With the bronze temple under attack temporal energy is seeping out everywhere. The Timewalkers placed collectors all through this forest trying to gather all the errant magic. Anything collected can also be used as extra power! Which is a good thing, this crisis is draining all our resources. I was supposed to retrieve the collectors, but I still need a moment to catch my breath. Could you get them for me?",starts={{npcID=187098,x=0.574,y=0.788,zoneID=13647}},ends={{npcID=187098,x=0.574,y=0.788,zoneID=13647}},coords={x=0.574,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[66082] = {id=66082,name="Time in a Bottle",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Great! The Timewalker staff intact! But, it is definitely drained. I know! You can recharge it using the temporal energy coalescing around the wildlife here. Unfortunately, that means defeating affected creatures in the forest. The energies were making them dangerous and unstable, and we would have had to cull the population after anyhow... Sometimes you have to sacrifice for the greater good. Could you help? I still need a minute.",starts={{npcID=187098,x=0.574,y=0.788,zoneID=13647}},ends={{npcID=187098,x=0.574,y=0.788,zoneID=13647}},coords={x=0.574,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[66083] = {id=66083,name="Feels Like the First Time",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Shepherding the timeways is a dangerous duty. Though you are not a Timewalker, Ambassador Chronormu believes you will be of great help. But to ensure your safety we must properly train you. Unfortunately, all our instructors are still missing. I will do my best to help. Let us see how we both do. I know the Ambassador Chronormu is counting on the both of us.",starts={{npcID=187877,x=0.574,y=0.788,zoneID=13647}},ends={{npcID=187877,x=0.574,y=0.788,zoneID=13647}},coords={x=0.574,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[66084] = {id=66084,name="Times Like These",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Despite that small hiccup during training, I believe you are prepared enough to aid us here. The distortions in the valley are allowing different time periods to cross over into ours. We are unsure why these timelines connect which is quite alarming. We need more information. Please, see if you can find anything about the creatures pouring in from different timelines. I am sure their passage will have left some sort of residue. By studying it we can hopefully find a way to get ahead of this crisis.",starts={{npcID=187877,x=0.574,y=0.788,zoneID=13647}},ends={{npcID=187877,x=0.574,y=0.788,zoneID=13647}},coords={x=0.574,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[66085] = {id=66085,name="If We Could Turn Back Time",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="A proper Timewalker never leaves a crisis half-resolved. Why wait and study when we have the tools we need already? Since you have my original staff, I found a spare for me to use. I am sure no one will miss it. This is my plan: we team up on those rifts together and save the day! All the days, really. Sorry, I still get confused about the time stuff. What do you say? The task should be simple enough, right?",starts={{npcID=187098,x=0.574,y=0.788,zoneID=13647}},ends={{npcID=187098,x=0.574,y=0.788,zoneID=13647}},coords={x=0.574,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[66087] = {id=66087,name="Closing Time",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="These incursions push the durability of this timeline to the point of breaking. If only we had our full contingent of Timewalkers! Though you are a novice with the staff, I am told that you have managed to help us out greatly. With an extra push, I believe you may further aid our cause. Normally, I would put you through a full training but the times are... unorthodox. Take this scroll of advanced knowledge and use it to push back the invaders! Be swift though, the effects are only temporary.",starts={{npcID=190929,x=0.574,y=0.788,zoneID=13647}},ends={{npcID=190929,x=0.574,y=0.788,zoneID=13647}},coords={x=0.574,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[66090] = {id=66090,name="Path of the Dark Rangers",level=50,requiredLevel=50,faction="alliance",expansion=9,zoneID=13983,starts={{npcID=185851,x=0.618,y=0.678,zoneID=13983}},ends={{npcID=185851,x=0.618,y=0.678,zoneID=13983}},coords={x=0.618,y=0.678,source="quest_giver",zoneID=13983},questType="standard"},
[66091] = {id=66091,name="Path of the Dark Rangers",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=13983,mapID=2070,starts={{npcID=185851,x=0.618,y=0.678,mapID=2070}},ends={{npcID=185851,x=0.618,y=0.678,mapID=2070}},coords={x=0.618,y=0.678,source="quest_giver",mapID=2070},questType="standard"},
[66094] = {id=66094,name="The Ruins of Szar Skeleth",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="According to the watcher's logs, the stone of Insight can be found in a draconic tower on a river in the center of the Ohn'ahran Plains. That should be Szar Skeleth. Be careful. We can be sure the Sundered Flame won't let us just walk in and take it. Once you get there, rendezvous with Toddy. Then we can retrieve the stone.",starts={{npcID=186870,x=0.544,y=0.556,zoneID=13647}},ends={{npcID=191159,x=0.4,y=0.674,zoneID=13645}},coords={x=0.544,y=0.556,source="quest_giver",zoneID=13647},questType="standard"},
[66100] = {id=66100,name="Supplying in Weight",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="I really screwed up this time. I only stepped away from the campsite for a moment, but I barely returned in time to see the tarasek snatching up everything I had not bolted down. Those supplies were expensive, and I can't exactly ask for help getting more! My sister Nori thinks I'm inept enough as it is. If you are sure you want to head through the valley, would you mind keeping an eye out for any stray bags of supplies?",starts={{npcID=191753,x=0.546,y=0.694,zoneID=13647}},ends={{npcID=187289,x=0.546,y=0.694,zoneID=13647},{npcID=191753,x=0.546,y=0.694,zoneID=13647}},coords={x=0.546,y=0.694,source="quest_giver",zoneID=13647},questType="standard"},
[66101] = {id=66101,name="From Such Great Heights",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Toddy and Naleidea have requested a survey report of the surrounding area immediately. Luckily, I have acquired an enchanted telescope and surveyor's disc that will help us scout out nearby areas from the safety of the clouds. Unluckily, I am deathly afraid of heights and cannot bring myself to set foot on the contraption. You are not afraid of heights, are you?",starts={{npcID=187257,x=0.758,y=0.334,zoneID=13644}},ends={{npcID=187257,x=0.758,y=0.334,zoneID=13644}},coords={x=0.758,y=0.334,source="quest_giver",zoneID=13644},questType="standard"},
[66103] = {id=66103,name="Eager to Please",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="We need more troops to defend the Obsidian Citadel. Now that we've got a foothold, it's important to make sure we've got fresh eyes and bodies for the effort. We have additional reserve troops at the Obsidian Bulwark that could reinforce us. They are well trained, but they'd benefit from a combat test with someone as skilled and experienced as you. So we know they're ready.",starts={{npcID=190899,x=0.266,y=0.624,zoneID=13644}},ends={{npcID=186331,x=0.424,y=0.662,zoneID=13644}},coords={x=0.266,y=0.624,source="quest_giver",zoneID=13644},questType="standard"},
[66104] = {id=66104,name="Forensic Ecology",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I'm at my wits end, . Tharu and I have made our way through nearly all the corpses only to stumble at the end because we cannot agree on a methodology. If only he would just listen to me! Ecologist Iskha sighs.> The stress of the situation is getting to us both. I don't even have a firm hypothesis yet. You look like you have a strong stomach. Will you take over on these last two gorlocs? You can borrow my scalpel.",starts={{npcID=186410,x=0.744,y=0.42,zoneID=13644}},ends={{npcID=186410,x=0.744,y=0.42,zoneID=13644}},coords={x=0.744,y=0.42,source="quest_giver",zoneID=13644},questType="standard"},
[66105] = {id=66105,name="A Scalpel of a Solution",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I believe we are gathering enough data safely from here but... Tharu is an exceptional ecologist and prefers we take action. Still, the ecosystem is fragile, and we may damage it if we are not careful. I do however agree we don't have much time. It might be worth indulging him. A little. Culling the rampaging elementals ought to buy us time without impeding our research. Be sure to cull them in equal numbers--we don't want to throw things further out of balance.",starts={{npcID=186410,x=0.744,y=0.42,zoneID=13644}},ends={{npcID=186410,x=0.744,y=0.42,zoneID=13644}},coords={x=0.744,y=0.42,source="quest_giver",zoneID=13644},questType="standard"},
[66106] = {id=66106,name="Don't Be So Shellfish",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I was a fool to doubt Iskha when he insisted there was more to this. He wouldn't be my mate if he wasn't always two steps ahead of me. We can make it up to him--by taking action, of course. If it's shells that are causing all this elemental chaos, why don't you go into their camp and take those shells right out of their slimy hands? Bring back piles of the wind and water shells, enough for Iskha to research to his heart's content.",starts={{npcID=186428,x=0.744,y=0.42,zoneID=13644}},ends={{npcID=186428,x=0.744,y=0.42,zoneID=13644}},coords={x=0.744,y=0.42,source="quest_giver",zoneID=13644},questType="standard"},
[66107] = {id=66107,name="Wildlife Rescue",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="It doesn't take an ecologist to see that the wetlands are in real trouble. But Iskha's got us stuck here examining dead creatures when we ought to be stopping them from dying in the first place! The red dragonflight is about preserving life--not dissecting it! I love Iskha, and he's good at what he does, but if we wait until he's done puttering, there won't be any wetlands left to save. I'll manage his overthinking. You get out there, get your boots muddy, and rescue some wildlife.",starts={{npcID=186428,x=0.744,y=0.42,zoneID=13644}},ends={{npcID=186428,x=0.744,y=0.42,zoneID=13644}},coords={x=0.744,y=0.42,source="quest_giver",zoneID=13644},questType="standard"},
[66108] = {id=66108,name="A Sledgehammer of a Solution",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="While I'm glad Tharu now sees my point of view, I'm also grateful he had you rescue wildlife while I was dawdling. The situation is much more dire than anticipated; he was right to take action. With what we've learned, I fear this elemental bombardment won't stop until we've dealt with the gorlocs. If I were Tharu and thinking actionably, I would go straight for their leaders. Without anyone to rally around, the fighting should dissipate and no longer threaten the wetlands.",starts={{npcID=186410,x=0.744,y=0.42,zoneID=13644}},ends={{npcID=186410,x=0.744,y=0.42,zoneID=13644}},coords={x=0.744,y=0.42,source="quest_giver",zoneID=13644},questType="standard"},
[66110] = {id=66110,name="Give Peace a Chance",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=13644,description="Aka'Magosh, $p. This expedition is under the protection of both the Horde and the Alliance. Our instructions are clear: give aid to any members of the Dragonscale Expedition regardless of their other allegiances. The Alliance's representatives, Captain Garrick and her son Henry, stand guard on the other side of camp. I fought with Captain Garrick against the scourge. She is honorable and will serve the Expedition well. Go offer her your assistance. Show her that the Horde honors its agreements.",starts={{npcID=184452,x=0.762,y=0.33,zoneID=13644}},ends={{npcID=184449,x=0.766,y=0.344,zoneID=13644}},coords={x=0.762,y=0.33,source="quest_giver",zoneID=13644},questType="standard"},
[66111] = {id=66111,name="Encroaching Elementals",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=13644,description="The crafters, artisans, and explorers of the Dragonscale Expedition are ill-suited to the vigors of battle. But not you and I, $p. Here in the Dragon Isles, let us use that strength to protect those who can't protect themselves. Clear out the elementals encroaching from the north, so the expedition can focus on their noble pursuits.",starts={{npcID=184449,x=0.766,y=0.344,zoneID=13644}},ends={{npcID=184449,x=0.766,y=0.344,zoneID=13644}},coords={x=0.766,y=0.344,source="quest_giver",zoneID=13644},questType="standard"},
[66112] = {id=66112,name="Always Be Crafting",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Have ye ever seen such powerful elementals?! I hear the guards grumblin' 'bout havin' to fight 'em all the time, but they're missin' the big picture... Bigger elementals means bigger craftin' components! While you're out there clearin' the elementals for our safety or whate'er it is ye be doin', be sure to pick up pieces of the biggest ones ye can find. I want tae try makin' somethin' out of 'em!",starts={{npcID=187261,x=0.764,y=0.344,zoneID=13644}},ends={{npcID=187261,x=0.764,y=0.344,zoneID=13644}},coords={x=0.764,y=0.344,source="quest_giver",zoneID=13644},questType="standard"},
[66114] = {id=66114,name="For the Benefit of the Queen",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="We safeguard our precious eggs to protect the future of all dragonflights. The Primalists do not simply threaten pain or anguish with their actions. They threaten us with extinction. I must inform our queen at once.",starts={{npcID=186795,x=0.55,y=0.31,zoneID=13644}},ends={{npcID=187290,x=0.622,y=0.73,zoneID=13644}},coords={x=0.55,y=0.31,source="quest_giver",zoneID=13644},questType="standard"},
[66115] = {id=66115,name="The Mandate of the Red",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Our calling is care and compassion. We aid the other flights not only for their own sake, but for the sake of dragonkind as a whole. Perhaps speaking with the dragonspawn here at the Ruby Lifeshrine will help you understand us further.",starts={{npcID=187290,x=0.622,y=0.73,zoneID=13644}},ends={{npcID=189260,x=0.626,y=0.704,zoneID=13644}},coords={x=0.622,y=0.73,source="quest_giver",zoneID=13644},questType="standard"},
[66116] = {id=66116,name="The Primary Threat",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14795,description="There are far too many vulnerable eggs to secure. If the enemy breaks through, all is lost! I am sure our guards are mustering on the field to push them back. Speak to Commander Lethanak , and he will use your strength where it will be most helpful.",starts={{npcID=190293,x=0.594,y=0.726,zoneID=13644}},ends={{npcID=187119,x=0.594,y=0.758,zoneID=13644}},coords={x=0.594,y=0.726,source="quest_giver",zoneID=13644},questType="standard"},
[66118] = {id=66118,name="Basalt Assault",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Raszageth and her Primalists have summoned towering earth elementals to break our walls. They must be stopped!",starts={{npcID=187119,x=0.594,y=0.758,zoneID=13644}},ends={{npcID=187119,x=0.594,y=0.758,zoneID=13644}},coords={x=0.594,y=0.758,source="quest_giver",zoneID=13644},questType="standard"},
[66119] = {id=66119,name="Ruby Life Pools: Primalist Invasion",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14063,description="The Primalists have torn their way into our home. We were not prepared for such an intense attack... several got through. One of our drakonid ventured in to follow them, but he has not reported his findings. I fear the worst. I will stand guard. No more shall breach our walls while we draw breath, but you must stop those who made it inside. Go!",starts={{npcID=187145,x=0.598,y=0.76,zoneID=13644},{npcID=205775,zoneID=14063}},ends={{npcID=187145,x=0.598,y=0.76,zoneID=13644},{npcID=205775,zoneID=14063}},coords={x=0.598,y=0.76,source="quest_giver",zoneID=13644},questType="dungeon"},
[66121] = {id=66121,name="Egg Evac",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The Primalists have stolen our eggs for their perverse rituals! They must be stopped. Help us recover our eggs before it is too late. Mark each egg as you find them, $p. I will ensure they are safely extracted from the area.",starts={{npcID=187129,x=0.594,y=0.76,zoneID=13644}},ends={{npcID=191895,x=0.536,y=0.802,zoneID=13644}},coords={x=0.594,y=0.76,source="quest_giver",zoneID=13644},questType="standard"},
[66122] = {id=66122,name="Proto-Fight",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="These proto-dragons detest us. They believe we are a twisted version of dragonkind that is manipulated and chained by the Titans. They do not understand. Which is why they feel safe even as they throw their forces at our walls. They are mistaken. Take this spear, $p. Kill our enemies.",starts={{npcID=187119,x=0.594,y=0.758,zoneID=13644}},ends={{npcID=187129,x=0.594,y=0.76,zoneID=13644},{npcID=191895,x=0.536,y=0.802,zoneID=13644}},coords={x=0.594,y=0.758,source="quest_giver",zoneID=13644},questType="standard"},
[66123] = {id=66123,name="Cut Off the Head",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Jadzigeth , one of Raszageth's foul lieutenants, proudly leads the Primalists here. Let us show them all what happens to those who stand against us.",starts={{npcID=191895,x=0.536,y=0.802,zoneID=13644}},ends={{npcID=191895,x=0.536,y=0.802,zoneID=13644}},coords={x=0.536,y=0.802,source="quest_giver",zoneID=13644},questType="standard"},
[66124] = {id=66124,name="Exeunt, Triumphant",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="From what I saw, the queen fell back to the Wild Hatchery. It is an outpost to keep watch over the proto-drakes in the area... I only hope that its defenses are enough. We must head there at once!",starts={{npcID=191895,x=0.536,y=0.802,zoneID=13644}},ends={{npcID=187278,x=0.462,y=0.784,zoneID=13644}},coords={x=0.536,y=0.802,source="quest_giver",zoneID=13644},questType="standard"},
[66126] = {id=66126,name="Unlocking Our Past",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Bring me an assembled Key",ends={{npcID=187272,x=0.248,y=0.61,zoneID=13644}},questType="standard"},
[66128] = {id=66128,name="Next Steps",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="These stones are an incredible discovery, even if their intended use is never realized. But before we try them out, we have a process to adhere to. They must be examined and cataloged, and reports sent and received to both the Reliquary and Explorers' League headquarters. Let's meet back at basecamp. We can go over what's next.",starts={{npcID=190865,x=0.644,y=0.15,zoneID=13647},{npcID=191159,x=0.4,y=0.674,zoneID=13645},{npcID=193350,x=0.538,y=0.506,zoneID=13646}},ends={{npcID=187276,x=0.472,y=0.826,zoneID=13644}},coords={x=0.644,y=0.15,source="quest_giver",zoneID=13647},questType="standard"},
[66129] = {id=66129,name="Unlocking Our Past",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,description="Bring me an assembled Key",ends={{npcID=187275,x=0.322,y=0.524,zoneID=13644}},questType="standard"},
[66130] = {id=66130,name="Unlocking Our Past",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Bring me an assembled Key",ends={{npcID=187284,x=0.268,y=0.624,zoneID=13644}},questType="standard"},
[66131] = {id=66131,name="Unlocking Our Past",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Bring me an assembled Key",ends={{npcID=187447,x=0.276,y=0.564,zoneID=13644}},questType="standard"},
[66134] = {id=66134,name="Azeroth Pest Control",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="You there! Hatchling! Lend me a hand, won't you? These podlings are ripping up all my plants! All kinds of elementals have invaded the gardens, and they seem to be... affecting the wildlife. It's like their energy has driven these podlings mad! More mad than usual! I've got my hands full with just these three. Please! Before they rip up all my flower beds.",starts={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},ends={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},coords={x=0.378,y=0.754,source="quest_giver",zoneID=13647},questType="standard"},
[66135] = {id=66135,name="The Gardener's Apprentice",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Basilton! Lord Basilton, where are you? My executive assistant and apprentice, Lord Basilton, has gone missing! He loves to explore, but he's even worse at defending himself than I am. I'm a gardener, not a warrior! Could you please go find that layabout? I need him here so I can think. He's usually in the shed, digging through piles of junk. Be careful though. He can be a bit prickly at first.",starts={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},ends={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},coords={x=0.378,y=0.754,source="quest_giver",zoneID=13647},questType="standard"},
[66136] = {id=66136,name="Elemental Extract",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="A huge fire elemental destroyed the pond a few days ago. I think it's behind all this ruckus, but it's too big to fight. We need to weaken it somehow. But don't count Old Gryrmpech out just yet, I have a plan! Water elementals decided to make themselves at home in the Blue flight's gazebo. If you can collect enough essence from them, we might be able to use their magic against them. Fight fire with fire, right? Well, fight fire with water, I guess. Anyway, you should probably get going.",starts={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},ends={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},coords={x=0.378,y=0.754,source="quest_giver",zoneID=13647},questType="standard"},
[66137] = {id=66137,name="Lashing Out",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="I'm sure the podlings aren't the only wildlife acting like hooligans. Alexstrasza's tree has always been a thorn in my side. Her life magic draws all sorts of plants and animals to it, good and bad. And guess who has to take care of the bad ones? Old Gryrmpech , that's who! Aspects above, I'm getting too old for this. The stewards aren't trained in combat, so it is up to you to take care of the Life-Binder's weed problem.",starts={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},ends={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},coords={x=0.378,y=0.754,source="quest_giver",zoneID=13647},questType="standard"},
[66138] = {id=66138,name="Like Sands Through the Hourglass",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Like the rest of the gardens, Nozdormu's hourglass has had to weather the elemental unrest. Turbulent wind elementals came through and scattered the magical sand contained within. Without this sand, Nozdormu's influence here is greatly diminished. As a steward-in-training, I have been tasked with overseeing the hourglass at all times. If you would collect the sand in my stead, I would be eternally grateful.",starts={{npcID=187310,x=0.352,y=0.726,zoneID=13647}},ends={{npcID=187310,x=0.352,y=0.726,zoneID=13647}},coords={x=0.352,y=0.726,source="quest_giver",zoneID=13647},questType="standard"},
[66139] = {id=66139,name="Flame at Last",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Alright, youngling, I've placed all the water elemental essences in this jar for you. If you just toss it at the big one, it should work. I mean, when has water not worked against fire? It's foolproof. The heat, uh, isn't good for my joints, so I'll just stay here. I trust you can handle it. Good luck, young one!",starts={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},ends={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},coords={x=0.378,y=0.754,source="quest_giver",zoneID=13647},questType="standard"},
[66141] = {id=66141,name="Broken Traditions, Broken Bodies",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="My fellow furbolg are no longer themselves. They have done... bad things. Now, they have become worse things. Furbolg has never fought furbolg! My brother and I escaped them. I came here looking for help. He remains by our clan's den. Help us before our clan is lost!",starts={{npcID=187301,x=0.632,y=0.586,zoneID=13646}},ends={{npcID=187308,x=0.634,y=0.53,zoneID=13646}},coords={x=0.632,y=0.586,source="quest_giver",zoneID=13646},questType="standard"},
[66147] = {id=66147,name="Crystals in the Water",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We might not look it this moment, but we are professionals. The Expedition entrusted us with finding a clutch of rare crystals in the area--a geological survey if you will. I'm still collecting myself after the gorloc attack. Would you be a dear and go look for these crystals? Bring samples back if you can.",starts={{npcID=187156,x=0.076,y=0.442,zoneID=13646}},ends={{npcID=187156,x=0.076,y=0.442,zoneID=13646}},coords={x=0.076,y=0.442,source="quest_giver",zoneID=13646},questType="standard"},
[66148] = {id=66148,name="Former Furbolg Family",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Primalists came. They offered us new strength: the command of the elements. I did not think Stoneheart would accept their gifts. Our clan did not need power. He thought nothing of the cost. His terrible decision cannot be unmade. The magic has corrupted my clan--like disease rots a root. My heart breaks, but culling the corrupted is the only way.",starts={{npcID=187308,x=0.634,y=0.53,zoneID=13646}},ends={{npcID=187534,x=0.608,y=0.504,zoneID=13646}},coords={x=0.634,y=0.53,source="quest_giver",zoneID=13646},questType="standard"},
[66149] = {id=66149,name="Elemental Influence",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Narn says not all the Rustpines followed Stoneheart or the Primalists. Some resisters are held against their will. Totems spewing rock and mud restrain them... to force them to obey. Shatter the totems. Set them free!",starts={{npcID=187308,x=0.634,y=0.53,zoneID=13646}},ends={{npcID=187534,x=0.608,y=0.504,zoneID=13646}},coords={x=0.634,y=0.53,source="quest_giver",zoneID=13646},questType="standard"},
[66150] = {id=66150,name="Rescuing Radza",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Radza Thunderclaw is our Spiritkeeper. She holds true our traditions and history. Primalist beliefs go against everything our clan holds true. I knew she would defy Stoneheart! Stoneheart will do anything to bring her to heel. No one is chieftain without Radza's blessing! Narn says Khargall Fivefangs , the Chieftain's guard, is trying to break her. If Radza dies, our clan dies with her. Go aid her, , and be ready. He will not let her go without a fight.",starts={{npcID=187308,x=0.634,y=0.53,zoneID=13646}},ends={{npcID=187616,x=0.608,y=0.504,zoneID=13646}},coords={x=0.634,y=0.53,source="quest_giver",zoneID=13646},questType="standard"},
[66151] = {id=66151,name="His Stone Heart",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We howl with grief for our chieftain, yet he lives. What remains of Stoneheart is in the cave ahead. Many tried to reason with him. He killed them--and almost killed Narn. He is a monster! This is the goal of the primalists. They would turn us into stone and flame to serve them. There is no Rustpine left in him. He must be destroyed before others meet the same fate.",starts={{npcID=187616,x=0.608,y=0.504,zoneID=13646}},ends={{npcID=187616,x=0.608,y=0.504,zoneID=13646}},coords={x=0.608,y=0.504,source="quest_giver",zoneID=13646},questType="standard"},
[66152] = {id=66152,name="Nowhere to Go",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We cannot stay here. I do not know what to do... where to go next... We will return to your Camp Nowhere. The tuskarr should know what happened at Rustpine. If we tell our story and keep it, maybe it will not happen again...",starts={{npcID=187535,x=0.61,y=0.504,zoneID=13646}},ends={{npcID=188897,x=0.632,y=0.586,zoneID=13646}},coords={x=0.61,y=0.504,source="quest_giver",zoneID=13646},questType="standard"},
[66154] = {id=66154,name="Salivatory Samples",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="This is going to reflect very poorly on my record. Somehow in a single day we've managed to stir up the local gorlocs, lose half of our equipment, and are now down a dwarf. In this situation, protocol dictates that we be as efficient as possible. Go thin out some of our toothy antagonists and bring me their saliva for further testing while you're at it. Only the good stuff, mind you.",starts={{npcID=187136,x=0.076,y=0.442,zoneID=13646}},ends={{npcID=187136,x=0.076,y=0.442,zoneID=13646}},coords={x=0.076,y=0.442,source="quest_giver",zoneID=13646},questType="standard"},
[66155] = {id=66155,name="Ruriq's River Rapids Ride",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I did not expect my brother's approval... but it is welcome, all the same. The time has come! Let's see if our hard work has paid off! Join me in The Fallstrider, , and we shall take off down the river, catching fish for Iskaara as we go!",starts={{npcID=186157,x=0.448,y=0.506,zoneID=13646}},ends={{npcID=186157,x=0.448,y=0.506,zoneID=13646},{npcID=190287,x=0.342,y=0.524,zoneID=13646}},coords={x=0.448,y=0.506,source="quest_giver",zoneID=13646},questType="standard"},
[66156] = {id=66156,name="Renowned with the Dragonscale Expedition",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13644,description="Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer! Return to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.",ends={{npcID=189226,x=0.47,y=0.826,zoneID=13644}},questType="standard"},
[66159] = {id=66159,name="A Message Most Dire",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Kalecgos would not speak of what happened in the Azure Span till you arrived. Whatever he has to share gives me a terrible sense of foreboding, .",starts={{npcID=187678,x=0.58,y=0.358,zoneID=13862}},ends={{npcID=187678,x=0.58,y=0.358,zoneID=13862}},coords={x=0.58,y=0.358,source="quest_giver",zoneID=13862},questType="standard"},
[66163] = {id=66163,name="Nowhere to Hide",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Welcome to Valdrakken, . The climate in the city has been a bit warm of late, and I do not mean the weather. The Primalists are skulking about, fomenting dissent among the citizens of our city. Our foes are crafty. They have been disguising themselves as citizens of our city to hide from the Scalesworn. They know how to avoid my guards but will not suspect an outsider. Take this Dragon's Eye gem, it should help you see through their disguises. Go reveal and kill these infiltrators!",starts={{npcID=189842,x=0.56,y=0.402,zoneID=13862}},ends={{npcID=189842,x=0.56,y=0.402,zoneID=13862}},coords={x=0.56,y=0.402,source="quest_giver",zoneID=13862},questType="standard"},
[66164] = {id=66164,name="Fishy Fingers",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Now that Mordigan's off licking rocks, we can get to the crux of the problem... Those perfidious fishmen have pilfered my parts! We weren't in this dinky little village for more than an hour and WHAM! Gorloc were swarming all over us! Rowe was yelling, Aelnara was screaming, and I'm flailing around with my wrench like a madgnome! See if you can't salvage the situation and get some of my parts back!",starts={{npcID=187198,x=0.076,y=0.442,zoneID=13646}},ends={{npcID=187198,x=0.076,y=0.442,zoneID=13646}},coords={x=0.076,y=0.442,source="quest_giver",zoneID=13646},questType="standard"},
[66166] = {id=66166,name="Eyes and Ears",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="The Primalists have been spewing their propaganda among the citizens of Valdrakken. Our enemies are too wily to say anything in the presence of my Scalesworn, but perhaps you might be able to get close enough to eavesdrop on their conversations. I have marked locations on your map for further investigation. You may want to visit the Transmogrifier to see about changing your look to avoid any suspicion. Take this enchanted stone, as long as you have it on hand we will be able to communicate.",starts={{npcID=189842,x=0.56,y=0.402,zoneID=13862}},ends={{npcID=189842,x=0.56,y=0.402,zoneID=13862}},coords={x=0.56,y=0.402,source="quest_giver",zoneID=13862},questType="standard"},
[66167] = {id=66167,name="Southern Exposure",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Based on your discoveries I suspect the Primalists are attacking Commander Eranog's Garrison at South Hold. But, my Scalesworn cannot leave the city as that would be exactly what the Primalists are hoping for. I need your help again, . Travel to South Hold, see what kind of forces we are facing, and if possible make contact with the garrison guardians there.",starts={{npcID=189842,x=0.56,y=0.402,zoneID=13862}},ends={{npcID=190180,x=0.376,y=0.83,zoneID=13647}},coords={x=0.56,y=0.402,source="quest_giver",zoneID=13862},questType="standard"},
[66169] = {id=66169,name="Vengeance, Served Hot",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The Primalists caught us completely unawares. My fellow guardians were ripped apart by these monsters. I would have joined them in death if you had not shown up when you did. Off in the distance I can still hear the sounds of battle. Perhaps others still live, maybe even Commander Eranog. Lend me your aid. I need you to cause a distraction so I can sneak to a position closer in. Killing a few of these so called \"Magmasworn\" would be perfect.",starts={{npcID=190180,x=0.376,y=0.83,zoneID=13647}},ends={{npcID=190180,x=0.376,y=0.83,zoneID=13647}},coords={x=0.376,y=0.83,source="quest_giver",zoneID=13647},questType="standard"},
[66170] = {id=66170,name="Silent Vigil",level=60,requiredLevel=60,faction="alliance",expansion=9,zoneID=10565,description="Dori'thur hovers silently, peering at you with keen, expectant eyes. Perhaps the noble owl wishes you to see something of import.>",questType="standard"},
[66173] = {id=66173,name="Hall of Samples",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="Did you hear what that console said? There's a hall full of samples. Ancient titan machinery? Specimens from other worlds? Only Tyr knows what's in there! Let's change that.",starts={{npcID=192820,x=0.55,y=0.562,zoneID=13647}},ends={{npcID=193374,x=0.572,y=0.526,zoneID=13647}},coords={x=0.55,y=0.562,source="quest_giver",zoneID=13647},questType="standard"},
[66174] = {id=66174,name="Hall of the Aspects",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="The Hall of the Aspects, eh? Why would Tyr seal something like this away? Was he hidin' something? The implications are staggering--hopefully we'll find some answers in there.",starts={{npcID=192820,x=0.55,y=0.562,zoneID=13647}},coords={x=0.55,y=0.562,source="quest_giver",zoneID=13647},questType="standard"},
[66175] = {id=66175,name="Field Experiment",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Thanks to you, our geological survey is now operating at nearly 96% efficiency! Those are rookie numbers. Help me run the samples you collected through my Geoscanner 289-07 . It should give us a baseline as to what exactly is going on at the plateau.",starts={{npcID=187198,x=0.076,y=0.442,zoneID=13646}},ends={{npcID=187198,x=0.076,y=0.442,zoneID=13646}},coords={x=0.076,y=0.442,source="quest_giver",zoneID=13646},questType="standard"},
[66176] = {id=66176,name="Elemental Experimentation",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="Go conduct experiments on the water elementals harassing the gorlocs!",questType="standard"},
[66177] = {id=66177,name="No Dwarf Left Behind",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The salt levels here are off the charts! We need to find Mordigan and get him out of there. He must be dangerously dehydrated by now. He's only been gone a couple hours. See if you can't determine which path the grumpy old dwarf took!",starts={{npcID=187198,x=0.076,y=0.442,zoneID=13646}},ends={{npcID=188030,x=0.108,y=0.412,zoneID=13646}},coords={x=0.076,y=0.442,source="quest_giver",zoneID=13646},questType="standard"},
[66178] = {id=66178,name="A Day in the Groves",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="Rymek was sent here by the blue flight to learn about and protect our gardens. I am glad for their support. We are few in number, and our losses have been great. The blue dragonflight commands powerful magic, so we can learn a great deal from each other. Come. Let us demonstrate the green dragonflight's important role here in the Dragon Isles.",starts={{npcID=186955,x=0.298,y=0.6,zoneID=13645}},ends={{npcID=187525,x=0.332,y=0.518,zoneID=13645}},coords={x=0.298,y=0.6,source="quest_giver",zoneID=13645},questType="standard"},
[66179] = {id=66179,name="Seeds for the Future",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="The Primalists' attack left its mark on the Emerald Gardens. I wish to see it grow and flower once again. In this part of the garden, we have an overabundance of lashers. Their seeds can be used by the Sisters of the Garden to cultivate vegetation in those damaged glades. Thin out the lashers to collect their seeds, and then give those seeds to the Sisters. They sometimes struggle to inflict harm on any creature, even when it is in the best interest of the gardens overall.",starts={{npcID=187525,x=0.332,y=0.518,zoneID=13645}},ends={{npcID=187525,x=0.332,y=0.518,zoneID=13645}},coords={x=0.332,y=0.518,source="quest_giver",zoneID=13645},questType="standard"},
[66180] = {id=66180,name="Wake the Ancients",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="There are many ways to keep the gardens safe, and we have allies to help us. A few Ancients rest dormant in these glades. They are giant trees sworn to defend the forest and the creatures within. Use this fragment of my breath to wake them.",starts={{npcID=187525,x=0.332,y=0.518,zoneID=13645}},ends={{npcID=187525,x=0.332,y=0.518,zoneID=13645}},coords={x=0.332,y=0.518,source="quest_giver",zoneID=13645},questType="standard"},
[66181] = {id=66181,name="A Frenzied Defender",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="I have noticed that these gardens have rather diverse defenses, from the dragons to the drakonid and ancients... and even the wildlife! But there is one defender that seems to have become rather too zealous in its protectiveness. It even tried to swoop at me when I arrived! And since we know something has been killing within these groves, it cannot hurt to be too cautious. Unfortunately, this creature must be slain before it can do more damage.",starts={{npcID=189850,x=0.284,y=0.486,zoneID=13645}},ends={{npcID=189850,x=0.284,y=0.486,zoneID=13645}},coords={x=0.284,y=0.486,source="quest_giver",zoneID=13645},questType="standard"},
[66182] = {id=66182,name="Gerithus's Research",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="The green dragonflight has many duties, not solely in the tending of the garden. We also defend the Emerald Dream, and some extend their attention even further. My son Gerithus , for example, has always had interest in all kinds of magic. You and Rymek should seek him out, to see what he is working on and help where you can.",starts={{npcID=187525,x=0.332,y=0.518,zoneID=13645}},ends={{npcID=189849,x=0.284,y=0.486,zoneID=13645}},coords={x=0.332,y=0.518,source="quest_giver",zoneID=13645},questType="standard"},
[66183] = {id=66183,name="Emerald Tears",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="We may've only recently returned to the Emerald Gardens, relatively speaking, but we carry our long-lasting feelings with us. Many of us are still reeling from the death of Ysera, my grandmother. Including myself. I wish I had gotten to spend more time with her and to learn more from her. What amazing things she's seen in her life! In places like the Emerald Gardens, when we shed tears, they can crystalize and carry great power within them. I have an idea for how this galvanized grief could help us.",starts={{npcID=189849,x=0.284,y=0.486,zoneID=13645}},ends={{npcID=189849,x=0.284,y=0.486,zoneID=13645}},coords={x=0.284,y=0.486,source="quest_giver",zoneID=13645},questType="standard"},
[66184] = {id=66184,name="Anchors to Life",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="Based on my research, I believe there's a way to reestablish Ysera's ties to the Emerald Dream, so we can bring her closer to Azeroth. When Ysera died, the Winter Queen used her own power to restore her in Ardenweald. For now, she's bound there, but I think if we can just get Ysera over into the Emerald Dream, we can use these anchors to keep her there. But I'm getting ahead of everything. First, we have to infuse these anchors with the power of those Emerald Tears.",starts={{npcID=189849,x=0.284,y=0.486,zoneID=13645}},ends={{npcID=189849,x=0.284,y=0.486,zoneID=13645}},coords={x=0.284,y=0.486,source="quest_giver",zoneID=13645},questType="standard"},
[66185] = {id=66185,name="Across the Weald",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=11510,description="It is time. I know I said that I was fine, but ever since Solethus' death, it's like I've been missing something essential. I am alive, and he is not. That feels... wrong. But there might be a way I can set things right. Ysera is the only one who can help us get control of Ancient Bough again. I think I can help bring her back. It's getting harder and harder to cross over. We need to make this count. Tyrande and Malfurion will meet us there.",starts={{npcID=187594,x=0.284,y=0.58,zoneID=13645}},ends={{npcID=187634,x=0.458,y=0.608,zoneID=11510}},coords={x=0.284,y=0.58,source="quest_giver",zoneID=13645},questType="standard"},
[66186] = {id=66186,name="The Price",level=36,requiredLevel=36,faction="alliance",expansion=9,zoneID=11510,description="I am eager to return to the Emerald Dream and defend the gardens from the Incarnates and their followers. But I cannot leave Ardenweald yet, not with my bond to the Winter Queen. I dare not ask anyone to do this, unless they accept the consequences. As I did. But there is one who could take my place.",starts={{npcID=187634,x=0.458,y=0.608,zoneID=11510}},ends={{npcID=187636,x=0.458,y=0.608,zoneID=11510}},coords={x=0.458,y=0.608,source="quest_giver",zoneID=11510},questType="standard"},
[66187] = {id=66187,name="Mad Mordigan & The Crystal King",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I've scouted the perimeter. If Mordigan's anywhere, he's inside this cave. He's definitely inside this cave. LOU-C said these crystals have dangerous dehydrating properties. See if you can't separate him from his... geological finds. And try not to hurt him too much. He's fairly respected in his field.",starts={{npcID=188030,x=0.108,y=0.412,zoneID=13646}},ends={{npcID=188030,x=0.108,y=0.412,zoneID=13646}},coords={x=0.108,y=0.412,source="quest_giver",zoneID=13646},questType="standard"},
[66188] = {id=66188,name="Storm's Rest",level=36,requiredLevel=36,faction="alliance",expansion=9,zoneID=11510,description="Let us go into the Grove of Awakening. The Winter Queen is the only one who can transfer this bond from Ysera to me. I have faith that she will agree. She aided Ysera in a time of desperate need, and now Ysera can help us in turn. If the Winter Queen agrees, I expect that I will not be able to remain awake for long. The weight of the bond will be heavy to bear. In time, I hope that I may wake again and gaze upon the fully grown might of the new tree.",starts={{npcID=187636,x=0.458,y=0.608,zoneID=11510}},ends={{npcID=188348,x=0.452,y=0.636,zoneID=11510}},coords={x=0.458,y=0.608,source="quest_giver",zoneID=11510},questType="standard"},
[66189] = {id=66189,name="Step Into the Life",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="We mustn't delay. I can feel the energies of rebirth surging in me. I am ready to cross back into the Emerald Dream. From the realms of Death into Life. Follow me through the gate of Awakening, and we will race across the Dreamway to Ancient Bough. I expect there will be some resistance within, so be on your guard.",starts={{npcID=188348,x=0.452,y=0.636,zoneID=11510}},ends={{npcID=187646,x=0.186,y=0.518,zoneID=13645},{npcID=207216,x=0.188,y=0.516,zoneID=13645}},coords={x=0.452,y=0.636,source="quest_giver",zoneID=11510},questType="standard"},
[66190] = {id=66190,name="So Close",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,mapID=2023,description="I must take a moment to thank you, , for all your help. Truly, I never thought I would have a chance to admire the Dream within Ancient Bough! Not as a humble emissary! How very kind. Lord Somnikus has graciously invited me to set foot inside the grove and see the portal. I would be honored if you would join me. I will remember this moment for the rest of my life. Share it with me.",starts={{npcID=189857,x=0.22,y=0.508,mapID=2023}},ends={{npcID=187561,x=0.22,y=0.492,mapID=2023}},coords={x=0.22,y=0.508,source="quest_giver",mapID=2023},questType="standard"},
[66191] = {id=66191,name="And Yet So Far",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="I cannot slip into the Dream here as I once did. With the bough defenses activated, we are essentially blocked from the grove. But I'm afraid it only gets worse, . I believe Rymek did not merely trick us to gain access to the Dream. I suspect he is looking for something within it... something precious and powerful that I swore to protect. Not even Gerithus or Somnikus knew of its existence, but now, my hand is forced. You must know the truth.",starts={{npcID=187561,x=0.22,y=0.492,zoneID=13645}},ends={{npcID=187561,x=0.22,y=0.492,zoneID=13645}},coords={x=0.22,y=0.492,source="quest_giver",zoneID=13645},questType="standard"},
[66196] = {id=66196,name="A Quack For Help",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,starts={{npcID=187439,x=0.8,y=0.428,zoneID=13644}},ends={{npcID=186428,x=0.744,y=0.42,zoneID=13644}},coords={x=0.8,y=0.428,source="quest_giver",zoneID=13644},questType="standard"},
[66201] = {id=66201,name="Hooves of War",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Balakar will marshal his forces for war. I will do the same, but we are outnumbered. The dragons have asked for our aid, and we can use their help to even the odds. To answer their call for an alliance, I must blow the Horn of Drusahl, but I need Ohn'ahra's blessing. Will you help me? Go to Teerakai and deliver my declaration of war to my lieutenant, Jebotai. He will marshal my forces and direct you to the mystics who can find Ohn'ahra.",starts={{npcID=181198,x=0.6,y=0.374,zoneID=13645}},ends={{npcID=187787,x=0.418,y=0.618,zoneID=13645}},coords={x=0.6,y=0.374,source="quest_giver",zoneID=13645},questType="standard"},
[66210] = {id=66210,name="Gather the Family",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Your friend Kalecgos wishes to speak of ley lines, but preparations must be made for the funeral. While I meet with him, could you gather the final offerings from around Iskaara and place them in the funeral boat alongside dear old Ponoliak? I hope you take a moment to enjoy the town, as well! My people will welcome you warmly, especially after your help in Brackenhide.",starts={{npcID=186480,x=0.132,y=0.494,zoneID=13646}},ends={{npcID=186480,x=0.132,y=0.494,zoneID=13646}},coords={x=0.132,y=0.494,source="quest_giver",zoneID=13646},questType="standard"},
[66211] = {id=66211,name="Brackenhide Hollow: To the Source",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13991,description="We cannot thank you enough for your aid pushing back the Brackenhide gnolls. But they continue to gather, using their foul decay magic from some source deep within Brackenhide Hollow. Worse, we have not heard from the tuskarr in that area for weeks, now. I fear something terrible is happening there. We must protect our home. Please, gather your forces, find our people, and see what you can do about the decay!",starts={{npcID=186480,x=0.132,y=0.494,zoneID=13646},{npcID=205780,zoneID=13991}},ends={{npcID=186480,x=0.132,y=0.494,zoneID=13646},{npcID=205780,zoneID=13991}},coords={x=0.132,y=0.494,source="quest_giver",zoneID=13646},questType="dungeon"},
[66212] = {id=66212,name="Fishing: Aileron Seamoth",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Doesn't ANYBODY know how to fish PROPERLY anymore? Lukoturukk wiggles his nose angrily.> You, with the face, go get me some fish. GOOD fish. And no grungles!",starts={{npcID=193877,x=0.14,y=0.494,mapID=2024}},ends={{npcID=193877,x=0.14,y=0.494,mapID=2024}},coords={x=0.14,y=0.494,source="quest_giver",mapID=2112},questType="standard"},
[66213] = {id=66213,name="The Weave of a Tale",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="My dearest wife, Poa, is an excellent storyteller. But it's been thirty years, and she tells the same ones over and over again! Please, , talk to Poa and give her a new story to tell. What's that? Tell her a story about your adventures? Don't be ridiculous -- I don't want to hear about that! The greatest stories are always about fish. Tell a story about fish, even if you have to make one up!",starts={{npcID=186446,x=0.124,y=0.494,zoneID=13646}},ends={{npcID=186446,x=0.124,y=0.494,zoneID=13646}},coords={x=0.124,y=0.494,source="quest_giver",zoneID=13646},questType="standard"},
[66217] = {id=66217,name="WANTED: Krojek the Shoreprowler",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We've been watching the great shark we know as Krojek for many years now, waiting for the best time to hunt him down. His hunting ground has meandered closer and closer to the shore. That means the time is now. Gather your hunting party and take him out!",starts={{npcID=186568,x=0.124,y=0.498,zoneID=13646}},ends={{npcID=186568,x=0.124,y=0.498,zoneID=13646}},coords={x=0.124,y=0.498,source="quest_giver",zoneID=13646},questType="group"},
[66218] = {id=66218,name="Scampering Scamps",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Hello again. Could you do me and Norukk a favor? Our kids, Neelo and Nau, left to play. They know they should be back by now. I am occupied, so please find them. I doubt they are in danger; my kids know how to take care of themselves.",starts={{npcID=186186,x=0.128,y=0.486,zoneID=13646}},ends={{npcID=187674,x=0.106,y=0.468,zoneID=13646}},coords={x=0.128,y=0.486,source="quest_giver",zoneID=13646},questType="standard"},
[66221] = {id=66221,name="Moving On",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="With the Bronze Oathstone restored, Alexstrasza can proceed with her plan. Travel to Valdrakken, . She will want to hear of your success.",starts={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},ends={{npcID=187678,x=0.58,y=0.358,zoneID=13862}},coords={x=0.6,y=0.824,source="quest_giver",zoneID=13647},questType="standard"},
[66222] = {id=66222,name="The Calm Before the Storm",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Nokhud are powerful and have many allies. It will take all we have to withstand them. , you have the Khanam Matra's trust. Her orders were to rally our friends and prepare our people. I need your help. Seek Hojin to mobilize the remaining khansguard. Alert Scout Khenyug to possible Nokhud incursions. Inform Agura to expect wounded, and tell Gensai to prepare our provisions. As for the mystics, I believe they left recently. I will see if any remain in Teerakai.",starts={{npcID=187787,x=0.418,y=0.618,zoneID=13645}},ends={{npcID=187787,x=0.418,y=0.618,zoneID=13645}},coords={x=0.418,y=0.618,source="quest_giver",zoneID=13645},questType="standard"},
[66223] = {id=66223,name="Can We Keep It?",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=14433,mapID=2151,description="He's only trying to eat us because he's so hungry! Fish! Nobody can turn down some tasty, ice cold, raw fish! Frigidfish are the best, ever. You can fish them up all over the ocean! But if you can't fish one yourself, Jinkutuk in Iskaara will definitely sell you some. Bring me so many he won't be hungry any more!",starts={{npcID=187674,x=0.106,y=0.468,mapID=2024}},ends={{npcID=187674,x=0.106,y=0.468,mapID=2024}},coords={x=0.106,y=0.468,source="quest_giver",mapID=2151},questType="standard"},
[66224] = {id=66224,name="Mystic Mystery",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I'm sorry, I've failed to commune with Ohn'ahra. You will need someone else to fulfill the Khanam Matra's request. Several days ago, my fellow mystics were called to Ridgewater Retreat on an urgent request from Tigari Khan. They should still be there. Meet me outside of town. The least I can do is show you the way.",starts={{npcID=186290,x=0.368,y=0.572,zoneID=13645}},ends={{npcID=187795,x=0.492,y=0.632,zoneID=13645}},coords={x=0.368,y=0.572,source="quest_giver",zoneID=13645},questType="standard"},
[66225] = {id=66225,name="Toting Totems",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Boku asked why I sent a message calling all mystics to Ridgewater Retreat. I sent no such message. Balakar purposefully drew my mystics into a trap to cripple Clan Ohn'ir. But there may be a second reason. The Nokhud are gathering mystic totems, as many as they can find. These totems are blessed by Ohn'ahra. The Nokhud motives in this are unclear, but we cannot allow them to take Ohn'ahra's gifts. Recover as many totems as you can.",starts={{npcID=195316,x=0.494,y=0.632,zoneID=13645}},ends={{npcID=190648,x=0.494,y=0.632,zoneID=13645},{npcID=195316,x=0.494,y=0.632,zoneID=13645}},coords={x=0.494,y=0.632,source="quest_giver",zoneID=13645},questType="standard"},
[66226] = {id=66226,name="Emotional Support Companions",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Please don't hurt me... What? You're here to help? You must save the animals! The Nokhud attacked without warning. We all fled for our lives! I barely escaped death by diving into the lake. The animals! We left them behind. Please, I beg you, rescue the creatures. Who knows what cruelty the Nokhud have in store for them.",starts={{npcID=187796,x=0.47,y=0.712,zoneID=13645}},ends={{npcID=187796,x=0.47,y=0.712,zoneID=13645}},coords={x=0.47,y=0.712,source="quest_giver",zoneID=13645},questType="standard"},
[66227] = {id=66227,name="Some Good Fishing",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Another pair of hands! I could use some help catching enough fish to bring home for a meal. These Kirin Tor seem concerned about something called magical anomalies in the area, whatever that means. You're all welcome to stay here as long as you pitch in and help out. Grab a fishing pole and start fishing. Many hands make light work!",starts={{npcID=185608,x=0.414,y=0.356,zoneID=13646}},ends={{npcID=185608,x=0.414,y=0.356,zoneID=13646}},coords={x=0.414,y=0.356,source="quest_giver",zoneID=13646},questType="standard"},
[66228] = {id=66228,name="Camp Antonidas",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The Kirin Tor have our main camp set up to the south of here: Camp Antonidas. I believe Noriko and Khadgar are there now gathering adventurers to aid Kalecgos in reclaiming the Azure Oathstone. If you wish to help in our endeavours, go there.",starts={{npcID=185603,x=0.414,y=0.356,zoneID=13646}},ends={{npcID=183543,x=0.466,y=0.4,zoneID=13646}},coords={x=0.414,y=0.356,source="quest_giver",zoneID=13646},questType="standard"},
[66230] = {id=66230,name="A Sketchy Request",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The tarasek took everything they could get their claws on, including my scouting ledger. These overgrown lizards hoard trinkets and trophies by the dozens. I am sure that they stashed my ledger away somewhere. Could you keep an eye out for it as you work your way through the pass? Oh, and ? If you do manage to find it, please do not look inside. The contents are sort of... personal.",starts={{npcID=191753,x=0.546,y=0.694,zoneID=13647}},ends={{npcID=187289,x=0.546,y=0.694,zoneID=13647}},coords={x=0.546,y=0.694,source="quest_giver",zoneID=13647},questType="standard"},
[66232] = {id=66232,name="Afront 'Till A Salt",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We don't mind accommodating you and your friends in our little place--not that anyone asked-- but would you be a good neighbor and nab me some crystal flakes if you're going up to the springs? We use 'em to preserve all kinds of things. It's a crucial part of keeping food around here. The larger gorlocs are absolutely covered in the stuff. Maybe get some flakes off them?",starts={{npcID=186212,x=0.074,y=0.442,zoneID=13646}},ends={{npcID=186212,x=0.074,y=0.442,zoneID=13646}},coords={x=0.074,y=0.442,source="quest_giver",zoneID=13646},questType="standard"},
[66236] = {id=66236,name="Catching Wind",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Nokhud are collecting totems. The Primalists are capturing ohuna. And Ohn'ahra is silent. Whatever the Nokhud plans are, we must foil them. You and Boku must travel to Windsong Rise. Our enemies are likely there already. Search for Ohn'ahra there. If her children are in danger, she will undoubtedly go to them, and we must help. The Windmother is powerful, but I fear what these Primalists are capable of.",starts={{npcID=190648,x=0.494,y=0.632,zoneID=13645}},ends={{npcID=187804,x=0.58,y=0.688,zoneID=13645}},coords={x=0.494,y=0.632,source="quest_giver",zoneID=13645},questType="standard"},
[66237] = {id=66237,name="Spiritual Allies",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=14,mapID=1,description="Our arrival will not have gone unnoticed. Allow me to speak with them before we enter. I have something of a history with the council. There will be time for introductions after.",starts={{npcID=189386,x=0.456,y=0.128,mapID=1}},ends={{npcID=189389,x=0.456,y=0.128,mapID=1}},coords={x=0.456,y=0.128,source="quest_giver",mapID=1},questType="standard"},
[66239] = {id=66239,name="Spreading Decay",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Brena turns Kargpaw's totem over and over in her thick hands.> Kargpaw is a pawn. He isn't the source of this rot. We must find it, before the decay spreads further. The closest tuskarr presence from here is a trading outpost, just across the bridge on the way to Iskaara. We should check in with them... and quickly.",starts={{npcID=186228,x=0.344,y=0.31,zoneID=13646}},ends={{npcID=187721,x=0.286,y=0.348,zoneID=13646}},coords={x=0.344,y=0.31,source="quest_giver",zoneID=13646},questType="standard"},
[66241] = {id=66241,name="Thaldraszus Rally",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[66242] = {id=66242,name="Weather Control",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="This unnatural storm is heavy with magic. By the looks of it, the Nokhud are learning to manipulate the sacred essence of Windsong Rise to create storm elementals. Some have had more success than others... , we can't allow them to continue.",starts={{npcID=187804,x=0.58,y=0.688,zoneID=13645}},ends={{npcID=187809,x=0.606,y=0.636,zoneID=13645}},coords={x=0.58,y=0.688,source="quest_giver",zoneID=13645},questType="standard"},
[66243] = {id=66243,name="A Gift of Hope",level=60,requiredLevel=60,faction="alliance",expansion=9,zoneID=11510,description="Greetings, Maw Walker. I bear a summons from the Winter Queen. She requests your presence in Ardenweald to witness a ceremony involving others from your world. Shandris Feathermoon will be among them. You can find her in the Grove of Awakening.",ends={{npcID=187733,x=0.458,y=0.608,zoneID=11510}},questType="standard"},
[66244] = {id=66244,name="To Valdrakken",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Thanks to you, we narrowly avoided a complete catastrophe. However, we should convene with the other Aspects and share word of what happened here. Please meet me at the Seat of the Aspects within Valdrakken. I'm sure the others will have insight into what Raszageth and her Primalists are attempting. There is a crossing into Thaldraszus north and a bit east of here. The flight is scenic, but do not take too long getting there.",starts={{npcID=190000,x=0.394,y=0.63,mapID=2024}},ends={{npcID=187658,x=0.574,y=0.586,mapID=2025},{npcID=187678,x=0.58,y=0.358,mapID=2112}},coords={x=0.394,y=0.63,source="quest_giver",mapID=2112},questType="standard"},
[66245] = {id=66245,name="Remember the Fallen",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="So many of my comrades have fallen. Please... Collect their identifying signets so that their names may not be forgotten.",starts={{npcID=190180,x=0.376,y=0.83,zoneID=13647}},ends={{npcID=190180,x=0.376,y=0.83,zoneID=13647}},coords={x=0.376,y=0.83,source="quest_giver",zoneID=13647},questType="standard"},
[66246] = {id=66246,name="The Fog of Battle",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The Primalist attack came suddenly and with no warning. My unit attempted to find our leader, Commander Eranog, but before we could get to the other side of the garrison we were cut off. In the battle my unit leader, Sergeant Tagrik, held off three Primalists by himself as Kaora, Mikor, and myself battled at his side. Their screams are the last thing I remember before I fell. Please, , if you see any signs of my unit let me know what happened to them.",starts={{npcID=190180,x=0.376,y=0.83,zoneID=13647}},ends={{npcID=190180,x=0.376,y=0.83,zoneID=13647}},coords={x=0.376,y=0.83,source="quest_giver",zoneID=13647},questType="standard"},
[66247] = {id=66247,name="Slightly Used Weapons",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="This spear appears to be in good shape, given the condition of its former owner. Guardian Velomir mentioned to keep an eye out for useful materials, perhaps a few more of these spears can be obtained from the Magmasworn.",ends={{npcID=190180,x=0.376,y=0.83,zoneID=13647}},questType="standard"},
[66248] = {id=66248,name="Tying Things Together",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="This coil of heavy rope seems to be in good condition. Guardian Velomir said to keep an eye out for useful materials, perhaps if you can find a few more coils he might find them useful.",starts={{npcID=377114,x=0.385,y=0.834,zoneID=13647}},ends={{npcID=190180,x=0.376,y=0.83,zoneID=13647}},coords={x=0.385,y=0.834,source="quest_giver",zoneID=13647},questType="standard"},
[66249] = {id=66249,name="Clear the Sky",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="You did well to gather those spears and rope. With them, we can ensure those haughty Primalists will no longer rule the skies! There is a platform up the stairway with several Siege Scorpions . If you use the rope to string their bows and use the spears as ammunition, you should be able to strike the Magmasworn's dragons in the air! Once cleared, the path up the spire will be safe and we can continue our search for Commander Eranog.",starts={{npcID=190180,x=0.376,y=0.83,zoneID=13647}},ends={{npcID=190558,x=0.404,y=0.854,zoneID=13647}},coords={x=0.376,y=0.83,source="quest_giver",zoneID=13647},questType="standard"},
[66250] = {id=66250,name="Where's The Chief?",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="This is the only part of the fortress we haven't yet searched, . If Commander Eranog is anywhere, it has to be here. Let us see what we can find out.",starts={{npcID=190558,x=0.404,y=0.854,zoneID=13647}},ends={{npcID=190562,x=0.402,y=0.852,zoneID=13647}},coords={x=0.404,y=0.854,source="quest_giver",zoneID=13647},questType="standard"},
[66251] = {id=66251,name="Fire Fighter",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Commander Eranog has betrayed us and left this beast in charge. You have done so much for me already, but I can not handle that monster in my current state. Please, do this one last thing for me and help ensure that South Hold Gate does not fall to these Primalists. We must kill their leader! Help me, .",starts={{npcID=190562,x=0.402,y=0.852,zoneID=13647}},ends={{npcID=190562,x=0.402,y=0.852,zoneID=13647}},coords={x=0.402,y=0.852,source="quest_giver",zoneID=13647},questType="standard"},
[66252] = {id=66252,name="Reporting In",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="The Primalists threat has been diminished, . Forces from Valdrakken will be headed in soon, and can clean up any remnants. You should head back to the city and inform Captain Drine of what has happened. She will be interested to know what occurred here with Commander Eranog. Thank you again, , for everything.",starts={{npcID=190562,x=0.402,y=0.852,zoneID=13647}},ends={{npcID=189842,x=0.56,y=0.402,zoneID=13862}},coords={x=0.402,y=0.852,source="quest_giver",zoneID=13647},questType="standard"},
[66254] = {id=66254,name="Pessimistic Mystic",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="War? Dragons? You need me to contact Ohn'ahra? I can't. I can't hear Ohn'ahra at all. I'm just an initiate, and it seems like Ohn'ahra has withdrawn her blessings from me. Maybe I'm not good enough... When my mentor assigned me to this clan, she gifted me with these totems. She said they would empower me if ever I doubted myself. Will you help me place them? I will try to call upon Ohn'ahra one more time.",starts={{npcID=186290,x=0.368,y=0.572,zoneID=13645}},ends={{npcID=186290,x=0.368,y=0.572,zoneID=13645}},coords={x=0.368,y=0.572,source="quest_giver",zoneID=13645},questType="standard"},
[66256] = {id=66256,name="Eagle-itarian",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="We've discovered why the Nokhud want mystic totems. They can be used to capture the Children of Ohn'ahra. Though the Nokhud have stolen the totems, the Primalists are the ones behind this blasphemy. The Children of Ohn'ahra are sacred ohuna, blessed by the Windmother herself. Please, , free any ohuna you see! And if you come across any Primalists...",starts={{npcID=187804,x=0.58,y=0.688,zoneID=13645}},ends={{npcID=187809,x=0.606,y=0.636,zoneID=13645}},coords={x=0.58,y=0.688,source="quest_giver",zoneID=13645},questType="standard"},
[66257] = {id=66257,name="Fowl Sorcery",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="It is said that Ohn'ahra infused the spear of our ancestor, Maruuk, with her power. Balakar Khan must have told the Primalists about that legend. They have stolen the magic from Ohn'ahra's children, polluted it with storm sorcery, and infused it into ballista bolts. Why would the Nokhud need such weapons? We shouldn't wait to find out. These storm bolts are being loaded into wagons for transport. Take my totems and place one atop each wagon you come across. My wind magic will smash them to pieces.",starts={{npcID=187804,x=0.58,y=0.688,zoneID=13645}},ends={{npcID=187809,x=0.606,y=0.636,zoneID=13645}},coords={x=0.58,y=0.688,source="quest_giver",zoneID=13645},questType="standard"},
[66258] = {id=66258,name="Oh No, Ohn'ahra!",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="That Primalist is restraining Ohn'ahra, but just barely. She doesn't seem to notice us. Tigari Khan would say, \"Even the slightest breeze can topple a teetering stone.\" If I can disrupt her spell, even just a little, Ohn'ahra might be able to break free. Keep the guards distracted. I have an idea.",starts={{npcID=187809,x=0.606,y=0.636,zoneID=13645}},ends={{npcID=195024,x=0.614,y=0.628,zoneID=13645}},coords={x=0.606,y=0.636,source="quest_giver",zoneID=13645},questType="standard"},
[66259] = {id=66259,name="A Storm of Ill Tidings",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description=", we need to tell the Khanam Matra everything that's happened, including the capture of Ohn'ahra. You must go to Maruukai as quickly as you can. You'll have to go alone. I was hurt in the fall, and I'd just slow you down. Don't worry about me. I'll catch up later. Go!",starts={{npcID=195024,x=0.614,y=0.628,zoneID=13645}},ends={{npcID=181198,x=0.6,y=0.374,zoneID=13645}},coords={x=0.614,y=0.628,source="quest_giver",zoneID=13645},questType="standard"},
[66261] = {id=66261,name="A Minor Setback",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Ah, adventurer! Just the sort of well-armed individual I was hoping to encounter. I'm here in this literal backwater on very important Kirin Tor business, you see, and whilst I was beginning to set up my camp, I was chased off by filthy, mangy gnolls. In fact, a rather concerning number of gnolls have gathered nearby, enough that I believe they pose a threat to the wider Span. Fear not though, for I have a plan! Meet me in the lake just over there, and I'll explain everything.",starts={{npcID=187764,x=0.21,y=0.388,zoneID=13646}},ends={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},coords={x=0.21,y=0.388,source="quest_giver",zoneID=13646},questType="standard"},
[66262] = {id=66262,name="Waste Water Cleanup",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="First things first--I need my base of operations back! But the elementals running amok around here have made it very difficult to gain even a toehold. And of course it is those wretched gnolls' fault. The gnolls have dumped so much refuse, offal, and Light knows what else into the lake that the local elementals have started to go berserk. Be a dear and clean up a few of the more revolting messes before things come to a head. And, more importantly, before they stain my robes permanently!",starts={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},ends={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},coords={x=0.226,y=0.416,source="quest_giver",zoneID=13646},questType="standard"},
[66263] = {id=66263,name="A Precision Approach",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Gnolls are awful creatures. Smelly. Always scratching, laughing at you. And there are multitudes here and more are constantly arriving. We, and by that I mean you, could reap them like wheat for days and never get anywhere. They can't be suffered to stay here. We must strike at the heart of the snake! Remove their leadership and they'll be paralyzed with indecision and despair. What do you mean why are we doing this? Isn't it obvious? They're gnolls! What more reason could one need?",starts={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},ends={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},coords={x=0.226,y=0.416,source="quest_giver",zoneID=13646},questType="standard"},
[66264] = {id=66264,name="Disarmed and Docile",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="There's a frankly unnerving amount of weaponry being waved about up there. Relieving them of some should help calm things down. Or at least calm my nerves. What are they going to do without weapons, after all? Attack you with their bare hands? Ha!",starts={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},ends={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},coords={x=0.226,y=0.416,source="quest_giver",zoneID=13646},questType="standard"},
[66265] = {id=66265,name="Who's Next?",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Aha! Well, it seems that another gnoll has stepped up to assume command. Just as I expected. Yes. Having a trusted vice-warlord to ensure continuation of government makes perfect sense now, doesn't it? We'll just have to hit them a little harder to tumble their bureaucracy, hm? What? Am I going to take this moment to reflect on whether I'm rushing to judgement on these gnolls? Ridiculous! They're gnolls! Quickly now! Kill Cracktooth before the iron cools off or they arrange for an election!",starts={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},ends={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},coords={x=0.226,y=0.416,source="quest_giver",zoneID=13646},questType="standard"},
[66266] = {id=66266,name="Filthy Mongrels",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Those flea-bitten Hyena Mongrels the gnolls breed have got to go! Not only do they have no manners at all--you would not believe the places I've seen them relieve themselves--but they may very well be able to sniff me out despite my exemplary illusions. Do the well-mannered world a favor and remove them from it.",starts={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},ends={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},coords={x=0.226,y=0.416,source="quest_giver",zoneID=13646},questType="standard"},
[66267] = {id=66267,name="M.E.T.A.",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Those fiends! Pillaging and murder are one thing, but animal abuse? I'll not stand for it. The gnolls have set out traps for animals to catch and feed to their slavering hyena mutts. Find a way to free their fluffy captives and show the ruffians how a mage ethically treats animals! Of course this makes ethical sense in light of my recent actions. What exactly are you trying to insinuate?",starts={{npcID=198202,x=0.234,y=0.418,zoneID=13646}},ends={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},coords={x=0.234,y=0.418,source="quest_giver",zoneID=13646},questType="standard"},
[66268] = {id=66268,name="Third Try's the Charm",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="What? Another one's seized power? Whatever happened to abhorring a vacuum? Or at least waiting for a respectful period of mourning to pass in order to keep up appearances? Do they have no decency? No sense of propriety? No respect for a well-crafted plan? I made charts! Deal with this Bloodclaw fellow. I need a moment. And I don't need your nagging comments, thank you very much!",starts={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},ends={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},coords={x=0.226,y=0.416,source="quest_giver",zoneID=13646},questType="standard"},
[66269] = {id=66269,name="Just To Be Sure",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Just... kill anyone who looks like they might be magically inclined. Or has organizational skills. Or looks overly ambitious. Really, just use your best judgement on this one. Your \"best judgement\" is to stop speaking to me? Come on, ! They're... up to something nefarious, obviously!",starts={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},ends={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},coords={x=0.226,y=0.416,source="quest_giver",zoneID=13646},questType="standard"},
[66270] = {id=66270,name="Whack-a-Gnoll",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Oh, Light... there are more on their way! How could this happen? All my careful planning! The days spent hiding in this rancid lake! The assassinations! This should have thrown them into chaos and caused their settlement to crumble, but we've barely slowed them down! Maybe... maybe you're right, . I've been wrong all along... No! Impossible! We're in too deep now anyway. Go...deal with these new arrivals. I need time to collect myself.",starts={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},ends={{npcID=187463,x=0.226,y=0.416,zoneID=13646}},coords={x=0.226,y=0.416,source="quest_giver",zoneID=13646},questType="standard"},
[66278] = {id=66278,name="One Drakonid's Junk",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Gryrmpech will know what to do with it.>",starts={{npcID=376451,x=0.389,y=0.742,zoneID=13647}},ends={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},coords={x=0.389,y=0.742,source="quest_giver",zoneID=13647},questType="standard"},
[66279] = {id=66279,name="New Kid on the Clock",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Oh yeah, this pocket watch belongs to one of the stewards that help me tend to the gardens. He's one of Nozdormu's. Orizmu , I think? I can't keep all these kids straight. Most days he stands next to that hourglass near Alexstraza's tree without moving. Or blinking. Nozdormu's bunch have always been strange, if you ask me. But, he'll be grateful you brought this to him.",starts={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},ends={{npcID=187310,x=0.352,y=0.726,zoneID=13647}},coords={x=0.378,y=0.754,source="quest_giver",zoneID=13647},questType="standard"},
[66299] = {id=66299,name="The Awaited Egg-splosion",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Our prototype worked! Excellent! Now it's time for the main course. This time, YOU are the chef. With some necessary adjustments, you'll suit up in your disguise again. Then you'll take our masterpiece EGG-splosive, dunk it in this rancid stew here, head up to the matriarch's cave, plate it for her, and glide back down with the blasts detonating behind you! If all things go as planned, she'll be toast. Because of the explosion. Which will burn her to toasty bits.",starts={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},ends={{npcID=183912,x=0.5,y=0.698,zoneID=13647}},coords={x=0.5,y=0.698,source="quest_giver",zoneID=13647},questType="standard"},
[66308] = {id=66308,name="Feeding the Fire",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The creation of new weapons and armor in the Earth-Warder's Forge will insure our eventual victory over the Djaradin. The flames of the forge though must be constantly kept fueled. Cindershard Coal will provide the strongest heat, necessary to forge weapons. You can find Cindershard Coal from deposits and Elementals within the Cindershard Seam.",starts={{npcID=188179,x=0.248,y=0.604,zoneID=13644}},ends={{npcID=188179,x=0.248,y=0.604,zoneID=13644}},coords={x=0.248,y=0.604,source="quest_giver",zoneID=13644},questType="standard"},
[66320] = {id=66320,name="The Flow of Time",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The threads of time flow like a river, with many bends and branches. Occasionally, those flows can be changed. However, any anomaly left unresolved may doom our destiny to a false timeline. We are quickly approaching one of those anomalies. I have sent Chronormu to the Shifting Sands to investigate and correct any issues to the one true timeline. I foresee that your assistance will be invaluable. Please lend us your aid and meet with Chronormu.",starts={{npcID=187669,x=0.608,y=0.392,zoneID=13862}},ends={{npcID=187100,x=0.574,y=0.788,zoneID=13647}},coords={x=0.608,y=0.392,source="quest_giver",zoneID=13862},questType="standard"},
[66321] = {id=66321,name="Bar Their Efforts",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Djaradin forces are threatening an attack on our position. I can feel it down to my claws. We should strike first. Before they have a chance to mobilize! Go to the Burning Ascent and wreak havoc on the djaradin forces there.",starts={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},ends={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},coords={x=0.276,y=0.564,source="quest_giver",zoneID=13644},questType="standard"},
[66323] = {id=66323,name="Idling Pie",level=1,requiredLevel=1,faction="horde",expansion=9,zoneID=1637,description="Now that we have the wares back we can finish up here. But all my workers are lazin' about the city. Find where they're hidin' and 'encourage' 'em to head back here. A little leftover pie to the face, should have 'em runnin'.",starts={{npcID=187758,x=0.484,y=0.76,zoneID=1637}},ends={{npcID=187758,x=0.484,y=0.76,zoneID=1637}},coords={x=0.484,y=0.76,source="quest_giver",zoneID=1637},questType="standard"},
[66324] = {id=66324,name="Never Forgotten",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="The antidote is ready. Use it to search the Support Creche for survivors. Work quickly--the effect will not last long, so you may have to reapply it. If any of my people yet draw breath, save them. And if they do not, I ask that you recover their horn signets so that their names may be honored. While inside, perhaps you can find evidence of how this infestation came to be.",starts={{npcID=184163,x=0.202,y=0.19,mapID=85}},ends={{npcID=184163,x=0.202,y=0.19,mapID=85}},coords={x=0.202,y=0.19,source="quest_giver",mapID=85},questType="standard"},
[66326] = {id=66326,name="The Tools of One's Trade",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="A forge of this power needs specialized tools--ones that can take the tremendous heat. But the djaradin have ransacked the place and stole many of the tools we need for this work. If you can, recover those tools from them, so that we may continue our efforts to arm our allies.",starts={{npcID=188179,x=0.248,y=0.604,zoneID=13644}},ends={{npcID=188179,x=0.248,y=0.604,zoneID=13644}},coords={x=0.248,y=0.604,source="quest_giver",zoneID=13644},questType="standard"},
[66327] = {id=66327,name="Chasing the Wind",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="We must take a moment to pause and consider our strategy. We need Ohn'ahra's blessing to sound the Horn of Drusahl and summon the green dragons. Without their aid, we cannot win this war. The Nokhud already outnumber the other clans, and their forces are bolstered by the Primalists. And now Koroleth has captured our Windmother! We must therefore find Ohn'ahra before the Nokhud can launch their final attack and encircle Maruukai. I will send all of our scouts. I only hope we can find her in time.",starts={{npcID=181198,x=0.6,y=0.374,zoneID=13645}},ends={{npcID=188068,x=0.73,y=0.406,zoneID=13645}},coords={x=0.6,y=0.374,source="quest_giver",zoneID=13645},questType="standard"},
[66328] = {id=66328,name="Green Dragon Down",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Those dragons went down over the plains to the west. We must get to them quickly before the Nokhud do. We would not want them to think of all Maruuk as their enemies because of Balakar's actions.",starts={{npcID=188068,x=0.73,y=0.406,zoneID=13645}},ends={{npcID=188068,x=0.73,y=0.406,zoneID=13645}},coords={x=0.73,y=0.406,source="quest_giver",zoneID=13645},questType="standard"},
[66329] = {id=66329,name="Blowing of the Horn",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Why would they have brought Ohn'ahra here? Unless... ! I do not think Balakar intends to destroy the Horn. I think this is a trap! We must find a way past this wind, quickly!",starts={{npcID=188068,x=0.73,y=0.406,zoneID=13645}},ends={{npcID=188068,x=0.73,y=0.406,zoneID=13645}},coords={x=0.73,y=0.406,source="quest_giver",zoneID=13645},questType="standard"},
[66331] = {id=66331,name="The Primalist Front",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Khanam Matra sent word that she and her forces have arrived in the Emerald Gardens. They've located Koroleth and her Primalists. It appears a massive enemy invasion is gathering on a beach to the north. Wisely, she has several scouts watching strategic locations around the battlefield. Go and collect their reports, then meet me and my forces at the battlefront. Glory awaits us in battle, and, if we succeed, there will be vengeance.",starts={{npcID=188106,x=0.282,y=0.576,zoneID=13645}},ends={{npcID=188601,x=0.256,y=0.404,zoneID=13645}},coords={x=0.282,y=0.576,source="quest_giver",zoneID=13645},questType="standard"},
[66333] = {id=66333,name="Justice for Solethus",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="So long as a single green dragon draws breath, these Primalists will not defile the Ancient Bough without a fight. We are eager to do our part in this battle, but as long as those dragonkiller ballistae are on the field, we cannot approach. The Nokhud's strongest warriors guard them, so you will need to take down the warriors as well. Destroy the ballistae and Nokhud Warmongers . Eliminate this threat, and the green dragons will turn the tide of battle.",starts={{npcID=189599,x=0.256,y=0.404,zoneID=13645}},ends={{npcID=191494,x=0.744,y=0.41,zoneID=13645}},coords={x=0.256,y=0.404,source="quest_giver",zoneID=13645},questType="standard"},
[66335] = {id=66335,name="Deconstruct Additional Pylons",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="With those vile weapons destroyed, the green dragonflight can join the fray in force. We are much more familiar with the situation on the ground. We need to light up some targets, so Merithra and her dragons can strike from above. Merithra gave me these enchanted seeds. Place them near the Primalist pylons . We will use their light to call in attacks from airborne dragons.",starts={{npcID=191494,x=0.744,y=0.41,zoneID=13645}},ends={{npcID=191494,x=0.744,y=0.41,zoneID=13645}},coords={x=0.744,y=0.41,source="quest_giver",zoneID=13645},questType="standard"},
[66336] = {id=66336,name="The Isle of Emerald",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Your part in this has not escaped me, mortal. It is in large part due to your bravery that we were able to defeat the Primalists. I have invited the centaur to join me under the Ancient Bough. You, along with the Khanam Matra and her people, are welcome in our home. Follow this path through the archway across the water and into the trees beyond. I will wait for you there.",starts={{npcID=188150,x=0.256,y=0.482,zoneID=13645}},ends={{npcID=188181,x=0.222,y=0.51,zoneID=13645}},coords={x=0.256,y=0.482,source="quest_giver",zoneID=13645},questType="standard"},
[66337] = {id=66337,name="Stormbreaker",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description=", to me! We are within reach of victory! The Primalist ranks are broken, and their war is all but through. Everything we have achieved hinges on this final battle against the Primalist leader, Koroleth . Let us finish this, you and I! Together! To battle, !",starts={{npcID=191494,x=0.744,y=0.41,zoneID=13645}},ends={{npcID=188150,x=0.256,y=0.482,zoneID=13645}},coords={x=0.744,y=0.41,source="quest_giver",zoneID=13645},questType="standard"},
[66339] = {id=66339,name="The Nokhud Offensive: The Wind Belongs to the Sky",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13982,description="Is this the end of your time with us, , or will you aid us once again? My scouts report that Balakar has withdrawn into his stronghold, where he is holding Ohn'ahra. This is unacceptable! Meanwhile, his Nokhud raiders storm across the plains wreaking havoc. While we engage them in battle, you could infiltrate the Nokhud stronghold and rescue Ohn'ahra. Will you do this for us?",starts={{npcID=188601,x=0.256,y=0.404,zoneID=13645}},ends={{npcID=181198,x=0.6,y=0.374,zoneID=13645}},coords={x=0.256,y=0.404,source="quest_giver",zoneID=13645},questType="dungeon"},
[66340] = {id=66340,name="Into the Azure",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="We have done our part. Though I must remain here to watch over the Oathstone and guide the green dragonflight, know that you leave here with our gratitude and faith. I have received word the Kirin Tor are seeking help in claiming the Azure Oathstone. Helping them with their Oathstone will bring us one step closer to healing Azeroth. Find Pakina and Masud the Wise of the Kirin Tor. They will instruct you further. Safe journey and pleasant dreams, .",starts={{npcID=188181,x=0.222,y=0.51,zoneID=13645}},ends={{npcID=185599,x=0.716,y=0.806,zoneID=13645}},coords={x=0.222,y=0.51,source="quest_giver",zoneID=13645},questType="standard"},
[66344] = {id=66344,name="With the Wind at Our Backs",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="So the Primalists have recruited Clan Nokhud as allies. We have held off the Primalists until now, but the Nokhud have brought a new weapon: a dragonkiller ballista. I fear Solethus will not be the last dragon to fall to its foul storm magic. Come. I will take you to the dragons' haven at Shady Sanctuary. You can tell me what you know of the Nokhud while the Khanam Matra gathers her forces. We must prepare for our next move.",starts={{npcID=188156,x=0.724,y=0.506,zoneID=13645}},ends={{npcID=188106,x=0.282,y=0.576,zoneID=13645}},coords={x=0.724,y=0.506,source="quest_giver",zoneID=13645},questType="standard"},
[66349] = {id=66349,name="Training Rock",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=10424,mapID=1409,description="Remove those rocks!",questType="standard"},
[66351] = {id=66351,name="Smoke Over the Mountain",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Pathfinder Jeb looks at the mountain ridge beyond the camp and sniffs.> I don't like it. Pathfinder Yips should've been here days ago. Was gonna help me teach this new batch of explorers how to climb these pillars safely. Now I see smoke in the distance. I don't like it at all.",starts={{npcID=187700,x=0.472,y=0.834,zoneID=13644}},ends={{npcID=181039,x=0.624,y=0.504,zoneID=13644}},coords={x=0.472,y=0.834,source="quest_giver",zoneID=13644},questType="standard"},
[66352] = {id=66352,name="What the Enemy Knows",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="It is vital that we determine the Sundered Flame's mission in these ruins and how it relates to the arcane surge. We'll do this the old fashioned way: reconnaissance and espionage. The ruins are overrun with Sundered Flame devotees. I am sure some of them carry orders that may illuminate their mysterious goals. Use any means necessary to obtain these documents.",starts={{npcID=189166,x=0.65,y=0.586,zoneID=13646}},ends={{npcID=189166,x=0.65,y=0.586,zoneID=13646}},coords={x=0.65,y=0.586,source="quest_giver",zoneID=13646},questType="standard"},
[66353] = {id=66353,name="R.A.D. Anomalies",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="There is a LOT of arcane energy here... But! The R.A.D. can help with that! It's an awesome device--it's right in the name: \"Rannan's Awesome Device!\" It detects AND dispels arcane energy. Here... hold it! Do you feel the POWER in your hands? No? Well, now that you've got it, take it and dispel those anomalies!",starts={{npcID=189171,x=0.65,y=0.586,zoneID=13646}},ends={{npcID=189171,x=0.65,y=0.586,zoneID=13646}},coords={x=0.65,y=0.586,source="quest_giver",zoneID=13646},questType="standard"},
[66354] = {id=66354,name="The Spark",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The forge is ready. All it needs now is flame. Place the damaged Oathstone fragments upon the forge, and Wrathion shall provide the spark to ignite the process.",starts={{npcID=186493,x=0.246,y=0.61,zoneID=13644}},ends={{npcID=186493,x=0.246,y=0.61,zoneID=13644}},coords={x=0.246,y=0.61,source="quest_giver",zoneID=13644},questType="standard"},
[66363] = {id=66363,name="Basilisk Bucklers",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Interlinked scales are the key to stopping an arrow. The bucklers we make are the best in the plains. However, I am short of basilisk hides for my next order. I see you are interested in learning about our crafts. Gather basilisk hides from around the Dragon Isles, and I will give you instruction on our techniques.",starts={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},ends={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},coords={x=0.366,y=0.63,source="quest_giver",zoneID=13862},questType="standard"},
[66364] = {id=66364,name="To Fly a Kite",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Let me tell you about an opportunity. The proto-drakes and proto-dragons have an amazing range of motion on their wings. And the ribbing! It is so extendable. We mostly make our kites from stretched hides. With the proto-drakes causing havoc, I was wondering if you could return some of their wings to me? I can make kites that would be the envy of the tribe.",starts={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},ends={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},coords={x=0.368,y=0.624,source="quest_giver",zoneID=13862},questType="standard"},
[66368] = {id=66368,name="Island In A Storm",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="There has been little time to rest. The elementals' assault is relentless! A moment of respite would be welcome and allow me to craft more wards for our defense. See what you can do to thin out the onslaught on our perimeter.",starts={{npcID=187609,x=0.374,y=0.718,zoneID=13644}},ends={{npcID=187609,x=0.374,y=0.718,zoneID=13644}},coords={x=0.374,y=0.718,source="quest_giver",zoneID=13644},questType="standard"},
[66369] = {id=66369,name="The Earthen Ward",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I have empowered a ward using the rings you collected. It has gathered the very stones of the earth around it and created a Living Earthen defender to protect this territory. Test the Earthen Ward to ensure it's functional.",starts={{npcID=187609,x=0.374,y=0.718,zoneID=13644}},ends={{npcID=187609,x=0.374,y=0.718,zoneID=13644}},coords={x=0.374,y=0.718,source="quest_giver",zoneID=13644},questType="standard"},
[66383] = {id=66383,name="Legendary Assistance",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description=", we have convinced the Enlightened Brokers to provide additional supplies for the battle against the Jailer!",starts={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},ends={{npcID=182257,x=0.348,y=0.642,zoneID=13536}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="standard"},
[66391] = {id=66391,name="To the Ruins!",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Are you interested in hearing about my invention, the R.A.D.? No? Well, I'll tell you anyway--because it found something. Today it detected a HUGE SURGE of arcane energy from the Karnthar Ruins. Lathos thinks the Sundered Flame are to blame. It's the PERFECT opportunity to showcase the R.A.D.! Wanna come? It's going to be awesome.",starts={{npcID=188144,x=0.634,y=0.58,zoneID=13646}},ends={{npcID=189171,x=0.65,y=0.586,zoneID=13646}},coords={x=0.634,y=0.58,source="quest_giver",zoneID=13646},questType="standard"},
[66392] = {id=66392,name="Rallying Nature's Allies",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="We cannot give into despair now. We must push forward. We must think of another way through the barrier. First, we need our allies. Countless elementals summoned by Rymek are pouring through the portal. We will need an army that can move in the Dream like we can, or one that can be brought in easily. Rally the druids and centaur in Shady Sanctuary. It is time to call upon their oaths to preserve the grove.",starts={{npcID=187561,x=0.22,y=0.492,zoneID=13645}},ends={{npcID=187594,x=0.284,y=0.58,zoneID=13645}},coords={x=0.22,y=0.492,source="quest_giver",zoneID=13645},questType="standard"},
[66393] = {id=66393,name="To Somnikus",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="Somnikus has been melancholy and agitated since the death of his son. Though we have all endured loss, I cannot imagine what I would feel were something like that to happen to Gerithus. Go with Rymek to the isle, and see if there's anything we can do. Somnikus suspects that the Primalists are on the verge of another attack. I fear that he may do something rash. Do not worry. Because of your help with the Emerald Oathstone, you can cross the barrier easily.",starts={{npcID=187509,x=0.284,y=0.486,zoneID=13645}},ends={{npcID=186469,x=0.22,y=0.51,zoneID=13645}},coords={x=0.284,y=0.486,source="quest_giver",zoneID=13645},questType="standard"},
[66394] = {id=66394,name="Thin the Veil",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="There must be a way to lower the barrier from within this grove. I sense several points around us that strengthen it. If you can deactivate enough of those, we should be able to lower it the rest of the way so the others may join us.",starts={{npcID=187646,x=0.186,y=0.518,zoneID=13645}},ends={{npcID=187646,x=0.186,y=0.518,zoneID=13645}},coords={x=0.186,y=0.518,source="quest_giver",zoneID=13645},questType="standard"},
[66395] = {id=66395,name="The Chittering Rocks",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="Merithra needn't worry about me. I'm fine. My son's death... I'm fine. If you really want to help put my mind at ease, there is something you could do. I suspect Primalists will try to invade these lands again. Unlike last time, I doubt they'll attack the Ancient Bough directly. They know we'd defeat them. See those rocks over there? Those off-color, slightly smelly rocks? I hear something moving underneath them. Perhaps Primalists are lurking nearby! Could you investigate? Squash whatever you find.",starts={{npcID=186469,x=0.22,y=0.51,zoneID=13645}},ends={{npcID=186469,x=0.22,y=0.51,zoneID=13645}},coords={x=0.22,y=0.51,source="quest_giver",zoneID=13645},questType="standard"},
[66396] = {id=66396,name="Guarded Appreciation",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="I know it can be quite exhausting work to defend such an important locale. And often, we drakonids and dragonspawn get very little thanks for our dedication. I wish to bestow some of my own appreciation to the guards here in Ancient Bough. Here, offer them these gifts from me, as a sign of friendship. I hope my heartfelt gesture properly expresses my gratitude.",starts={{npcID=189857,x=0.22,y=0.508,zoneID=13645}},ends={{npcID=189857,x=0.22,y=0.508,zoneID=13645}},coords={x=0.22,y=0.508,source="quest_giver",zoneID=13645},questType="standard"},
[66397] = {id=66397,name="Our Full Strength",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="We need reinforcements, and quickly. But Merithra cannot yet join us in the grove because of the barrier. We will need to manage both from here within the Dream. Slay these Primalists and take anything you need from them, so we can melt those ice prisons and free the grove guards.",starts={{npcID=187646,x=0.186,y=0.518,zoneID=13645}},ends={{npcID=188763,x=0.186,y=0.516,zoneID=13645}},coords={x=0.186,y=0.518,source="quest_giver",zoneID=13645},questType="standard"},
[66398] = {id=66398,name="The Emerald Dragonflight",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="If we are to eradicate the Primalists from the Emerald Dream, the one place we must secure is Lunedane. According to my son, that is where Rymek has gone. It is the last line of defense for the nascent Tree. There, an ancient artifact shields the Tree from being found. And, it is powerful enough to expel all our enemies at once. I do not know if my mother has the power to command and use it anymore. But we will deal with that once we have found and stopped Rymek. Fly with us, as one.",starts={{npcID=187660,x=0.188,y=0.512,zoneID=13645}},ends={{npcID=188787,x=0.22,y=0.76,zoneID=13645}},coords={x=0.188,y=0.512,source="quest_giver",zoneID=13645},questType="standard"},
[66399] = {id=66399,name="We'll Cross that Bridge",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="We have to do something about this snow! If we're to give you proper support against Rymek and his minions, we can't have our wings freezing off. I sense powerful Frost Cores nearby. They're probably sustaining this blizzard. If you can destroy them, we can take out Rymek's minions in short order. And Somnikus is out there too. He flew off for Rymek like a dragon possessed. We need to get to him as soon as we can.",starts={{npcID=188787,x=0.22,y=0.76,zoneID=13645}},ends={{npcID=188840,x=0.208,y=0.796,zoneID=13645}},coords={x=0.22,y=0.76,source="quest_giver",zoneID=13645},questType="standard"},
[66400] = {id=66400,name="Winter's Fall",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="Somnikus struggles to breathe as he slowly freezes.> I managed... to stop him from reaching the tree. I hope it was enough. Rymek must fall, now. It is up to you. Tell Ysera and Merithra that I am sorry... for being a foolish old dragon.",starts={{npcID=188840,x=0.208,y=0.796,zoneID=13645}},ends={{npcID=188847,x=0.198,y=0.816,zoneID=13645}},coords={x=0.208,y=0.796,source="quest_giver",zoneID=13645},questType="standard"},
[66401] = {id=66401,name="The Dreamer",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="We have fought so hard to reach this point, and only one thing remains. The power in Lunedane will only respond to someone who can command the Emerald Dream from within. I had thought that it could only be my mother, but... I see how she has changed. I do not know if that difference is better, but it is real and I must acknowledge that. Come, let us face this moment together.",starts={{npcID=188847,x=0.198,y=0.816,zoneID=13645}},ends={{npcID=188848,x=0.196,y=0.818,zoneID=13645}},coords={x=0.198,y=0.816,source="quest_giver",zoneID=13645},questType="standard"},
[66402] = {id=66402,name="Like Mother, Like Daughter",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="From the moment I stepped into the Dream again, I knew that things were different. But now that we have beaten Rymek and his Primalists, I must consider all of the implications of what has happened. My daughter has worked to keep the green dragonflight together after my death. It is only fitting that she be the one to ascend now. Merithra must lead the Emerald Flight.",starts={{npcID=188850,x=0.198,y=0.816,zoneID=13645}},ends={{npcID=188848,x=0.196,y=0.818,zoneID=13645}},coords={x=0.198,y=0.816,source="quest_giver",zoneID=13645},questType="standard"},
[66409] = {id=66409,name="Pressing Matters",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="The chieftain is not taking visitors. Whether Iskaara sent you or not, we're dealing with our own share of trouble right now. We don't need outsiders bringing more of it. If you want our time, make yourself useful and help our guards. The djaradin have been attacking us from across the river. Flameshaper Lorak is behind the assault. He may not look like much as far as djaradin go, but he's got more brains than the rest of them. Deal with him and bring back proof. Then we'll talk.",starts={{npcID=188301,x=0.55,y=0.382,zoneID=13644}},ends={{npcID=188301,x=0.55,y=0.382,zoneID=13644}},coords={x=0.55,y=0.382,source="quest_giver",zoneID=13644},questType="standard"},
[66410] = {id=66410,name="Worst Impressions",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="So this is what we've been reduced to. An outsider does more work for us in a day than our chieftain has in weeks. Come. I will take you to him. Maybe this will be the kick in the stern that he needs.",starts={{npcID=188301,x=0.55,y=0.382,zoneID=13644}},ends={{npcID=187323,x=0.538,y=0.412,zoneID=13644}},coords={x=0.55,y=0.382,source="quest_giver",zoneID=13644},questType="standard"},
[66411] = {id=66411,name="Troubled Waters",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="It saddens me to see our chieftain like this, but our needs cannot wait. The river has provided for us for generations. But as the djaradin push forward, the waters recede, and the creatures fight with each other for space and resources. Without guards, our anglers cannot venture far to fish. Our food stores dwindle by the day. You do not seem to need protection though. Take this net to help gather any fish you can from the river. Meat from the nearby crabs would also be welcome.",starts={{npcID=188283,x=0.536,y=0.392,zoneID=13644}},ends={{npcID=188283,x=0.536,y=0.392,zoneID=13644}},coords={x=0.536,y=0.392,source="quest_giver",zoneID=13644},questType="standard"},
[66412] = {id=66412,name="Carry On, Basilton",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="There is one more thing this old drakonid would like to ask you, before you leave. Back when Lord Basilton and I first met, we would go on all sorts of adventures together. I think that's why he wanders off. He misses exploring. I can't do that for him anymore. But you can! You can take him to see places I never would have dreamed of, I can tell. However, we should ask Basilton what he thinks first.",starts={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},ends={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},coords={x=0.378,y=0.754,source="quest_giver",zoneID=13647},questType="standard"},
[66413] = {id=66413,name="Encroaching Heat",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,starts={{npcID=384405,x=0.531,y=0.353,zoneID=13644}},ends={{npcID=188283,x=0.536,y=0.392,zoneID=13644}},coords={x=0.531,y=0.353,source="quest_giver",zoneID=13644},questType="standard"},
[66414] = {id=66414,name="All But One",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="I have seen what you've done for the village. In easier times, I would have handled it, but... Tutaqan glances towards the river, then back to you.> Some of our ottuks went missing recently. We believe they swam too close to the djaradin's territory. Several were recovered. None of them alive. Few in one piece. We could not find my ottuk, Ipko. She has been my hunting partner for many years. If she... Please... aid me. If you search the river, I will search the shore.",starts={{npcID=187323,x=0.538,y=0.412,zoneID=13644}},ends={{npcID=187323,x=0.538,y=0.412,zoneID=13644}},coords={x=0.538,y=0.412,source="quest_giver",zoneID=13644},questType="standard"},
[66415] = {id=66415,name="The Only Way Past Is Through",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="Unujaak told you to come, didn't he? He was the one who helped me find Ipko when I became a hunter--or, rather, helped Ipko find me. They choose and we are chosen. He is hurting. Everyone is hurting because of me. I know that they need me to lead, but I have been half of a leader without her. If I couldn't protect her, how can I protect all of Uktulut? I cannot forgive myself. But I cannot let that weight keep me from putting at least one foot on the path I must walk.",starts={{npcID=187323,x=0.538,y=0.412,zoneID=13644}},ends={{npcID=187323,x=0.538,y=0.412,zoneID=13644}},coords={x=0.538,y=0.412,source="quest_giver",zoneID=13644},questType="standard"},
[66417] = {id=66417,name="Salvaging Supplies",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="Bah! I can't believe Tutaqan's still moping around when we need him to command his guards and hunters! We used to trade with the Iskaara at our pier, but that's gone belly up with the djaradin closing in and scaring off our traders. Half of last month's supplies and most of our boats are still lost out in the shallow river. The guards and hunters want to help, but they've got no weapons. You look like you can protect yourself, so get out there and grab something I can make spears with!",starts={{npcID=188285,x=0.542,y=0.386,zoneID=13644}},ends={{npcID=188285,x=0.542,y=0.386,zoneID=13644}},coords={x=0.542,y=0.386,source="quest_giver",zoneID=13644},questType="standard"},
[66418] = {id=66418,name="Testing the Tuskarrsenal",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,mapID=2022,description="The first weapon is ready! Soaking the bones in river water warmed by the djaradin's fire made them more pliable. I'll remember that trick! Since you've been helpful so far, I'll do you the honor of letting you test out some authentic Uktulut weaponry. You'll find no sharper blade or sturdier haft this side of the Dragon Isles. Go test this out in our training area for me. Maybe it'll remind the chieftain what real fighting looks like! Ha!",starts={{npcID=188285,x=0.542,y=0.386,mapID=2022}},ends={{npcID=188285,x=0.542,y=0.386,mapID=2022}},coords={x=0.542,y=0.386,source="quest_giver",mapID=2022},questType="standard"},
[66420] = {id=66420,name="Happy Hour",level=1,requiredLevel=1,faction="alliance",expansion=9,zoneID=1519,description="Now that the merchandise is back, it's time ta get everything else sorted out. With everything going on some of my crew decided it would be okay to disappear for some extended meal times. See if ye can find them and get them back here. We can all celebrate AFTER the work is done.",starts={{npcID=188342,x=0.514,y=0.706,zoneID=1519}},ends={{npcID=188342,x=0.514,y=0.706,zoneID=1519}},coords={x=0.514,y=0.706,source="quest_giver",zoneID=1519},questType="standard"},
[66422] = {id=66422,name="The Expedition Continues!",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="An ancient site, an organization with inscrutable motivations--even Rannan's R.A.D and its analyses... It all stirs the explorer in me. We must discover more about what's going on here. There are stairs to the south leading up to a tower. We shall press on.",starts={{npcID=189166,x=0.65,y=0.586,zoneID=13646}},ends={{npcID=189236,x=0.656,y=0.608,zoneID=13646}},coords={x=0.65,y=0.586,source="quest_giver",zoneID=13646},questType="standard"},
[66423] = {id=66423,name="Worries and Validations",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The deaths of these Sundered Flame underscore how dangerous the Ruins of Karnthar are. But Rannan believes that with some tinkering the R.A.D. can still quell the energies here. Again, we're treating the symptoms and not the root cause. Search the ruins for clues and see if you can discern their original function. And make haste, . We may not have much time.",starts={{npcID=189236,x=0.656,y=0.608,zoneID=13646}},ends={{npcID=189236,x=0.656,y=0.608,zoneID=13646}},coords={x=0.656,y=0.608,source="quest_giver",zoneID=13646},questType="standard"},
[66425] = {id=66425,name="Arcane Overload",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="There! Finished! May I present to you... the R.A.D.D.E.R! DUN DUN DUUUUN! I have calibrated it to the frequency of the energy surrounding the dragon consoles and inscribed a glyph of dispel magic on it. The R.A.D.D.E.R. will dispel the arcane energy and shut down the dragon console , but the glyph will weaken after each use. Pretty handy, isn't it? I detect four of these consoles in our vicinity. Go shut them down!",starts={{npcID=188845,x=0.656,y=0.608,zoneID=13646}},ends={{npcID=188845,x=0.656,y=0.608,zoneID=13646}},coords={x=0.656,y=0.608,source="quest_giver",zoneID=13646},questType="standard"},
[66426] = {id=66426,name="Running Out of Time",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I can feel the arcane surge growing as we speak. I suspect there is not much time before the ruins make Rannan's J.A.M. look like a distant star in the night sky. We have to get there and stop it. Please be careful, $p. Meet us by the east tower. We will assess the situation there.",starts={{npcID=189236,x=0.656,y=0.608,zoneID=13646}},ends={{npcID=189792,x=0.684,y=0.604,zoneID=13646}},coords={x=0.656,y=0.608,source="quest_giver",zoneID=13646},questType="standard"},
[66427] = {id=66427,name="A Looming Menace",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The arcane wounds I suffered cannot be healed in the field. I am afraid that they are too grave for me to fight. I must ask your help again, . You have to find Tharohn and stop her from overloading more consoles. Doing so would buy Rannan a few precious moments to calibrate the R.A.D. ... R.A.D.D.E.R... whatever he's calling it now. Maybe then we can thwart the Sundered Flame's machinations.",starts={{npcID=189792,x=0.684,y=0.604,zoneID=13646}},ends={{npcID=189792,x=0.684,y=0.604,zoneID=13646}},coords={x=0.684,y=0.604,source="quest_giver",zoneID=13646},questType="standard"},
[66428] = {id=66428,name="Friendship For Granted",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Alright! The R.A.D.D.E.R.E.R is calibrated and ready to go--for you! Why am I not using it? Simple! You have to think of and consider all the possibilities. Let's say it blows up. Who would fix it if I am injured, unconscious, or dead? Could you imagine? Now, go dispel the barrier so we can return to camp and get Lathos patched up. I'll be... standing back.",starts={{npcID=189791,x=0.684,y=0.604,zoneID=13646}},ends={{npcID=189791,x=0.684,y=0.604,zoneID=13646}},coords={x=0.684,y=0.604,source="quest_giver",zoneID=13646},questType="standard"},
[66429] = {id=66429,name="I Will Remember",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I... I need a few moments, please. Go back to Camp Nowhere, $p. I will meet you there.",starts={{npcID=189791,x=0.684,y=0.604,zoneID=13646}},ends={{npcID=193337,x=0.636,y=0.588,zoneID=13646}},coords={x=0.684,y=0.604,source="quest_giver",zoneID=13646},questType="standard"},
[66431] = {id=66431,name="In Mourning",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="This did not need to happen. Those cowardly djaradin... slaughtering our ottuks and leaving them for their twisted beasts to pick clean... I do not take Tutaqan 's grief lightly, but I worry for the future of our people if he dwells in darkness and grief for too long. We need to act. It looks like he was headed to the overlook above us. You have done him a great favor this day. He may be open to any good will you can show him. Please, see what can be done.",starts={{npcID=188283,x=0.536,y=0.392,zoneID=13644}},ends={{npcID=187323,x=0.538,y=0.412,zoneID=13644}},coords={x=0.536,y=0.392,source="quest_giver",zoneID=13644},questType="standard"},
[66435] = {id=66435,name="Site Salvage",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I've worked with many elementals as a shaman, but I've never seen any this aggressive! The Expedition discovered a titan vault here, but a barrier protects the inner chamber. When we tried to dispel the barrier, I think we triggered some kind of security system... There were suddenly angry elementals everywhere! Many explorers were working in the dig site when the elementals attacked. Many of them are trapped, and NONE of them are fighters. Please go down into the dig site and help them retreat!",starts={{npcID=188735,x=0.66,y=0.58,zoneID=13644}},ends={{npcID=190352,x=0.666,y=0.56,zoneID=13644}},coords={x=0.66,y=0.58,source="quest_giver",zoneID=13644},questType="standard"},
[66436] = {id=66436,name="Unearthed Troublemakers",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The earth elementals are not just trying to repel us, they're destroying artifacts and equipment, too! It's as though they've been programmed to destroy anything titan... We're holding them off, but we can't continue to study this site while they're here. Please help us push them back so we can have some exploring room!",starts={{npcID=188735,x=0.66,y=0.58,zoneID=13644}},ends={{npcID=190352,x=0.666,y=0.56,zoneID=13644}},coords={x=0.66,y=0.58,source="quest_giver",zoneID=13644},questType="standard"},
[66437] = {id=66437,name="A Key Element",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Elementalist Taiyang might know what to do with it.>",ends={{npcID=190352,x=0.666,y=0.56,zoneID=13644}},questType="standard"},
[66438] = {id=66438,name="Lofty Goals",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Air is a powerful element. It cuts through stone and fills sails to take us where we need to go. My hypothesis is that air will be the most effective at removing this barrier. It's simple, really. My scouts report they've found the Orb of Primal Gales . Scout Ri'tal can lead you to it. You can find them near Hornswog Hollow. Quickly!",starts={{npcID=188503,x=0.666,y=0.56,zoneID=13644}},ends={{npcID=190352,x=0.666,y=0.56,zoneID=13644}},coords={x=0.666,y=0.56,source="quest_giver",zoneID=13644},questType="standard"},
[66439] = {id=66439,name="Rapid Fire Plans",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Elemental orbs, eh? If there's earth, there's bound to be fire! The primalists over near tae hornswog nests are reshapin' tae land with lava. If anyone has an interest in tae Orb o' Primal Flames, it'd be them! Take them out and see if they have anythin' useful!",starts={{npcID=188053,x=0.666,y=0.56,zoneID=13644}},ends={{npcID=190352,x=0.666,y=0.56,zoneID=13644}},coords={x=0.666,y=0.56,source="quest_giver",zoneID=13644},questType="standard"},
[66440] = {id=66440,name="Closure",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="I do not know what to say. I had no idea that the chieftain's pain ran so deep. It makes sense. Ottuks are not pets to our people--especially not to hunters like our chieftain. They are our friends, our companions... and members of our families. Ipko was Tutaqan 's first and only ottuk. Uktulut hunters hold this bond to be sacred. I will see that her passage to the place of our ancestors is a peaceful one.",starts={{npcID=188283,x=0.536,y=0.392,zoneID=13644}},ends={{npcID=187323,x=0.538,y=0.412,zoneID=13644}},coords={x=0.536,y=0.392,source="quest_giver",zoneID=13644},questType="standard"},
[66441] = {id=66441,name="Distilled Effort",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The Orb of Primal Stone is a fortuitous find, but Acadia and Tae'shara have conflicting hypotheses regarding the barrier. I have my own hypothesis. Perhaps with more elemental orbs an answer will become clear. One of the explorers saw an oversized water elemental in a nearby cave. Defeat the elemental, and perhaps you will find another orb.",starts={{npcID=190352,x=0.666,y=0.56,zoneID=13644}},ends={{npcID=190352,x=0.666,y=0.56,zoneID=13644}},coords={x=0.666,y=0.56,source="quest_giver",zoneID=13644},questType="standard"},
[66442] = {id=66442,name="Let's Get Theoretical",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="We now have four elemental orbs! Let us see which hypothesis proves fruitful.",starts={{npcID=190352,x=0.666,y=0.56,zoneID=13644}},ends={{npcID=197860,x=0.664,y=0.558,zoneID=13644}},coords={x=0.666,y=0.56,source="quest_giver",zoneID=13644},questType="standard"},
[66443] = {id=66443,name="Calling the Hunting Party",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,starts={{npcID=188301,x=0.55,y=0.382,zoneID=13644}},ends={{npcID=188301,x=0.55,y=0.382,zoneID=13644}},coords={x=0.55,y=0.382,source="quest_giver",zoneID=13644},questType="standard"},
[66444] = {id=66444,name="While the Iron Is Hot",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="I spoke to our lookouts on the way down. They say this djaradin-- Zhurtan the Riverboiler --has begun his heinous ritual southwest of here, close to the waterfalls where many of our ottuks build their nests. If they're boiling the river upstream from us now, I assume they've decided to be done with us more quickly. We would be forced to starve or retreat. We will do neither. They've prodded us like cowards afraid of a true fight. So let's bring the fight to them this time, shall we?",starts={{npcID=187323,x=0.538,y=0.412,zoneID=13644}},ends={{npcID=187323,x=0.538,y=0.412,zoneID=13644}},coords={x=0.538,y=0.412,source="quest_giver",zoneID=13644},questType="standard"},
[66445] = {id=66445,name="Honor Our Fallen",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The djaradin have no regard for the sanctity of the Citadel or the bodies of our kin! They break the bones of the dead and take their personal keepsakes as souvenirs. This disrespect cuts at the heart of every proud black dragon. They deserve honor. Recover these items that the djaradin have stripped from the bodies of our fallen.",starts={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},ends={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},coords={x=0.276,y=0.564,source="quest_giver",zoneID=13644},questType="standard"},
[66447] = {id=66447,name="Beyond the Barrier",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Now that the barrier is down, let us explore the vault!",starts={{npcID=197860,x=0.664,y=0.558,zoneID=13644}},ends={{npcID=190354,x=0.658,y=0.574,zoneID=13644}},coords={x=0.664,y=0.558,source="quest_giver",zoneID=13644},questType="standard"},
[66448] = {id=66448,name="The Wayward Waywatcher",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The Waywatchers have kept the roads of Thaldraszus safe for travelers for as long as I can remember. It is a duty that my family has upheld with honor for generations. Alas, my sister Alvi seems less than interested in that honor of late. She is supposed to report to me here each morning, but I have not heard from her in over a day. If you find a bronze drakonid east of here, lazing about with her head in the clouds, I ask that you direct her to me. Otherwise, I will have to seek her out myself.",starts={{npcID=187202,x=0.524,y=0.686,zoneID=13647}},ends={{npcID=191753,x=0.546,y=0.694,zoneID=13647}},coords={x=0.524,y=0.686,source="quest_giver",zoneID=13647},questType="standard"},
[66449] = {id=66449,name="Hands-Off Operation",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Qalashi dustbinders are trying to imprison our whelps. It seems their leader is planning to use them for some nefarious purpose. We cannot let this happen! But the djaradin are not the only enemy here. Phoenixes are also tracking our whelps, presenting even more danger. You must protect the the whelps and eliminate the enemies that threaten them. Osoria will assist you.",starts={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},ends={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},coords={x=0.276,y=0.564,source="quest_giver",zoneID=13644},questType="standard"},
[66456] = {id=66456,name="A Poisonous Palette",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="I may not be great at my job, but at least I paid attention when I was learning how to do it. Every Waywatcher worth her scales knows how to make a proper antidote. I just need enough poison to mix it properly. Nori said the tarasek who attacked her had spears coated with the stuff. Find them and bring their spears to me. If my hunch is correct, I'll be able to make an antidote with the residue from the spearheads. I just hope we have enough time.",starts={{npcID=187289,x=0.546,y=0.694,zoneID=13647}},ends={{npcID=187289,x=0.546,y=0.694,zoneID=13647}},coords={x=0.546,y=0.694,source="quest_giver",zoneID=13647},questType="standard"},
[66457] = {id=66457,name="Ending the Blue Period",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The Embertooth all follow an oversized brute that I've taken to calling Bluescale . He has always been the aggressive sort, but until now he's always kept his pack of scavengers away from the main roads. Sure, they were territorial, but hostile? Not until now. Bluescale has to be responsible for this sudden escalation. Find him and take him down.",starts={{npcID=187289,x=0.546,y=0.694,zoneID=13647}},ends={{npcID=187289,x=0.546,y=0.694,zoneID=13647}},coords={x=0.546,y=0.694,source="quest_giver",zoneID=13647},questType="standard"},
[66458] = {id=66458,name="Legacy of Tyr: Secrets of the Past",level=70,requiredLevel=70,faction="alliance",expansion=9,zoneID=1519,description="To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored. Inconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead. Queen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there. Word is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!",starts={{npcID=189569,x=0.798,y=0.272,zoneID=1519}},ends={{npcID=189569,x=0.798,y=0.272,zoneID=1519}},coords={x=0.798,y=0.272,source="quest_giver",zoneID=1519},questType="dungeon"},
[66459] = {id=66459,name="The Field of Ferocity: Terror of the Swamp!",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Welcome one and all to the Fields of Ferocity! While this sparring field is used for traditional events, the centaurs have graciously allowed me to set up shop off-season. They say it tests their strength and brings them honor. You want to take home the title of champion? Well then, let me know when you're ready and you can take on the introductory competition.",starts={{npcID=188868,x=0.53,y=0.372,zoneID=13645}},ends={{npcID=188871,x=0.532,y=0.372,zoneID=13645}},coords={x=0.53,y=0.372,source="quest_giver",zoneID=13645},questType="group"},
[66460] = {id=66460,name="The Field of Ferocity: Lord of Decay!",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I tried to get one of those nasty gnolls for this gauntlet. Unfortunately, none of my associates know how to speak with them. We did manage to catch one of their freaky creations though. That should serve as a good opponent! Let me know when you want to start the second round!",starts={{npcID=188868,x=0.53,y=0.372,zoneID=13645}},ends={{npcID=188871,x=0.532,y=0.372,zoneID=13645}},coords={x=0.53,y=0.372,source="quest_giver",zoneID=13645},questType="group"},
[66461] = {id=66461,name="The Field of Ferocity: Foe from the Volcano!",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="One of the first volunteers for this competition hails from the Waking Shores. A big djaradin fellow, not quite as angry as his kin. He just seems to enjoy the sport of fighting. Hey, that works for me.",starts={{npcID=188868,x=0.53,y=0.372,zoneID=13645}},ends={{npcID=188871,x=0.532,y=0.372,zoneID=13645}},coords={x=0.53,y=0.372,source="quest_giver",zoneID=13645},questType="group"},
[66462] = {id=66462,name="The Field of Ferocity: Lost in the Dream!",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="You know, for it being the Dragon Isles, I haven't seen too many dragons. We did get a duo of dragonkin that requested to be signed up for this competition together though. They seem plenty eager to prove themselves though, so good luck!",starts={{npcID=188868,x=0.53,y=0.372,zoneID=13645}},ends={{npcID=188871,x=0.532,y=0.372,zoneID=13645}},coords={x=0.53,y=0.372,source="quest_giver",zoneID=13645},questType="group"},
[66463] = {id=66463,name="The Field of Ferocity: Elemental Revenge Round!",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="We're changing the roster at the last minute. Some Primalist bigwig wants to join in on the competition to face you. And I'm not saying no to an angry elemental dragon. I'm sure you'll be fine. If not, then... well, you signed the waiver, right?",starts={{npcID=188868,x=0.53,y=0.372,zoneID=13645}},ends={{npcID=188871,x=0.532,y=0.372,zoneID=13645}},coords={x=0.53,y=0.372,source="quest_giver",zoneID=13645},questType="group"},
[66464] = {id=66464,name="The Field of Ferocity: Master of the Hunt!",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="This is it. You and your pals have hit the big time. A match against the champ, Huntmaster Amaa herself. Don't pat yourself on the back just yet. She's ruthless. It was nice knowing you. After she kills you, can I have your stuff?",starts={{npcID=188868,x=0.53,y=0.372,zoneID=13645}},ends={{npcID=188871,x=0.532,y=0.372,zoneID=13645}},coords={x=0.53,y=0.372,source="quest_giver",zoneID=13645},questType="group"},
[66465] = {id=66465,name="Cache and Release",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Even with their leader gone, the Tarasek are unlikely to stop using their poison-tipped spears simply because we ask them nicely. I cannot risk even one of these weapons being used on an unsuspecting traveler. They will all need to be destroyed. If you did not see any in the caches by the pools, then the Embertooth are likely keeping their spears closer to the source. No one else will get hurt because of my carelessness. Enter the cave and destroy any weapon caches that you find.",starts={{npcID=187289,x=0.546,y=0.694,zoneID=13647}},ends={{npcID=187289,x=0.546,y=0.694,zoneID=13647}},coords={x=0.546,y=0.694,source="quest_giver",zoneID=13647},questType="standard"},
[66467] = {id=66467,name="Art Imitates Life",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The last time I was in this cave, I sketched a massive flower that dripped a vile, viscous sap. It's one of my best drawings, I couldn't forget it if I tried. That sap is what's stuck to these tarasek spears, I'm sure of it. They must have started harvesting it to envenom their weapons. The plant is beautiful; it will be a shame to kill it. Still, we can't let the tarasek keep harvesting it. , please cull the plant and put a stop to this whole mess.",starts={{npcID=187289,x=0.546,y=0.694,zoneID=13647}},ends={{npcID=187289,x=0.546,y=0.694,zoneID=13647}},coords={x=0.546,y=0.694,source="quest_giver",zoneID=13647},questType="standard"},
[66468] = {id=66468,name="What Once Was Ours",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Are you a mortal of action, or are you going to get out of our way, ? I have lost many good soldiers to those Primalists up ahead. We have an idea of what they are planning, but we must first rout the enemy and rescue those serving under me.",starts={{npcID=189174,x=0.526,y=0.672,zoneID=13647}},ends={{npcID=189188,x=0.548,y=0.644,zoneID=13647}},coords={x=0.526,y=0.672,source="quest_giver",zoneID=13647},questType="standard"},
[66470] = {id=66470,name="The Forward Push",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Sharnax scratches her chin.> The commander was right. The Primalists are calling reinforcements from the elemental planes. Sharnax smirks.> It would be a shame if something happened to their gateways, .",starts={{npcID=189188,x=0.548,y=0.644,zoneID=13647}},ends={{npcID=189188,x=0.548,y=0.644,zoneID=13647}},coords={x=0.548,y=0.644,source="quest_giver",zoneID=13647},questType="standard"},
[66471] = {id=66471,name="Prime Planning",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The commander ordered me to establish a forward base and dispatch any resistance. It wasn't until I did all the dispatching that I realized something. Sharnax lets out a long sigh.> The Primalists were talking about Tyrhold. Unless you are exceptionally skilled at interrogation, I need you to discover their plans.",starts={{npcID=189188,x=0.548,y=0.644,zoneID=13647}},ends={{npcID=189188,x=0.548,y=0.644,zoneID=13647}},coords={x=0.548,y=0.644,source="quest_giver",zoneID=13647},questType="standard"},
[66472] = {id=66472,name="Primal List",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The gateways closed, the elementals slain, and the Primalists stopped... for now. Sharnax laughs.> Is there anything we cannot do, ? I guess only time will tell. Take the plans back to the commander. I am certain he will be glad to see we have been successful.",starts={{npcID=189188,x=0.548,y=0.644,zoneID=13647}},ends={{npcID=189174,x=0.526,y=0.672,zoneID=13647}},coords={x=0.548,y=0.644,source="quest_giver",zoneID=13647},questType="standard"},
[66473] = {id=66473,name="The Land Awakens",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The fiends in this cave were too much for me. Sharnax lets out a labored cough.> I have seen what you can do. I need you to slay these elementals before they reach their full potential. We cannot allow the Primalists to take control of Tyrhold!",starts={{npcID=189188,x=0.548,y=0.644,zoneID=13647}},ends={{npcID=189188,x=0.548,y=0.644,zoneID=13647}},coords={x=0.548,y=0.644,source="quest_giver",zoneID=13647},questType="standard"},
[66484] = {id=66484,name="Know Your Enemy: Proto-Dragons",level=10,requiredLevel=10,faction="none",expansion=9,questType="standard"},
[66488] = {id=66488,name="WANTED: Frigellus",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Previously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. While this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land. Please see that it is safely neutralized. Bring word of your success to Custodian Cynegos .",starts={{npcID=376757,x=0.462,y=0.396,zoneID=13646}},ends={{npcID=189952,x=0.46,y=0.382,zoneID=13646}},coords={x=0.462,y=0.396,source="quest_giver",zoneID=13646},questType="group"},
[66489] = {id=66489,name="Setting the Defense",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Custodian Cynegos and I were just discussing the impact the Primalist attack has had on the plans to assault the Cobalt Assembly, and I had an idea. Take my wand and empower their weapons! A little bit of fire should do the trick...",starts={{npcID=192335,x=0.46,y=0.384,zoneID=13646}},ends={{npcID=192335,x=0.46,y=0.384,zoneID=13646}},coords={x=0.46,y=0.384,source="quest_giver",zoneID=13646},questType="standard"},
[66493] = {id=66493,name="Send It!",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Hey! Hey you! I have some mail for our apprentices in the field: care packages, gifts, things they've ordered via magical courier... Standard fare, really. Mind doing me a favor and handing them out?",starts={{npcID=188915,x=0.46,y=0.388,zoneID=13646}},ends={{npcID=188915,x=0.46,y=0.388,zoneID=13646}},coords={x=0.46,y=0.388,source="quest_giver",zoneID=13646},questType="standard"},
[66500] = {id=66500,name="Ways of Seeing",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We're not doing anything! We're not doing anything! Hang on a minute... You look like a pretty important ... Want in on a secret? Turns out there's magical art in these ruins. And we can see it! I can show you how to see 'em too! Just... don't tell Noriko yet.",starts={{npcID=189198,x=0.476,y=0.402,zoneID=13646}},ends={{npcID=189198,x=0.476,y=0.402,zoneID=13646}},coords={x=0.476,y=0.402,source="quest_giver",zoneID=13646},questType="standard"},
[66503] = {id=66503,name="For The Love of Others",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Ah, I see my apprentices have roped you into their little games. It appears they--and you--have stumbled onto something. The purpose behind these ruins is slowly revealing itself to us, and there's more than faded images and song... Something calls out from atop this tower. I see the intrigue in your eyes. Go. You have my permission. See what you can see.",starts={{npcID=183543,x=0.466,y=0.4,zoneID=13646}},ends={{npcID=183543,x=0.466,y=0.4,zoneID=13646}},coords={x=0.466,y=0.4,source="quest_giver",zoneID=13646},questType="standard"},
[66504] = {id=66504,name="A Shard of Crystalized Mana",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="Lathos may find it interesting.",questType="standard"},
[66507] = {id=66507,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[66508] = {id=66508,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=1637,mapID=85,starts={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},ends={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[66509] = {id=66509,name="Paranoid 1",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,description="Agura sent me out here to pick FLOWERS for my ANXIETY but there are CREATURES and I'm terrified.",questType="standard"},
[66511] = {id=66511,name="Renowned with the Iskaara Tuskarr",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13646,description="You continue to show us that you are an integral member of our community. To honor that bond seek me out in Iskaara as I have prepared a pack of supplies to aid you.",ends={{npcID=193006,x=0.13,y=0.492,zoneID=13646}},questType="standard"},
[66513] = {id=66513,name="Ground Leave",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,mapID=84,description="Perhaps we should get an idea of this city, if it is to be our new home. A scouting mission, if you will. Go, see what this place has to offer. I will follow Wrathion and attempt to help in any way I can. Try not to upset the locals any more than you must, though. I doubt many of them are used to seeing dragons walk among them. Meet up with us once you've gotten the lay of the land.",starts={{npcID=189324,x=0.322,y=0.496,mapID=37}},ends={{npcID=189603,x=0.798,y=0.272,mapID=84}},coords={x=0.322,y=0.496,source="quest_giver",mapID=84},questType="standard"},
[66516] = {id=66516,name="Mundane Gems, I Think Not!",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="It's such a waste. The djaradin of this land use powerful gems as mundane decorations. Mere jewelry! Gems have so many uses: telescopes, mirrors, focusing pointers, not to mention the myriad magical properties they possess. We must rectify this situation, explorer. Relieve the djaradin of their gems, and bring them back to me. I'll make sure they're put to better use! Be careful though--the djaradin are fierce warriors.",starts={{npcID=191001,x=0.368,y=0.626,zoneID=13862}},ends={{npcID=191001,x=0.368,y=0.626,zoneID=13862}},coords={x=0.368,y=0.626,source="quest_giver",zoneID=13862},questType="standard"},
[66517] = {id=66517,name="A New Source of Weapons",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="These Sundered Flame pose a great threat to our borders. Their weapons are concerning. Gather what you can of their weapons--we can study them for any weaknesses, and even use them for our own defenses. I have faith in you, outsider. If you perform this task for us, I will teach you some of our own blacksmithing arts.",starts={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},ends={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},coords={x=0.366,y=0.63,source="quest_giver",zoneID=13862},questType="standard"},
[66523] = {id=66523,name="Tending the Forge",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="If you're looking for an instructor, I'm sorry to say I... Ah, you're not an apprentice! My apologies. Allow me to introduce myself. I am Custodian Vernagos , one of the caretakers of these ruins. More specifically, the task of restoring this workspace to its former glory has fallen upon my very tired shoulders. Would you be able to lend a hand? All the reagents I need are nearby: ice elemental cores, embercones, hornswog leather... Fairly standard, easily gathered stuff. What say you?",starts={{npcID=189208,x=0.46,y=0.41,zoneID=13646}},ends={{npcID=189208,x=0.46,y=0.41,zoneID=13646}},coords={x=0.46,y=0.41,source="quest_giver",zoneID=13646},questType="standard"},
[66524] = {id=66524,name="Amateur Protography",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="So, you want to be a seasoned cataloger like me? You've come to the right place! The Wild Preserve is teeming with knowledge waiting to be found and filed! And how do I do that you ask? Why, with my handy Catalog-izer 3000 Dragon Isles edition--now with improved motion capture! To gain experience, photograph a proto-dragon egg, a whelp learning to fly, and a hunting proto-drake. Meet me at the ancient, proto-dragon skeleton west of here, and I'll assess your photos.",starts={{npcID=187705,x=0.484,y=0.826,zoneID=13644}},ends={{npcID=193740,x=0.39,y=0.832,zoneID=13644}},coords={x=0.484,y=0.826,source="quest_giver",zoneID=13644},questType="standard"},
[66525] = {id=66525,name="Competitive Protography",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Well, now that you've cut your teeth on some starter shots, how about we move onto something a little spicier? I spotted a gorgeous proto-drake flying around the area behind us. Beautiful horns, scales crackling with electricity... Probably the work of the Primalists, no doubt, but art is art! See if you can get a picture of the proto-drake and some of its eggs. You might have to climb up a bit to get a good shot!",starts={{npcID=193740,x=0.39,y=0.832,zoneID=13644}},ends={{npcID=193740,x=0.39,y=0.832,zoneID=13644}},coords={x=0.39,y=0.832,source="quest_giver",zoneID=13644},questType="standard"},
[66526] = {id=66526,name="Preserving the Wilds",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The Wild Preserve is one of the few areas where proto-dragons thrive. But the Primalists are disrupting their nesting grounds by sending sorties to capture and experiment on proto-whelps and proto-drakes. Show them no mercy. Locate these Primalist poachers, wipe them out, and free their captives. The proto-dragon species depends on it.",starts={{npcID=193954,x=0.39,y=0.832,zoneID=13644}},ends={{npcID=193954,x=0.39,y=0.832,zoneID=13644}},coords={x=0.39,y=0.832,source="quest_giver",zoneID=13644},questType="standard"},
[66527] = {id=66527,name="Professional Protography",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I haven't trained a photographer as good as you... that's still alive, that is. It's a dangerous profession. Speaking of dangerous, our final target is a large proto-dragon we believe may be one of the next apex predators in this preserve. Let's get up close and personal and take a picture!",starts={{npcID=193740,x=0.39,y=0.832,zoneID=13644}},ends={{npcID=193740,x=0.39,y=0.832,zoneID=13644}},coords={x=0.39,y=0.832,source="quest_giver",zoneID=13644},questType="standard"},
[66528] = {id=66528,name="King Without a Crown",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="This ancient proto-dragon must have been a glorious creature when it was alive--perhaps the largest the Wild Preserve has ever seen. But it wasn't enough. Observe the skeleton more closely, so we may learn the story of its final moments.",starts={{npcID=193954,x=0.39,y=0.832,zoneID=13644}},ends={{npcID=193954,x=0.39,y=0.832,zoneID=13644}},coords={x=0.39,y=0.832,source="quest_giver",zoneID=13644},questType="standard"},
[66529] = {id=66529,name="A Thousand Words",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="With all that we've learned here, I can't imagine moving on without a memento. Would you be kind enough to take my picture next to the proto-dragon fossils?",starts={{npcID=193954,x=0.39,y=0.832,zoneID=13644}},ends={{npcID=189484,x=0.388,y=0.836,zoneID=13644}},coords={x=0.39,y=0.832,source="quest_giver",zoneID=13644},questType="standard"},
[66534] = {id=66534,name="Ground Leave",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=1637,mapID=85,description="It seems like our arrival was noticed after all. Maybe there's hope for these people yet. I'll follow up with Ebyssian and the Horde leadership and try to smooth this out. You're on recon. See what this place has to offer. We may be here for a while, after all. Come find us once you're finished. Hopefully we'll have all the boring bits sorted out by then.",starts={{npcID=189389,x=0.456,y=0.128,mapID=1}},ends={{npcID=184786,x=0.442,y=0.382,mapID=85}},coords={x=0.456,y=0.128,source="quest_giver",mapID=85},questType="standard"},
[66546] = {id=66546,name="Retrieve the Discs",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="The discs in here represent the sum of this facility's knowledge. We need to retrieve them! I'll bring the barrier down with this console. It'll be on ye to retrieve the discs.",starts={{npcID=192820,x=0.55,y=0.562,zoneID=13647}},ends={{npcID=192967,x=0.544,y=0.554,zoneID=13647}},coords={x=0.55,y=0.562,source="quest_giver",zoneID=13647},questType="standard"},
[66547] = {id=66547,name="It Belongs in a Museum... Eventually",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="Waves of titan security, escaped proto-dragons, keys that turn you into constructs... I'll just say it. I've never had so much fun in my LIFE! Although Naleidea will probably say this is where the real fun begins. We're sitting on a trove of confidential titan data, thanks to the effort ye put in! When ye can, come meet us at camp and we'll compare notes.",starts={{npcID=192967,x=0.544,y=0.554,zoneID=13647}},ends={{npcID=192980,x=0.472,y=0.826,zoneID=13644}},coords={x=0.544,y=0.554,source="quest_giver",zoneID=13647},questType="standard"},
[66549] = {id=66549,name="Waking Shores Rally",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66553] = {id=66553,name="Hollow Up",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The Winterpelt are a special case among the furbolgs. I'd categorize 'em as a wee bit \"isolationist.\" They are ghosts in the hollow, their pelts blendin' in with tha snow. Usedta keep to themselves, but now they're outright aggressive. They attacked our camp with nae provocation! Somethin' must be wrong to drive 'em to it. I can't ask 'em what happened--yet--but maybe ye can find some clues in their village?",starts={{npcID=189401,x=0.654,y=0.16,zoneID=13646}},ends={{npcID=189401,x=0.654,y=0.16,zoneID=13646}},coords={x=0.654,y=0.16,source="quest_giver",zoneID=13646},questType="standard"},
[66554] = {id=66554,name="Aggressive Self-Defense",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="With the Winterpelt all in a tizzy, I don't imagine they'll appreciate ya poking around up there. Don't be afraid to defend yourself if they start somethin'. A firm reminder that ya mean business might knock some sense back into 'em. Try not to kill anyone though, will ya? I know how ya adventurin' types can get.",starts={{npcID=189401,x=0.654,y=0.16,zoneID=13646}},ends={{npcID=189401,x=0.654,y=0.16,zoneID=13646}},coords={x=0.654,y=0.16,source="quest_giver",zoneID=13646},questType="standard"},
[66555] = {id=66555,name="Bear With Me",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Aye, sounds like a right mess up there--like a storm blew through and wrecked the whole place. I can see why they'd be up in arms, but why attack us? This would be a lot easier if we could just talk it out, but the Winterpelt are famously tight-lipped and don't seem to speak any of the common branches of Furbolg-ish. Furbolgian? Eh, ye know what I mean. I don't suppose ya happened to have a nice chat with any of 'em while ye were checking in on them, did ye?",starts={{npcID=189401,x=0.654,y=0.16,zoneID=13646}},ends={{npcID=189401,x=0.654,y=0.16,zoneID=13646}},coords={x=0.654,y=0.16,source="quest_giver",zoneID=13646},questType="standard"},
[66556] = {id=66556,name="Ice Cave Ya Got There",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Well, yer accent is atrocious, and ten-thousand years o' isolation an' linguistic drift hasn't done us any favors, but I think I got a rough impression at least. The common thread in what they were tryin' to say was somethin' aboot a \"bad cave wind\" or an \"evil storm cave.\" That, or their laundry was too Thursday? Look, this isn't like learnin' Gnomish; there're goin' to be some hiccups. I'm pretty sure aboot the cave though, so let's start there.",starts={{npcID=189401,x=0.654,y=0.16,zoneID=13646}},ends={{npcID=189401,x=0.654,y=0.16,zoneID=13646}},coords={x=0.654,y=0.16,source="quest_giver",zoneID=13646},questType="standard"},
[66557] = {id=66557,name="Academic Acquaintances",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Aye, this Winterpelt variation on furbolg is provin' to be a tough nut to crack even for me. I've got some colleagues down in Camp Nowhere who might be able to help. I hear there are other furbolg tribes in the area, and comparin' notes on those dialects might give us somethin' to go off of.",starts={{npcID=189401,x=0.654,y=0.16,zoneID=13646}},ends={{npcID=187301,x=0.632,y=0.586,zoneID=13646}},coords={x=0.654,y=0.16,source="quest_giver",zoneID=13646},questType="standard"},
[66558] = {id=66558,name="Rowie",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="You were the one that came back with the others from Brackenhide, weren't you? Then you probably know what happened to Kaqiata... Her son, Rowie , has been distraught ever since Brena and the others returned without her. I'll stay here in case he comes back, but could you look for him? I think he ran off towards the ice cave to the east. He said something about trying to fight the yeti in there!",starts={{npcID=189533,x=0.138,y=0.49,zoneID=13646}},ends={{npcID=186542,x=0.16,y=0.504,zoneID=13646}},coords={x=0.138,y=0.49,source="quest_giver",zoneID=13646},questType="standard"},
[66559] = {id=66559,name="Back To Camp",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I saw Mordigan run out of there like a dwarf possessed. I'll go chase him down and make sure he gets back to the others in one piece. If you hug the cliff and jump down the waterfalls, you should be able to avoid stirring up any more of the gorlocs. See you back at camp.",starts={{npcID=188030,x=0.108,y=0.412,zoneID=13646}},ends={{npcID=187136,x=0.076,y=0.442,zoneID=13646}},coords={x=0.108,y=0.412,source="quest_giver",zoneID=13646},questType="standard"},
[66575] = {id=66575,name="Item as Questgiver: Vial",level=40,requiredLevel=40,faction="none",expansion=9,zoneID=13823,questType="standard"},
[66577] = {id=66577,name="Aspectral Invitation",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,mapID=84,description="Ah, $p. Impeccable timing! I just met with Lord Commander Turalyon and his allies, and they have accepted the Aspects' invitation to the Dragon Isles . You will be coming along, of course? It wouldn't be the same without you! I imagine you have noticed some unfamiliar faces gathered here. The ones with the wings are called dracthyr. They have only known me a short time, but they are already great admirers. Ah, but where are my manners? We should have a chat.",starts={{npcID=189569,x=0.798,y=0.272,mapID=84}},ends={{npcID=189569,x=0.798,y=0.272,mapID=84}},coords={x=0.798,y=0.272,source="quest_giver",mapID=84},questType="standard"},
[66579] = {id=66579,name="Sounds of Healing",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,description="Olea Manu might know more about this.>",ends={{npcID=183962,x=0.37,y=0.446,zoneID=13536}},questType="standard"},
[66582] = {id=66582,name="Power Procurement",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,description="In normal circumstances, the capture of energy is not problematic. However, the energy we require is massive and unstable. This enchanted vessel should provide a safe means of transport. There is a region to the southwest filled with energy-laden creatures. The anomalous energy within these creatures is powerful, but unstable. Capture their energy and return it to me. Then we may embark on the remainder of this journey together.",starts={{npcID=189764,x=0.458,y=0.406,zoneID=13646}},ends={{npcID=189764,x=0.458,y=0.406,zoneID=13646}},coords={x=0.458,y=0.406,source="quest_giver",zoneID=13646},questType="standard"},
[66586] = {id=66586,name="Legacy of Tyr: Secrets of the Past",level=70,requiredLevel=70,faction="horde",expansion=9,zoneID=1637,description="To stop Raszageth from freeing the other Incarnates, the Aspects' power must be restored. But this will not be an easy task. The Titans are silent and Keeper Tyr is long dead. Queen Alexstrasza has devised a plan. In the Badlands lies a Titan facility called Uldaman. She believes Tyr's companions hid a disc of his memories inside its depths. Take your allies to Uldaman and find the disc for the Dragon Queen. Let us hope Tyr's knowledge can be used to re-empower the Aspects.",starts={{npcID=190239,x=0.558,y=0.126,zoneID=14},{npcID=190239,x=0.442,y=0.382,zoneID=1637}},ends={{npcID=190239,x=0.558,y=0.126,zoneID=14},{npcID=190239,x=0.442,y=0.382,zoneID=1637}},coords={x=0.558,y=0.126,source="quest_giver",zoneID=14},questType="dungeon"},
[66589] = {id=66589,name="Expeditionary Coordination",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,mapID=84,description="The name's Toddy. I'll be headin' up our band of cheery adventurers under the banner of the Dragonscale Expedition. We'll get into the details later. For now, let's focus on gatherin' up our crew. Every expedition worth its salt has a variety of folk. We'll be needin' scholars, artisans, and of course explorers. Well? What're you standin' here for? Assemble that crew!",starts={{npcID=189602,x=0.798,y=0.272,mapID=84}},ends={{npcID=189077,x=0.228,y=0.556,mapID=84}},coords={x=0.798,y=0.272,source="quest_giver",mapID=84},questType="standard"},
[66595] = {id=66595,name="Dormant Discovery",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Members of the Dragonscale Expedition: Your assistance is required! Report to the Rubyscale Outpost at once!",ends={{npcID=189066,x=0.472,y=0.902,zoneID=13644}},questType="standard"},
[66596] = {id=66596,name="Whispers on the Winds",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,description="Hello, $p. It's been a while, and I wish we had more time to catch up. But you see, I've just had a rather enlightening... no, make that foreboding... yes, a foreboding conversation with an old friend. Sometimes a revelation can be both, after all. I really must tell you of what I've learned.",starts={{npcID=193450,x=0.558,y=0.126,zoneID=14},{npcID=193450,x=0.23,y=0.558,zoneID=1519}},ends={{npcID=189569,x=0.798,y=0.272,zoneID=1519}},coords={x=0.558,y=0.126,source="quest_giver",zoneID=14},questType="standard"},
[66597] = {id=66597,name="This Old Stone",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="This stone behind me is just one piece of, what do ye call it--ancient technology--we stumbled upon here in the Isles. But, we're not entirely sure what they are just yet. Baffling, really. We've sent word to some friends to see if they can help. In the meantime, perhaps ye can figure out how tae use it?",starts={{npcID=189066,x=0.472,y=0.902,zoneID=13644}},ends={{npcID=189066,x=0.472,y=0.902,zoneID=13644}},coords={x=0.472,y=0.902,source="quest_giver",zoneID=13644},questType="standard"},
[66598] = {id=66598,name="Nightborne Know-How",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,description="Ancient symbols aren't really me thing. However... Ah hah! Here it is! Bit of a trek, but a few of those old magic users can be found... here. Maybe they have somethin' tae offer.",starts={{npcID=189066,x=0.472,y=0.902,zoneID=13644}},ends={{npcID=189764,x=0.458,y=0.406,zoneID=13646}},coords={x=0.472,y=0.902,source="quest_giver",zoneID=13644},questType="standard"},
[66611] = {id=66611,name="Clearing the Skies",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,description="Can you hear that? Bugs! All around. Some of them are getting pretty big. Why don't you and your gliding friend use the thermal behind me and do something about it?",questType="standard"},
[66612] = {id=66612,name="Crabtender's Quandry",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The crabs are in danger! This particular bunch has been through a rough season. Their previous habitat was ransacked by the Primalists, and then I led them to this area only for gorlocs to invade! I thought they would be safe here, but the gorlocs only nurture aggression in their crabs, leading them to an early demise! Please, defeat some of the gorlocs so the crabs can escape!",starts={{npcID=196827,x=0.596,y=0.512,zoneID=13644}},ends={{npcID=196827,x=0.596,y=0.512,zoneID=13644}},coords={x=0.596,y=0.512,source="quest_giver",zoneID=13644},questType="standard"},
[66622] = {id=66622,name="Wayward Tools",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="This is terrible! My *hic* tools seem to have run off when I wasn't looking. I can't *hic* stand the thought of them all alone out there, no doubt scared out of their minds! Would you round them up for me? Just be patient and *hic* try to soothe their nerves and I'm sure they'll warm right up to you!",starts={{npcID=186755,x=0.656,y=0.162,zoneID=13646}},ends={{npcID=186755,x=0.656,y=0.162,zoneID=13646}},coords={x=0.656,y=0.162,source="quest_giver",zoneID=13646},questType="standard"},
[66633] = {id=66633,name="Make a Statement",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="These djaradin believe the black dragonflight is finished. They don't fear or respect Wrathion's authority here. We need a statement to remind them that the obsidian flight has returned, and that we are stronger than ever. Slay the djaradin and mark each corpse so they don't forget who rules here.",starts={{npcID=190899,x=0.266,y=0.624,zoneID=13644}},ends={{npcID=190899,x=0.266,y=0.624,zoneID=13644}},coords={x=0.266,y=0.624,source="quest_giver",zoneID=13644},questType="standard"},
[66635] = {id=66635,name="Reunited, Once Again",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="That should be enough. I can sense the others just on the outside of the grove, ready to enter the Dream. When you're ready, speak to me and I will break the ice walls and bring down the dome. I hope that my changes will not dishearten the flight. We will not be done, but we will be all together again.",starts={{npcID=187646,x=0.186,y=0.518,zoneID=13645}},ends={{npcID=187660,x=0.188,y=0.512,zoneID=13645}},coords={x=0.186,y=0.518,source="quest_giver",zoneID=13645},questType="standard"},
[66636] = {id=66636,name="The Other Side",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="We've finally figured out the placement of the third stone--and ye get to do the honors! I've affixed the stone to what's left of the watcher's staff. Just climb the scaffolding there, hold it up, and watch the show!",starts={{npcID=191838,x=0.542,y=0.554,zoneID=13647}},ends={{npcID=192820,x=0.55,y=0.562,zoneID=13647}},coords={x=0.542,y=0.554,source="quest_giver",zoneID=13647},questType="standard"},
[66646] = {id=66646,name="Quelling Causalities",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The Infinite has forced the energies of time to aggression. This is not good. Please slay any time elementals you encounter while assisting Ambassador Chronormu. I will remain here and help her hold Eternus in place.",starts={{npcID=186433,x=0.596,y=0.826,zoneID=13647}},ends={{npcID=186433,x=0.596,y=0.826,zoneID=13647}},coords={x=0.596,y=0.826,source="quest_giver",zoneID=13647},questType="standard"},
[66647] = {id=66647,name="Elemental Unfocus",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Kalecgos and I are under heavy fire in the skies above the mountain. The Primalists are unrelenting and their army endless. Soon, Kalecgos and I may be overrun by their forces. But I have a plan. At the base of the mountain is a disturbed orc named Ruvin Stonegrinder. The Kirin Tor fought her numerous times. She holds a device that can absorb and redirect elemental energies. Take it from her, then meet me further in.",starts={{npcID=186305,x=0.7,y=0.352,zoneID=13646}},ends={{npcID=186688,x=0.744,y=0.378,zoneID=13646}},coords={x=0.7,y=0.352,source="quest_giver",zoneID=13646},questType="standard"},
[66649] = {id=66649,name="Turning the Wheel",level=60,requiredLevel=60,faction="none",expansion=9,questType="raid"},
[66650] = {id=66650,name="Fate's Finale",level=60,requiredLevel=60,faction="none",expansion=9,questType="raid"},
[66651] = {id=66651,name="Up to No-khud",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Nokhud and Ukhel clans have overtaken the Eternal Kurgans. Their purpose can only be malign. Our most esteemed ancestors are buried there. I sent Initiate Zorig to investigate. He still has not returned. He is capable, but lacking in confidence. Please help him put a stop to their foul activities!",starts={{npcID=188224,x=0.408,y=0.616,zoneID=13645}},ends={{npcID=188225,x=0.39,y=0.66,zoneID=13645}},coords={x=0.408,y=0.616,source="quest_giver",zoneID=13645},questType="standard"},
[66652] = {id=66652,name="Return to Mender",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I can't see what they're doing from here, but I fear they're desecrating the kurgans. Please go to the nearest tomb, and see if you can stop the ritual they're performing. And if you find anything that may tell us their purpose here, please bring it back to me.",starts={{npcID=188225,x=0.39,y=0.66,zoneID=13645}},ends={{npcID=188225,x=0.39,y=0.66,zoneID=13645}},coords={x=0.39,y=0.66,source="quest_giver",zoneID=13645},questType="standard"},
[66654] = {id=66654,name="Desecrator Annihilator",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,mapID=2023,description="My mother was a hero. She deserves peace and rest, not this... enslavement! None of our heroes do. They must pay for this. And our ancestors must rest once more with their weapons, with honor. Take the weapons back from those desecrators!",starts={{npcID=188225,x=0.39,y=0.66,mapID=2023}},ends={{npcID=189858,x=0.338,y=0.654,mapID=2023}},coords={x=0.39,y=0.66,source="quest_giver",mapID=2023},questType="standard"},
[66655] = {id=66655,name="Reagents of De-Necromancy",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I fear the spirits will be unable to find their tombs, even if we release them from the Ukhel's grip. The Ukhel are also raising the ancestors' animal companions who guided and protected them in life. Bring me the skulls of those animals, and the sacred soil disturbed by these enemies. Combined, these reagents should help the ancestors find peace.",starts={{npcID=188225,x=0.39,y=0.66,zoneID=13645}},ends={{npcID=189858,x=0.338,y=0.654,zoneID=13645}},coords={x=0.39,y=0.66,source="quest_giver",zoneID=13645},questType="standard"},
[66656] = {id=66656,name="Definitely Eternal Slumber",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The ancestors are gripped by this dark magic. They will fight before they follow. The Ukhel raised our fiercest warriors and hunters. Stopping them will be no easy task. I'm going to come along and help. It's time I put my mother's spear back to use. Once they are defeated, use this totem I've crafted to help the subdued spirits find their way back to the kurgans.",starts={{npcID=189858,x=0.338,y=0.654,zoneID=13645}},ends={{npcID=193985,x=0.31,y=0.689,zoneID=13645}},coords={x=0.338,y=0.654,source="quest_giver",zoneID=13645},questType="standard"},
[66657] = {id=66657,name="And Stay Dead!",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Tombcaller Arban has holed up in the largest kurgan, where the first Maruuk ancestors were laid to rest. Stop Arban before he raises Maruuk and Teera!",starts={{npcID=193985,x=0.31,y=0.689,zoneID=13645}},ends={{npcID=193985,x=0.31,y=0.689,zoneID=13645}},coords={x=0.31,y=0.689,source="quest_giver",zoneID=13645},questType="standard"},
[66658] = {id=66658,name="The Nokhud Offensive: Founders Keepers",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Teera and Maruuk's weapons were removed before we stopped Tombcaller Arban. Our greatest ancestors may fight again in these plains... for the Nokhud. Go to the Nokhud Offensive. Find Maruuk and Teera. When you have subdued them, bring their weapons back to the Teerakai burial mound. We will lay them back to rest with the honor they deserve, in a place we can protect more easily.",starts={{npcID=193985,x=0.31,y=0.689,zoneID=13645}},ends={{npcID=190068,x=0.41,y=0.616,zoneID=13645}},coords={x=0.31,y=0.689,source="quest_giver",zoneID=13645},questType="dungeon"},
[66660] = {id=66660,name="On Your Mark... Get Set...",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13996,description="Nozdormu 's gaze is unfocused.> The further they fall, the faster they travel. They punch holes through the fabric of time which send out great ripples. You will need to be swift to catch them. Nozdormu 's focus sharpens and shifts to you.> I will send my timewalkers to help you navigate the timeways and speed your efforts. Avoid entangling with the temporal locals and do not stop until you have found Chronormu! Go. We have precious little time.",starts={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},ends={{npcID=187435,x=0.434,y=0.692,zoneID=13993},{npcID=187435,x=0.524,y=0.74,zoneID=13996}},coords={x=0.6,y=0.824,source="quest_giver",zoneID=13647},questType="standard"},
[66661] = {id=66661,name="It's Just a Coin, What Could it Cost?",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=10565,mapID=1670,questType="standard"},
[66671] = {id=66671,name="Path to Nowhere",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Ye look like a willin' and able adventurer! How would ye like to help out the Dragonscale Expedition? We've got ourselves a lovely camp in the middle of a nice bit of wilderness. There's plenty for ye to do if ye'd like to take the trip over there. Talk to me sis, Maddy, when ye get there. She'll get ye all settled in.",starts={{npcID=190001,x=0.456,y=0.398,zoneID=13646}},ends={{npcID=187800,x=0.632,y=0.584,zoneID=13646}},coords={x=0.456,y=0.398,source="quest_giver",zoneID=13646},questType="standard"},
[66673] = {id=66673,name="Speak to Koranos",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13862,description="The Watchers have observed much over the years. Many of them are lost to the vagaries of time, but we still have Koranos.",starts={{npcID=186870,x=0.544,y=0.556,zoneID=13647}},ends={{npcID=186870,x=0.544,y=0.556,zoneID=13647}},coords={x=0.544,y=0.556,source="quest_giver",zoneID=13647},questType="standard"},
[66675] = {id=66675,name="Aspect Power",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The Mother Oathstone is an ancient gift bestowed to our flights by the Titans. If what we have learned is true, I might be able to reactivate it and in doing so restore our aspectral powers. Though we are unsure of the outcome, if this has the slightest chance of working I must attempt it. , I would appreciate if you would join me in this.",starts={{npcID=187658,x=0.574,y=0.586,zoneID=13647}},ends={{npcID=192455,x=0.574,y=0.59,zoneID=13647}},coords={x=0.574,y=0.586,source="quest_giver",zoneID=13647},questType="standard"},
[66676] = {id=66676,name="Sneaking In",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,mapID=2023,description="This is Lizi... she's my secret friend. I've been taking care of her since she was rejected by her mother. This isn't looking good. Whatever they did to her is beyond my knowledge. I have to bring her home. My Ohn may ground me for the rest of time, but Lizi must get help. I am ever grateful to you, $p. I'm sorry this was more trouble than you signed up for. If you wouldn't mind one more adventure... please face my Ohn's wrath with me? Meet me back at the springs.",starts={{npcID=190014,x=0.562,y=0.77,mapID=2023}},ends={{npcID=190014,x=0.562,y=0.77,mapID=2023}},coords={x=0.562,y=0.77,source="quest_giver",mapID=2023},questType="standard"},
[66680] = {id=66680,name="Counting Sheep",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="How frustrating. A rabid stag did this while my brother Olekk and I were scouting. Are you here to help? After the primalists attacked, our herd of argali scattered into the pines. Their wool and milk are essential to the camp's functions. Take this whistle, which commands Wish to herd the argali back home. Sondo the butcher has her favorite treats if she needs extra encouragement.",starts={{npcID=190025,x=0.81,y=0.59,zoneID=13645}},ends={{npcID=190025,x=0.81,y=0.59,zoneID=13645}},coords={x=0.81,y=0.59,source="quest_giver",zoneID=13645},questType="standard"},
[66681] = {id=66681,name="Tempests Abound",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="If you're venturing out into the pines, please slay any stormtouched animals. This is not easy for me to ask, but they're clearly in pain, unable to be helped, and spreading the aggression. I suspect it's the primalists' doing. It must be coming from their outpost nearby, where I saw a strange magical altar at work. I'm going to go investigate again. If I'm not back by the time you return, Scout Watu can brief you on additional tasks. We're grateful for any help.",starts={{npcID=190024,x=0.81,y=0.588,zoneID=13645}},ends={{npcID=190025,x=0.81,y=0.59,zoneID=13645}},coords={x=0.81,y=0.588,source="quest_giver",zoneID=13645},questType="standard"},
[66683] = {id=66683,name="Last Resort Analysis",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Of course I get gored by a stag, of all creatures. Now I'm just another one who needs help. My brother will get all the credit, and no one back home will be surprised. What? What's that you've got there? Glowing rocks? I'll look at one, but take the rest to somebody else. I'm a hunter, not an archaeologist. Maybe this is a sign for me to switch jobs. Go on, you've proven more useful than I.",starts={{npcID=190025,x=0.81,y=0.59,zoneID=13645}},ends={{npcID=190025,x=0.81,y=0.59,zoneID=13645}},coords={x=0.81,y=0.59,source="quest_giver",zoneID=13645},questType="standard"},
[66684] = {id=66684,name="Storm Chasing",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I...completely lost control. Olekk was right. This terrible magic has to be the primalists' doing. Please, stop them! I must get my brother back to camp.",starts={{npcID=190025,x=0.81,y=0.59,zoneID=13645}},ends={{npcID=190025,x=0.81,y=0.59,zoneID=13645}},coords={x=0.81,y=0.59,source="quest_giver",zoneID=13645},questType="standard"},
[66687] = {id=66687,name="Land of the Apex",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="You should know of Rellen, the Learned, who gave centaur the tools to survive a merciless land. His memory requires offerings from worthy beasts. Take care, traveler. They are not as dangerous as they were eons past, but they're still the plains' apex predators.",starts={{npcID=190164,x=0.416,y=0.566,zoneID=13645}},ends={{npcID=190164,x=0.416,y=0.566,zoneID=13645}},coords={x=0.416,y=0.566,source="quest_giver",zoneID=13645},questType="standard"},
[66688] = {id=66688,name="Signs of the Wind",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="When the elements, true primals of the world, challenged the centaur, Himia met them with our given gift. The wind. A singing stone stands strong in the plains. There, you can offer tokens of the wind to evoke her memory. Such tokens may be found all around us--a bird's feather, a plant spore, a river's reeds.",starts={{npcID=190164,x=0.416,y=0.566,zoneID=13645}},ends={{npcID=377226,x=0.493,y=0.495,zoneID=13645}},coords={x=0.416,y=0.566,source="quest_giver",zoneID=13645},questType="standard"},
[66689] = {id=66689,name="More Than A Rock",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,ends={{npcID=190025,x=0.81,y=0.59,zoneID=13645}},questType="standard"},
[66690] = {id=66690,name="The Nokhud Offensive: The Final Ancestor",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13982,description="You've proven yourself an ally to us, with genuine interest in our values and way of life. There is one more ancestor I'd like to tell you about, but it will be dangerous. Kill the traitorous Balakar, leader of Nokhud, son of none. He wears a precious medallion at all times. Bring it back to me, and I will be forever in your debt.",starts={{npcID=190164,x=0.416,y=0.566,zoneID=13645}},ends={{npcID=190164,x=0.416,y=0.566,zoneID=13645}},coords={x=0.416,y=0.566,source="quest_giver",zoneID=13645},questType="dungeon"},
[66691] = {id=66691,name="Waking Shores - Race 01 - Intermediate",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66698] = {id=66698,name="Counting Argali",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="One of our key resources is our argali herd. Every loss is felt deeply for the strength of our clan. A few of the argali have gotten separated and have wandered away from the herd. Our shepherds could use your assistance reclaiming them.",starts={{npcID=185870,x=0.556,y=0.524,zoneID=13645}},ends={{npcID=185870,x=0.556,y=0.524,zoneID=13645}},coords={x=0.556,y=0.524,source="quest_giver",zoneID=13645},questType="standard"},
[66699] = {id=66699,name="Ask the Locals",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Kalecgos is wise to seek the tuskarr's counsel. They have generations of experience with this land. Many are resting here on their way to their various camps across the Span. Ask around! One of them must know about local ley lines.",starts={{npcID=183543,x=0.466,y=0.4,zoneID=13646}},ends={{npcID=190225,x=0.456,y=0.388,zoneID=13646}},coords={x=0.466,y=0.4,source="quest_giver",zoneID=13646},questType="standard"},
[66700] = {id=66700,name="The Black Locus",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="It really is quite enticing, isn't it? The Locus was too much for the Sundered Flame. However, it fits just right in my hands. Funny, that. Perhaps not. Not this day. Not again. Take it from me. It is not my burden to bear. Good bye, dear friend.",starts={{npcID=191154,x=0.662,y=0.242,zoneID=13645}},ends={{npcID=190089,x=0.66,y=0.25,zoneID=13645}},coords={x=0.662,y=0.242,source="quest_giver",zoneID=13645},questType="standard"},
[66703] = {id=66703,name="Snowball Effect",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,description="Snowhide gnolls smart. They know you put food on ice, food is good longer. But just ice no good. Magic ice be better! This be the work of shamans. And they put Frostbite here, so he starve to death next to delicious tuskarr meat. If want help tuskarrs, time running out. But Frostbite knows how to break the spell. Why Frostbite help? He no like shamans either.",starts={{npcID=189625,x=0.584,y=0.42,zoneID=13646}},ends={{npcID=189625,x=0.584,y=0.42,zoneID=13646}},coords={x=0.584,y=0.42,source="quest_giver",zoneID=13646},questType="standard"},
[66704] = {id=66704,name="Mugurlglrlgl!",level=40,requiredLevel=40,faction="horde",expansion=9,zoneID=14092,description="Mrglgulglrrlglgul! Grurguglullgurl! Gruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl. Mgrgulllglll gurl gugll.",starts={{npcID=183855,x=0.6,y=0.66,zoneID=14092}},ends={{npcID=183855,x=0.6,y=0.66,zoneID=14092}},coords={x=0.6,y=0.66,source="quest_giver",zoneID=14092},questType="standard"},
[66708] = {id=66708,name="Riders in the Snow",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Greetings, . This magical dome is truly astonishing, is it not? But even though it protects us from the biting cold and the wilderness, we cannot count on the Kirin Tor forever. A few days ago, some of our most seasoned hunters ventured into the forests looking for food and supplies, but they never came back. Even though I know their leader, Old Grimtusk , is a seasoned hiker and hunter, it is very hard not to worry about him and his hunting party. Can you find them for me?",starts={{npcID=190300,x=0.658,y=0.254,zoneID=13646}},ends={{npcID=189963,x=0.592,y=0.398,zoneID=13646}},coords={x=0.658,y=0.254,source="quest_giver",zoneID=13646},questType="standard"},
[66709] = {id=66709,name="Field Medic 101",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,starts={{npcID=189963,x=0.592,y=0.398,zoneID=13646}},ends={{npcID=189963,x=0.592,y=0.398,zoneID=13646}},coords={x=0.592,y=0.398,source="quest_giver",zoneID=13646},questType="standard"},
[66711] = {id=66711,name="Delicacy in the Dark",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Due to the nature of our clan, some resources are in short supply. We do not have the luxury of time to claim the land's metal resources. The late khan established multiple trade connections with a variety of individuals, and I see no reason to discontinue their services. The nearby bay contains buckets where we catch whelks - they're considered a delicacy for some of our neighbors. Bring a collection back to me for use in trade.",starts={{npcID=185853,x=0.714,y=0.31,zoneID=13645}},ends={{npcID=185853,x=0.714,y=0.31,zoneID=13645}},coords={x=0.714,y=0.31,source="quest_giver",zoneID=13645},questType="standard"},
[66715] = {id=66715,name="The Extraction",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Right now the most important thing is to bring back my people. Preferably in one piece. And as much as it pains me to say this, I'm in no condition to fight them on my own. Will you help us?",starts={{npcID=189963,x=0.592,y=0.398,zoneID=13646}},ends={{npcID=189625,x=0.584,y=0.42,zoneID=13646}},coords={x=0.592,y=0.398,source="quest_giver",zoneID=13646},questType="standard"},
[66719] = {id=66719,name="One Step Backwards",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="My friend, it is with great sorrow that I must say that I am familiar with the plight facing your kind in these ruins. If you proceed any further, you too will surely succumb to their madness. Be it through your nurture or your nature, the call you hear is a physiological one. You have a craving that must be sated. It brings me great shame to say that I possess the means to feed this malediction. It will not quite be the same, but you will be able to function... For now.",starts={{npcID=186300,x=0.64,y=0.182,zoneID=13645}},ends={{npcID=186300,x=0.64,y=0.182,zoneID=13645}},coords={x=0.64,y=0.182,source="quest_giver",zoneID=13645},questType="standard"},
[66722] = {id=66722,name="Wild Preserve Slalom - Advanced",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66724] = {id=66724,name="The Gleamfisher",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I am sorry you have been dragged into this, traveler. My brother tends to get... carried away. This is only the latest of his follies. But this one might get him killed. He won't listen to me. He probably won't listen to you, either. Our ancestor, Kauriq the Gleamfisher, though, is the center of his fixation. She may be able to. Please catch some Gleamfish and bring them here. I shall use them to help us commune with her spirit, which lingers in this stone.",starts={{npcID=186386,x=0.454,y=0.542,zoneID=13646}},ends={{npcID=186157,x=0.448,y=0.506,zoneID=13646}},coords={x=0.454,y=0.542,source="quest_giver",zoneID=13646},questType="standard"},
[66725] = {id=66725,name="Wild Preserve Circuit",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66729] = {id=66729,name="Conditionals",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="I don't like the alliance. Remember me? Go kill Mawsworn.",questType="standard"},
[66730] = {id=66730,name="True Survivors",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I know we're pretty banged up, but we can't forget why we're here. Our people are counting on us, and I don't plan on letting them down. We've got to find a temporary place for ourselves in these savage parts, and I know just the place. Now quit whining and MOVE IT.",starts={{npcID=189963,x=0.592,y=0.398,zoneID=13646}},ends={{npcID=196812,x=0.588,y=0.348,zoneID=13646}},coords={x=0.592,y=0.398,source="quest_giver",zoneID=13646},questType="standard"},
[66733] = {id=66733,name="Apex Canopy River Run - Advanced",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66734] = {id=66734,name="Leave Bee Alone",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Oh, thank the Life-Binder! Someone with empty hands! These gardens are normally a lovely playground for our whelps, but the bees have multiplied uncontrollably. The blooms returned with vigor--and so have the bees. The whelps are terrified, the dragons are annoyed, and just yesterday one was stung and-- Vaeros takes a deep breath to center himself then looks at you pleadingly.> Will you please gather up the bees and relocate them to the lake? Take this smoke diffuser ; it will calm them down.",starts={{npcID=190525,x=0.552,y=0.634,zoneID=13644}},ends={{npcID=190525,x=0.552,y=0.634,zoneID=13644}},coords={x=0.552,y=0.634,source="quest_giver",zoneID=13644},questType="standard"},
[66735] = {id=66735,name="Just a Trim",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The bees scaring the whelps is not the only problem. While pollination is usually a good thing, the recent swarm has caused the flora to grow out of control. Would you mind taking my gardening shears and cutting back the shrubs? Some have already begun to sprout dangerous lashers, but I hope we can stop more from doing so. An ounce of prevention is worth a pound of cure, after all. And I could... very much use some prevention right now, .",starts={{npcID=190525,x=0.552,y=0.634,zoneID=13644}},ends={{npcID=190525,x=0.552,y=0.634,zoneID=13644}},coords={x=0.552,y=0.634,source="quest_giver",zoneID=13644},questType="standard"},
[66737] = {id=66737,name="A Better Start",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Vaeros is diligent, but whelps have a way of finding trouble. Not mine, of course--but I suppose not every dragon rears their clutch to understand the gravity of their station. While I am loathe to encourage outdoor play over study, I will help you safeguard the garden more effectively. Take these seeds and plant them nearby. When mature, the blooms produce a fragrance that insects find disagreeable. The gardeners can help you--and maybe my bronze brethren, if you mind your manners.",starts={{npcID=190533,x=0.552,y=0.636,zoneID=13644}},ends={{npcID=190533,x=0.552,y=0.636,zoneID=13644}},coords={x=0.552,y=0.636,source="quest_giver",zoneID=13644},questType="standard"},
[66779] = {id=66779,name="Heir Apparent",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="As Neltharion's heir and leader of the only surviving flight of black dragons, I was not expecting to find myself in competition for my birthright. Particularly not against a self-important whelp younger than you, mortal. Nevertheless, if you need more than these self-evident facts, feel free to speak with members of my flight. There's no need to take my word on the subject.",starts={{npcID=185894,x=0.242,y=0.558,zoneID=13644}},ends={{npcID=185894,x=0.242,y=0.558,zoneID=13644}},coords={x=0.242,y=0.558,source="quest_giver",zoneID=13644},questType="standard"},
[66780] = {id=66780,name="Claimant to the Throne",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I have dedicated myself to saving Azeroth from destruction time and time again, and this fool thinks he can just swoop in and claim the title of aspect? I think not. Talk to my people, . See what they have to say about me and what I have done for this world.",starts={{npcID=187495,x=0.244,y=0.556,zoneID=13644}},ends={{npcID=187495,x=0.244,y=0.556,zoneID=13644}},coords={x=0.244,y=0.556,source="quest_giver",zoneID=13644},questType="standard"},
[66781] = {id=66781,name="A Matter of Taste",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The disrespect around here! A couple smelly gorlocs steal bits from our equipment and we have to shut it all doon... Ha! I've been lickin' rocks since before ye were a wee babe! Did nae need nae fancy gnomish gadgetry. Bring me a rock, and I'll prove it!",starts={{npcID=190691,x=0.076,y=0.442,zoneID=13646}},ends={{npcID=190691,x=0.076,y=0.442,zoneID=13646}},coords={x=0.076,y=0.442,source="quest_giver",zoneID=13646},questType="standard"},
[66783] = {id=66783,name="Renewal of Vows",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Centuries ago, I made a vow of friendship and cooperation with the first centaur. Although much has changed, I feel it is time for us to renew that vow again. A recitation was composed to help future generations of centaur remember their bond with the green dragonflight. Each verse must be answered with an offering from the khans. I hope the centaur can still remember the original meanings. The choice of gift is critical. Choose the right offering, and our allegiance is bound.",starts={{npcID=188181,x=0.222,y=0.51,zoneID=13645}},ends={{npcID=188181,x=0.222,y=0.51,zoneID=13645}},coords={x=0.222,y=0.51,source="quest_giver",zoneID=13645},questType="standard"},
[66784] = {id=66784,name="Starve the Storm",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="You fight well for one who must balance on only two legs! It matters not how hard we fight so long as the Primalists continue to draw reinforcements. We must close that portal, the Storm Corridor! Fight your way into the nearby cavern and slay the Primalist Storm-Summoners holding it open. I will aid you if I am able.",starts={{npcID=191494,x=0.744,y=0.41,zoneID=13645}},ends={{npcID=191494,x=0.744,y=0.41,zoneID=13645}},coords={x=0.744,y=0.41,source="quest_giver",zoneID=13645},questType="standard"},
[66785] = {id=66785,name="The Last Eggtender",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I understand your concern, , but all will be rectified shortly as it seems that we are about to have company. Feel free to stay and witness what transpires. It should be quite cathartic. Do speak with our egg tender when you have a moment, though. She will no doubt need the support.",starts={{npcID=190740,x=0.578,y=0.672,zoneID=13644}},ends={{npcID=185904,x=0.616,y=0.686,zoneID=13644}},coords={x=0.578,y=0.672,source="quest_giver",zoneID=13644},questType="standard"},
[66788] = {id=66788,name="Egg-cited for the Future",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I can scarcely believe it! Eggs of the Black Dragonflight! After all this time! But look at the state of this place! It will not do at all! Nothing is too good for these eggs. Though with those two blowhards squabbling like children for the Life-Binder's favor, you can bet they have not spared a thought for us! You, though, will not leave an old egg tender all alone, will you?",starts={{npcID=185904,x=0.616,y=0.686,zoneID=13644}},ends={{npcID=185904,x=0.616,y=0.686,zoneID=13644}},coords={x=0.616,y=0.686,source="quest_giver",zoneID=13644},questType="standard"},
[66814] = {id=66814,name="The Judgment of Tyr",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="Welcome to the Veiled Ossuary. Originally built to house and memorialize the dead. Now the likely location of the stone we've come to call the Judgment of Tyr . We haven't received reports of any overt Sundered Flame presence here, but the expedition has learned that they prefer to strike unawares. Be on your guard, .",starts={{npcID=190855,x=0.622,y=0.182,zoneID=13647}},ends={{npcID=190865,x=0.644,y=0.15,zoneID=13647}},coords={x=0.622,y=0.182,source="quest_giver",zoneID=13647},questType="standard"},
[66825] = {id=66825,name="A Ruby Lifecalling",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="$p! How fortunate you are here! We are about to begin a Lifecalling Ceremony and would be honored if you assisted us. A dragonspawn's Calling is very special. Some become masterful gardeners; others care for particular wildlife. These young dragonspawn have finished their training and are ready to take on their first Callings. I know they would be thrilled to have you participate. When you're ready, please present each of the items on this table to them.",starts={{npcID=191025,x=0.618,y=0.738,zoneID=13644}},ends={{npcID=191025,x=0.618,y=0.738,zoneID=13644}},coords={x=0.618,y=0.738,source="quest_giver",zoneID=13644},questType="standard"},
[66827] = {id=66827,name="Flowers of our Labor",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The legend says she only sings it for those who prove their devotion to life. I've been tending this garden for years... And I think my plants and I are finally ready. I'll start setting up by the pool here. You can help me with the harvest! Gather seed pods from beneath bushes, dragonflowers from sunny fields, and dragonfruit high in the trees. You can borrow my old rake to help with those. And watch out--sometimes the foliage can be feisty!",starts={{npcID=190866,x=0.602,y=0.664,zoneID=13644}},ends={{npcID=190866,x=0.602,y=0.664,zoneID=13644}},coords={x=0.602,y=0.664,source="quest_giver",zoneID=13644},questType="standard"},
[66828] = {id=66828,name="Huddle at the Hollow",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I've never seen Akora this upset. Usually she's as sunny as her flowers, but that legend means a lot to her. She talks about it all the time. Hm... Keshki fidgets with their glasses.> I don't know a lot about plants, and I don't think frogs would cheer up anyone but me... But north of here there's a quiet spot where I do my thinking: Hornswog Hollow. Maybe we can find something to cheer her up there? Or, uh, try to formulate a plan to help?",starts={{npcID=190868,x=0.602,y=0.664,zoneID=13644}},ends={{npcID=191011,x=0.652,y=0.636,zoneID=13644}},coords={x=0.602,y=0.664,source="quest_giver",zoneID=13644},questType="standard"},
[66830] = {id=66830,name="Hornswoggled!",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Oh, those hornswogs make me so mad! Keshki stomps her foot angrily, knocking her glasses askew> They're big, greedy bullies! Just because the place is named after them doesn't mean they get to jump all around and eat everything smaller than them! Here, use my jar of fireflies --it's a frog-minder's best friend. It'll calm the frogs enough that you can collect them, and we can get them out of harm's way. And if any hornswogs get in your way, don't be afraid to bully them back!",starts={{npcID=191011,x=0.652,y=0.636,zoneID=13644}},ends={{npcID=191011,x=0.652,y=0.636,zoneID=13644}},coords={x=0.652,y=0.636,source="quest_giver",zoneID=13644},questType="standard"},
[66831] = {id=66831,name="Home Is Where the Frogs Are",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="All the frogs are rounded up, ! I guess we're, uh, taking the frogs to Akora anyway. They'll be safe at the Life Pools until the hornswogs get bored and move on. Um, well, I guess we didn't find anything to cheer up Akora. I hope she understands...",starts={{npcID=191011,x=0.652,y=0.636,zoneID=13644}},ends={{npcID=190868,x=0.602,y=0.664,zoneID=13644}},coords={x=0.652,y=0.636,source="quest_giver",zoneID=13644},questType="standard"},
[66834] = {id=66834,name="Rellen, the Learned",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Bring your offerings to the central den. You may witness the legend of Rellen, the Learned, who gave centaur our livelihood as we know it.",starts={{npcID=190164,x=0.416,y=0.566,zoneID=13645}},ends={{npcID=190164,x=0.416,y=0.566,zoneID=13645}},coords={x=0.416,y=0.566,source="quest_giver",zoneID=13645},questType="standard"},
[66837] = {id=66837,name="Nothing for Breakfast",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="My brother Valdo was supposed to order more supplies. But it's been a week and nothing has come. I'm not surprised. The lazy oaf probably took a nap instead! Now we're short on food, and I'm too busy to hunt on top of my chores--and Valdo's! Would you hunt for us? The meat of the vorquin striders and striped bruffalon south of here would keep the kitchen open until I can order supplies.",starts={{npcID=190315,x=0.188,y=0.244,zoneID=13646}},ends={{npcID=190315,x=0.188,y=0.244,zoneID=13646}},coords={x=0.188,y=0.244,source="quest_giver",zoneID=13646},questType="standard"},
[66838] = {id=66838,name="It's Cold Up Here",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Being a good innkeeper means anticipating guests' needs. Unfortunately, I didn't anticipate how cold the nights would be here. Oops? My guests are going to need blankets--and good, thick ones. Maybe bear pelts will do? There are some large bears in the forest just east of here. If you bring me some of their pelts, I'll pay you for them! Please? Think of the adventurers and their cold, cold feet...",starts={{npcID=190315,x=0.188,y=0.244,zoneID=13646}},ends={{npcID=190315,x=0.188,y=0.244,zoneID=13646}},coords={x=0.188,y=0.244,source="quest_giver",zoneID=13646},questType="standard"},
[66839] = {id=66839,name="It's Brew Time!",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The gang had some time off and was hankerin' for a pint, so we bellied up to the inn. But, ach! I can nae believe it! They didna have any brew! What kind o' inn is that? One ran by the Stonehinges--that's what kind! So we're takin' matters into our own hands! The forest to the east has flowers and herbs that we could use to brew some sweet mead. Feel like helpin' me and doin' some flower pickin'? There'd be somethin' in it for ye!",starts={{npcID=190672,x=0.19,y=0.232,zoneID=13646}},ends={{npcID=190672,x=0.19,y=0.232,zoneID=13646}},coords={x=0.19,y=0.232,source="quest_giver",zoneID=13646},questType="standard"},
[66840] = {id=66840,name="Water Safety",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="My greatest responsibility is to make sure everyone has access to clean drinking water. With the gnolls to the east dealing with the decay, I must make sure that the camp is safe. I don't want to alarm anyone by personally taking samples, but I feel testing is necessary. Bring me samples from the three nearby waterfalls, and I will reward you handsomely.",starts={{npcID=190679,x=0.186,y=0.236,zoneID=13646}},ends={{npcID=190679,x=0.186,y=0.236,zoneID=13646}},coords={x=0.186,y=0.236,source="quest_giver",zoneID=13646},questType="standard"},
[66841] = {id=66841,name="A Shard of the Past",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I've seen ye runnin' in and out of the camp helpin' people. Ye think ye could help ol' Gannar too? I surveyed the area, and somethin' caught me old eyes. I think 'tis an ancient potsherd or a jar or somethin' just down south of here at the edge of that waterfall. Now, I am not much of a swimmer, but I'll give ye some coin and you can deliver the findings to Thanessa Silverbloom .",starts={{npcID=190666,x=0.192,y=0.246,zoneID=13646}},ends={{npcID=190652,x=0.186,y=0.236,zoneID=13646}},coords={x=0.192,y=0.246,source="quest_giver",zoneID=13646},questType="standard"},
[66843] = {id=66843,name="Out of Lukh",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Ach! Have ye seen me assistant, Lukh? The kid wanted a moment to look 'round, but he's been gone for an hour! I told him it ain't safe here and to nae walk far, but the kid has a head as thick as a ram's. I can nae say I blame him. it's pretty out here, and he has a thing for flowers. Could ye help me find 'em? They need me and the wagon back at Three-Falls Lookout!",starts={{npcID=190884,x=0.192,y=0.268,zoneID=13646}},ends={{npcID=190884,x=0.192,y=0.268,zoneID=13646}},coords={x=0.192,y=0.268,source="quest_giver",zoneID=13646},questType="standard"},
[66844] = {id=66844,name="The Great Shokhari",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Of all da animals I have seen here, Shokahri, da great sky vixen, be da most proud. It be a shame she preyed on a gnoll shaman, cause now she be crazed with decay. When I saw her eating one of her kits, I knew something was not right. I took da kits away and brought them here, but Shokhari attacked me, swiping me good. I almost didn't make it. Shokhari must be put down. If da decay rots more of her mind, she be coming for us soon.",starts={{npcID=190892,x=0.19,y=0.24,zoneID=13646}},ends={{npcID=190892,x=0.19,y=0.24,zoneID=13646}},coords={x=0.19,y=0.24,source="quest_giver",zoneID=13646},questType="standard"},
[66845] = {id=66845,name="Legendary Foil",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Last night, I was lying in my bedroll, tossing and turning, when an unnatural chill filled the inn. Then, out of nowhere I saw... the ghost of a draconid! It went through my luggage then vanished into thin air! But the true horror is that when I woke up... the ghost had taken my most beloved card! Would you be so kind as to track down the ghost and get my card back? It is my most prized possession.",starts={{npcID=190799,x=0.188,y=0.244,zoneID=13646}},ends={{npcID=190799,x=0.188,y=0.244,zoneID=13646}},coords={x=0.188,y=0.244,source="quest_giver",zoneID=13646},questType="standard"},
[66846] = {id=66846,name="The Heart of the Deck",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The day the Dragon Isles began their slumber was the day of my very last match. Fate was cruel, and I lost my strongest card before I could compete. Guo-Hee's card, you see, was mine. I do not know how her ancestors came upon it. Alas, I cannot claim it as my own as it has been in her family for centuries. That was a foolish mistake on my part. Perhaps you and I could craft a card together? A truly unique card... Yes! Will you help me? Speak to me once you are ready.",starts={{npcID=191741,x=0.188,y=0.244,zoneID=13646}},ends={{npcID=191741,x=0.188,y=0.244,zoneID=13646}},coords={x=0.188,y=0.244,source="quest_giver",zoneID=13646},questType="standard"},
[66847] = {id=66847,name="Vault of the Incarnates: Fury of the Storm-Eater",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=14617,description="No! We locked the Incarnates away to save this world and now Raszageth seeks to free them! She cannot succeed, . All life on Azeroth is in grave danger if you do not stop her! I shall return to Nozdormu at the Seat of the Aspects to plan for whatever is to come. Khadgar and Kalecgos are already inside with a contingent of allies. Join them to put an end to Raszageth. Good luck, champion.",starts={{npcID=190902,x=0.724,y=0.562,zoneID=13647}},ends={{npcID=193460,zoneID=14617}},coords={x=0.724,y=0.562,source="quest_giver",zoneID=13647},questType="raid"},
[66848] = {id=66848,name="Omens on the Wind",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Ohn'ahra does not speak in language as we do. Her voice carries through the very winds. We mystics are trained to feel her presence, follow her call, and interpret her messages. I have used the materials you gathered to bind totems to this particular call. Aid me in a ritual to center her voice, then I will interpret her song.",starts={{npcID=184595,x=0.856,y=0.208,zoneID=13645}},ends={{npcID=184595,x=0.856,y=0.208,zoneID=13645}},coords={x=0.856,y=0.208,source="quest_giver",zoneID=13645},questType="standard"},
[66856] = {id=66856,name="Becca Black and the Seven Gnomes",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts. Wrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.",starts={{npcID=191014,x=0.264,y=0.622,zoneID=13644}},ends={{npcID=191014,x=0.264,y=0.622,zoneID=13644}},coords={x=0.264,y=0.622,source="quest_giver",zoneID=13644},questType="standard"},
[66858] = {id=66858,name="Tour the Trading Post",level=1,requiredLevel=1,faction="alliance",expansion=9,zoneID=14771,description="Fancy yourself a collector, trader, or adventurer? We've travelled all over Azeroth collecting goods of the finest quality for someone exactly like you! Visit one of our outposts in Stormwind or Dornogal and browse all the latest goods! --T&W Trading Post Be sure to present this flyer for some extra Trader's Tender !",ends={{npcID=185468,x=0.51,y=0.718,zoneID=1519},{npcID=219244,x=0.446,y=0.56,zoneID=14771}},questType="standard"},
[66879] = {id=66879,name="Hornstrider Havoc",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Hornstriders! They've got bone-breaking beaks, fast legs for getting away from danger, and they can eat anything in the Isles. This Calling's the easiest around! It's just me and my favorite big birds spending time together. And if anything comes up, I know how to wrangle all of the Isles' critters. Would you mind following me to the hornstrider plateaus up north? I wouldn't mind an extra pair of hands while getting set up.",starts={{npcID=191176,x=0.618,y=0.736,zoneID=13644}},ends={{npcID=191280,x=0.534,y=0.584,zoneID=13644}},coords={x=0.618,y=0.736,source="quest_giver",zoneID=13644},questType="standard"},
[66880] = {id=66880,name="Ravine River Run",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[66882] = {id=66882,name="Lost Battlepack",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Talonstalker Kavia might want this.>",ends={{npcID=190899,x=0.266,y=0.624,zoneID=13644}},questType="standard"},
[66883] = {id=66883,name="Ancient Horn Ring",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Exadria might want this.>",ends={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},questType="standard"},
[66884] = {id=66884,name="Fireproof Gear",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The armor of the djaradin can withstand even the fiercest flames. Such qualities would be of great use in combating them! See what you can gather from the djaradin. We can study it, and apply the same enchantments to our own armor.",starts={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},ends={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},coords={x=0.368,y=0.624,source="quest_giver",zoneID=13862},questType="standard"},
[66885] = {id=66885,name="Emerald Gardens Ascent",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[66890] = {id=66890,name="Stolen Tools",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="We have been plagued by gnolls raiding our supply caravans. They appear to be obsessed with the various engineering tools within. We cannot risk these violent raiders figuring out our specialized art! Also, these thefts have set our production schedule back more than I'd like to admit. If you can retrieve some of the stolen engineering parts, we can get back on schedule.",starts={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},ends={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},coords={x=0.366,y=0.628,source="quest_giver",zoneID=13862},questType="standard"},
[66891] = {id=66891,name="Explosive Ash",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The molten phoenixes in the Dragon Isles create an unusual ash substance once they die. It could be used to create some material improvements for some complex, life-changing machinery. Though I would probably use it for explosives.",starts={{npcID=191001,x=0.368,y=0.626,zoneID=13862}},ends={{npcID=191001,x=0.368,y=0.626,zoneID=13862}},coords={x=0.368,y=0.626,source="quest_giver",zoneID=13862},questType="standard"},
[66892] = {id=66892,name="Deluge Dilemma",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Elementals are killing the hornstriders! I know how to wrangle large critters, but I never thought I'd have to go toe-to-toe with an elemental! These aren't anything like baby thunder lizards... Dazakros sighs, distressed.> Please knock down a few of them elementals. Hornstriders have a lot more sense than we give them credit for. They'll fight back if they have the means to!",starts={{npcID=191280,x=0.534,y=0.584,zoneID=13644}},ends={{npcID=191280,x=0.534,y=0.584,zoneID=13644}},coords={x=0.534,y=0.584,source="quest_giver",zoneID=13644},questType="standard"},
[66893] = {id=66893,name="Beaky Reclamation",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I may not know anything about water elementals, but I do know hornstriders! I've thrown together a salve that'll keep the 'striders healthy and ready to fight. I've never had a chance to apply it to a real hornstrider, but I've done all the studying I can do. It's time to put on a brave face and lather them up!",starts={{npcID=191280,x=0.534,y=0.584,zoneID=13644}},ends={{npcID=191280,x=0.534,y=0.584,zoneID=13644}},coords={x=0.534,y=0.584,source="quest_giver",zoneID=13644},questType="standard"},
[66894] = {id=66894,name="Same as the Old Boss",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,description="The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing. However, Deathwing has not returned, and still there is no Twilight. It is time for a new leader. You can help bring about the change.",starts={{npcID=191307,x=0.32,y=0.522,zoneID=13644}},ends={{npcID=191307,x=0.32,y=0.522,zoneID=13644}},coords={x=0.32,y=0.522,source="quest_giver",zoneID=13644},questType="standard"},
[66895] = {id=66895,name="Same as the Old Boss",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,description="The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing. However, Deathwing has not returned, and still there is no Twilight. It is time for a new leader. You can help bring about the change.",starts={{npcID=191310,x=0.32,y=0.522,zoneID=13644}},ends={{npcID=191310,x=0.32,y=0.522,zoneID=13644}},coords={x=0.32,y=0.522,source="quest_giver",zoneID=13644},questType="standard"},
[66897] = {id=66897,name="Fuel for the Forge",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="To make the best blades, you need the heat that only a Magma Core can provide. We try to keep a few on hand as a fuel source for our forges. Lately, we've been running low on cores and could use a resupply. Magma Cores are obtainable from most lava creatures in the Dragon Isles.",starts={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},ends={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},coords={x=0.366,y=0.63,source="quest_giver",zoneID=13862},questType="standard"},
[66899] = {id=66899,name="Fuzzy Legs",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="We have received a request for \" Fuzzy Legs \" for tailoring... Don't look at me, I don't make the requests, I just pass them on. I imagine the legs of tarantulas would fulfill this request.",starts={{npcID=191001,x=0.368,y=0.626,zoneID=13862}},ends={{npcID=191001,x=0.368,y=0.626,zoneID=13862}},coords={x=0.368,y=0.626,source="quest_giver",zoneID=13862},questType="standard"},
[66900] = {id=66900,name="Enchanted Relics",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Ah, the tides have brought you at just the right time! Gnolls have stolen some of our relics. These are more precious than most--they have been enchanted. We cannot allow the gnolls to learn our magics! Someone of your skill should have no issue identifying the stolen relics. Please, will you lend us your aid?",starts={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},ends={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},coords={x=0.368,y=0.624,source="quest_giver",zoneID=13862},questType="standard"},
[66929] = {id=66929,name="Gotta Collect Them All",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="$PC, do you mind helping me get my cards back? I told Setogosa I need them to show other students how to play Hearthstone. I want to form a club, but she's not giving them back! She's always been rude to me, but this is taking it further than normal.",starts={{npcID=191414,x=0.606,y=0.432,zoneID=13647}},ends={{npcID=191414,x=0.606,y=0.432,zoneID=13647}},coords={x=0.606,y=0.432,source="quest_giver",zoneID=13647},questType="standard"},
[66931] = {id=66931,name="Who Brought the Ruckus?",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="That was no ordinary quake.",starts={{npcID=187290,x=0.622,y=0.73,zoneID=13644}},ends={{npcID=190293,x=0.594,y=0.726,zoneID=13644}},coords={x=0.622,y=0.73,source="quest_giver",zoneID=13644},questType="standard"},
[66935] = {id=66935,name="Crystal Quill Pens",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="There are unique creatures in these lands called crystalspines. They are cute little creatures protected by sharp crystal quills . When I was treating one of our researchers for being stuck by one, I noticed that there was a lingering power resonating within. They might make for an excellent source of enchanting crystals.",starts={{npcID=191001,x=0.368,y=0.626,mapID=2112}},ends={{npcID=191001,x=0.368,y=0.626,mapID=2112}},coords={x=0.368,y=0.626,source="quest_giver",mapID=2112},questType="standard"},
[66937] = {id=66937,name="Decaying News",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The gnolls and their use of decay magic are concerning. We need to gather as much knowledge as we can, in case the threat escalates. As alchemists, we are used to gathering such foul substances safely--plus, we're used to the smell. Will you lend your aid?",starts={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},ends={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},coords={x=0.366,y=0.628,source="quest_giver",zoneID=13862},questType="standard"},
[66938] = {id=66938,name="Mammoth Marrow",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Creating new and unusual brews is one of our many specialties. While we do enjoy experimenting with new and fascinating ingredients, we have a few common ingredients that we keep in stock. One of these ingredients is the marrow from mammoth tusks. We have run short on marrow and would appreciate your help in collecting more for our alchemists.",starts={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},ends={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},coords={x=0.366,y=0.63,source="quest_giver",zoneID=13862},questType="standard"},
[66939] = {id=66939,name="Hunting the Huntmaster",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I heard from one of the guards in Camp Nowhere that there's a nasty piece of work mutilating the local wildlife. Calls itself a 'huntmaster'. Hunting is one thing, but I can't abide torturing any living thing. Besides, my wagon could use a good luck charm. Bring me back its paw.",starts={{npcID=191205,x=0.466,y=0.386,zoneID=13646}},ends={{npcID=194590,x=0.632,y=0.584,zoneID=13646}},coords={x=0.466,y=0.386,source="quest_giver",zoneID=13646},questType="standard"},
[66940] = {id=66940,name="Elixir Experiment",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Our alchemists have recently looked into a variety of new ingredients for experimentation. Their most recent interest is... interesting... to say the least. It appears that gorloc mucus has some properties that can be beneficial for certain elixirs.",starts={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},ends={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},coords={x=0.366,y=0.63,source="quest_giver",zoneID=13862},questType="standard"},
[66941] = {id=66941,name="Tremendous Tools",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The djaradin have some mighty large tools and weaponry. We can easily find a use for such tools, even if only to smelt them down into more tools for ourselves. Bring back some djaradin tools for us to study and use.",starts={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},ends={{npcID=191002,x=0.366,y=0.63,zoneID=13862}},coords={x=0.366,y=0.63,source="quest_giver",zoneID=13862},questType="standard"},
[66942] = {id=66942,name="Enemy Engineering",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="It may be a bit controversial, but I believe that we can study the rituals of the Primalists to learn new ways to channel elemental power. I'm confident that once we understand the pathways of their magic, we can use it to create all sorts of innovative engineering products.",starts={{npcID=191001,x=0.368,y=0.626,zoneID=13862}},ends={{npcID=191001,x=0.368,y=0.626,zoneID=13862}},coords={x=0.368,y=0.626,source="quest_giver",zoneID=13862},questType="standard"},
[66943] = {id=66943,name="Wood for Writing",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="We've found some unusual information in our studies of the Dragon Isles. For instance, the bark of treants afflicted by decay magic acts similarly to hide parchment. This odd parchment is strangely able to hold the magic for more powerful inscriptions. Very useful! Can you help us gather some?",starts={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},ends={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},coords={x=0.366,y=0.628,source="quest_giver",zoneID=13862},questType="standard"},
[66944] = {id=66944,name="Peacock Pigments",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The peacocks of the Dragon Isles have such colorful feathers! I bet we can make some pigments from them for our scribes to use as ink.",starts={{npcID=191001,x=0.368,y=0.626,zoneID=13862}},ends={{npcID=191001,x=0.368,y=0.626,zoneID=13862}},coords={x=0.368,y=0.626,source="quest_giver",zoneID=13862},questType="standard"},
[66945] = {id=66945,name="Icy Ink",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The icy beasts in the frozen biomes excrete a very rare and mysterious liquid. The liquid's properties make it the perfect binding agent for our inks. I'm a southpaw so the prospect of not smudging my page is very exciting to me.",starts={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},ends={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},coords={x=0.366,y=0.628,source="quest_giver",zoneID=13862},questType="standard"},
[66948] = {id=66948,name="The Emissary's Arrival",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I will admit that I have not left the Emerald Gardens in all my life, and as such, I have never met a centaur, let alone a mortal from the mainland. However, I am not here for a kindly visit, but rather to plead for the centaur's aid in securing our oathstone and protecting our charge. I am glad to see you are here to help as well. There is much to discuss.",starts={{npcID=194927,x=0.61,y=0.404,zoneID=13645}},ends={{npcID=194927,x=0.61,y=0.404,zoneID=13645}},coords={x=0.61,y=0.404,source="quest_giver",zoneID=13645},questType="standard"},
[66949] = {id=66949,name="Trinket Bandits",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The gnolls have quite a collection of trinkets. Tuskarr trinkets. They have either stolen them from our villages, or worse, from the brave tuskarr that fell in battle against them. These trinkets are our heritage and should reside with us. If you bring some back to me, I will teach you the techniques that are used to make them.",starts={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},ends={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},coords={x=0.368,y=0.624,source="quest_giver",zoneID=13862},questType="standard"},
[66950] = {id=66950,name="Heart of a Giant",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="There are various giants within the Dragon Isles that are rumored to contain beautiful gems at their core. We normally don't hunt the creatures of the Isles for treasures, but these giants have caused quite a bit of havoc. We may as well collect these gems in the process of clearing out the destructive giants.",starts={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},ends={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},coords={x=0.368,y=0.624,source="quest_giver",zoneID=13862},questType="standard"},
[66951] = {id=66951,name="Population Control",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Recently there has been an overpopulation of a few different species on the Dragon Isles. In particular, the rockfang and the bruffalon. We don't want to be wasteful, of course. Be sure to collect as much of the hides as you can from the creatures.",starts={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},ends={{npcID=191004,x=0.368,y=0.624,zoneID=13862}},coords={x=0.368,y=0.624,source="quest_giver",zoneID=13862},questType="standard"},
[66952] = {id=66952,name="The Gnoll's Clothes",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The gnolls are a constant threat, launching bloody raids and attacks against the expeditions and peoples of the Dragon Isles. So how are their clothes so clean? After your battles with these raiders, could you collect a sample of their worn cloth for me to analyze?",starts={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},ends={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},coords={x=0.366,y=0.628,source="quest_giver",zoneID=13862},questType="standard"},
[66953] = {id=66953,name="All Things Fluffy",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The tailors are always anxious to get their hands on that fluffy argali fur. The wool is especially useful for surviving in the freezing cold mountains of the Dragon Isles.",starts={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},ends={{npcID=191000,x=0.366,y=0.628,zoneID=13862}},coords={x=0.366,y=0.628,source="quest_giver",zoneID=13862},questType="standard"},
[66956] = {id=66956,name="Dragonhunter Igordan",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66957] = {id=66957,name="A Shadow In The Ice",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I've heard whispers while passing through Camp Antonidas. Talk of mutilated fauna being found across the icy steppes. Some nothing more than bloody splatters. Whatever it is, it's got the mages scared and made the local wildlife scarce. Poke around the top of the glacier. If I was a betting dwarf, I'd say that's where any apex predator worth its salt would stake its claim. Bring me a piece of it so we can soothe the Kirin Tor.",starts={{npcID=191205,x=0.466,y=0.386,zoneID=13646}},ends={{npcID=194590,x=0.632,y=0.584,zoneID=13646}},coords={x=0.466,y=0.386,source="quest_giver",zoneID=13646},questType="standard"},
[66958] = {id=66958,name="Protect And Herd",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I was talking with some hunters out of Iskaara the other day, and they mentioned finding a grisly scene. Apparently, a particularly murderous rhino, Bloodhorn, has been goring the smaller bruffalon in the area. The bruffalon have enough competition in Azure Span without worrying about getting their herds thinned out by an invasive brute from out of town! Bring me his horn. I'd like to make a good impression on our Tuskarr friends!",starts={{npcID=191205,x=0.466,y=0.386,zoneID=13646}},ends={{npcID=194590,x=0.632,y=0.584,zoneID=13646}},coords={x=0.466,y=0.386,source="quest_giver",zoneID=13646},questType="standard"},
[66959] = {id=66959,name="Tour the Trading Post",level=1,requiredLevel=1,faction="horde",expansion=9,zoneID=1637,description="Rare antiquities from every corner of Azeroth! Fine goods fit for any taste! You will not find these unique treasures anywhere else, friend. Come see us at one of our outposts in Orgrimmar or Dornogal and gaze in wonder upon the mysteries in store for you! --Zen' shiri Trading Post Be sure to present this flyer for some extra Trader's Tender !",ends={{npcID=185472,x=0.488,y=0.762,zoneID=1637}},questType="standard"},
[66960] = {id=66960,name="Klozicc the Ascended",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66963] = {id=66963,name="Out For Delivery",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I tried to tell Vevesi that I could pull the wagon out of the mud. But, no, he insisted on using magic to get it out... And now look what he's done. Hauler Bennet sighs.> While I try to talk sense into Vevesi, can you run up the hill to the Basecamp and let Cataloger Wulferd know that he might need to ship another crate of camera supplies over from Boralus?",starts={{npcID=191698,x=0.484,y=0.788,zoneID=13644}},ends={{npcID=187705,x=0.484,y=0.826,zoneID=13644}},coords={x=0.484,y=0.788,source="quest_giver",zoneID=13644},questType="standard"},
[66964] = {id=66964,name="Artifacts in the Wrong Hands",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We've got a myriad, no, an incalculable number of problems here! Oh man, where to start! The Kirin Tor uncovered a Sundered Flame plot. They're after an artifact called \"Valthrux\". It's immensely powerful and... sentient? That's an exponential increase in danger if you're keeping track. One Alia Sunsoar went south with a pair of tuskarr to investigate the Sundered Flame. She should have been back by now. Please find her and stop the Sundered Flame from acquiring the artifact!",starts={{npcID=196545,x=0.658,y=0.252,zoneID=13646}},ends={{npcID=196254,x=0.672,y=0.444,zoneID=13646}},coords={x=0.658,y=0.252,source="quest_giver",zoneID=13646},questType="standard"},
[66968] = {id=66968,name="Pruning The Pack",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="See those imprints in the snow? Yeti tracks. Something must of riled them up to hunt this close to the road. See if you can't hunt down their pack leader. We don't want them to start ambushing travellers! If he's a particularly mean brute, collect his head. That should dissuade the others.",starts={{npcID=191205,x=0.466,y=0.386,zoneID=13646}},ends={{npcID=194590,x=0.632,y=0.584,zoneID=13646}},coords={x=0.466,y=0.386,source="quest_giver",zoneID=13646},questType="standard"},
[66969] = {id=66969,name="Clans of the Plains",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="While you wait for the emissary to arrive, Sansok Khan is interested to hear how meeting the clans went. She sent me to find you and tell you to meet her in the center of Maruukai to discuss.",ends={{npcID=191283,x=0.614,y=0.396,zoneID=13645}},questType="standard"},
[66970] = {id=66970,name="Ty'foon the Ascended",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[66971] = {id=66971,name="The Face of Death",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Tell me, friend. Have you ever seen the face of death? What am I saying? Of course you have. Death, after all, has many faces. I've heard tell from the Imbu tuskarr that one of its faces lives up in these hills. To even say its name is to invite a violent, frigid death: Frostjaw. Well, now you have to hunt it--for my sake at least!",starts={{npcID=191205,x=0.466,y=0.386,zoneID=13646}},ends={{npcID=194590,x=0.632,y=0.584,zoneID=13646}},coords={x=0.466,y=0.386,source="quest_giver",zoneID=13646},questType="standard"},
[66972] = {id=66972,name="Old Stonetusk",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I have a grim task for you, $p. Not every kill is a measure of skill. Some are measures of kindness. There's an old bull mammoth wandering the forest east of Camp Antonidas. I saw him from a distance awhile back, and I hear his sad trumpeting every so often. Clearly he's in great pain. He's started crashing blindly through the undergrowth, and I'm worried he's becoming a danger to others. It'd make my old heart glad if you put a fellow weary soul to rest. Bring me his tusk so we can honor him.",starts={{npcID=191205,x=0.466,y=0.386,zoneID=13646}},ends={{npcID=194590,x=0.632,y=0.584,zoneID=13646}},coords={x=0.466,y=0.386,source="quest_giver",zoneID=13646},questType="standard"},
[66997] = {id=66997,name="Nursery Direction",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I'm so grateful that Lasztak has accepted the Calling of a Whelptender! Especially given how many of the precious little things are teething right now. Beyond that, the nursery gardens are admittedly facing challenges. The whelps are stressed and the tenders are--well, more stressed than usual. Please, whenever you have a spare moment, find me in the gardens below. We could use your help as well!",starts={{npcID=191174,x=0.618,y=0.736,zoneID=13644}},ends={{npcID=190525,x=0.552,y=0.634,zoneID=13644}},coords={x=0.618,y=0.736,source="quest_giver",zoneID=13644},questType="standard"},
[66998] = {id=66998,name="Fighting Fire with... Water",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="In all my years of tending to the lava elementals, I have never seen them act like this! We can barely keep them contained to the cave. Do you have a minute to spare? We'll hold the exit while you thin their numbers inside. Here, take this bottled water elemental with you. I always carry a few spare bottled water elementals when I'm looking after the lava elementals. Natural enemies make for good distractions!",starts={{npcID=188297,x=0.59,y=0.348,zoneID=13644}},ends={{npcID=188297,x=0.59,y=0.348,zoneID=13644}},coords={x=0.59,y=0.348,source="quest_giver",zoneID=13644},questType="standard"},
[67004] = {id=67004,name="Good Things in Large Boxes",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Our efforts have created everything we need to open an Earth-Warder's Vault . There are several beneath the Citadel. Locate one and I will reward you. I have crafted chains to help move it. If you bring the Vault here, we can share in the riches. Watch for the Vault being moved, as I have dispatched others to find them as well.",starts={{npcID=188179,x=0.248,y=0.604,zoneID=13644}},ends={{npcID=188179,x=0.248,y=0.604,zoneID=13644}},coords={x=0.248,y=0.604,source="quest_giver",zoneID=13644},questType="standard"},
[67007] = {id=67007,name="Archival Assistance",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13862,description="ADVENTURE SEEKERS, ARCHIVAL ENTHUSIASTS-- The archives call to those who seek answers, yearn to discover, and those who wish to reveal secrets of the past, and perhaps, the future! This request is not for the faint of heart, nor those of wavering will. Only curious and brave adventurers need apply. - Kemora",starts={{npcID=381687,x=0.558,y=0.485,zoneID=13642},{npcID=381687,x=0.477,y=0.468,zoneID=13862}},ends={{npcID=189973,x=0.348,y=0.28,zoneID=13862}},coords={x=0.558,y=0.485,source="quest_giver",zoneID=13642},questType="standard"},
[67011] = {id=67011,name="Tale of an Adventure: Molten Core",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13646,mapID=2024,description="So, you want to tell me a story of your adventure?",questType="standard"},
[67033] = {id=67033,name="Assemble the Defenses",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The Primalists have been hunting the Kirin Tor since we arrived in the Azure Span . They detest our practice of arcane magic. I'll send word to Kalecgos to return from the Azure Archives. In the meantime, we need to hold them off. It seems one of our main arcane defenses was destroyed in their initial attack. Bring the pieces back to me and I can reassemble it.",starts={{npcID=183543,x=0.466,y=0.4,zoneID=13646}},ends={{npcID=183543,x=0.466,y=0.4,zoneID=13646}},coords={x=0.466,y=0.4,source="quest_giver",zoneID=13646},questType="standard"},
[67034] = {id=67034,name="Of Wind and Water",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="To the east is a great dragonspring which serves as a nesting area for wild eagles. The feathers they shed still contain their magic for quite some time and are used in many rituals. The area also hosts raging spirits of the elements, and their cores are of some use as well. Bring a collection of both back to me - and remember that the eagles are sacred, I will not accept feathers that are gathered from their harm.",starts={{npcID=185867,x=0.558,y=0.518,zoneID=13645}},ends={{npcID=185867,x=0.558,y=0.518,zoneID=13645}},coords={x=0.558,y=0.518,source="quest_giver",zoneID=13645},questType="standard"},
[67035] = {id=67035,name="Preservation of Knowledge",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Greetings, . I am Althanus . I wish we could have met in a less... chaotic time. We were helping the Kirin Tor study the history of this place just a few moments before the Primalists attacked. I fear several tomes may still be out there, at risk of being destroyed in this dreadful assault. Please, you must recover these tomes! If they're destroyed, the history of this place will be lost.",starts={{npcID=192222,x=0.466,y=0.398,zoneID=13646}},ends={{npcID=192222,x=0.466,y=0.398,zoneID=13646}},coords={x=0.466,y=0.398,source="quest_giver",zoneID=13646},questType="standard"},
[67036] = {id=67036,name="Wrath of the Kirin Tor",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I've assembled the pieces of the device you recovered. Place it near Khadgar and use it to repel the Primalists! We just need to hold out a little longer until Kalecgos arrives.",starts={{npcID=183543,x=0.466,y=0.4,zoneID=13646}},ends={{npcID=183543,x=0.466,y=0.4,zoneID=13646}},coords={x=0.466,y=0.4,source="quest_giver",zoneID=13646},questType="standard"},
[67039] = {id=67039,name="An Amazing Journey",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="A few of the clan's pets ended up getting lost along the last journey between camps. They're not hunting animals so I doubt they can take care of themselves properly out there! Do you think you could go search for them? They may not be hunting partners, but they're important members of the clan regardless!",starts={{npcID=185881,x=0.706,y=0.628,zoneID=13645}},ends={{npcID=185880,x=0.704,y=0.628,zoneID=13645}},coords={x=0.706,y=0.628,source="quest_giver",zoneID=13645},questType="standard"},
[67044] = {id=67044,name="Tale of a Hero: Yanikk",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=7558,mapID=641,description="Let me tell you the tale of Yanikk.",questType="standard"},
[67047] = {id=67047,name="Warm Away These Shivers",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="I believe the plant you're looking for has a fine, narrow stem and red leaves all about it. You'll be hard-pressed not to run into any of those dastardly crawlers while you're collecting flowers though. I'd advise you steer clear when you can, or ready a sharp weapon when you can't. And let your dragon friend know they can repay me in a cup or two of the stuff next time I'm in the city.",starts={{npcID=185778,x=0.516,y=0.62,zoneID=13646}},ends={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},coords={x=0.516,y=0.62,source="quest_giver",zoneID=13646},questType="standard"},
[67050] = {id=67050,name="Frostbite: Causes and Symptoms",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Elements live in the totems, . Release them and break the ice. Free your tuskarr friends!",starts={{npcID=189625,x=0.584,y=0.42,zoneID=13646}},ends={{npcID=189963,x=0.592,y=0.398,zoneID=13646}},coords={x=0.584,y=0.42,source="quest_giver",zoneID=13646},questType="standard"},
[67051] = {id=67051,name="Dragon Eyes",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="We know the djaradin will attack us directly, but I'm worried about other dangers out there as well. Ones that aren't so obvious. I have dispatched three dragons to survey the surrounding area and pinpoint any potential threats. Meet with each of them. Collect their reports for me. Once you have gathered this information, return to me so we can best prepare for what the djaradin are planning.",starts={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},ends={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},coords={x=0.276,y=0.564,source="quest_giver",zoneID=13644},questType="standard"},
[67053] = {id=67053,name="Give Peace a Chance",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=13644,description="Light be with you, $p. This expedition is under the protection of both the Horde and Alliance. Our orders are clear: give aid to any members of the expedition, regardless of their other allegiances. The Horde's representatives, Warlord Grimaxe and her daughter Shuja, stand guard on the other side of camp. I fought with Warlord Grimaxe against the scourge. She is noble and will serve this expedition well. Go offer her your assistance. Show her that the Alliance honors its commitments.",starts={{npcID=184449,x=0.766,y=0.344,zoneID=13644}},ends={{npcID=184452,x=0.762,y=0.33,zoneID=13644}},coords={x=0.766,y=0.344,source="quest_giver",zoneID=13644},questType="standard"},
[67063] = {id=67063,name="10,000 Years of Roasting",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Spices? Oh! Ya must be with da big 'ol dragon cook. Da one with a little duck chef on her head. Djaradin collect up a powder, Spicy Lava Spices , off da fiery elementals down below. Don' you look at me like dat! It's what da Djaradin be calling dem, not me! Good luck down there. I wouldn't go alone if was you.",starts={{npcID=189207,x=0.254,y=0.542,zoneID=13644}},ends={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},coords={x=0.254,y=0.542,source="quest_giver",zoneID=13644},questType="group"},
[67064] = {id=67064,name="Rambling Delight",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Oh, Rumiastrasza ! Myself and the dryad sisters, Celina and Felina, had a lovely evening cooking for her. The kelp we ate is a unique strain called Glimmering Ramblekelp. Swarms of frillfish devour them all along the coast. I wouldn't be surprised if they attack you while you're plucking their food from the sea floor. Please give the chefs my best when you see them. They're always welcome here in our sanctuary.",starts={{npcID=186502,x=0.286,y=0.604,zoneID=13645}},ends={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},coords={x=0.286,y=0.604,source="quest_giver",zoneID=13645},questType="standard"},
[67065] = {id=67065,name="Future-Fresh Fungi",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13992,description="A delicious mushroom? Alternate futures are not pantries to be raided for midmorning snacks. But still... I would be lying if I said I had never dreamed of eating Rumi and Morsel's cooking again. Very well! You have my permission to pass through the portal, though I advise you to find others to travel with. My wardens have mentioned these dark mushrooms to me before. Apparently, they never stay in the same place for very long. Make of that what you will.",starts={{npcID=187025,x=0.602,y=0.822,zoneID=13647}},ends={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},coords={x=0.602,y=0.822,source="quest_giver",zoneID=13647},questType="group"},
[67066] = {id=67066,name="Delights to Delve For",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Rumi and Morsel? Gosh, that was quite a long time ago now. Eating a fish with a dragon and duck chef duo sounds like the beginning of a tale Elder Poa might tell for the younglings. We'd be hard-pressed to forget such a happening! The fish was a Savory Deviant Dealfish , a top Tuskarr favorite! They're rare, but found just off the coast here. Fair warning - it's azuretooth mating season. Those bloodthirsty fiends will take a chunk out of you for messing with their favorite snack.",starts={{npcID=186212,x=0.074,y=0.442,zoneID=13646}},ends={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},coords={x=0.074,y=0.442,source="quest_giver",zoneID=13646},questType="standard"},
[67067] = {id=67067,name="Navigating the Leapmaize",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="There's a dragon chef in Valdrakken ? Truly? I'll have to ask her to try my arclight bisque! It's an old family recipe. I know the plant you speak of. It grows around streams here, but it's caused some problems. The stalks of leapmaize seem to be a natural feeding ground for beetles and small salamanthars, which are, in turn, natural prey of the hornswogs. That's fine if you can spot them out in the open, but there's a few here that are incredibly stealthy. I'd watch my back if I were you.",starts={{npcID=189400,x=0.652,y=0.58,zoneID=13644}},ends={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},coords={x=0.652,y=0.58,source="quest_giver",zoneID=13644},questType="standard"},
[67068] = {id=67068,name="Anything But a Breeze",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Breezehunters?! Oh, those falcons have been a problem. Just the other day, our stable master, Marren, almost fell to her death trying to tame one. She's pretty proud, so she blamed it on the breezehunter itself. Told me that if it didn't think her eggs were being attacked, it wouldn't have been so aggressive as to bully her off the cliff's edge. I guess that means that you might find the eggs you're looking for out there? It was to the east, just around the mountainside here.",starts={{npcID=196161,x=0.858,y=0.352,zoneID=13645}},ends={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},coords={x=0.858,y=0.352,source="quest_giver",zoneID=13645},questType="standard"},
[67071] = {id=67071,name="What a Long, Sweet Trip It's Been",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="! Just who Morsel and I were looking for! From the bottom of both of our winged-hearts, we thank you dearly. We started The Ruby Feast to share the Isles' culinary culture with all of Azeroth's races, and to learn from them too. We had you running from one end of our beloved continent to another, but you helped bring our dream vision of these gatherings to each honored visitor and guest here. As friends, we would like to give you a gift. Grab the top journal from our hoard behind the cauldron.",starts={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},ends={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},coords={x=0.614,y=0.118,source="quest_giver",zoneID=13862},questType="standard"},
[67073] = {id=67073,name="Red Dawn",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="We've come so close to recovering our powers... should Raszageth succeed before our powers return, I fear that the timeways will bend to a dark future for all of Azeroth. We must not allow this to occur, ! Hurry, you must find and aid Alexstrasza before all is lost!",starts={{npcID=192455,x=0.574,y=0.59,zoneID=13647}},ends={{npcID=190902,x=0.724,y=0.562,zoneID=13647}},coords={x=0.574,y=0.59,source="quest_giver",zoneID=13647},questType="standard"},
[67074] = {id=67074,name="The Gift of Silver",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13862,description="Shortly before his passing, Keeper Tyr gifted us with a dragon scale forged of purest silver. We kept it in the vaults of Valdrakken during our absence, but I believe it is time to share it once more. Though we have no idea the purpose for this memento, it has always been a symbol of unity and friendship to us. As a true ally to dragonkind, we would like to share it with you. Speak to me when you are ready, .",starts={{npcID=187678,x=0.58,y=0.358,zoneID=13862}},ends={{npcID=187678,x=0.58,y=0.358,zoneID=13862}},coords={x=0.58,y=0.358,source="quest_giver",zoneID=13862},questType="standard"},
[67075] = {id=67075,name="The Magic Within",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="Intriguing. There are many mysteries living within this citadel that no one, save Keeper Tyr himself, understand. If we are to unlock this further we shall have to explore more of Tyrhold. I believe that the scale will draw out secrets stored within this place. However. there is one complication. The guardians of Tyrhold are still... unstable. They may take your exploration as disruption and try to interfere. Take this conduit. It will help you should the guardians prove troublesome.",starts={{npcID=192480,x=0.604,y=0.588,zoneID=13647}},ends={{npcID=192480,x=0.604,y=0.588,zoneID=13647}},coords={x=0.604,y=0.588,source="quest_giver",zoneID=13647},questType="standard"},
[67076] = {id=67076,name="A Spark of Discovery",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="Though this spark is of peculiar origin, I sense it is familiar. I am not sure of its purpose, but I believe it may lead to your next step in unraveling this mystery. Follow it and see if you can learn more of its purpose, while I see what else I can discover in the meantime.",starts={{npcID=192480,x=0.604,y=0.588,zoneID=13647}},ends={{npcID=193492,x=0.622,y=0.594,zoneID=13647}},coords={x=0.604,y=0.588,source="quest_giver",zoneID=13647},questType="standard"},
[67077] = {id=67077,name="Memories of the Past",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="This place is where we last saw our friend, Tyr. We did not understand the circumstances by which he had to leave, only that it was for something important. Though it may be difficult for our hearts to bear, I believe this spark called us here to witness that time once more. With Nozdormu's aid we may relive that moment and see if there was some other clue Tyr left behind for us.",starts={{npcID=192573,x=0.602,y=0.586,zoneID=13647}},ends={{npcID=192573,x=0.602,y=0.586,zoneID=13647}},coords={x=0.602,y=0.586,source="quest_giver",zoneID=13647},questType="standard"},
[67078] = {id=67078,name="Parting Instructions",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="To my dear friends, I apologize for my sudden departure. But, I promise that you are not without my aid. I know that you have come upon the time of great need, but to ensure this gift does not get misused I must ask you to perform a series of tasks. The first is simple: reactivate the forge within Tyrhold. The Silver Scale is the key.",starts={{npcID=192496,x=0.604,y=0.586,zoneID=13647}},ends={{npcID=192480,x=0.604,y=0.588,zoneID=13647}},coords={x=0.604,y=0.586,source="quest_giver",zoneID=13647},questType="standard"},
[67079] = {id=67079,name="Hard Lock Life",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="The security in the forge is stricter than in any other area of Tyrhold. This will be quite a challenge for us, . Only certain units around the citadel have the capability to bypass this security, and the protocols to unlock require more than one code in case of corruption. These units will not want to relinquish their overrides, you may have to take them by force. Be careful, .",starts={{npcID=192480,x=0.604,y=0.588,zoneID=13647}},ends={{npcID=192480,x=0.604,y=0.588,zoneID=13647}},coords={x=0.604,y=0.588,source="quest_giver",zoneID=13647},questType="standard"},
[67080] = {id=67080,name="Artisan's Supply: Dragon's Alchemical Solution",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Are you looking for work, alchemist? The Artisan's Consortium has reached out to me with a \"crafting order\" for my alchemical solutions. I am as curious as the next dragonkin to find out more about these business practices, but I am simply too busy. Perhaps this is an opportunity for you, my apprentice. Create some alchemical solution by reclaiming your earlier concoctions, and bring it to Haephesta , just down the path.",starts={{npcID=191893,x=0.602,y=0.722,zoneID=13644}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},coords={x=0.602,y=0.722,source="quest_giver",zoneID=13644},questType="standard"},
[67081] = {id=67081,name="Halls of Infusion: An Infusion of Materials",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14082,description="You have reactivated the forge. The next task will not be as simple. Transcribed within the scale are schematics for something I require you to forge. I have entrusted one of my watchers, Irideus, with the necessary materials for this task. They are of special origin, and only few of them are left in existence. Seek Irideus within the Halls of Infusion, where I hope his careful watch has kept the facility operating in an orderly fashion.",starts={{npcID=192496,x=0.604,y=0.586,zoneID=13647}},ends={{npcID=192496,x=0.604,y=0.586,zoneID=13647}},coords={x=0.604,y=0.586,source="quest_giver",zoneID=13647},questType="dungeon"},
[67084] = {id=67084,name="The Silver Purpose",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="Your task is at hand, my friends. Cast the ingots into the fire and activate the forge. I have prepared the necessary procedures for you already. The Silver Scale holds the schematic. Its purpose shall reveal itself to you.",starts={{npcID=192496,x=0.604,y=0.586,zoneID=13647}},ends={{npcID=192573,x=0.602,y=0.586,zoneID=13647}},coords={x=0.604,y=0.586,source="quest_giver",zoneID=13647},questType="standard"},
[67093] = {id=67093,name="An Anomalous Shrine",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="My research team located a strange sanctum nearby. We were able to make out some writing on the outside of it--titan runes, to be exact--which we believe reference Aman'Thul the Highfather, leader of the titans, in several places. We tried to inspect more closely but must have triggered the sanctum's defenses. A massive sand amalgam blocked us off and we narrowly made it out alive. We aren't certain what it's protecting, but it must be important. Can you investigate?",starts={{npcID=192543,x=0.602,y=0.82,zoneID=13647}},ends={{npcID=187669,x=0.608,y=0.392,zoneID=13862}},coords={x=0.602,y=0.82,source="quest_giver",zoneID=13647},questType="standard"},
[67094] = {id=67094,name="A Dryad's Work Is Never Done",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="It is wonderful to see Valdrakken so lively again, but there are so many things that have wilted under thousands of years of neglect - not the least of which are all of the adorable little city critters! Alas, we don't have enough dryads to go around tending to them all. Say, how would you like to be appointed Honorary Valdrakken Dryad? Some of the city's cutest little friends have gone far too long without their preferred snacks. Won't you help me tend to them?",starts={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},ends={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},coords={x=0.728,y=0.66,source="quest_giver",zoneID=13862},questType="standard"},
[67099] = {id=67099,name="Dragon Eyes",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="We know the djaradin will attack us directly, but I'm worried about other dangers out there as well. Ones that aren't so obvious. I have dispatched three dragons to survey the surrounding area and pinpoint any potential threats. Meet with each of them. Collect their reports for me. Once you have gathered this information, return to me so we can best prepare for what the djaradin are planning.",starts={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},ends={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},coords={x=0.276,y=0.564,source="quest_giver",zoneID=13644},questType="standard"},
[67100] = {id=67100,name="A Gift for Miguel",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="$p, could you do me a favor? I want to get a gift for my husband, Miguel. He means so much to me, but I've been so busy lately that I haven't had time to make him anything. Could you help me make him something high quality?",starts={{npcID=192574,x=0.602,y=0.722,zoneID=13644},{npcID=192574,x=0.394,y=0.698,zoneID=13862}},ends={{npcID=192574,x=0.602,y=0.722,zoneID=13644},{npcID=192574,x=0.394,y=0.698,zoneID=13862}},coords={x=0.602,y=0.722,source="quest_giver",zoneID=13644},questType="standard"},
[67111] = {id=67111,name="The Ailing Apprentice",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="This mission was a mistake from the beginning. Alia Sunsoar enlisted our aid to keep the Sundered Flame from acquiring a dangerous artifact. We had tracked it down to these ruins. But the Sundered Flame beat us here and the area is infested with ice spiders. Alia was badly poisoned, and I fear she will not last long without the antidote. I can make it, but I need venom glands from the nearby spiders. I'm afraid to leave her. Will you find some for me?",starts={{npcID=196254,x=0.672,y=0.444,zoneID=13646}},ends={{npcID=196254,x=0.672,y=0.444,zoneID=13646}},coords={x=0.672,y=0.444,source="quest_giver",zoneID=13646},questType="standard"},
[67137] = {id=67137,name="Professionally Equipped",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Say, I heard from Haephesta that you're a working artisan as well. We'd like to get you set up with some professional equipment. Free of charge. That's what business partners are for, right? Talk to our tailor, Mahra Treebender , to get fitted.",starts={{npcID=192539,x=0.598,y=0.716,zoneID=13644},{npcID=192539,x=0.718,y=0.81,zoneID=13645},{npcID=192539,x=0.394,y=0.698,zoneID=13862}},ends={{npcID=192674,x=0.61,y=0.7,zoneID=13644}},coords={x=0.598,y=0.716,source="quest_giver",zoneID=13644},questType="standard"},
[67142] = {id=67142,name="Wyrm Food",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="It's hungry work, defending and fighting for the Obsidian Citadel, and dragons can eat a great deal. We need to replenish our stores. Lurking beneath the hardened lava, squirming through the magma, are some very tasty worms. This may not appeal to you, but to a hungry dragon, they are delicious. Take our servant Gulchak and use his pointer to direct him towards disturbances in the lava. He will attract the worms for you to harvest.",starts={{npcID=196518,x=0.276,y=0.566,zoneID=13644}},ends={{npcID=196518,x=0.276,y=0.566,zoneID=13644}},coords={x=0.276,y=0.566,source="quest_giver",zoneID=13644},questType="standard"},
[67143] = {id=67143,name="To Give One's Heart",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,description="Now that we have the elemental essence gathered, do you think you could put them in this bottle? It's a simple recipe that you can craft the same way as any other recipe. If you lost, or use up the high-quality reagents, you can always get more from the elementals at Hornswog Hollow.",starts={{npcID=192574,x=0.602,y=0.722,zoneID=13644},{npcID=192574,x=0.394,y=0.698,zoneID=13862}},ends={{npcID=192539,x=0.598,y=0.716,zoneID=13644},{npcID=192539,x=0.394,y=0.698,zoneID=13862},{npcID=192539,x=0.718,y=0.81,zoneID=13645}},coords={x=0.602,y=0.722,source="quest_giver",zoneID=13644},questType="standard"},
[67154] = {id=67154,name="Entropic Remnants",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="When an entity passes through the timeways, the sands of time can sometimes accumulate on their body. Typically, this sand dissipates in short order--but sometimes, the entropic fluctuations inherent in time travel can cause that sand to vitrify. In these cases, it becomes rather difficult to remove. I've ruined several good pairs of shoes this way. Vitrified sand can be quite powerful for our purposes. It would be in best interest to reclaim as much of it as we can.",starts={{npcID=192543,x=0.602,y=0.82,zoneID=13647}},ends={{npcID=192543,x=0.602,y=0.82,zoneID=13647}},coords={x=0.602,y=0.82,source="quest_giver",zoneID=13647},questType="standard"},
[67167] = {id=67167,name="It's Time To Duel!",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13642,description="With my deck back, I can focus on recruiting new members to my club! I was thinking about asking the dracthyr... Oh, that is another thing you can help me out with, ! I am going to be a bit busy trying to get other dragons to join and I really want to get the dracthyr involved. Do you mind talking to them for me? Be warned; many of them have never played before.",starts={{npcID=191414,x=0.606,y=0.432,zoneID=13647}},ends={{npcID=191414,x=0.606,y=0.432,zoneID=13647}},coords={x=0.606,y=0.432,source="quest_giver",zoneID=13647},questType="standard"},
[67174] = {id=67174,name="Arcane Detection",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Greetings! I am Miva Star-Eye , and I am conducting arcane investigations in this area. The Azure Span has magic all around it. Some of it is benign... while some can be quite dangerous. I've been tasked with ensuring no arcane energies reside in anything the tuskarr possess. We already had one incident in Camp Antonidas of a fishing box spontaneously combusting! Can you take my detector and examine a few objects here? I need to continue speaking with Julk over here.",starts={{npcID=192750,x=0.412,y=0.358,zoneID=13646}},ends={{npcID=192750,x=0.412,y=0.358,zoneID=13646}},coords={x=0.412,y=0.358,source="quest_giver",zoneID=13646},questType="standard"},
[67175] = {id=67175,name="How To Stop An Exploding Toy Boat",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I am loathe to part a child from their toy, but it would be a great value to the Kirin Tor to study how it absorbed so much arcana. Then again... I do not want to slight our new tuskarr allies. I do have a wand that could dispel the magic... Let's speak with Toolk's mother, then decide what to do.",starts={{npcID=192750,x=0.412,y=0.358,zoneID=13646}},ends={{npcID=192750,x=0.412,y=0.358,zoneID=13646}},coords={x=0.412,y=0.358,source="quest_giver",zoneID=13646},questType="standard"},
[67177] = {id=67177,name="WANTED: Gorger",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="If you are going to be amongst the tuskarr, you would do well to lend a hand! As of late, a beast we call Gorger has been making its home nearby. More of its kind seem to be migrating to this area. This is something we can take advantage of. Kill the Gorger and bring me its horns. We'll need them for building supplies to expand this outpost.",starts={{npcID=192760,x=0.414,y=0.364,zoneID=13646}},ends={{npcID=192760,x=0.414,y=0.364,zoneID=13646}},coords={x=0.414,y=0.364,source="quest_giver",zoneID=13646},questType="group"},
[67178] = {id=67178,name="White Eyes, Blue Dragon",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="$PC can you make sure the match happens as fairly as possible? Setogosa is known for bending the rules to suit her whims. I would not wish to see Yumadormu lose due to cheating.",starts={{npcID=192733,x=0.58,y=0.404,zoneID=13647}},ends={{npcID=191414,x=0.606,y=0.432,zoneID=13647}},coords={x=0.58,y=0.404,source="quest_giver",zoneID=13647},questType="standard"},
[67221] = {id=67221,name="A Head for Metal",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="To fully utilize the potential of the Earth-Warder's forge, you must learn the basics of creating Obsidian Seared Alloy. Only then can you follow in the footsteps of Neltharion's greatest smiths. Bring me a piece of Crystallized Draconium found deep within the Cindershard Seam. Then I shall gift you the knowledge you desire.",starts={{npcID=191194,x=0.246,y=0.61,zoneID=13644}},ends={{npcID=191194,x=0.246,y=0.61,zoneID=13644}},coords={x=0.246,y=0.61,source="quest_giver",zoneID=13644},questType="standard"},
[67222] = {id=67222,name="Darkened Clouds",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Primalists have infected Windsong Rise with their nonsense teachings. Our kin there are foolish to entertain their ideas. If we assist with clearing this sacred ground of their presence, perhaps the other clans will come to our aid in time of need. Do you think you could assist?",starts={{npcID=185853,x=0.714,y=0.31,zoneID=13645}},ends={{npcID=185853,x=0.714,y=0.31,zoneID=13645}},coords={x=0.714,y=0.31,source="quest_giver",zoneID=13645},questType="standard"},
[67295] = {id=67295,name="That's My Specialty",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13862,description="So, you've started taking up a specialization, eh? 'Tis a glorious thing to have an exclusive skill you can call your own. As a member of the Artisan's Consortium, I would be delighted to help you on your journey to honing your specialization. Have you a minute to listen to my words of wisdom, and perhaps learn something to help you on your adventures?",starts={{npcID=192539,x=0.598,y=0.716,zoneID=13644},{npcID=192539,x=0.718,y=0.81,zoneID=13645},{npcID=192539,x=0.394,y=0.698,zoneID=13862}},ends={{npcID=192539,x=0.598,y=0.716,zoneID=13644},{npcID=192539,x=0.718,y=0.81,zoneID=13645},{npcID=192539,x=0.394,y=0.698,zoneID=13862}},coords={x=0.598,y=0.716,source="quest_giver",zoneID=13644},questType="standard"},
[67298] = {id=67298,name="The Wonders of the World",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13862,description="My husband Thomas has gained many insights from exploring these primal lands. Perhaps following in his footsteps would similarly inspire you?",starts={{npcID=192539,x=0.598,y=0.716,zoneID=13644},{npcID=192539,x=0.718,y=0.81,zoneID=13645},{npcID=192539,x=0.394,y=0.698,zoneID=13862}},ends={{npcID=193548,x=0.46,y=0.598,zoneID=13645}},coords={x=0.598,y=0.716,source="quest_giver",zoneID=13644},questType="standard"},
[67299] = {id=67299,name="Drakes be Gone",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The primalists have been ceaselessly attacking our camp with their drakes! We've been able to keep them at bay with our shields, but we could use more aid in taking them out of the sky. Use one of our blasters to take those drakes down!",starts={{npcID=189751,x=0.658,y=0.254,zoneID=13646}},ends={{npcID=189751,x=0.658,y=0.254,zoneID=13646}},coords={x=0.658,y=0.254,source="quest_giver",zoneID=13646},questType="standard"},
[67564] = {id=67564,name="Artisan's Courier",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Adventurer, are you headed into the Lifeshrine? Would you mind taking this invoice to Thomas Bright ? He ordered a few custom-made bottles and our glassblower has finally returned with the price of materials required. He should be just down the path there, likely gushing to some poor soul about how great his husband is... I am sure he will pay you for your time.",starts={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},ends={{npcID=192574,x=0.602,y=0.722,zoneID=13644},{npcID=192574,x=0.394,y=0.698,zoneID=13862}},coords={x=0.578,y=0.682,source="quest_giver",zoneID=13644},questType="standard"},
[67605] = {id=67605,name="Thundering Plains",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="There is a great storm beast which wanders this ridge. Many a Shikaar hunter has attempted to take it down, only to fall to its ferocity. If you wish for some hunting glory, you may attempt to bring down the beast. Bring back its horn as tribute.",starts={{npcID=185870,x=0.556,y=0.524,zoneID=13645}},ends={{npcID=185870,x=0.556,y=0.524,zoneID=13645}},coords={x=0.556,y=0.524,source="quest_giver",zoneID=13645},questType="group"},
[67606] = {id=67606,name="A Dryadic Remedy",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="While you were gone, I heard from a dreamhare that one of the local ducklings is feeling rather down in the dumps. Luckily, I know exactly how to fix that! Whenever I'm feeling moody, I snack on something sweet and tasty! As an expert in cute, lovable creatures, I know that the same principle will surely apply here. This particular duckling is fond of a local dessert known as a Tasty Hatchling's Treat. Won't you find one and bring it to the poor dear? It's the dryadic thing to do, after all!",starts={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},ends={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},coords={x=0.728,y=0.66,source="quest_giver",zoneID=13862},questType="standard"},
[67700] = {id=67700,name="To the Dragon Isles!",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=13644,description="Great news, $p! The spearhead of our expedition has made landfall in the Dragon Isles . Thanks to the efforts of yerself and other Dragonscale Expedition members, we've established a protected landing site and made contact with the dragonflight's embassy. Are ye prepared to accompany us on our next voyage to the Dragon Isles ?",starts={{npcID=189077,x=0.228,y=0.556,zoneID=1519}},ends={{npcID=189022,x=0.82,y=0.318,zoneID=13644}},coords={x=0.228,y=0.556,source="quest_giver",zoneID=1519},questType="standard"},
[67722] = {id=67722,name="Break on Through",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="Toddy and Naleidea are preparing to head out. Meet at the Sealed Titan Facility in Thaldraszus. Apparently they've made a breakthrough. Be sure to bring any pertinent information back for cataloging!",starts={{npcID=189226,x=0.47,y=0.826,zoneID=13644}},ends={{npcID=191838,x=0.542,y=0.554,zoneID=13647}},coords={x=0.47,y=0.826,source="quest_giver",zoneID=13644},questType="standard"},
[67724] = {id=67724,name="The Fending Flames",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Kattigat and I came here to prove ourselves by stopping the Sundered Flame and recovering the Valthrux. Now we're stuck watching over this elf after she takes a few ice spider bites. We haven't even fought the Sundered Flame yet, and the spiders may do us in before we can! We need to keep them at bay. Thankfully, there's a natural way to repel them. Burning silk from their cocoons creates an aroma that repulses the spiders. Grab some silk and I'll throw it on the fire. It'll keep them away!",starts={{npcID=191715,x=0.672,y=0.444,zoneID=13646}},ends={{npcID=191715,x=0.672,y=0.444,zoneID=13646}},coords={x=0.672,y=0.444,source="quest_giver",zoneID=13646},questType="standard"},
[67741] = {id=67741,name="Archive Ambit",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[67772] = {id=67772,name="The Trouble with Taivan",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Hello, friend. Welcome back to Maruukai. I am Selbekh, healer of Clan Teerai. Are you good with animals, ? Perhaps the influence of a newcomer is just what I need. Taivan here, while a very good companion, has become something of a burden on my clan. I'm afraid if we can't find a good use for him, I may have to send him away. Will you help me?",starts={{npcID=192621,x=0.612,y=0.4,zoneID=13645}},ends={{npcID=192629,x=0.714,y=0.496,zoneID=13645}},coords={x=0.612,y=0.4,source="quest_giver",zoneID=13645},questType="standard"},
[67921] = {id=67921,name="The Hunting Hound",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Go and hunt the nearby beasts with your giant bakar. The bigger, the better. I will observe from here, and decide if he is worthy of Shikaar training. Be warned, I will only accept the best.",starts={{npcID=192629,x=0.714,y=0.496,zoneID=13645}},ends={{npcID=192629,x=0.714,y=0.496,zoneID=13645}},coords={x=0.714,y=0.496,source="quest_giver",zoneID=13645},questType="standard"},
[68083] = {id=68083,name="Try Again, Taivan!",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Return to the Teerai and tell them that not even I can train Taivan to be a hunter. He simply does not have it in him. He is the most un-ferocious bakar I have ever seen, and I bet he would even try to make friends with the wild game if we let him! Hah!",starts={{npcID=192629,x=0.714,y=0.496,zoneID=13645}},ends={{npcID=192621,x=0.612,y=0.4,zoneID=13645}},coords={x=0.714,y=0.496,source="quest_giver",zoneID=13645},questType="standard"},
[68084] = {id=68084,name="The Gentle Giant",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="If Taivan is really as \"un-ferocious\" as Jadar says he is, perhaps he'll be better suited as a herding bakar! The Aylaag are expert argali shepherds, and aren't so proud that they require lavish gifts to help another clan. Please send Taivan to Shepherd Tevatei at the Mallakh, a spot between two hills in the south-west where they train their bakar. Ohn'ahra, please let this work. If it doesn't, I'm all out of ideas.",starts={{npcID=192621,x=0.612,y=0.4,zoneID=13645}},ends={{npcID=192633,x=0.49,y=0.41,zoneID=13645}},coords={x=0.612,y=0.4,source="quest_giver",zoneID=13645},questType="standard"},
[68085] = {id=68085,name="Shaping a Shepherd",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="You want me to train your bakar in shepherding? Well, that's certainly what we do here, but I've never trained one quite so BIG before... The argali don't seem to be bothered by his presence, though, and they're very good judges of character. Trust me. I'm willing to give him a shot, but a herding bakar needs to not only be gentle, but smart, too. And if they aren't able to take charge of the herd, the argali won't obey them. It's harder than it looks! Go on and give it a try, I'll watch.",starts={{npcID=192633,x=0.49,y=0.41,zoneID=13645}},ends={{npcID=192633,x=0.49,y=0.41,zoneID=13645}},coords={x=0.49,y=0.41,source="quest_giver",zoneID=13645},questType="standard"},
[68087] = {id=68087,name="Danger in Daruukhan",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I guess there's nothing to be done but send you and Taivan back to Maruukai. Wait... who is that approaching? Not another stranger with a giant bakar, I hope!",starts={{npcID=192633,x=0.49,y=0.41,zoneID=13645}},ends={{npcID=192621,x=0.612,y=0.4,zoneID=13645}},coords={x=0.49,y=0.41,source="quest_giver",zoneID=13645},questType="standard"},
[68639] = {id=68639,name="Prowling Polar Predators",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="The species we've been sent to study is the frigidpelts. Their hunting grounds have been tainted by ley lines. Arcane energies leech into the water and into the plants... and into prey species like the slyvern. But unlike other organisms, the frigidpelts survive the process and gain power from it. They also become aggressive--which is a problem. Engage a few, and I will take notes on their strength and aggression. My report will help the Kirin Tor decide what to do for them.",starts={{npcID=192825,x=0.636,y=0.288,zoneID=13646}},ends={{npcID=192825,x=0.636,y=0.288,zoneID=13646}},coords={x=0.636,y=0.288,source="quest_giver",zoneID=13646},questType="standard"},
[68640] = {id=68640,name="Sudden Isolation",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="We used to trade frequently with the Uktulut tribe in the Waking Shores , but they haven't been sending or accepting shipments for months now. Our letters have gone unanswered. Naturally, we suspect the worst. Their chieftain, Tutaqan, has always been the reasonable sort. Somewhat prone to strong emotions, but I can't imagine anything terrible could have happened under his leadership. Could you please check on them? If they need help, we'll happily provide.",starts={{npcID=193006,x=0.13,y=0.492,zoneID=13646}},ends={{npcID=188301,x=0.55,y=0.382,zoneID=13644}},coords={x=0.13,y=0.492,source="quest_giver",zoneID=13646},questType="standard"},
[68641] = {id=68641,name="Mossing the Mark",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Poor girl... She must have gotten sick after eating something tainted. Luckily, my grandfather was a druid and taught me how to treat arcane-based illnesses. I don't have all the components on me, but we can make do with what's around. First, I will need some drakmoss. It is a rare lichen that only grows on dragon bones.",starts={{npcID=192830,x=0.636,y=0.288,zoneID=13646}},ends={{npcID=192830,x=0.636,y=0.288,zoneID=13646}},coords={x=0.636,y=0.288,source="quest_giver",zoneID=13646},questType="standard"},
[68642] = {id=68642,name="Needles to Say",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I want to help Sylvie, but I don't want to delay Cally any longer. To give Sylvie the medicine, I need arcane-infused quills from the crystalpine. I'm sure they won't mind if you pluck a few off! And mind the bakar! They eat crystalpine and might get mad at you touching it. If you do have to defend yourself, you can collect some spines from them as well. But... try not to do that, please.",starts={{npcID=192830,x=0.636,y=0.288,zoneID=13646}},ends={{npcID=192830,x=0.636,y=0.288,zoneID=13646}},coords={x=0.636,y=0.288,source="quest_giver",zoneID=13646},questType="standard"},
[68643] = {id=68643,name="Vitamins and Minerals",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I suppose I should have expected that Steria would be upset at me asking you to fight animals... There are of course alternative research methods. Take these vials and collect some water from the nearby ice crystals. I theorize that they contain minerals infused with ley crystal energy--and may be fueling the outbreak here.",starts={{npcID=192825,x=0.636,y=0.288,zoneID=13646}},ends={{npcID=192825,x=0.636,y=0.288,zoneID=13646}},coords={x=0.636,y=0.288,source="quest_giver",zoneID=13646},questType="standard"},
[68644] = {id=68644,name="Sugar, Spice, and Everything Nice",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="There! Now I have all I need for Sylvie ! And just in time. I doubt she would have lasted much longer like this. But... I need someone to help me. I'd ask Cally but... would you mind assisting me again? Let me know when or if you're ready, .",starts={{npcID=192830,x=0.636,y=0.288,zoneID=13646}},ends={{npcID=192830,x=0.636,y=0.288,zoneID=13646}},coords={x=0.636,y=0.288,source="quest_giver",zoneID=13646},questType="standard"},
[68794] = {id=68794,name="Ally of Dragons",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13862,description="Your aid to the Dragon Isles has not gone unnoticed, . The Life-Binder herself wishes to show you something as a reward for your service to dragonkind. Go and speak to her at the top of the tower. All the Aspects await you.",starts={{npcID=197478,x=0.456,y=0.552,zoneID=13862}},ends={{npcID=187678,x=0.58,y=0.358,zoneID=13862}},coords={x=0.456,y=0.552,source="quest_giver",zoneID=13862},questType="standard"},
[68795] = {id=68795,name="Skyriding",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="One thing you may have already discovered about this place: the Dragon Isles are vast. Some of the drakes have an intense interest in exploring every corner and secret hiding place in this renewed land, even those places that are not readily reached from the ground. They are eager for a second set of eyes to aid them in their journey, and in trade will gladly bear a rider across the lands. Speak with Lord Andestrasz , here in the Ruby Lifeshrine. He will explain more of what they intend.",starts={{npcID=187290,x=0.622,y=0.73,zoneID=13644}},ends={{npcID=193287,x=0.576,y=0.668,zoneID=13644}},coords={x=0.622,y=0.73,source="quest_giver",zoneID=13644},questType="standard"},
[68796] = {id=68796,name="The Skytop Observatory",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Those are the basics of riding a drake! You are doing quite well. Now, I would like to introduce you to some of the others involved in this adventure. We have made a home for ourselves over at the Skytop Observatory. Celormu will be able to help guide you there. Speak to him when you feel ready to take to the skies! See you there!",starts={{npcID=193287,x=0.576,y=0.668,zoneID=13644}},ends={{npcID=193359,x=0.752,y=0.55,zoneID=13644}},coords={x=0.576,y=0.668,source="quest_giver",zoneID=13644},questType="standard"},
[68797] = {id=68797,name="A New Set of Horns",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Just as mortals do, dragons care very much about their appearance. Your drake is able to change as well, according to what you find and experience. Speak to Glensera at the Rostrum of Transformation, and see for yourself!",starts={{npcID=193359,x=0.752,y=0.55,zoneID=13644}},ends={{npcID=193359,x=0.752,y=0.55,zoneID=13644}},coords={x=0.752,y=0.55,source="quest_giver",zoneID=13644},questType="standard"},
[68798] = {id=68798,name="Skyriding Talents and You",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Obviously, it is not just Glensera and myself that are invested in these adventurers. Lithragosa is also excited to help you hone your dragonriding skills, and you have already met Celormu which is excellent. Your next stop is to speak to Lithragosa , who can show you what skills you can learn!",starts={{npcID=193359,x=0.752,y=0.55,zoneID=13644}},ends={{npcID=193359,x=0.752,y=0.55,zoneID=13644}},coords={x=0.752,y=0.55,source="quest_giver",zoneID=13644},questType="standard"},
[68799] = {id=68799,name="Return to the Ruby Lifeshrine",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="And this is just the beginning of your dragonriding journey! Keep your eyes open for new adventures and experiences throughout the Dragon Isles, and be sure to visit us in any of our outposts. For now, return to Alexstrasza to continue your exploration in these lands.",starts={{npcID=193359,x=0.752,y=0.55,zoneID=13644}},ends={{npcID=187290,x=0.622,y=0.73,zoneID=13644}},coords={x=0.752,y=0.55,source="quest_giver",zoneID=13644},questType="standard"},
[68863] = {id=68863,name="A Lost Tribe",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="Hi, ! Murik wanted to talk to you about something real important back in Iskaara. You should go see what it is.",starts={{npcID=197631,x=0.456,y=0.554,zoneID=13862}},ends={{npcID=193006,x=0.13,y=0.492,zoneID=13646}},coords={x=0.456,y=0.554,source="quest_giver",zoneID=13862},questType="standard"},
[69093] = {id=69093,name="A New Mystery",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp. He eagerly tries to explain.> Sealed door. Titan secrets. Yes? Doc Nanners nods excitedly, awaiting your response.>",starts={{npcID=196643,x=0.454,y=0.55,zoneID=13862}},ends={{npcID=186869,x=0.478,y=0.824,zoneID=13644}},coords={x=0.454,y=0.55,source="quest_giver",zoneID=13862},questType="standard"},
[69094] = {id=69094,name="Saving Centaur",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The treachery of the Nokhud knows no limits! Only craftsmen live in the village of Daruukhan. They stood no chance against the raiders. We desperately need your help, . The Nokhud are still nearby, and we must tend to the wounded! Search the village, and carry any survivors you find to me. We will triage and stabilize who we can!",starts={{npcID=192621,x=0.612,y=0.4,zoneID=13645}},ends={{npcID=192621,x=0.612,y=0.4,zoneID=13645}},coords={x=0.612,y=0.4,source="quest_giver",zoneID=13645},questType="standard"},
[69095] = {id=69095,name="Homeward Hound",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="We have everyone stabilized, thanks to you and Taivan , but many of these villagers will need to heal for a while longer in Maruukai. Why don't the two of you lead our train back? You are both the heroes of the day, after all!",starts={{npcID=192621,x=0.612,y=0.4,zoneID=13645}},ends={{npcID=192621,x=0.612,y=0.4,zoneID=13645}},coords={x=0.612,y=0.4,source="quest_giver",zoneID=13645},questType="standard"},
[69096] = {id=69096,name="Taivan's Purpose",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Do you see that young one, sitting by themselves over on the bank of the stream? Chimei lost both of their parents in the Nokhud attack. I have healed all of their physical wounds, but they have not eaten or said a word to anyone since we found them. They just sit and stare. This is beyond my skills, and I am at a loss. Will you try to talk to them, ?",starts={{npcID=192621,x=0.612,y=0.4,zoneID=13645}},ends={{npcID=192621,x=0.612,y=0.4,zoneID=13645}},coords={x=0.612,y=0.4,source="quest_giver",zoneID=13645},questType="standard"},
[69097] = {id=69097,name="A Vault Unsealed",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description="Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp. He eagerly tries to explain.> Loud dwarf. Serious elf. Ready for you. Yes? Doc Nanners nods excitedly, awaiting your response.>",starts={{npcID=196643,x=0.454,y=0.55,zoneID=13862}},ends={{npcID=189226,x=0.47,y=0.826,zoneID=13644}},coords={x=0.454,y=0.55,source="quest_giver",zoneID=13862},questType="standard"},
[69667] = {id=69667,name="Steamgill",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[69668] = {id=69668,name="Smogswog the Firebreather",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[69837] = {id=69837,name="Sunscale Behemoth",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[69838] = {id=69838,name="Amethyzar the Glittering",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[69848] = {id=69848,name="Massive Magmashell",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[69849] = {id=69849,name="Enraged Steamburst Elemental",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[69851] = {id=69851,name="Ripsaw the Stalker",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[69852] = {id=69852,name="Territorial Coastling",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[69854] = {id=69854,name="Solethus' Gravestone",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[69855] = {id=69855,name="A Climber's Calling",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp for training. He eagerly tries to explain.> From Big Jeb. Good friend. Climb now. Yes? Doc Nanners nods excitedly, awaiting your response.>",starts={{npcID=196643,x=0.454,y=0.55,zoneID=13862}},ends={{npcID=187700,x=0.472,y=0.834,zoneID=13644}},coords={x=0.454,y=0.55,source="quest_giver",zoneID=13862},questType="standard"},
[69856] = {id=69856,name="Fulgurb",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[69862] = {id=69862,name="Save a Slyvern",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Now that she's healed, I think Sylvie wants to show us something. Our work isn't done yet, ! Let's see what's upsetting her.",starts={{npcID=192830,x=0.636,y=0.288,zoneID=13646}},ends={{npcID=192830,x=0.636,y=0.288,zoneID=13646}},coords={x=0.636,y=0.288,source="quest_giver",zoneID=13646},questType="standard"},
[69864] = {id=69864,name="Forgotten Creation",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[69869] = {id=69869,name="A Cataloger's Paradise",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp for training. He eagerly tries to explain.> Kind elf. Proud tiny-man. Many cameras. Yes? Doc Nanners nods excitedly, awaiting your response.>",starts={{npcID=196643,x=0.454,y=0.55,zoneID=13862}},ends={{npcID=187707,x=0.484,y=0.826,zoneID=13644}},coords={x=0.454,y=0.55,source="quest_giver",zoneID=13862},questType="standard"},
[69870] = {id=69870,name="Pictures with Purpose",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Pictures bring people together, $p. Our catalogers are typically sent out in pairs for safety, and it has been lovely to see members of different factions and backgrounds working together in pursuit of knowledge on these incredible isles. One such eager duo is currently charting one of the central rivers of the Waking Shores . If you wish to aid our efforts, join them in cataloging the wildlife there.",starts={{npcID=187707,x=0.484,y=0.826,zoneID=13644}},ends={{npcID=185651,x=0.498,y=0.684,zoneID=13644}},coords={x=0.484,y=0.826,source="quest_giver",zoneID=13644},questType="standard"},
[69871] = {id=69871,name="Malsegan",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[69873] = {id=69873,name="Henlare",level=40,requiredLevel=40,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[69877] = {id=69877,name="Oshigol",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[69878] = {id=69878,name="Ronsak the Decimator",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[69879] = {id=69879,name="Spellwrought Snowman",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[69888] = {id=69888,name="Unusual Suspects",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,description=", you're here. Good. Don't react, but our findings on the titan discs have just been stolen! Other than us, only the Sundered Flame know what we were up to in that facility. I need ye to take this device and scan some of the suspicious members that have joined us recently. Reveal the spy and recover the data if you can. We cannae allow it to fall into their hands!",starts={{npcID=187276,x=0.472,y=0.826,zoneID=13644}},ends={{npcID=187276,x=0.472,y=0.826,zoneID=13644}},coords={x=0.472,y=0.826,source="quest_giver",zoneID=13644},questType="standard"},
[69891] = {id=69891,name="Lepidoralia the Resplendent",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[69895] = {id=69895,name="Summoned Destroyer",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[69896] = {id=69896,name="Disastrous Detour",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I knew joining the Dragonscale Expedition meant venturing into dangerous territory. But I was not expecting to fight off elementals! Our dig site at the Life Vault Ruins is in complete disarray! Stone monstrosities are rising up out of the ground! We called in an elementalist to consult, but I believe she will need all the help she can get. Perhaps you can help her? Our camp is just across the river.",starts={{npcID=190273,x=0.636,y=0.618,zoneID=13644}},ends={{npcID=188735,x=0.66,y=0.58,zoneID=13644}},coords={x=0.636,y=0.618,source="quest_giver",zoneID=13644},questType="standard"},
[69897] = {id=69897,name="Behavior Analysis \"Homework\"",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I need to talk to someone who knows proto-whelps. Like the ones that live in the Wild Preserve! Are they as angry as the big ones? Do they bite or breathe fire at you? What if I... er... you petted a proto-whelp? Would they know that you're nice and trying to help them? I'm asking for science, of course. Tyrgon always tells us to test our hippa... no... hypo... hmph! Hyppotatotoast... ugh! THEORIES! I think they would like petting and it would make them feel good. Could you test that for me?",starts={{npcID=193500,x=0.458,y=0.814,zoneID=13644}},ends={{npcID=193500,x=0.458,y=0.814,zoneID=13644}},coords={x=0.458,y=0.814,source="quest_giver",zoneID=13644},questType="standard"},
[69898] = {id=69898,name="Scientific Meat-thod",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="So, I have, uh, more homework... Professor Tyrgon's lessons are super tough! He wants us to find out what proto-whelps, uh, eat! Yeah... I already know the answer! It's riverbeast meat! Can you bring me a piece of riverbeast meat? Some riverbeast meat would be a great \"visual aid\" for my project. But it has to be a REALLY good piece, ok? Like... the ones from Pudgy Riverbeasts. One like a momma proto-drake would give their whelp to make them strong because, uh, it will make Mister Tyrgon happy.",starts={{npcID=193500,x=0.458,y=0.814,zoneID=13644}},ends={{npcID=193500,x=0.458,y=0.814,zoneID=13644}},coords={x=0.458,y=0.814,source="quest_giver",zoneID=13644},questType="standard"},
[69899] = {id=69899,name="Secret Research",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I know.. I am acting weird. I'm sorry! You probably guessed I am not being truthful. I can tell you my secret... if you like. But you will have to promise not to tell the adults!",starts={{npcID=193500,x=0.458,y=0.814,zoneID=13644}},ends={{npcID=192298,x=0.46,y=0.814,zoneID=13644}},coords={x=0.458,y=0.814,source="quest_giver",zoneID=13644},questType="standard"},
[69900] = {id=69900,name="Identifying the Source",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Judging by what the children have said, we might have a primalist prowling the Wild Preserve. This calls for immediate investigation. According to what other researchers have observed, Primalists like to steal eggs and whelps to infuse them with power and corrupt them. Those that don't acclimate to the process suffer a slow death... not that the primalists seem to care... We need them out of the Preserve. Attend to that, and I will try to distract the children. They must not know of this.",starts={{npcID=192298,x=0.46,y=0.814,zoneID=13644}},ends={{npcID=192298,x=0.46,y=0.814,zoneID=13644}},coords={x=0.46,y=0.814,source="quest_giver",zoneID=13644},questType="standard"},
[69901] = {id=69901,name="Bring In the Expert",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Did Iyali say how long this creature has been suffering? If it's too injured to eat, we need to treat it quickly. Normally a Dragonscale Expedition camp would have everything I need to help this whelp, but getting supplies to the \"frontier\" here on the Dragon Isles has proven tricky. There have been significant delays in our supply routes. But, fear not. The land itself will provide! If you bring me Sunlight Flowers , I can craft a soothing balm that will calm the drake so I can heal it.",starts={{npcID=192298,x=0.46,y=0.814,zoneID=13644}},ends={{npcID=192298,x=0.46,y=0.814,zoneID=13644}},coords={x=0.46,y=0.814,source="quest_giver",zoneID=13644},questType="standard"},
[69902] = {id=69902,name="Theory in Practice",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description=", I require your assistance... I hope no one was expecting me to craft, subdue the whelp, heal, and teach these children all at once! Multitasking like that is certainly overrated. Now, you can start by using those flowers. I'll need a couple minutes to prepare myself to heal the proto-whelp. Hopefully, the children will find this incident... instructional.",starts={{npcID=192298,x=0.46,y=0.814,zoneID=13644}},ends={{npcID=192298,x=0.46,y=0.814,zoneID=13644}},coords={x=0.46,y=0.814,source="quest_giver",zoneID=13644},questType="standard"},
[69904] = {id=69904,name="Suspiciously Quiet",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Can you spare a minute, $p? I haven't heard from my two apprentices, Scrumpy and Tucky, in some time. This is concerning. I sent them to fetch us supplies for the inn. They couldn't have strayed too far... Please find them, but I warn you... They're... quite the handful.",starts={{npcID=183543,x=0.466,y=0.4,zoneID=13646}},ends={{npcID=189198,x=0.476,y=0.402,zoneID=13646}},coords={x=0.466,y=0.4,source="quest_giver",zoneID=13646},questType="standard"},
[69910] = {id=69910,name="Where is Wrathion?",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=13644,description="How unusual. Ebyssian told us that Wrathion would be awaiting our arrival along with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons. It isn't like a dragon to break a promise. At least this eager drakonid is here to greet us. Would you kindly inquire into when the others shall arrive?",starts={{npcID=184870,x=0.766,y=0.336,zoneID=13644}},ends={{npcID=193362,x=0.766,y=0.336,zoneID=13644}},coords={x=0.766,y=0.336,source="quest_giver",zoneID=13644},questType="standard"},
[69911] = {id=69911,name="Excuse the Mess",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I wish I knew more about how to welcome you to the Dragon Isles, but I'm only the sentry. Sendrax motions to the tower behind her.> You could try talking with Ambassador Fastrasz in the visitor center. He might be able to answer more of your questions before the dragons arrive. Mind your step in there. He was clearing out rubble last I saw.",starts={{npcID=193362,x=0.766,y=0.336,zoneID=13644}},ends={{npcID=193362,x=0.766,y=0.336,zoneID=13644}},coords={x=0.766,y=0.336,source="quest_giver",zoneID=13644},questType="standard"},
[69912] = {id=69912,name="My First Real Emergency!",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Sendrax looks puzzled.> I have never known the majordomo to be late to anything, much less THIS late to something THIS important. Most unusual... Sendrax perks up at a thought.> I could use my emergency signal flare to alert them to your arrival. Then they would come rushing to greet you immediately! I've never fired my emergency signal flare before, though...",starts={{npcID=193362,x=0.766,y=0.336,zoneID=13644}},ends={{npcID=193371,x=0.762,y=0.344,zoneID=13644}},coords={x=0.766,y=0.336,source="quest_giver",zoneID=13644},questType="standard"},
[69914] = {id=69914,name="The Djaradin Have Awoken",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I wish we'd time for more pleasant introductions, but we can't all be Chronormu, can we? I am Selistra, majordomo to Alexstrasza the Life-Binder, Queen of the Dragons. Queen Alexstrasza asked me to convey her kindest regards and escort you to her at the Life Pools. But I'm afraid I must ask for your assistance before we go meet her. Our ancient rivals, the djaradin, have awoken from their slumber under the earth and have already assaulted a nearby outpost!",starts={{npcID=193372,x=0.762,y=0.344,zoneID=13644}},ends={{npcID=193363,x=0.762,y=0.344,zoneID=13644}},coords={x=0.762,y=0.344,source="quest_giver",zoneID=13644},questType="standard"},
[69915] = {id=69915,name="Targeted Ads",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Hi, hi, hi! You looking for a gig? We're doing a BIG opening sale for our new Crafting Order service, and we need to draw attention! But the wind took my flyers and I think some of the local goats ran off with them. Could you get my flyers back?",starts={{npcID=193108,x=0.72,y=0.81,zoneID=13645}},ends={{npcID=193108,x=0.72,y=0.81,zoneID=13645}},coords={x=0.72,y=0.81,source="quest_giver",zoneID=13645},questType="standard"},
[69918] = {id=69918,name="Shaking Our Foundations",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Djaradin stonebinders are threatening to break the very foundations of the Citadel! They have to be stopped! We haven't even had a chance to reclaim the Citadel as our own and yet it might crumble beneath us. We can't let that happen. Do what you can, ... by that I mean kill them!",starts={{npcID=190899,x=0.266,y=0.624,zoneID=13644}},ends={{npcID=190899,x=0.266,y=0.624,zoneID=13644}},coords={x=0.266,y=0.624,source="quest_giver",zoneID=13644},questType="standard"},
[69919] = {id=69919,name="A Craft in Need",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="You seem like a skilled crafter. Would you like to fill some crafting orders for fellow adventurers and get rich, rich, rich? I'll tell you the rules of working with the Artisan's Consortium, then you can pick up Crafting Orders at any crafting station on the Dragon Isles!",starts={{npcID=193108,x=0.72,y=0.81,zoneID=13645},{npcID=194026,x=0.354,y=0.588,zoneID=13862}},ends={{npcID=193108,x=0.72,y=0.81,zoneID=13645},{npcID=194026,x=0.354,y=0.588,zoneID=13862}},coords={x=0.72,y=0.81,source="quest_giver",zoneID=13645},questType="standard"},
[69923] = {id=69923,name="A Primal Threat",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=1519,description="Raszageth has wasted no time building up her Primalist forces. The Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms. The Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well. Seek out the enemy and study their methods. We have to stop them before it's too late.",starts={{npcID=193450,x=0.558,y=0.126,zoneID=14},{npcID=193450,x=0.23,y=0.558,zoneID=1519}},ends={{npcID=193450,x=0.558,y=0.126,zoneID=14},{npcID=193450,x=0.23,y=0.558,zoneID=1519}},coords={x=0.558,y=0.126,source="quest_giver",zoneID=14},questType="standard"},
[69925] = {id=69925,name="Calming the Storms",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=1519,description="These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor. You must show the same determination, . It is the only way to stop them. Find their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts. We must protect Azeroth!",starts={{npcID=193450,x=0.558,y=0.126,zoneID=14},{npcID=193450,x=0.23,y=0.558,zoneID=1519}},ends={{npcID=193450,x=0.558,y=0.126,zoneID=14},{npcID=193450,x=0.23,y=0.558,zoneID=1519}},coords={x=0.558,y=0.126,source="quest_giver",zoneID=14},questType="standard"},
[69926] = {id=69926,name="Becca Black and the Seven Gnomes",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts. Wrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.",starts={{npcID=191014,x=0.264,y=0.622,zoneID=13644}},ends={{npcID=191014,x=0.264,y=0.622,zoneID=13644}},coords={x=0.264,y=0.622,source="quest_giver",zoneID=13644},questType="standard"},
[69932] = {id=69932,name="Every Life Counts",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Making potions for Gelikyr means that I don't have time for my other duties. A duck landed in my garden with a broken rib. I've tended to the wound, but her dressing needs replacing. And since you're so eager to help... Szareth shoves a list of ingredients into your hand.> This is what you'll need. Bring the rest to me.",starts={{npcID=193538,x=0.502,y=0.676,zoneID=13647}},ends={{npcID=193538,x=0.502,y=0.676,zoneID=13647}},coords={x=0.502,y=0.676,source="quest_giver",zoneID=13647},questType="standard"},
[69933] = {id=69933,name="Curiosity's Price",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Look across the ravine, . Primalists attacked Gelikyr Post days ago, and the battle still rages. Those people need salves and stitching. I can make it for them, but my ingredients are running low. Since you've chosen to intrude upon my home, consider yourself volunteered. Go to my garden and find the largest vine you can. Snap it from the root, then bring it to me.",starts={{npcID=193538,x=0.502,y=0.676,zoneID=13647}},ends={{npcID=193538,x=0.502,y=0.676,zoneID=13647}},coords={x=0.502,y=0.676,source="quest_giver",zoneID=13647},questType="standard"},
[69934] = {id=69934,name="Bleeding Hearts",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The potions are ready--now to deliver them. Take one crate to a small cave in the ravine below us. No one will be there to accept it, but you can trust it will be used well. Take another crate to the infirmary in Gelikyr Post. An old friend tends to the patients there. I... realize this is not your duty. Nor is it really mine. But you've been surprisingly helpful, and this medicine could save lives.",starts={{npcID=193538,x=0.502,y=0.676,zoneID=13647}},ends={{npcID=193042,x=0.516,y=0.692,zoneID=13647}},coords={x=0.502,y=0.676,source="quest_giver",zoneID=13647},questType="standard"},
[69936] = {id=69936,name="Zambul, Head Vandal",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Good work. Those desecrators cannot force any more of my ancestors to fight for them. But the brute yelling out their orders must be handled. That is their overseer, Zambul. He must be stopped. Take him down.",starts={{npcID=189858,x=0.338,y=0.654,zoneID=13645}},ends={{npcID=189858,x=0.338,y=0.654,zoneID=13645}},coords={x=0.338,y=0.654,source="quest_giver",zoneID=13645},questType="standard"},
[69937] = {id=69937,name="Sylvan Succor",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Ah, , there you are! I've been looking all over for you. Another of our local critters has been suffering from a distinct lack of affectionate treat-feeding of late. Won't you go and find them something sweet to snack on?",starts={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},ends={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},coords={x=0.728,y=0.66,source="quest_giver",zoneID=13862},questType="standard"},
[69939] = {id=69939,name="Sylvan Succor",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Ah, , there you are! I've been looking all over for you. Another of our local critters has been suffering from a distinct lack of affectionate treat-feeding of late. Won't you go and find them something sweet to snack on?",starts={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},ends={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},coords={x=0.728,y=0.66,source="quest_giver",zoneID=13862},questType="standard"},
[69940] = {id=69940,name="Sylvan Succor",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Ah, , there you are! I've been looking all over for you. Another of our local critters has been suffering from a distinct lack of affectionate treat-feeding of late. Won't you go and find them something sweet to snack on?",starts={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},ends={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},coords={x=0.728,y=0.66,source="quest_giver",zoneID=13862},questType="standard"},
[69944] = {id=69944,name="Chasing Storms",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=14,description="Well, that wizard certainly knows how to make an entrance, doesn't he? We won't be able to set sail until someone gets those elemental storms under control. Check-in with Storm Huntress Suhrakka . She's leading the expedition efforts to investigate the storms and can help outfit you with whatever gear you need. While you handle that, I'll coordinate the rest of the preparations. At least it'll give me some time to read a few more volumes on dragon history before we set sail.",starts={{npcID=197279,x=0.558,y=0.126,zoneID=14}},ends={{npcID=195899,x=0.558,y=0.124,zoneID=14}},coords={x=0.558,y=0.126,source="quest_giver",zoneID=14},questType="standard"},
[69946] = {id=69946,name="The Master of Their Craft",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="While I was traveling through these plains, I met an old centaur in a cave up north. They had clearly mastered their craft and had wisdom to spare. They helped me understand the knowledge I had gained from the Dragon Isles. If you're curious about specializing in your profession, seek out the wisdom of this master. Khadin was their name, of Clan Teerai.",starts={{npcID=192574,x=0.602,y=0.722,zoneID=13644},{npcID=192574,x=0.394,y=0.698,zoneID=13862}},ends={{npcID=193110,x=0.518,y=0.33,zoneID=13645}},coords={x=0.602,y=0.722,source="quest_giver",zoneID=13644},questType="standard"},
[69950] = {id=69950,name="Sylvan Succor",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Ah, , there you are! I've been looking all over for you. Another of our local critters has been suffering from a distinct lack of affectionate treat-feeding of late. Won't you go and find them something sweet to snack on?",starts={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},ends={{npcID=192522,x=0.728,y=0.66,zoneID=13862}},coords={x=0.728,y=0.66,source="quest_giver",zoneID=13862},questType="standard"},
[69952] = {id=69952,name="Crystalus",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13992,mapID=2085,questType="standard"},
[69955] = {id=69955,name="Emblazion",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[69959] = {id=69959,name="Gaelzion",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[69962] = {id=69962,name="Corrupted Proto-Dragon",level=40,requiredLevel=40,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[69963] = {id=69963,name="Ancient Protector",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[69965] = {id=69965,name="Quality Assurance",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Are you looking for work, ? I represent a new trade company, the Artisan's Consortium, which matches artisans and clients through our crafting orders network. The Dragonscale Expedition placed an order for some enchanted mining tools. The tools are crafted, but we would like to test them before completing the order. We will pay you for your services, of course.",starts={{npcID=192438,x=0.764,y=0.344,zoneID=13644}},ends={{npcID=192438,x=0.764,y=0.344,zoneID=13644}},coords={x=0.764,y=0.344,source="quest_giver",zoneID=13644},questType="standard"},
[69967] = {id=69967,name="Lookout Mordren",level=40,requiredLevel=40,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[69968] = {id=69968,name="Prozela Galeshot",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[69971] = {id=69971,name="Iceblade Trio",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13992,mapID=2085,questType="standard"},
[69974] = {id=69974,name="Pipspark Thundersnap",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[69975] = {id=69975,name="Neela Firebane",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[69979] = {id=69979,name="A Worthy Hunt",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Wisdom is not gained. It is earned. If you wish to prove yourself worthy, you will do so in the manner of my people: learning as we act. Find and hunt Thousandmile , the Elderbull, he who has escaped the hunt for generations. From this, you will gain the wisdom you seek.",starts={{npcID=193110,x=0.518,y=0.33,zoneID=13645}},ends={{npcID=193110,x=0.518,y=0.33,zoneID=13645}},coords={x=0.518,y=0.33,source="quest_giver",zoneID=13645},questType="standard"},
[69980] = {id=69980,name="Seavine: Fisherman Tinnak's Gift",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[69981] = {id=69981,name="Customer Satisfaction",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,description="Hey , got a tick to help with something? Some of our favorite customers placed recrafting orders through the Artisan's Consortium, but we haven't heard back from them. If you run into them, can you check to make sure they're satisfied with their purchases? Gotta keep customers happy, happy, happy!",starts={{npcID=193108,x=0.72,y=0.81,zoneID=13645}},ends={{npcID=193835,x=0.718,y=0.812,zoneID=13645}},coords={x=0.72,y=0.81,source="quest_giver",zoneID=13645},questType="standard"},
[69983] = {id=69983,name="Flamecarved Bone",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Talonstalker Kavia might want to see this.>",ends={{npcID=190899,x=0.266,y=0.624,zoneID=13644}},questType="standard"},
[69984] = {id=69984,name="Gold-Banded Dragon Tooth",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Exadria might want to see this.>",ends={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},questType="standard"},
[69992] = {id=69992,name="Sigil of Storms",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=14,ends={{npcID=195899,x=0.558,y=0.124,zoneID=14}},questType="standard"},
[70025] = {id=70025,name="Artisan's Supply: Draconium Sickle",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="You look like someone with nothing to do. How's about employment? I have a crafting order to fill for the Artisan's Consortium for a draconium sickle . Now I could easily take care of this, but as an apprentice I think it makes more sense for you to take this one on. Craft the sickle and bring it to the Ruby Lifeshrine, a draenei named Haephesta will pay you for it.",starts={{npcID=192164,x=0.258,y=0.544,zoneID=13644}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},coords={x=0.258,y=0.544,source="quest_giver",zoneID=13644},questType="standard"},
[70026] = {id=70026,name="Artisan's Supply: Lava Beetles",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Are you looking for work, herbalist? The Artisan's Consortium asked me to gather some beetles for their customers. The land is plentiful, but not so much that I can simply step away and be back with their request. But if you venture out, perhaps you could collect a few beetles on your way?",starts={{npcID=192010,x=0.574,y=0.658,zoneID=13644},{npcID=192549,x=0.768,y=0.34,zoneID=13644}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},coords={x=0.574,y=0.658,source="quest_giver",zoneID=13644},questType="standard"},
[70027] = {id=70027,name="Artisan's Supply: Surveyor's Cloth Bands",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Are you looking for work, tailor? The Artisan's Consortium asked me to craft some wristbands for their customers. While I appreciate that these explorers are trying to involve themselves with our weaving, I do not have time for such requests. Perhaps you would be interested in taking on this project?",starts={{npcID=191894,x=0.614,y=0.7,zoneID=13644}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},coords={x=0.614,y=0.7,source="quest_giver",zoneID=13644},questType="standard"},
[70028] = {id=70028,name="Artisan's Supply: Salt Deposits",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Are ye looking for work, miner? I was talkin' to Haephesta an' she says the Artisan's Consortium is needin' salt for their customers. Noo I'd do it meself, but, well, I dinna want to. Be a pal and fetch 'em for 'er, eh?",starts={{npcID=187261,x=0.764,y=0.344,zoneID=13644}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},coords={x=0.764,y=0.344,source="quest_giver",zoneID=13644},questType="standard"},
[70029] = {id=70029,name="Artisan's Supply: Runed Serevite Rods",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,description="You seem to have a magical touch, enchanter. Would you be able to help with an order I've got? The Artisan's Consortium has requested several rods made of Serevite for a customer, but enchanting rods aren't quite my specialty. If you're willing, Haephesta at the Ruby Lifeshrine will compensate you for your time and effort!",starts={{npcID=192055,x=0.758,y=0.332,zoneID=13644},{npcID=192116,x=0.568,y=0.756,zoneID=13645},{npcID=198903,x=0.414,y=0.61,zoneID=13645}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},coords={x=0.758,y=0.332,source="quest_giver",zoneID=13644},questType="standard"},
[70030] = {id=70030,name="Artisan's Supply: Quality-Assured Optics",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Ah, an engineer! Excellent timing. I've got some schematics to fix, but some tall lady came by asking for a set of optics. You know how to make those, right? Take 'em to the Ruby Lifeshrine when you have 'em crafted. I think she said she was with the Artisan's Consortium or something.",starts={{npcID=192165,x=0.43,y=0.666,zoneID=13644}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},coords={x=0.43,y=0.666,source="quest_giver",zoneID=13644},questType="standard"},
[70031] = {id=70031,name="Artisan's Supply: Chef's Smooth Rolling Pin",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Are you looking for work, scribe? I received an order from a company called the Artisan's Consortium. It seems like a simple enough task for an apprentice crafter such as yourself.",starts={{npcID=198125,x=0.572,y=0.582,zoneID=13644}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},coords={x=0.572,y=0.582,source="quest_giver",zoneID=13644},questType="standard"},
[70032] = {id=70032,name="Artisan's Supply: Jeweler's Specs",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Are you looking for work, jewelcrafter? The Artisan's Consortium asked me to craft some spectacles for their customers. Me! Like I have time for this. You can do it, yeah?",starts={{npcID=190103,x=0.654,y=0.252,zoneID=13645},{npcID=192121,x=0.254,y=0.542,zoneID=13644}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},coords={x=0.654,y=0.252,source="quest_giver",zoneID=13645},questType="standard"},
[70033] = {id=70033,name="Artisan's Supply: Pioneer's Leather Boots",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Are you looking for work, leatherworker? The Artisan's Consortium asked me to craft some boots for their customers. Clearly they don't understand my popularity. Do you know how many explorers have come through today complaining of holes in their shoes? If you have the time, take these measurements. Perhaps this Artisan's Consortium could be a promising business opportunity for you.",starts={{npcID=192027,x=0.808,y=0.594,zoneID=13645},{npcID=196628,x=0.394,y=0.554,zoneID=13645},{npcID=192048,x=0.766,y=0.348,zoneID=13644},{npcID=195785,x=0.29,y=0.61,zoneID=13862}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644}},coords={x=0.808,y=0.594,source="quest_giver",zoneID=13645},questType="standard"},
[70034] = {id=70034,name="Artisan's Supply: Salamanther Scales",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Are you looking for work, skinner? The Artisan's Consortium asked me to gather the scales of a salamanther for their customers. I may be an artisan, but I am no one's errand child! But... ah, perhaps you could find some?",starts={{npcID=191392,x=0.81,y=0.594,mapID=2023},{npcID=194185,x=0.846,y=0.232,mapID=2023},{npcID=192558,x=0.766,y=0.348,mapID=2022}},ends={{npcID=192498,x=0.578,y=0.682,mapID=2022}},coords={x=0.81,y=0.594,source="quest_giver",mapID=2151},questType="standard"},
[70040] = {id=70040,name="Tumbling Through Time",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="When the magic of Bronze and Infinite collided, it sent Chronormu and Eternus into an uncontrolled tumble through time. As they fall, they rip the fabric of time itself, sending out countless ripples across time and space. We must locate them and bring them back. Only then will we be able to stop any further damage. I see that you will be the one to stop Chronormu's fall. I would ask that you to gather the allies you will need to save Chronormu, while I focus on her magic.",starts={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},ends={{npcID=186931,x=0.6,y=0.824,zoneID=13647}},coords={x=0.6,y=0.824,source="quest_giver",zoneID=13647},questType="standard"},
[70041] = {id=70041,name="The Storm-Eater's Fury",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Raszageth is attempting to rip all the arcane magic out of the tower so she can destroy it! Kalecgos is doing what he can to hold her back, and I am using my magic to try to replenish the ley energy. I fear we will not last much longer. As we speak, more Primalists make their way up here to overwhelm us! Take my modified Arcane Disc . Hold off the incoming Primalists... and let us hope for a miracle.",starts={{npcID=193837,x=0.78,y=0.324,zoneID=13646}},ends={{npcID=187034,x=0.782,y=0.332,zoneID=13646}},coords={x=0.78,y=0.324,source="quest_giver",zoneID=13646},questType="standard"},
[70042] = {id=70042,name="Opportunities Abound",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Ya scared me, thought I was nabbed! Look at all the brave explorers ready to conquer the Dragon Isles... packs bulging with tools and equipment. We could get rich here! Check around see if you can grab a few items, and I'll cut you in on the profits.",starts={{npcID=193838,x=0.762,y=0.344,zoneID=13644}},ends={{npcID=193838,x=0.762,y=0.344,zoneID=13644}},coords={x=0.762,y=0.344,source="quest_giver",zoneID=13644},questType="standard"},
[70048] = {id=70048,name="A Primal Threat",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,description="Raszageth has wasted no time building up her Primalist forces. The Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms. The Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well. Seek out the enemy and study their methods. We have to stop them before it's too late.",starts={{npcID=193450,x=0.558,y=0.126,zoneID=14},{npcID=193450,x=0.23,y=0.558,zoneID=1519}},ends={{npcID=193450,x=0.558,y=0.126,zoneID=14},{npcID=193450,x=0.23,y=0.558,zoneID=1519}},coords={x=0.558,y=0.126,source="quest_giver",zoneID=14},questType="standard"},
[70049] = {id=70049,name="Calming the Storms",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,description="These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor. You must show the same determination, . It is the only way to stop them. Find their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts. We must protect Azeroth!",starts={{npcID=193450,x=0.558,y=0.126,zoneID=14},{npcID=193450,x=0.23,y=0.558,zoneID=1519}},ends={{npcID=193450,x=0.558,y=0.126,zoneID=14},{npcID=193450,x=0.23,y=0.558,zoneID=1519}},coords={x=0.558,y=0.126,source="quest_giver",zoneID=14},questType="standard"},
[70050] = {id=70050,name="Chasing Storms",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,description="So the handsome fellas are sendin' ye on a wee adventure, eh? That's fine. The expedition won't be able to set sail until someone gets those elemental storms under control anyway. Check-in with Storm Hunter William . He's leading the expedition efforts to investigate the storms and can outfit ye with whatever gear you need. I'll coordinate the rest of the preparations here while ye have all the fun out there. Ye'll owe me one, though!",starts={{npcID=189077,x=0.228,y=0.556,zoneID=1519}},ends={{npcID=195912,x=0.25,y=0.532,zoneID=1519}},coords={x=0.228,y=0.556,source="quest_giver",zoneID=1519},questType="standard"},
[70055] = {id=70055,name="Sigil of Storms",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,ends={{npcID=195912,x=0.25,y=0.532,zoneID=1519}},questType="standard"},
[70058] = {id=70058,name="Friend on the Mend",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Happy Duck got hurt while we were flying around... He was doing so good and then I... I hit a tree! Lillistrasza gestures mournfully at the damaged duck plushie on her head.> His stuffing is falling out! His feathers are all bent! One of his eyes is gone! Noooo! You can help fix Happy Duck, right?",starts={{npcID=193955,x=0.598,y=0.704,zoneID=13644}},ends={{npcID=192674,x=0.61,y=0.7,zoneID=13644}},coords={x=0.598,y=0.704,source="quest_giver",zoneID=13644},questType="standard"},
[70061] = {id=70061,name="Training Wings",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The dragons were gone from the Isles for quite some time, $p. To tell the truth... some of our skills have atrophied as they were passed down from generation to generation. These whelps should be easy to teach, yet we are having some trouble wrangling them. Say. I have seen that even Majordomo Selistra trusts you with the most crucial tasks. Would you lend us your aid and help one of our young?",starts={{npcID=194174,x=0.622,y=0.706,zoneID=13644}},ends={{npcID=191768,x=0.622,y=0.728,zoneID=13644}},coords={x=0.622,y=0.706,source="quest_giver",zoneID=13644},questType="standard"},
[70062] = {id=70062,name="Some Call Me Bug Catcher",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Ah, young , I could use your help. I have raised generations of life here. None more my favorite than the ducklings. But my body has grown old and weak... still that does not stop the cycle. I need you to catch food for my brood.",starts={{npcID=186503,x=0.302,y=0.582,zoneID=13645}},ends={{npcID=186503,x=0.302,y=0.582,zoneID=13645}},coords={x=0.302,y=0.582,source="quest_giver",zoneID=13645},questType="standard"},
[70069] = {id=70069,name="Others Call Me Duck Herder",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="My days grow shorter... Still my duties are not done. The brood should all be by the creek. I leave them there hoping they will grow more independent. Soon they will have to fend for themselves. Today they will rely on you. Please bring them the food you caught, and then the ducklings to me. Be wary of Pilot , she is always jumping off something.",starts={{npcID=186503,x=0.302,y=0.582,zoneID=13645}},ends={{npcID=186503,x=0.302,y=0.582,zoneID=13645}},coords={x=0.302,y=0.582,source="quest_giver",zoneID=13645},questType="standard"},
[70070] = {id=70070,name="But... I Am the Hero of Ducks",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Hold on... there is something... Gracus looks around.> Firequackers! The boy must have gone down the river again! No matter how often I tell him, he always tries to play with the hornswogs! I need you to go check on him. I hope he didn't get swallowed again.",starts={{npcID=186503,x=0.302,y=0.582,zoneID=13645}},ends={{npcID=186503,x=0.302,y=0.582,zoneID=13645}},coords={x=0.302,y=0.582,source="quest_giver",zoneID=13645},questType="standard"},
[70122] = {id=70122,name="Explorers in Peril",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=13644,description="Don't mistake the expedition's scholarly pursuits as timidness, $p. We are not recluses studying books in far-off towers. We are adventurers, hunting down knowledge first-hand in every corner of Azeroth! That same passion for adventure often leads us into the path of perils and hazards, and a few expedition members have bitten off a little more than they could chew... But, hey, the danger makes it more fun!",starts={{npcID=189022,x=0.82,y=0.318,zoneID=13644}},ends={{npcID=187251,x=0.766,y=0.336,zoneID=13644},{npcID=189022,x=0.82,y=0.318,zoneID=13644}},coords={x=0.82,y=0.318,source="quest_giver",zoneID=13644},questType="standard"},
[70123] = {id=70123,name="Primal Pests",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=13644,description="I'd swear that those proto-dragons edge closer to camp every time I turn my back... Those are not the dragons Wrathion invited us here to meet. Proto-dragons are ruthless predators who cannot be reasoned with. We must be ruthless in return. Cull their numbers to keep their ambitions in check, or this expedition will be over before it begins.",starts={{npcID=189035,x=0.82,y=0.318,zoneID=13644}},ends={{npcID=187252,x=0.766,y=0.344,zoneID=13644}},coords={x=0.82,y=0.318,source="quest_giver",zoneID=13644},questType="standard"},
[70124] = {id=70124,name="Practice Materials",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=13644,description="The proto-drakes here are unlike any I've seen before. Their scales appear to be naturally flame-resistant, stronger than steel, and don't lose flexibility in the process. Incredible. The artisans are clamoring to get their hands on some to work with. Start with the whelps. The smaller scales should be more pliable until we've mastered our techniques with 'em.",starts={{npcID=189021,x=0.82,y=0.318,zoneID=13644}},ends={{npcID=189058,x=0.764,y=0.344,zoneID=13644}},coords={x=0.82,y=0.318,source="quest_giver",zoneID=13644},questType="standard"},
[70125] = {id=70125,name="Where is Wrathion?",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=13644,description="Hm, wonder where Wrathion is? He said he'd be here waitin' for us with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons. It does nae seem like a dragon to break a promise. Well! At least this eager wee drakonid is here to welcome us. Can you talk to 'em and find out when the others are gonna arrive?",starts={{npcID=187251,x=0.766,y=0.336,zoneID=13644}},ends={{npcID=193362,x=0.766,y=0.336,zoneID=13644}},coords={x=0.766,y=0.336,source="quest_giver",zoneID=13644},questType="standard"},
[70126] = {id=70126,name="A Finishing Touch",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Ah, $p, good to see you. You've been an exceptional help for the Artisan's Consortium, and to Thomas and myself personally. Thank you. There is one more thing you should know as a crafter, and that's building a rapport with your clients. I filled a crafting order for a customer today. Could you talk to him for me? Try to convince him to come to me for his future crafting needs. Remind him that he needs to come to me personally if he wants high-quality goods.",starts={{npcID=192539,x=0.598,y=0.716,zoneID=13644},{npcID=192539,x=0.718,y=0.81,zoneID=13645},{npcID=192539,x=0.394,y=0.698,zoneID=13862}},ends={{npcID=192539,x=0.598,y=0.716,zoneID=13644},{npcID=192539,x=0.718,y=0.81,zoneID=13645},{npcID=192539,x=0.394,y=0.698,zoneID=13862}},coords={x=0.598,y=0.716,source="quest_giver",zoneID=13644},questType="standard"},
[70129] = {id=70129,name="Toejam the Terrible",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="You're right, I'm not strong enough to take on this yeti... not alone! But you're here! The lair of the evil yeti, Toejam the Terrible , is just ahead. This cave is... big. Not scary! Maybe a little scary. Could you go in there and soften him up a bit? I'll... I'll be right behind you!",starts={{npcID=186542,x=0.16,y=0.504,zoneID=13646}},ends={{npcID=189533,x=0.138,y=0.49,zoneID=13646}},coords={x=0.16,y=0.504,source="quest_giver",zoneID=13646},questType="standard"},
[70132] = {id=70132,name="Stay a While",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=194076,x=0.578,y=0.668,mapID=2022}},ends={{npcID=194076,x=0.578,y=0.668,mapID=2022}},coords={x=0.578,y=0.668,source="quest_giver",mapID=2022},questType="standard"},
[70134] = {id=70134,name="Memories",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Thank you for listening to me, young one. I have a favor to ask. Don't worry. No more stories. When we left this place, I left a... time capsule of sorts. Would you... would you be able to retrieve it for me? We left it at the bottom of the Ruby Life Shrine, hidden behind one of the pillars. I hid it with a sigil. If you activate it, you should see my time capsule .",starts={{npcID=194076,x=0.578,y=0.668,zoneID=13644}},ends={{npcID=194076,x=0.578,y=0.668,zoneID=13644}},coords={x=0.578,y=0.668,source="quest_giver",zoneID=13644},questType="standard"},
[70135] = {id=70135,name="Encroaching Elementals",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=13644,description="The crafters, artisans, and explorers of the Dragonscale Expedition are ill-suited to the vigors of battle. But not you and I, $p. Here in the Dragon Isles, let us use that strength to protect those who can't protect themselves. Clear out the elementals encroaching from the north, so that the expedition can focus on their noble pursuits.",starts={{npcID=184452,x=0.762,y=0.33,zoneID=13644}},ends={{npcID=184452,x=0.762,y=0.33,zoneID=13644}},coords={x=0.762,y=0.33,source="quest_giver",zoneID=13644},questType="standard"},
[70136] = {id=70136,name="Haven't Got Time For the Pain",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Ugh... One moment... My first assignment... Unstable temporal energy seeping into the forest... Affecting the wildlife... Need to assess the impact and collect that magic for the Timewalkers... I was examining a pack of vorquin when I was attacked by a crazed bear overflowing with time magic. It caught me off guard. I barely escaped. Could you find my missing gear for me, ? Uh, you might also have to deal with that bear.",starts={{npcID=187098,x=0.574,y=0.788,zoneID=13647}},ends={{npcID=187098,x=0.574,y=0.788,zoneID=13647}},coords={x=0.574,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[70139] = {id=70139,name="Where There's a Ward, There's a Way",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="This reservoir used to be protected by three warding stones placed by Tyr. They were meant to stabilize the elemental magic that is prevalent in the Dragon Isles. When you woke me, I sensed damage done to the west ward. I fear the Primalists may have done this to all of them. Still, we must assess the damage done in order to figure out what we should do next.",starts={{npcID=189045,x=0.496,y=0.588,zoneID=13647}},ends={{npcID=189045,x=0.496,y=0.588,zoneID=13647}},coords={x=0.496,y=0.588,source="quest_giver",zoneID=13647},questType="standard"},
[70148] = {id=70148,name="Without Purpose",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Could I have a moment of your time? I'm worried about another dracthyr that passed through here. He asked my associates and me all kinds of questions, but seemed... disappointed with our answers. He called himself \" Talon Ethrethi \". I believe that makes him quite junior amongst your ranks? I got the sense that he could use a hand. Mind helping me keep the peace? I saw him talking with Kholmar over there.",starts={{npcID=192438,x=0.764,y=0.344,zoneID=13644}},ends={{npcID=192438,x=0.764,y=0.344,zoneID=13644}},coords={x=0.764,y=0.344,source="quest_giver",zoneID=13644},questType="standard"},
[70154] = {id=70154,name="A Gateway to Somewhere",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,description="The enchantment will protect us from the unstable energy contained within. I will open the way to the nearest stone. Once you pass through, stay close. I shall need your assistance when we arrive to power up the device.",starts={{npcID=189764,x=0.458,y=0.406,zoneID=13646}},ends={{npcID=189764,x=0.458,y=0.406,zoneID=13646}},coords={x=0.458,y=0.406,source="quest_giver",zoneID=13646},questType="standard"},
[70155] = {id=70155,name="Look, Listen, and Breathe",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Hail, . Few stop to say hello, let alone stay for a time. Most are in a rush to their next destination. Would you like to fish with me?",starts={{npcID=194282,x=0.34,y=0.594,zoneID=13645}},ends={{npcID=194282,x=0.34,y=0.594,zoneID=13645}},coords={x=0.34,y=0.594,source="quest_giver",zoneID=13645},questType="standard"},
[70156] = {id=70156,name="An Ancient Awakening",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The waygate sits just behind me. There is no way to tell how long we have until the waning enchantment on this vessel fades, or even worse, breaks. That amount of unstable energy being released could be catastrophic. Shall we continue?",starts={{npcID=189764,x=0.458,y=0.406,zoneID=13646}},ends={{npcID=189066,x=0.472,y=0.902,zoneID=13644}},coords={x=0.458,y=0.406,source="quest_giver",zoneID=13646},questType="standard"},
[70159] = {id=70159,name="A Taste of Home",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=13644,description="Oh, finally! Another dracthyr to lend a hand. My brother and I have been trying to cook up some rations to eat, but... Everything is so different around here. It's hard to find the same ingredients we used to cook with. But we can adapt. Go ask the Horde if they have anything we can substitute for vegetable matter, protein, and emulsifying fluid. Then we'll really have a meal.",starts={{npcID=194462,x=0.47,y=0.83,zoneID=13644}},ends={{npcID=194462,x=0.47,y=0.83,zoneID=13644}},coords={x=0.47,y=0.83,source="quest_giver",zoneID=13644},questType="standard"},
[70164] = {id=70164,name="A Tinker's Chance",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="If you have a moment, $p, I am close to a breakthrough! After the creche collapsed, I lost more than my ability to fight. I lost my identity as a dracthyr. Perhaps you can understand. I have always enjoyed putting things together and taking them apart, so Expedition seemed like a good fit for me. But this artifact is giving me some trouble. Would you ask Phosildral and Sibrit to review my notes? I want to prove I am a capable tinker... to them and to myself.",starts={{npcID=194136,x=0.654,y=0.586,zoneID=13644}},ends={{npcID=197543,x=0.654,y=0.586,zoneID=13644}},coords={x=0.654,y=0.586,source="quest_giver",zoneID=13644},questType="standard"},
[70166] = {id=70166,name="The Joy of Painting",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Do you like my collection? These are all the work of the greatest painter that ever lived, Hudson . They're rare and probably valuable--he's a recluse and hasn't painted anything in awhile. Oh, but I'd love to meet him... Or to learn from him! You... seem like the bold type. Would you find him for me? H-here! Take some of my work with you. Maybe he'll be impressed! Or maybe he'll think I'm terrible... oh dear.",starts={{npcID=194415,x=0.22,y=0.368,zoneID=13646}},ends={{npcID=194323,x=0.078,y=0.534,zoneID=13646}},coords={x=0.22,y=0.368,source="quest_giver",zoneID=13646},questType="standard"},
[70168] = {id=70168,name="Sad Little Accidents",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13982,description="You came all this way... I'm sorry. My dear Hudson used to love painting. It was his life! I don't know what's caused this block. A few weeks ago on his way back from a painting trip, he took all his unfinished paintings and threw each away in a fit of rage. Please, traveler, if you don't mind... could you find them? They may just give him back the spark he needs. Hudson does not shy away from dangerous places to find the best vistas. I hope you are prepared.",starts={{npcID=194425,x=0.078,y=0.534,zoneID=13646}},ends={{npcID=194323,x=0.078,y=0.534,zoneID=13646}},coords={x=0.078,y=0.534,source="quest_giver",zoneID=13646},questType="dungeon"},
[70169] = {id=70169,name="Even Trees Need Friends",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I know you and Ran are simply trying to be helpful. I don't think there's any helping me. My spark--my will to paint--is simply... gone. But Ran is right. I owe you at least to try. Bring this budding artist friend of yours to me.",starts={{npcID=194323,x=0.078,y=0.534,zoneID=13646}},ends={{npcID=194415,x=0.22,y=0.368,zoneID=13646}},coords={x=0.078,y=0.534,source="quest_giver",zoneID=13646},questType="standard"},
[70170] = {id=70170,name="Beat the Demons Out of It",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=14011,description="He can be very stubborn, I'm afraid. But I can't just give up on him. We'll just have to try again! There are more paintings still out there he threw out. These were in even more dangerous locations, so I hope you are up for the challenge!",starts={{npcID=194425,x=0.078,y=0.534,zoneID=13646}},ends={{npcID=194323,x=0.078,y=0.534,zoneID=13646}},coords={x=0.078,y=0.534,source="quest_giver",zoneID=13646},questType="dungeon"},
[70171] = {id=70171,name="Happy Little Accidents",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Ranpiata 's eyes look damp.> Is it me? Am I the reason he has lost his spark? He says he loves me, but... you heard how not painting makes him feel. I want what is best for him. If he is better off... I will go. There is one last piece he threw away. The last thing he tried to draw before giving up. I could not bear to see it go. I hid it away in our home. Please... bring it to him... as a memento.",starts={{npcID=194425,x=0.078,y=0.534,zoneID=13646}},ends={{npcID=194415,x=0.22,y=0.368,zoneID=13646}},coords={x=0.078,y=0.534,source="quest_giver",zoneID=13646},questType="standard"},
[70174] = {id=70174,name="The Shikaar",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Sansok Khan is the most skilled hunter in our clan. Though she cannot hear, she proved her capabilities time and time again as both a hunter and a leader. She is a mentor to us all, a trusted leader, and a fierce defender of the Maruuk. It is an honor for you to speak with her.",starts={{npcID=185882,x=0.756,y=0.316,zoneID=13645}},ends={{npcID=181217,x=0.856,y=0.252,zoneID=13645}},coords={x=0.756,y=0.316,source="quest_giver",zoneID=13645},questType="standard"},
[70175] = {id=70175,name="Broken Banding",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,ends={{npcID=193915,x=0.754,y=0.338,zoneID=13644}},questType="standard"},
[70178] = {id=70178,name="Expedition Supply Kit",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,description="Explorer, your discoveries have been invaluable. There is even more out there to uncover and we have the tools to help you do it. Come back to the Dragonscale Basecamp and gear up using the Expedition Supply Kit .",questType="standard"},
[70179] = {id=70179,name="A Two for One Deal",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Greetings, adventurer! Say, you look like a capable person. Could you give me a hand? Azkra and I are charged with watching over this tower, which is in what I like to call \"an exciting state of pre-renovation.\" My problem is as we started repairs, the local earth elementals attacked us! So I thought \"Zefren, why not take care of the earth elementals and get some building materials at the same time?\" Which is where you come in! Could you help?",starts={{npcID=194525,x=0.544,y=0.308,zoneID=13644}},ends={{npcID=194525,x=0.544,y=0.308,zoneID=13644}},coords={x=0.544,y=0.308,source="quest_giver",zoneID=13644},questType="standard"},
[70180] = {id=70180,name="Jump-Start? Jump-Starting!",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Some folks in the city claim this here device was created by the legendary Titan Watcher Tyr. Problem is we can't get it to work! We tried all the usual tricks, dissemblin', gyroscopin', a little mild electrocution. None of it sides the electrocution worked. Actually... I just had a great idea. See that gyrocopter over there? Hop in and let's see if we can give this titan thing a little more... juice.",starts={{npcID=196066,x=0.84,y=0.542,zoneID=13862}},ends={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},coords={x=0.84,y=0.542,source="quest_giver",zoneID=13862},questType="standard"},
[70181] = {id=70181,name="First Challenge of Tyr: Finesse",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13646,description="\"Wield the Keeper's power and carry its light to a better future for us all.\"",starts={{npcID=379290,x=0.672,y=0.308,zoneID=13646}},ends={{npcID=195827,x=0.672,y=0.308,zoneID=13646}},coords={x=0.672,y=0.308,source="quest_giver",zoneID=13646},questType="standard"},
[70182] = {id=70182,name="The Sweet Taste of Victory",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="There is great potential in small things. The Bottled Essence may feel light as a feather, but it holds immense power. Take it to the Engine of Innovation.",starts={{npcID=195827,x=0.672,y=0.308,zoneID=13646}},ends={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},coords={x=0.672,y=0.308,source="quest_giver",zoneID=13646},questType="standard"},
[70183] = {id=70183,name="Specialized Secrets: Alchemy",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,starts={{npcID=193110,x=0.518,y=0.33,zoneID=13645}},ends={{npcID=193110,x=0.518,y=0.33,zoneID=13645}},coords={x=0.518,y=0.33,source="quest_giver",zoneID=13645},questType="standard"},
