[70194] = {id=70194,name="Specialized Secrets: Tailoring",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,starts={{npcID=193110,x=0.518,y=0.33,zoneID=13645}},ends={{npcID=193110,x=0.518,y=0.33,zoneID=13645}},coords={x=0.518,y=0.33,source="quest_giver",zoneID=13645},questType="standard"},
[70195] = {id=70195,name="Taken By Storm",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="According to reports, the Nokhud were accompanied by an outsider wielding never-before-seen magic. This outsider tore through our ranks like a tempest. If the Nokhud have allies who can wreak this much havoc, we must find out as much as we can about them. I have sent my ohuna, Altan, to find this outsider. She has not flown back, and I am concerned. , can you search for clues about this outsider and see what has become of Altan?",starts={{npcID=195316,x=0.494,y=0.632,zoneID=13645}},ends={{npcID=190648,x=0.494,y=0.632,zoneID=13645}},coords={x=0.494,y=0.632,source="quest_giver",zoneID=13645},questType="standard"},
[70197] = {id=70197,name="The Call of the Isles",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,description="Are ye ready for the adventure of a lifetime? I know I sure am! Our allies have gathered and supplies are loaded. So what're you waiting for? Meet me at the Stormwind docks. It's time to set sail for the Dragon Isles !",ends={{npcID=189077,x=0.228,y=0.556,zoneID=1519}},questType="standard"},
[70198] = {id=70198,name="The Call of the Isles",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=14,description="Our allies gather in Durotar. This is a very exciting time! Join us, ! It's time to set sail for the Dragon Isles !",ends={{npcID=197279,x=0.558,y=0.126,zoneID=14}},questType="standard"},
[70199] = {id=70199,name="Catch and Release: Scalebelly Mackerel",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=197645,x=0.336,y=0.642,mapID=2022},{npcID=197645,x=0.814,y=0.784,mapID=2023},{npcID=197645,x=0.568,y=0.648,mapID=2025},{npcID=197645,x=0.742,y=0.414,mapID=2151}},ends={{npcID=194584,x=0.632,y=0.758,mapID=2022},{npcID=197645,x=0.336,y=0.642,mapID=2022},{npcID=197645,x=0.814,y=0.784,mapID=2023},{npcID=197645,x=0.568,y=0.648,mapID=2025},{npcID=197645,x=0.742,y=0.414,mapID=2151},{npcID=196840,x=0.588,y=0.348,mapID=2024}},coords={x=0.336,y=0.642,source="quest_giver",mapID=2024},questType="standard"},
