[70202] = {id=70202,name="Catch and Release: Cerulean Spinefish",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=197645,x=0.336,y=0.642,mapID=2022},{npcID=197645,x=0.814,y=0.784,mapID=2023},{npcID=197645,x=0.568,y=0.648,mapID=2025},{npcID=197645,x=0.742,y=0.414,mapID=2151}},ends={{npcID=194584,x=0.632,y=0.758,mapID=2022},{npcID=197645,x=0.336,y=0.642,mapID=2022},{npcID=197645,x=0.814,y=0.784,mapID=2023},{npcID=197645,x=0.568,y=0.648,mapID=2025},{npcID=197645,x=0.742,y=0.414,mapID=2151},{npcID=196840,x=0.588,y=0.348,mapID=2024}},coords={x=0.336,y=0.642,source="quest_giver",mapID=2112},questType="standard"},
[70203] = {id=70203,name="Catch and Release: Temporal Dragonhead",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=197645,x=0.336,y=0.642,mapID=2022},{npcID=197645,x=0.814,y=0.784,mapID=2023},{npcID=197645,x=0.568,y=0.648,mapID=2025},{npcID=197645,x=0.742,y=0.414,mapID=2151}},ends={{npcID=194584,x=0.632,y=0.758,mapID=2022},{npcID=197645,x=0.336,y=0.642,mapID=2022},{npcID=197645,x=0.814,y=0.784,mapID=2023},{npcID=197645,x=0.568,y=0.648,mapID=2025},{npcID=197645,x=0.742,y=0.414,mapID=2151},{npcID=196840,x=0.588,y=0.348,mapID=2024}},coords={x=0.336,y=0.642,source="quest_giver",mapID=2024},questType="standard"},
[70204] = {id=70204,name="Golden Claw",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,ends={{npcID=193915,x=0.754,y=0.338,zoneID=13644}},questType="standard"},
[70207] = {id=70207,name="Tail Fragment",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,ends={{npcID=193915,x=0.754,y=0.338,zoneID=13644}},questType="standard"},
[70210] = {id=70210,name="Tradition Not Forgotten",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="One tradition for the Aylaag as we stay at this camp is for our members to make the pilgrimage to the Eternal Kurgans to ask for journeys safe from that which plagued our ancestors. The presence of the Nokhud has made this pilgrimage perilous. If you do not mind, I would ask you would uphold our tradition for us.",starts={{npcID=185867,x=0.558,y=0.518,zoneID=13645}},ends={{npcID=185867,x=0.558,y=0.518,zoneID=13645}},coords={x=0.558,y=0.518,source="quest_giver",zoneID=13645},questType="standard"},
[70211] = {id=70211,name="Stomping Explorers",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The influx of explorers to the Dragon Isles isn't letting up anytime soon. We need to replenish your stock of Explorer's Plate Boots . Even serevite can't withstand what is being asked of these boots. Get to work and see me when you have finished the job.",starts={{npcID=185546,x=0.37,y=0.468,zoneID=13862}},ends={{npcID=185546,x=0.37,y=0.468,zoneID=13862}},coords={x=0.37,y=0.468,source="quest_giver",zoneID=13862},questType="standard"},
[70212] = {id=70212,name="Penumbrus",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[70213] = {id=70213,name="Harkyn Grymstone",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[70215] = {id=70215,name="Curiosity is Key",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,description="My hesitation to discuss these symbols was not for a lack of trust in you, but rather the unknown nature of these symbols and the stones upon which they reside. Yes, stones. Multiple, in fact. Scattered across the Isles. Warpcaster Delandra glances at you. A hint of curiosity and excitement glows in her eyes.> You did not know. Very well. Your persistence and willingness to seek me out shows that you are keen to understand your recent discovery. Perhaps it is time we discuss this at length.",starts={{npcID=189764,x=0.458,y=0.406,zoneID=13646}},ends={{npcID=189764,x=0.458,y=0.406,zoneID=13646}},coords={x=0.458,y=0.406,source="quest_giver",zoneID=13646},questType="standard"},
[70220] = {id=70220,name="Shady Sanctuary",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="We must inform the rest of the green dragonflight that the barrier to the Ancient Bough is under threat. Gerithus and I have much to discuss. , I will place my mark upon you. The other dragons who see it will know that you are my trusted messenger. Go and rally my flight. They must know and prepare for the battle ahead.",starts={{npcID=188106,x=0.282,y=0.576,zoneID=13645}},ends={{npcID=188106,x=0.282,y=0.576,zoneID=13645}},coords={x=0.282,y=0.576,source="quest_giver",zoneID=13645},questType="standard"},
[70221] = {id=70221,name="Show Your Mettle",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=192574,x=0.602,y=0.722,mapID=2022},{npcID=192574,x=0.394,y=0.698,mapID=2112}},ends={{npcID=192574,x=0.602,y=0.722,mapID=2022},{npcID=192574,x=0.394,y=0.698,mapID=2112}},coords={x=0.602,y=0.722,source="quest_giver",mapID=2112},questType="standard"},
[70229] = {id=70229,name="Boku the Mystic",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The mystics were called away to Ridgewater Retreat a few days ago, but one mystic remains. His name is Boku. He can be found on top of the hill at the Ohn'ahran shrine. He's just an initiate, but he should be able to commune with Ohn'ahra and acquire her blessing. With Ohn'ahra on our side, we might be able to win this war before it starts.",starts={{npcID=187787,x=0.418,y=0.618,zoneID=13645}},ends={{npcID=186290,x=0.368,y=0.572,zoneID=13645}},coords={x=0.418,y=0.618,source="quest_giver",zoneID=13645},questType="standard"},
[70233] = {id=70233,name="Axe Shortage",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="A mix-up with orders resulted in a severe shortage of new axes for our explorers. We have an immediate need for more Draconium Axes and are looking for all blacksmiths to pitch in. In return, I will impart new Blacksmithing Knowledge to you to assist in making even more epic pieces.",starts={{npcID=185546,x=0.37,y=0.468,zoneID=13862}},ends={{npcID=185546,x=0.37,y=0.468,zoneID=13862}},coords={x=0.37,y=0.468,source="quest_giver",zoneID=13862},questType="standard"},
[70234] = {id=70234,name="All this Hammering",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The anvils have not been quiet since the Dragon Isles awoke. The anvils are doing fine, but our hammers are starting to crack. To keep up with the demand, we need to restock.",starts={{npcID=185546,x=0.37,y=0.468,zoneID=13862}},ends={{npcID=185546,x=0.37,y=0.468,zoneID=13862}},coords={x=0.37,y=0.468,source="quest_giver",zoneID=13862},questType="standard"},
[70235] = {id=70235,name="Repair Bill",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The Dragon Isles have not experienced conflict like this in millennia. Our work is not in dispute, but any good armor suffers from all of this constant use. I have a big order for Serevite Repair Hammers and I need everyone I can get to fill it. If you help out, I will again give you more information to expand your Dragon Isles Blacksmithing skills.",starts={{npcID=185546,x=0.37,y=0.468,mapID=2112}},ends={{npcID=185546,x=0.37,y=0.468,mapID=2112}},coords={x=0.37,y=0.468,source="quest_giver",mapID=2151},questType="standard"},
[70236] = {id=70236,name="Dislodged Dragoneye",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,ends={{npcID=193915,x=0.754,y=0.338,zoneID=13644}},questType="standard"},
[70239] = {id=70239,name="Untold Regrets",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Duroz is old, sick, and stubborn as a kodo. There was no stopping him getting on the airship to come here. Best I could do was come be his walking stick. I've seen him in pain enough times on the battlefield to know when he's hiding it. He's been getting worse every day out here. Can you help me get him to the potion makers? Ale's not doing the trick anymore. If you can carry our weapons, I can help him walk.",starts={{npcID=194801,x=0.568,y=0.644,zoneID=13644}},ends={{npcID=194805,x=0.572,y=0.656,zoneID=13644}},coords={x=0.568,y=0.644,source="quest_giver",zoneID=13644},questType="standard"},
[70240] = {id=70240,name="Pain Management",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="It is a good thing you brought him here when you did. I can tell he is in a great deal of pain, though he bears it well. So must we all when it comes time. I am afraid that it is age that ails him and not illness, but I may be able to relieve some portion of his suffering. Would you mind gathering some snapflowers, shallowlilies, and pure water from the garden nearby? I can create a pain medicine with these components, if you find enough.",starts={{npcID=194805,x=0.572,y=0.656,zoneID=13644}},ends={{npcID=194800,x=0.568,y=0.644,zoneID=13644}},coords={x=0.572,y=0.656,source="quest_giver",zoneID=13644},questType="standard"},
[70241] = {id=70241,name="The Bitter End",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="It just happened. I--He was sleeping and I looked away and-- We came back here every day, he just wanted to sit with the whelps, I didn't know he-- No, I knew. I knew. But I don't know what to do now. What do I do with him? Can you-- Can you find Bathoras ?",starts={{npcID=194801,x=0.568,y=0.644,zoneID=13644}},ends={{npcID=194805,x=0.572,y=0.656,zoneID=13644}},coords={x=0.568,y=0.644,source="quest_giver",zoneID=13644},questType="standard"},
[70242] = {id=70242,name="Life After Life",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I could sense that his friend bore a deep scar. Something in this place reopened it--perhaps so that it could heal cleanly this time. Now it is Kolgar's time to heal. In the terrace above us, you will find my friend Trellain working with the enchanters. Tell him that I require one of the vessels he uses in his work. He will give it to you freely.",starts={{npcID=194805,x=0.572,y=0.656,zoneID=13644}},ends={{npcID=194805,x=0.572,y=0.656,zoneID=13644}},coords={x=0.572,y=0.656,source="quest_giver",zoneID=13644},questType="standard"},
[70244] = {id=70244,name="Nokhud Can Come of This",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="For thousands of years, the Teerai have guarded the Horn of Drusahl, our most sacred relic. By sacking this village, Balakar has betrayed everything it means to be Maruuk. There can be no redemption for him now. We must retake the Horn before Balakar can destroy it and rescue any Teerai who yet live. I am going with you to personally bring that false Khan to justice. The Nokhud will know the wrath of the Khanam Matra!",starts={{npcID=188068,x=0.73,y=0.406,zoneID=13645}},ends={{npcID=188068,x=0.73,y=0.406,zoneID=13645}},coords={x=0.73,y=0.406,source="quest_giver",zoneID=13645},questType="standard"},
[70268] = {id=70268,name="Memories Revived",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="You found a partially destroyed diary . It appears to be written from the view point of a young black dragon woman, before the corruption. While the back part of it is illegible, skimming through the first part, a name stands out to you. Veritistrasz .",ends={{npcID=194076,x=0.578,y=0.668,zoneID=13644}},questType="standard"},
[70279] = {id=70279,name="Blood of Dragons",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="As you've no doubt seen, this land contains creatures which grow beyond their normal size. We consider these beasts as blessed by the gods of the wild, and they are often considered honorable targets for hunters to prove their strength. One of these beasts, which we call Karkidan , is nearby. I would be most impressed if you managed to take it down.",starts={{npcID=185870,x=0.556,y=0.524,zoneID=13645}},ends={{npcID=185870,x=0.556,y=0.524,zoneID=13645}},coords={x=0.556,y=0.524,source="quest_giver",zoneID=13645},questType="group"},
[70299] = {id=70299,name="Draconic Defensive",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I've heard words on the wind of outsiders allying with Clan Nokhud in an effort to defeat our dragon neighbors. These Primalists are a blight on the plains of our ancestors. Slay them, and bring me the cores of the elementals they command.",starts={{npcID=185867,x=0.558,y=0.518,zoneID=13645}},ends={{npcID=185867,x=0.558,y=0.518,zoneID=13645}},coords={x=0.558,y=0.518,source="quest_giver",zoneID=13645},questType="standard"},
[70319] = {id=70319,name="Nergazurai",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="My uncle told me many tales of his battle with a hornstrider named Nergazurai. He told me of its fuchsia scales weaving through the hills of the plains as it seeks its prey, its razor-sharp talons and venomous bite. While I was out hunting I saw the flash, but it was too late; it left me with a nasty bite in my shoulder. He was as terrible as my uncle described, but I came out alive. I need to clean the infection from his bite. Please, collect the reagents I need. Time is of the essence.",starts={{npcID=194904,x=0.846,y=0.252,zoneID=13645}},ends={{npcID=194904,x=0.846,y=0.252,zoneID=13645}},coords={x=0.846,y=0.252,source="quest_giver",zoneID=13645},questType="standard"},
[70335] = {id=70335,name="Simple Excavation Tools",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=188265,x=0.478,y=0.82,mapID=2022}},ends={{npcID=188265,x=0.478,y=0.82,mapID=2022}},coords={x=0.478,y=0.82,source="quest_giver",mapID=2022},questType="standard"},
[70337] = {id=70337,name="Emberwatch",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Hail, outsider. The winds tell me of a group taking shelter in the ruins of Emberwatch. They seem only interested in the past while we centaur choose to live for the present under the grace of Ohn'ahra. Nonetheless, they are guests in our home. I have fashioned for them these wind chimes so they may hear Ohn'ahra's presence. May it bring their hearth some joy and comfort.",starts={{npcID=195239,x=0.622,y=0.364,zoneID=13645}},ends={{npcID=190089,x=0.66,y=0.25,zoneID=13645}},coords={x=0.622,y=0.364,source="quest_giver",zoneID=13645},questType="standard"},
[70338] = {id=70338,name="They Took the Kits",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="If Sylvie is this distressed, that must mean it's her kits that are in there! While she was infected, the giants must have kit-napped her babies and she was too weak to save them. Kits are energetic at this age, hopefully they've all been quick enough to evade the giants until now... Here, make use of my invisibility charm-- Quickly, you must save them before they're eaten!",starts={{npcID=192830,x=0.636,y=0.288,zoneID=13646}},ends={{npcID=192830,x=0.636,y=0.288,zoneID=13646}},coords={x=0.636,y=0.288,source="quest_giver",zoneID=13646},questType="standard"},
[70339] = {id=70339,name="In Tyr's Footsteps: The Ohn'ahran Plains",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13645,description="Though you have done well in your first challenge, do not think you shall surpass all so easily. Keeper Tyr meant the Engine of Innovation to be only for those worthy enough to use it wisely. If you are undeterred, the next challenge shall be found in the Ohn'ahran Plains. I look forward to testing your capabilities, adventurer.",starts={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},ends={{npcID=380540,x=0.662,y=0.553,zoneID=13645}},coords={x=0.838,y=0.536,source="quest_giver",zoneID=13862},questType="standard"},
[70341] = {id=70341,name="Well-Earned Victory",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="The smallest of things can contain the greatest of treasures. Take the essence to the Engine of Innovation.",starts={{npcID=195924,x=0.662,y=0.554,zoneID=13645}},ends={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},coords={x=0.662,y=0.554,source="quest_giver",zoneID=13645},questType="standard"},
[70351] = {id=70351,name="Garden Party",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I've been tending to this garden for years, preparing for the day I'd finally accept my Lifecalling. Now that day is here! I love flowers and all trees and plants--even the bugs that live amongst them. I can feel nature's spirit--the Great Dragon Spirit--when I tend the garden. There's only one thing left to do. I'm going to invoke the Great Dragon Spirit, just like the legends. Akora smiles brightly.> Meet me down in the garden by the pool where her bones rest. I'll explain more there.",starts={{npcID=191012,x=0.618,y=0.736,zoneID=13644}},ends={{npcID=190866,x=0.602,y=0.664,zoneID=13644}},coords={x=0.618,y=0.736,source="quest_giver",zoneID=13644},questType="standard"},
[70352] = {id=70352,name="Scaling Ever Higher",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="You there, outsider! You have killed proto dragons before, yes? So it stands to reason that your experience combined with my hunting prowess, we can take down quite a few! There are springs around here that attract draconic beasts. Help me prove to my foolish other half that I am the better hunter.",starts={{npcID=185881,x=0.706,y=0.628,zoneID=13645}},ends={{npcID=185881,x=0.706,y=0.628,zoneID=13645}},coords={x=0.706,y=0.628,source="quest_giver",zoneID=13645},questType="standard"},
[70355] = {id=70355,name="Dragon Isles Alchemy",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=191893,x=0.602,y=0.722,mapID=2022}},ends={{npcID=191893,x=0.602,y=0.722,mapID=2022}},coords={x=0.602,y=0.722,source="quest_giver",mapID=2022},questType="standard"},
[70357] = {id=70357,name="Dragon Isles Blacksmithing",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=192164,x=0.258,y=0.544,mapID=2022}},ends={{npcID=192164,x=0.258,y=0.544,mapID=2022}},coords={x=0.258,y=0.544,source="quest_giver",mapID=2022},questType="standard"},
[70358] = {id=70358,name="Dragon Isles Blacksmithing",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=192563,x=0.764,y=0.344,mapID=2022}},ends={{npcID=192563,x=0.764,y=0.344,mapID=2022}},coords={x=0.764,y=0.344,source="quest_giver",mapID=2022},questType="standard"},
