[70360] = {id=70360,name="Dragon Isles Enchanting",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=192055,x=0.758,y=0.332,mapID=2022}},ends={{npcID=192055,x=0.758,y=0.332,mapID=2022}},coords={x=0.758,y=0.332,source="quest_giver",mapID=2022},questType="standard"},
[70361] = {id=70361,name="Dragon Isles Inscription",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=198125,x=0.572,y=0.582,mapID=2022}},ends={{npcID=198125,x=0.572,y=0.582,mapID=2022}},coords={x=0.572,y=0.582,source="quest_giver",mapID=2022},questType="standard"},
[70362] = {id=70362,name="Dragon Isles Leatherworking",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=192048,x=0.766,y=0.348,mapID=2022}},ends={{npcID=192048,x=0.766,y=0.348,mapID=2022}},coords={x=0.766,y=0.348,source="quest_giver",mapID=2022},questType="standard"},
[70363] = {id=70363,name="Dragon Isles Skinning",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=192558,x=0.766,y=0.348,mapID=2022}},ends={{npcID=192558,x=0.766,y=0.348,mapID=2022}},coords={x=0.766,y=0.348,source="quest_giver",mapID=2022},questType="standard"},
[70364] = {id=70364,name="Dragon Isles Herbalism",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=192010,x=0.574,y=0.658,mapID=2022}},ends={{npcID=192010,x=0.574,y=0.658,mapID=2022}},coords={x=0.574,y=0.658,source="quest_giver",mapID=2022},questType="standard"},
[70365] = {id=70365,name="Dragon Isles Jewelcrafting",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=192121,x=0.254,y=0.542,mapID=2022}},ends={{npcID=192121,x=0.254,y=0.542,mapID=2022}},coords={x=0.254,y=0.542,source="quest_giver",mapID=2022},questType="standard"},
[70366] = {id=70366,name="Dragon Isles Tailoring",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=191894,x=0.614,y=0.7,mapID=2022}},ends={{npcID=191894,x=0.614,y=0.7,mapID=2022}},coords={x=0.614,y=0.7,source="quest_giver",mapID=2022},questType="standard"},
[70368] = {id=70368,name="Occupation Examination",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,description="Hello! Are you interested in working with the Artisan's Consortium to earn plentiful profits and provide valuable goods and services to clients across Azeroth? ...Hmm? You have no professions? What a missed opportunity! Haephesta ponders for a moment.> I know! I will ask you a series of questions about your personality, and we will find out together which profession best suits you! How does that sound?",starts={{npcID=192498,x=0.578,y=0.682,zoneID=13644},{npcID=195043,x=0.718,y=0.786,zoneID=13645}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644},{npcID=195043,x=0.718,y=0.786,zoneID=13645}},coords={x=0.578,y=0.682,source="quest_giver",zoneID=13644},questType="standard"},
[70370] = {id=70370,name="Occupation Examination",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,description="Hello! Are you interested in working with the Artisan's Consortium to earn plentiful profits and provide valuable goods and services to clients across Azeroth? Excellent! Which two skills have you trained in? ...Hmm? You have only one profession? What a missed opportunity! Haephesta ponders for a moment.> I know! I will ask you a series of questions about your personality, and we will find out together which second profession best complements your first one! How does that sound?",starts={{npcID=192498,x=0.578,y=0.682,zoneID=13644},{npcID=195043,x=0.718,y=0.786,zoneID=13645}},ends={{npcID=192498,x=0.578,y=0.682,zoneID=13644},{npcID=195043,x=0.718,y=0.786,zoneID=13645}},coords={x=0.578,y=0.682,source="quest_giver",zoneID=13644},questType="standard"},
[70371] = {id=70371,name="Deathwingurlugull!",level=40,requiredLevel=40,faction="horde",expansion=9,zoneID=14092,description="Deathwingurlugull! Deathwingurlugull! Deathwingurlugull delgrbrrl!! Grrrooooooooom blarglg!!",starts={{npcID=183855,x=0.6,y=0.66,zoneID=14092}},ends={{npcID=183855,x=0.6,y=0.66,zoneID=14092}},coords={x=0.6,y=0.66,source="quest_giver",zoneID=14092},questType="standard"},
[70373] = {id=70373,name="Deathwingurlugull!",level=40,requiredLevel=40,faction="alliance",expansion=9,zoneID=14092,description="Deathwingurlugull! Deathwingurlugull! Deathwingurlugull delgrbrrl!! Grrrooooooooom blarglg!!",starts={{npcID=183854,x=0.598,y=0.66,zoneID=14092}},ends={{npcID=183854,x=0.598,y=0.66,zoneID=14092}},coords={x=0.598,y=0.66,source="quest_giver",zoneID=14092},questType="standard"},
[70374] = {id=70374,name="Himia, the Blessed",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The Elements lay claim to this land and do not welcome our intrusion. O, Elements, have you forgotten our protector--Air! Invisible, yet omnipresent and vital for all existence! Forgotten, as easy as you breathe it. After facing me, you will never forget again.",starts={{npcID=190950,x=0.492,y=0.494,zoneID=13645}},ends={{npcID=190164,x=0.416,y=0.566,zoneID=13645}},coords={x=0.492,y=0.494,source="quest_giver",zoneID=13645},questType="standard"},
[70376] = {id=70376,name="Second Challenge of Tyr: Might",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13645,description="\"Wield the Keeper's power and show the undaunted determination of one who stands strong.\"",starts={{npcID=380540,x=0.662,y=0.553,zoneID=13645}},ends={{npcID=195924,x=0.662,y=0.554,zoneID=13645}},coords={x=0.662,y=0.553,source="quest_giver",zoneID=13645},questType="standard"},
[70377] = {id=70377,name="Derelict Fashion",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,ends={{npcID=198062,x=0.394,y=0.484,zoneID=13647}},questType="standard"},
[70414] = {id=70414,name="Shaky Grounds",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="In the name of Khaz'goroth, what goes on here? This magma works with a mind of its own, consuming these elemental cavestones from below. Tis more than chance causin' this... I aim to figure it out! Place these Shattering Totems next to each trapped elemental to free them!",starts={{npcID=195234,x=0.37,y=0.558,zoneID=13644}},ends={{npcID=195234,x=0.37,y=0.558,zoneID=13644}},coords={x=0.37,y=0.558,source="quest_giver",zoneID=13644},questType="standard"},
[70437] = {id=70437,name="To Tyrhold",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Centuries have passed since the flights last visited Tyrhold. Nevertheless, we must travel there and investigate if the Mother Oathstone still functions. Come, speak with me at the Seat of the Aspects. We must learn about the dangers we may face at Tyr's former stronghold.",starts={{npcID=187678,x=0.58,y=0.358,zoneID=13862}},ends={{npcID=187658,x=0.574,y=0.586,zoneID=13647}},coords={x=0.58,y=0.358,source="quest_giver",zoneID=13862},questType="standard"},
[70438] = {id=70438,name="Flying Fish",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The fish could be biting better, don't you think? You know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it? Maybe you and your drake could give it a try?",starts={{npcID=195338,x=0.638,y=0.766,zoneID=13644}},ends={{npcID=195338,x=0.638,y=0.766,zoneID=13644}},coords={x=0.638,y=0.766,source="quest_giver",zoneID=13644},questType="standard"},
[70444] = {id=70444,name="The Fields of Ferocity",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="To the bravest Shikaar! Gather your best and head on over to the Fields of Ferocity . You could be crowned the fiercest of them all! Prove your might. Show us your best fight! Terms and conditions apply.",starts={{npcID=380902,x=0.623,y=0.423,zoneID=13645}},ends={{npcID=188868,x=0.53,y=0.372,zoneID=13645}},coords={x=0.623,y=0.423,source="quest_giver",zoneID=13645},questType="group"},
[70446] = {id=70446,name="A Personal History",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="In delving into the archives here, I've found threads that point towards the Obsidian Observatory as a place of personal importance to the Earth-Warder. I can only guess what knowledge it may contain about the history of our flight. Given Emberthal's interest in the subject, I informed her of my discovery. I pray that wasn't a mistake. She has gone ahead to scout. Please, keep an eye on her. She is a competent soldier, but this subject is... troubling. Who knows what truths you may uncover.",starts={{npcID=193456,x=0.25,y=0.562,zoneID=13644}},ends={{npcID=196253,x=0.446,y=0.64,zoneID=13644}},coords={x=0.25,y=0.562,source="quest_giver",zoneID=13644},questType="standard"},
[70450] = {id=70450,name="Otter Devastation",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Hey there, friend. These here ottuks keep stealin' my catch! Personally, I'd blow 'em up, but our Tuskarr friends don't seem too keen on that action. I made this here Ottuk Deterent Device MK-SH4RK, but... I aint a great swimmer. You seem like you got the goods, why don't ya do us all a favor, activate the device, swimmy-swim around over there, and scare 'em off?",starts={{npcID=195444,x=0.636,y=0.75,zoneID=13644}},ends={{npcID=195444,x=0.636,y=0.75,zoneID=13644}},coords={x=0.636,y=0.75,source="quest_giver",zoneID=13644},questType="standard"},
[70501] = {id=70501,name="License to Hunt",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,description="Ah, finally ready to prove yourself as a hunter? Keep in mind this is not as simple as running around and hunting everything that moves. The Shikaar hunt with purpose. We hunt to feed and clothe the clan, to prove our strength against mighty foes, and to balance nature. We do not hunt the land barren, we sow the seeds for future Grand Hunts as we go. Prove yourself capable of following these instructions and you may join us. However I do not have confidence in your friend there succeeding.",starts={{npcID=195454,x=0.64,y=0.41,zoneID=13645}},ends={{npcID=195454,x=0.64,y=0.41,zoneID=13645}},coords={x=0.64,y=0.41,source="quest_giver",zoneID=13645},questType="standard"},
[70503] = {id=70503,name="The Vigilance of Tyr",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="Bodies, broken gear, uncontrolled titan energy. What a disregard for safety, and... and protocol! It looks like they found the stone and it was unstable, bursting into pieces. Fortunately, I'm particularly adept at repairing magical devices. But before I can reform the stone we need to collect each and every piece.",starts={{npcID=193350,x=0.538,y=0.506,zoneID=13646}},ends={{npcID=193350,x=0.538,y=0.506,zoneID=13646}},coords={x=0.538,y=0.506,source="quest_giver",zoneID=13646},questType="standard"},
[70507] = {id=70507,name="The Insight of Tyr",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,description="Did ya see Szar Skeleth on your way in? It's that ruined tower to the northeast. We've got a bit of a good news, bad news situation there. The good news is the stone's already been found. Bad news is it was found by the Sundered Flame, specifically a magic-using dracthyr named Makko. And they're using it to control gorlocs. Did I mention the dracthyr's misuse of the stone drove them mad? Well, good luck!",starts={{npcID=191159,x=0.4,y=0.674,zoneID=13645}},ends={{npcID=191159,x=0.4,y=0.674,zoneID=13645}},coords={x=0.4,y=0.674,source="quest_giver",zoneID=13645},questType="standard"},
[70509] = {id=70509,name="Third Challenge of Tyr: Persistence",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13644,starts={{npcID=380918,x=0.64,y=0.414,zoneID=13644}},ends={{npcID=195737,x=0.64,y=0.414,zoneID=13644}},coords={x=0.64,y=0.414,source="quest_giver",zoneID=13644},questType="standard"},
[70510] = {id=70510,name="Victorious",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Once again I ask you to bring this essence to the Engine of Innovation.",starts={{npcID=195737,x=0.64,y=0.414,zoneID=13644}},ends={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},coords={x=0.64,y=0.414,source="quest_giver",zoneID=13644},questType="standard"},
[70526] = {id=70526,name="Ohn'ahran Plains Rally",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[70530] = {id=70530,name="Examination Week",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The students at Algeth'ar Academy ran out of solutions... again. Forgive me for asking, but could you gather more Dragon's Alchemical Solution so they can continue their studies?",starts={{npcID=185545,x=0.364,y=0.714,zoneID=13862}},ends={{npcID=185545,x=0.364,y=0.714,zoneID=13862}},coords={x=0.364,y=0.714,source="quest_giver",zoneID=13862},questType="standard"},
[70531] = {id=70531,name="Mana Markets",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Demand for mana potions has increased dramatically this week, $p. I will need your assistance filling customers' orders. Surely as a skilled alchemist you can spare a few, yes?",starts={{npcID=185545,x=0.364,y=0.714,zoneID=13862}},ends={{npcID=185545,x=0.364,y=0.714,zoneID=13862}},coords={x=0.364,y=0.714,source="quest_giver",zoneID=13862},questType="standard"},
[70532] = {id=70532,name="Aiding the Raiding",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Oh $p, I am glad to see you. Several champions have been injured in the latest assault against the Primalists. We are greatly in need of healing potions. As an adventurer yourself, I imagine you have several on hand already. We will need many.",starts={{npcID=185545,x=0.364,y=0.714,zoneID=13862}},ends={{npcID=185545,x=0.364,y=0.714,zoneID=13862}},coords={x=0.364,y=0.714,source="quest_giver",zoneID=13862},questType="standard"},
[70533] = {id=70533,name="Draught, Oiled Again",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Did you know that Writhefire Oil is an excellent reagent for finishing your draughts? I did. And now I am out of it. I cannot work without a plentiful stock of oils. Please $p, help me restock my laboratory.",starts={{npcID=185545,x=0.364,y=0.714,zoneID=13862}},ends={{npcID=185545,x=0.364,y=0.714,zoneID=13862}},coords={x=0.364,y=0.714,source="quest_giver",zoneID=13862},questType="standard"},
[70539] = {id=70539,name="And You Thought They Did Nothing",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Hey sparky, you know what everyone forgets they need when they're flying around on dragons? Goggles. You know what we sold out of today? Goggles. You know what I need from you right now? You guessed it!",starts={{npcID=185548,x=0.422,y=0.488,zoneID=13862}},ends={{npcID=185548,x=0.422,y=0.488,zoneID=13862}},coords={x=0.422,y=0.488,source="quest_giver",zoneID=13862},questType="standard"},
[70540] = {id=70540,name="An Engineer's Best Friend",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Hey sparky, have you seen my... Err... maybe hand me the... That's it--I think it's time we start keeping a few more tools around this shop, you know what I'm saying?",starts={{npcID=185548,x=0.422,y=0.488,zoneID=13862}},ends={{npcID=185548,x=0.422,y=0.488,zoneID=13862}},coords={x=0.422,y=0.488,source="quest_giver",zoneID=13862},questType="standard"},
[70541] = {id=70541,name="Hunting Tactics: Companion",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13647,description="Your renown with the Maruuk grows. You may now hunt alongside a tenacious bakar or swift ohuna companion.",starts={{npcID=192926,x=0.428,y=0.804,zoneID=13644},{npcID=192926,x=0.624,y=0.416,zoneID=13645},{npcID=192926,x=0.368,y=0.36,zoneID=13646},{npcID=192926,x=0.344,y=0.666,zoneID=13647}},ends={{npcID=192926,x=0.428,y=0.804,zoneID=13644},{npcID=192926,x=0.624,y=0.416,zoneID=13645},{npcID=192926,x=0.368,y=0.36,zoneID=13646},{npcID=192926,x=0.344,y=0.666,zoneID=13647}},coords={x=0.428,y=0.804,source="quest_giver",zoneID=13644},questType="standard"},
[70542] = {id=70542,name="Azure Span Rally",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[70545] = {id=70545,name="Blingtron 8000...?",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Hey sparky, I've got a secret project going on. People are going to go wild! But I've run out of the basics.... You wanna be a pal and get me some bolts?",starts={{npcID=185548,x=0.422,y=0.488,zoneID=13862}},ends={{npcID=185548,x=0.422,y=0.488,zoneID=13862}},coords={x=0.422,y=0.488,source="quest_giver",zoneID=13862},questType="standard"},
[70550] = {id=70550,name="Welcome to the Assembly",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We could use your aid. The Sundered Flame have taken control over most of the Cobalt Assembly. Please help us in this fight against them. Our numbers are small, but there are a few things we can do to aid you.",starts={{npcID=194680,x=0.49,y=0.23,zoneID=13646}},ends={{npcID=194680,x=0.49,y=0.23,zoneID=13646}},coords={x=0.49,y=0.23,source="quest_giver",zoneID=13646},questType="standard"},
[70557] = {id=70557,name="No Scopes",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Great gadgets, sparky, do I have a big one for you today! Apparently, some firework fad caught on with the hunters. They try setting them off to scare the ducks into the air. Bet the ducks are way to smart for that, but it won't stop us from profiting! Think you're up to the task?",starts={{npcID=185548,x=0.422,y=0.488,zoneID=13862}},ends={{npcID=185548,x=0.422,y=0.488,zoneID=13862}},coords={x=0.422,y=0.488,source="quest_giver",zoneID=13862},questType="standard"},
[70558] = {id=70558,name="Disillusioned Illusions",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="My scribe apprentice, you could not have chosen better timing. There has been a terrible accident! All of the Illusion Parchment I ordered turned out to be real! Can you believe it! Do they think this is some game? Someone might get hurt! Do you think you could rectify this situation and create some real illusions?",starts={{npcID=185540,x=0.386,y=0.732,zoneID=13862}},ends={{npcID=185540,x=0.386,y=0.732,zoneID=13862}},coords={x=0.386,y=0.732,source="quest_giver",zoneID=13862},questType="standard"},
[70559] = {id=70559,name="Quill You Help?",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="My scribe apprentice, I am delighted to see you. Earlier today I had a few novices come in to try their hand at inscription. They all wrote with too much force and snapped their quill nibs right off! I hate to ask, but could you craft a few more quills to keep in stock?",starts={{npcID=185540,x=0.386,y=0.732,zoneID=13862}},ends={{npcID=185540,x=0.386,y=0.732,zoneID=13862}},coords={x=0.386,y=0.732,source="quest_giver",zoneID=13862},questType="standard"},
[70560] = {id=70560,name="The Most Powerful Tool: Good Documentation",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="My scribe apprentice, do you feel ready for writing today? The Dragonscale Expedition has brought copious notes from their adventures, and they have asked that we compile their chicken-scratch penmanship into a suitable compendium for field-ready review. And oh, my hand is simply not up for the task today. Could I rely on you once more?",starts={{npcID=185540,x=0.386,y=0.732,zoneID=13862}},ends={{npcID=185540,x=0.386,y=0.732,zoneID=13862}},coords={x=0.386,y=0.732,source="quest_giver",zoneID=13862},questType="standard"},
[70561] = {id=70561,name="A Scribe's Tragedy",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="My scribe apprentice! It is awful, just terrible! I cannot fathom how I am to go on in my life! Talendara begins weeping.> ...I have run out of ink! Could you please bottle some more?",starts={{npcID=185540,x=0.386,y=0.732,zoneID=13862}},ends={{npcID=185540,x=0.386,y=0.732,zoneID=13862}},coords={x=0.386,y=0.732,source="quest_giver",zoneID=13862},questType="standard"},
[70562] = {id=70562,name="The Plumbers, Mason",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Jewelcrafter, how would you feel about a chance to practice your prospecting techniques? The architects and plumbers of the Dragonscale Expedition have requested that we acquire some stones for the construction of a new bath house. I think you will find this a suitable task to occupy you and practice your masonry.",starts={{npcID=190094,x=0.406,y=0.612,zoneID=13862}},ends={{npcID=190094,x=0.406,y=0.612,zoneID=13862}},coords={x=0.406,y=0.612,source="quest_giver",zoneID=13862},questType="standard"},
[70563] = {id=70563,name="The Exhibition",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Oh jewelcrafter, how would you feel about a chance to practice your gemcutting? I was going to put on a display of various cuts, and I suppose I could exhibit your gems as well, so long as you hurry. Submit nothing less than the highest quality for this demonstration.",starts={{npcID=190094,x=0.406,y=0.612,zoneID=13862}},ends={{npcID=190094,x=0.406,y=0.612,zoneID=13862}},coords={x=0.406,y=0.612,source="quest_giver",zoneID=13862},questType="standard"},
[70564] = {id=70564,name="Spectacular",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Jewelcrafter, there is an exhibition coming up, and I am concerned that the clients will not be able to see the beauty of each cut without the proper lenses. You do not need anything fancy. Just make a few loupes so our customers can see clearly.",starts={{npcID=190094,x=0.406,y=0.612,zoneID=13862}},ends={{npcID=190094,x=0.406,y=0.612,zoneID=13862}},coords={x=0.406,y=0.612,source="quest_giver",zoneID=13862},questType="standard"},
[70565] = {id=70565,name="Separation by Saturation",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Oh jewelcrafter, do you like my necklace? Of course you do. But I cannot show it off properly unless it stands out. I know! Why don't you make a few simple pendants and we shall flood the market. Once everyone is wearing your designs, my necklace will be a sparkling cut above the rest!",starts={{npcID=190094,x=0.406,y=0.612,zoneID=13862}},ends={{npcID=190094,x=0.406,y=0.612,zoneID=13862}},coords={x=0.406,y=0.612,source="quest_giver",zoneID=13862},questType="standard"},
[70567] = {id=70567,name="When You Give Bakar a Bone",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="I had some of the most beautiful bonewrought bows, but our bakar got to them before they could be put to use. Bakar love to chew bones, whether bow or not, and now they are ruined! Can you aid me in crafting replacements?",starts={{npcID=185551,x=0.286,y=0.614,zoneID=13862}},ends={{npcID=185551,x=0.286,y=0.614,zoneID=13862}},coords={x=0.286,y=0.614,source="quest_giver",zoneID=13862},questType="standard"},
[70568] = {id=70568,name="Tipping the Scales",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Our scale bracers are finely crafted and highly in demand. I am finding it difficult to keep up with all of the orders! Would you lend your skill in replenishing my supply?",starts={{npcID=185551,x=0.286,y=0.614,zoneID=13862}},ends={{npcID=185551,x=0.286,y=0.614,zoneID=13862}},coords={x=0.286,y=0.614,source="quest_giver",zoneID=13862},questType="standard"},
[70569] = {id=70569,name="For Trisket, a Task Kit",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="I have many valued customers, but Trisket is one of my favorites. Most recently he came to me because his herbalist's pouch has worn out. I offered to make him a selection of baskets to replace his old pouch. Would you help me with these tasks, $p? Trisket would be appreciative.",starts={{npcID=185551,x=0.286,y=0.614,zoneID=13862}},ends={{npcID=185551,x=0.286,y=0.614,zoneID=13862}},coords={x=0.286,y=0.614,source="quest_giver",zoneID=13862},questType="standard"},
[70571] = {id=70571,name="Drums Here!",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="We are known far and wide for our drums--the centaur have been honing these skills for generations. Unfortunately this means that our drums are in short supply these days. You have skills of your own, I see. Perhaps you could help me craft a few drums for our stores?",starts={{npcID=185551,x=0.286,y=0.614,zoneID=13862}},ends={{npcID=185551,x=0.286,y=0.614,zoneID=13862}},coords={x=0.286,y=0.614,source="quest_giver",zoneID=13862},questType="standard"},
[70572] = {id=70572,name="The Cold Does Bother Them, Actually",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="If there is one thing I have learned in my years as a seamstress, $p, it is that adventurers will always underestimate the cold. I have explorers in the Azure Span begging me for warmer robes. Would you take pity on them and craft a few?",starts={{npcID=193649,x=0.318,y=0.67,zoneID=13862}},ends={{npcID=193649,x=0.318,y=0.67,zoneID=13862}},coords={x=0.318,y=0.67,source="quest_giver",zoneID=13862},questType="standard"},
[70582] = {id=70582,name="Weave Well Enough Alone",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="If there is one thing I have learned in my years as a seamstress, $p, it is the importance of practice. Always be practicing your craft, even when you believe you have mastered everything. I want you to be able to weave with excellence without my supervision. Why don't you practice this week? Make a few Wildercloth Bolts at the highest quality.",starts={{npcID=193649,x=0.318,y=0.67,zoneID=13862}},ends={{npcID=193649,x=0.318,y=0.67,zoneID=13862}},coords={x=0.318,y=0.67,source="quest_giver",zoneID=13862},questType="standard"},
[70586] = {id=70586,name="Sew Many Cooks",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="If there is one thing I have learned in my years as a seamstress, $p, it is that too many cooks spoil everything. In this case, I was going to go out for a drink and an order came in last minute for an entire wardrobe of chef's uniforms. If you could sew the hats, I will take care of everything else.",starts={{npcID=193649,x=0.318,y=0.67,zoneID=13862}},ends={{npcID=193649,x=0.318,y=0.67,zoneID=13862}},coords={x=0.318,y=0.67,source="quest_giver",zoneID=13862},questType="standard"},
[70587] = {id=70587,name="A Knapsack Problem",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="If there is one thing I have learned in my years as a seamstress, $p, it is that you can never have enough space for your reagents. In fact, we could use a few more bags around here to hold everything. Would you mind stitching another?",starts={{npcID=193649,x=0.318,y=0.67,zoneID=13862}},ends={{npcID=193649,x=0.318,y=0.67,zoneID=13862}},coords={x=0.318,y=0.67,source="quest_giver",zoneID=13862},questType="standard"},
[70589] = {id=70589,name="Blacksmithing Services Requested",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Hi, hi, hi $p! Crafting orders are coming in left and right! If you're looking for work, the Artisan's Consortium always has orders to fill! You can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!",starts={{npcID=194026,x=0.354,y=0.588,zoneID=13862}},ends={{npcID=194026,x=0.354,y=0.588,zoneID=13862}},coords={x=0.354,y=0.588,source="quest_giver",zoneID=13862},questType="standard"},
[70591] = {id=70591,name="Engineering Services Requested",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Hi, hi, hi $p! Crafting orders are coming in left and right! If you're looking for work, the Artisan's Consortium always has orders to fill! You can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!",starts={{npcID=194026,x=0.354,y=0.588,zoneID=13862}},ends={{npcID=194026,x=0.354,y=0.588,zoneID=13862}},coords={x=0.354,y=0.588,source="quest_giver",zoneID=13862},questType="standard"},
