[70593] = {id=70593,name="Jewelcrafting Services Requested",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Hi, hi, hi $p! Crafting orders are coming in left and right! If you're looking for work, the Artisan's Consortium always has orders to fill! You can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!",starts={{npcID=194026,x=0.354,y=0.588,zoneID=13862}},ends={{npcID=194026,x=0.354,y=0.588,zoneID=13862}},coords={x=0.354,y=0.588,source="quest_giver",zoneID=13862},questType="standard"},
[70594] = {id=70594,name="Leatherworking Services Requested",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Hi, hi, hi $p! Crafting orders are coming in left and right! If you're looking for work, the Artisan's Consortium always has orders to fill! You can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!",starts={{npcID=194026,x=0.354,y=0.588,zoneID=13862}},ends={{npcID=194026,x=0.354,y=0.588,zoneID=13862}},coords={x=0.354,y=0.588,source="quest_giver",zoneID=13862},questType="standard"},
[70595] = {id=70595,name="Tailoring Services Requested",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Hi, hi, hi $p! Crafting orders are coming in left and right! If you're looking for work, the Artisan's Consortium always has orders to fill! You can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!",starts={{npcID=194026,x=0.354,y=0.588,zoneID=13862}},ends={{npcID=194026,x=0.354,y=0.588,zoneID=13862}},coords={x=0.354,y=0.588,source="quest_giver",zoneID=13862},questType="standard"},
[70613] = {id=70613,name="Get Their Bark Before They Bite",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13844,mapID=2025,description="$p, you are a skilled herbalist, are you not? I have alchemists nearly begging at my door... well, if I had a door... for more Writhebark . We have nearly sold out! Will you help me gather more? I fear if the alchemists cannot create the phials they need, they will begin experimenting with my belongings.",starts={{npcID=185549,x=0.38,y=0.684,mapID=2112}},ends={{npcID=185549,x=0.38,y=0.684,mapID=2112}},coords={x=0.38,y=0.684,source="quest_giver",mapID=2025},questType="standard"},
[70614] = {id=70614,name="Bubble Craze",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13844,mapID=2025,description="Agrikus shouts at you.> I have no more poppy tea! ...Oh, you're not one of them. Praise the Titans. Someone made \" Bubble Poppy Tea\" the most fashionable drink on the market this week and I've sold out of the herb completely. Please, could you bring more poppies before they return in droves?",starts={{npcID=185549,x=0.38,y=0.684,mapID=2112}},ends={{npcID=185549,x=0.38,y=0.684,mapID=2112}},coords={x=0.38,y=0.684,source="quest_giver",mapID=2025},questType="standard"},
[70615] = {id=70615,name="The Case of the Missing Herbs",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13844,mapID=2025,description="Aah, $p! There you are! They took it! They took my Saxifrage ! I left for barely two hours, and when I returned, someone had taken my Saxifrage ! All they left to show for their crimes was this heavy sack of gold coins. As if you could put a price on herbs! ...Please $p, I need more Saxifrage to replenish what that criminal took from me.",starts={{npcID=185549,x=0.38,y=0.684,mapID=2112}},ends={{npcID=185549,x=0.38,y=0.684,mapID=2112}},coords={x=0.38,y=0.684,source="quest_giver",mapID=2025},questType="standard"},
[70616] = {id=70616,name="How Many??",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13844,mapID=2025,description="Agrikus is crying as you approach.> They did it... I cannot believe they did it... Someone has come here and asked for the delivery of ONE THOUSAND herbs! I cannot even fathom this! It is preposterous. Ridiculous! Ludicrous!! ...Please help.",starts={{npcID=185549,x=0.38,y=0.684,mapID=2112}},ends={{npcID=185549,x=0.38,y=0.684,mapID=2112}},coords={x=0.38,y=0.684,source="quest_giver",mapID=2025},questType="standard"},
[70617] = {id=70617,name="All Mine, Mine, Mine",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14030,mapID=2112,description="There is nothing as useful as Draconium ore . So much can be done with it! It is the perfect ore, pure in every way. Bring me Draconium. I must have it. You are a miner, yes? Then go mine!",starts={{npcID=185553,x=0.39,y=0.512,mapID=2112}},ends={{npcID=185553,x=0.39,y=0.512,mapID=2112}},coords={x=0.39,y=0.512,source="quest_giver",mapID=2112},questType="standard"},
[70618] = {id=70618,name="The Call of the Forge",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14529,mapID=2200,description="The forge... she calls to me. And she asks for Serevite. You there! Bring me Serevite! Yes, lots of Serevite!",starts={{npcID=185553,x=0.39,y=0.512,mapID=2112}},ends={{npcID=185553,x=0.39,y=0.512,mapID=2112}},coords={x=0.39,y=0.512,source="quest_giver",mapID=2200},questType="standard"},
[70619] = {id=70619,name="A Study of Leather",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="You there! Perhaps you can help me with my studies of this leather. Some of it is soft and pliable, yet other pieces have a more firm temper--the better for crafting armor, I suspect. Bring me more leathers to investigate. I wish to continue my studies.",starts={{npcID=193846,x=0.288,y=0.604,zoneID=13862}},ends={{npcID=193846,x=0.288,y=0.604,zoneID=13862}},coords={x=0.288,y=0.604,source="quest_giver",zoneID=13862},questType="standard"},
[70620] = {id=70620,name="Scaling Up",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Many people ask me how I became so good at skinning. To them I say: it is all in the scales. Are you curious to learn more? Bring me some scales, and I will show you what I mean.",starts={{npcID=193846,x=0.288,y=0.604,zoneID=13862}},ends={{npcID=193846,x=0.288,y=0.604,zoneID=13862}},coords={x=0.288,y=0.604,source="quest_giver",zoneID=13862},questType="standard"},
[70621] = {id=70621,name="Third Challenge of Tyr: Persistence Embodied",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13644,description="Your third challenge was meant to have you overcome unfavorable odds. It was to help show me your persistence in all matters. I believe fighting djaradin and fixing my statue with the expectation that I would issue you a challenge is more than sufficient to fulfill your victory condition.",ends={{npcID=195737,x=0.64,y=0.414,zoneID=13644}},questType="standard"},
[70627] = {id=70627,name="What of the Winterpelt Clan?",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="We could join another clan... if we knew it to be safe. I worry the Primalists tempted other clans as they did ours. This \"Dragonscale Expedition\" tells me they have a clawhold near the Winterpelt clan. They may be tainted. Or they may heed our warning. With either truth, they need us. There is a \"furbolg expert,\" Sonova Snowden , in Theron's Watch. Please go to him and learn what he knows.",starts={{npcID=191123,x=0.632,y=0.586,zoneID=13646}},ends={{npcID=189401,x=0.654,y=0.16,zoneID=13646}},coords={x=0.632,y=0.586,source="quest_giver",zoneID=13646},questType="standard"},
[70633] = {id=70633,name="Fueling the Engine",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="You have done well to pass the first challenge that Keeper Tyr left behind. Though this is but the first step on your journey I have faith you shall do well. You have earned your chance at furthering yourself in unlocking the secrets of the Forge. Add the Bottled Essence to the Engine of Innovation and see what occurs.",starts={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},ends={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},coords={x=0.838,y=0.536,source="quest_giver",zoneID=13862},questType="standard"},
[70640] = {id=70640,name="WANTED: Boss",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="Previously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. While this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land. Please see that it is safely neutralized. Bring word of your success to Custodian Cynegos.",questType="standard"},
[70641] = {id=70641,name="A Waking Oath",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,description="Hold a moment, $p. I wish to personally thank you for your aid in restoring our oathstone. I was not aware of the dracthyr until your reawakening on the Forbidden Reach. It was unclear what your arrival among us meant. Whether your kind would prove to be a boon to the defense of life... or a bane. I would encourage you to learn more about our oathstone. Speak with a few of my flight here at the Ruby Lifeshrine. Perhaps you will find familiarity among our tales.",starts={{npcID=185905,x=0.622,y=0.73,mapID=2022}},ends={{npcID=185905,x=0.622,y=0.73,mapID=2022}},coords={x=0.622,y=0.73,source="quest_giver",mapID=2022},questType="standard"},
[70647] = {id=70647,name="Oh Where, Oh Where Can He Be?",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13862,description=", I am glad to see you! I am worried sick and could use your help. Recently, I rescued an abandoned proto-drake whelp. I named him Lubbins because he is so lovely! I brought him here to care for him and hopefully find him a good home as someone's pet. But now he is missing, and I am concerned that he is lost or hurt. I need to keep watch over the rest of my little ones, otherwise I would go searching for him myself. Would you please look for him?",starts={{npcID=185563,x=0.106,y=0.582,zoneID=13862}},ends={{npcID=185563,x=0.106,y=0.582,zoneID=13862}},coords={x=0.106,y=0.582,source="quest_giver",zoneID=13862},questType="standard"},
[70648] = {id=70648,name="Firava the Rekindler",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[70650] = {id=70650,name="In Tyr's Footsteps: The Waking Shores",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13644,description="You have proven yourself well so far, and though I have great faith you are worthy of the Engine I still must challenge you as is my designation. Go to the Waking Shores and find my statue and you shall receive further instructions.",starts={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},ends={{npcID=380918,x=0.64,y=0.414,zoneID=13644}},coords={x=0.838,y=0.536,source="quest_giver",zoneID=13862},questType="standard"},
[70697] = {id=70697,name="An Expert Opinion",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13646,description="Lubbins' wounds may have healed, but I am afraid his confidence may still be injured. I believe it is time to call on others for help. Far to the southwest in a remote section of the Azure Span there is a pet trainer named Patchu . She is one of the world's foremost experts on these matters. Please visit her, I am sure she can help Lubbins!",starts={{npcID=185563,x=0.106,y=0.582,zoneID=13862}},ends={{npcID=196069,x=0.138,y=0.498,zoneID=13646}},coords={x=0.106,y=0.582,source="quest_giver",zoneID=13862},questType="standard"},
[70698] = {id=70698,name="Researcher Sneakwing",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[70701] = {id=70701,name="Bakar Dream of Lost Argali",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Some of the clan's argali have wandered away from our flock again. The ridge around us is too dangerous for our shepherds to search for them. It would be a great boon if you could take one of our bakar and bring back the argali. Our shepherds can point you in the right direction.",starts={{npcID=185870,x=0.556,y=0.524,zoneID=13645}},ends={{npcID=185870,x=0.556,y=0.524,zoneID=13645}},coords={x=0.556,y=0.524,source="quest_giver",zoneID=13645},questType="standard"},
[70702] = {id=70702,name="Continued Waygate Exploration",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Thaelin Darkanvil , seeking your assistance.>",starts={{npcID=196643,x=0.454,y=0.55,zoneID=13862}},ends={{npcID=189066,x=0.472,y=0.902,zoneID=13644}},coords={x=0.454,y=0.55,source="quest_giver",zoneID=13862},questType="standard"},
[70703] = {id=70703,name="The Legacy of Tyrhold",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="Keeper Tyr did love his mysteries. Clearly, there is deeper meaning to the gift he gave us. As he most likely forged this scale at his former citadel, perhaps it will be the key to helping unlock its secrets. Go with Koranos to Tyrhold, . As a trusted advisor and watcher of this land, I am sure he will have insight into this matter.",starts={{npcID=187678,x=0.58,y=0.358,zoneID=13862}},ends={{npcID=192480,x=0.604,y=0.588,zoneID=13647}},coords={x=0.58,y=0.358,source="quest_giver",zoneID=13862},questType="standard"},
[70706] = {id=70706,name="Waygate: Shady Sanctuary",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,description="Our expedition reports a dormant stone out in the lush hillsides to the southwest. It's quite a journey, but worth sendin' someone with yer knowledge tae investigate.",questType="standard"},
[70708] = {id=70708,name="Hollow",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Feels like it's been years. Also feels like it's been minutes. I could use someone to talk to, if you have time. You wanna grab us a round of drinks? Get whatever you want. I'm paying.",starts={{npcID=194801,x=0.568,y=0.644,zoneID=13644}},ends={{npcID=194801,x=0.568,y=0.644,zoneID=13644}},coords={x=0.568,y=0.644,source="quest_giver",zoneID=13644},questType="standard"},
[70715] = {id=70715,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=9,questType="standard"},
[70716] = {id=70716,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=9,questType="standard"},
[70717] = {id=70717,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=9,questType="standard"},
[70719] = {id=70719,name="Shadeslash Trakken",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[70721] = {id=70721,name="After My Ohn Heart",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="There is a small pond by the Mirror of the Sky where Narman and I first met during my initiate training. Initiates travel up there to be closer to Ohn'ahra so they may feel the wind. I first saw him in the reflection of the water when a sudden breeze opened my eyes. It is the most beautiful sight in all of the plains. It will be the perfect place for our proposal.",starts={{npcID=190192,x=0.628,y=0.354,zoneID=13645}},ends={{npcID=197011,x=0.466,y=0.604,zoneID=13645}},coords={x=0.628,y=0.354,source="quest_giver",zoneID=13645},questType="standard"},
[70722] = {id=70722,name="What Lubbins Needs",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13646,description="I think that I know what we gotta do, . But first, let's talk about it! I even have a gift to give you after we're done! Fun, right?",starts={{npcID=196069,x=0.138,y=0.498,zoneID=13646}},ends={{npcID=196069,x=0.138,y=0.498,zoneID=13646}},coords={x=0.138,y=0.498,source="quest_giver",zoneID=13646},questType="standard"},
[70723] = {id=70723,name="Shattering the Earth Primalists",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.",ends={{npcID=196598,x=0.382,y=0.368,zoneID=13862}},questType="standard"},
[70730] = {id=70730,name="Shikaar Giver",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Oh, $p. Do you feel comfort under the sun? Do you feel safe under its bright caress? Does each new day represent hope for the future and a chance to live your life as you've always dreamt it? Then you know love as I do. Narman of Clan Shikaar is my sun. He is my warmth. He is my light. He is my hope. A man like him deserves a proposal worthy of stature. We must seek guidance from an Ohn.",starts={{npcID=190192,x=0.628,y=0.354,zoneID=13645}},ends={{npcID=190192,x=0.628,y=0.354,zoneID=13645}},coords={x=0.628,y=0.354,source="quest_giver",zoneID=13645},questType="standard"},
[70732] = {id=70732,name="A Practice Bout",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13646,description="All right! Now that you used that stone on Lubbins, let's have a practice bout to test out his skills! There's a big ole Hornswog named Gwosh that lives on the shore to the north of here. Gwosh loves to fight! Well, play really. He's super good with other pets, too! It'll be a perfect playtime... I mean fight... for Lubbins.",starts={{npcID=196069,x=0.138,y=0.498,zoneID=13646}},ends={{npcID=196069,x=0.138,y=0.498,zoneID=13646}},coords={x=0.138,y=0.498,source="quest_giver",zoneID=13646},questType="standard"},
[70738] = {id=70738,name="The You-ga Class",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Everything was going so well, but now? Elementals are causing some, um, mild challenges. Our guests were enjoying the facilities when suddenly, all these elementals appeared! Those nasty fiends have disrupted everything. Probably even the new you-ga instructor. Oh yes, you-ga is a new type of stretching that helps you meditate at the same time. I am sure both teacher and students are so relaxed they do not even notice the elementals. Still, better to be safe than sorry. Please, look for them.",starts={{npcID=194717,x=0.404,y=0.49,zoneID=13647}},ends={{npcID=194717,x=0.404,y=0.49,zoneID=13647}},coords={x=0.404,y=0.49,source="quest_giver",zoneID=13647},questType="standard"},
[70739] = {id=70739,name="Bloodlines, Sweets, and Teerai",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="I have hunted with khans, outrun our fastest bakar, and wrestled a full grown bruffalon bull bare-handed. As a hunter, I've nothing left to prove. However, as a partner, I still have much to learn. Windsage Dawa of Clan Ohn'ir is my heart and my joy. I wish only to prove worthy of his love, but I know nothing of traditions and rituals. I require the wisdom of the elders in Maruukai.",starts={{npcID=191924,x=0.636,y=0.404,zoneID=13645}},ends={{npcID=191924,x=0.636,y=0.404,zoneID=13645}},coords={x=0.636,y=0.404,source="quest_giver",zoneID=13645},questType="standard"},
[70740] = {id=70740,name="Steam Cleaning",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Xijan seems to think the elemental invasion on our beautiful spa is only a minor problem, but this surge of flame and steam needs to be brought under control immediately. We had booked musical acts to play in the lower area, but the elementals destroyed their gear. As we have never had such levels of elemental destruction in this area before, I suspect Primalist influences. If you want to help, clear the elementals on the east side of the lower spa. That is where the first events are scheduled.",starts={{npcID=196160,x=0.404,y=0.488,zoneID=13647}},ends={{npcID=196160,x=0.404,y=0.488,zoneID=13647}},coords={x=0.404,y=0.488,source="quest_giver",zoneID=13647},questType="standard"},
[70741] = {id=70741,name="Some Favorite Things",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,starts={{npcID=381297,x=0.415,y=0.474,zoneID=13647}},ends={{npcID=194717,x=0.404,y=0.49,zoneID=13647}},coords={x=0.415,y=0.474,source="quest_giver",zoneID=13647},questType="standard"},
[70742] = {id=70742,name="Runs in the Family",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="From the air, I scouted one of the artifacts Edress uncovered by the entrance of the ruins. Doubtless there are more inside. They are warded somehow, though I will need to get closer before I can examine them. The magic here is very old. The grounds appear deserted, but I wouldn't trust that to last long once we start meddling. Keep an eye out. We will uncover all we can.",starts={{npcID=196253,x=0.446,y=0.64,zoneID=13644}},ends={{npcID=196258,x=0.43,y=0.626,zoneID=13644}},coords={x=0.446,y=0.64,source="quest_giver",zoneID=13644},questType="standard"},
[70743] = {id=70743,name="Precious Baby",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="You there, $pr! Are you semi-competent? Do you have your priorities in check? Good! My precious Baby is missing. Save her immediately. Be quick about it, she can't fend for herself in these horrible conditions.",starts={{npcID=194812,x=0.404,y=0.49,zoneID=13647}},ends={{npcID=194812,x=0.404,y=0.49,zoneID=13647}},coords={x=0.404,y=0.49,source="quest_giver",zoneID=13647},questType="standard"},
[70744] = {id=70744,name="Look at the Bones!",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,starts={{npcID=381296,x=0.389,y=0.452,zoneID=13647}},ends={{npcID=194717,x=0.404,y=0.49,zoneID=13647}},coords={x=0.389,y=0.452,source="quest_giver",zoneID=13647},questType="standard"},
[70745] = {id=70745,name="Enforced Relaxation",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Those Primalists that you saw certainly do not seem like the leadership type to me. Who would be afraid of a little dog? Hah! So, if they mentioned Vadne, that sounds like their leader. She must be the one bringing in these elementals. We need to get rid of the summoner. They must be close by to be causing such trouble. Check the cave directly under us. I know it is where some of the less diligent employees like to take an extended break.",starts={{npcID=196160,x=0.404,y=0.488,zoneID=13647}},ends={{npcID=196160,x=0.404,y=0.488,zoneID=13647}},coords={x=0.404,y=0.488,source="quest_giver",zoneID=13647},questType="standard"},
[70746] = {id=70746,name="Shades of Blue",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="You there, $p! It's good to see a friendly face in these parts. Telash and I were just discussing reports we've heard of... newcomers, in the area. Blue dragons. Given our... history, with the blues, Telash and I thought it necessary to assess the situation ourselves. Please, join us.",starts={{npcID=197023,x=0.414,y=0.358,zoneID=13646}},ends={{npcID=197023,x=0.414,y=0.358,zoneID=13646}},coords={x=0.414,y=0.358,source="quest_giver",zoneID=13646},questType="standard"},
[70747] = {id=70747,name="The Azure Wizard",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I do not have time to quibble with sorcerers. Go and treat with this \"Archmage\", $p. Learn what you may, and be on your guard always. They might be allies still or enemies yet... Our reports indicate there's a large archival complex to the south of here. That is where I'm going.",starts={{npcID=197025,x=0.456,y=0.412,zoneID=13646}},ends={{npcID=192091,x=0.466,y=0.402,zoneID=13646}},coords={x=0.456,y=0.412,source="quest_giver",zoneID=13646},questType="standard"},
[70748] = {id=70748,name="For Blue Eyes Only",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="It is no wonder your companions have yet to find anything. These books were meant for blue eyes only. However, my presence should suffice in allowing for some of the more pertinent tomes to divulge their secrets.",starts={{npcID=197378,x=0.424,y=0.638,mapID=2024}},ends={{npcID=197378,x=0.424,y=0.638,mapID=2024}},coords={x=0.424,y=0.638,source="quest_giver",mapID=2024},questType="standard"},
[70751] = {id=70751,name="Terillod the Devout",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[70752] = {id=70752,name="Vaporizing the Water Primalists",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.",ends={{npcID=196598,x=0.382,y=0.368,zoneID=13862}},questType="standard"},
[70753] = {id=70753,name="Dissipating the Air Primalists",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.",ends={{npcID=196598,x=0.382,y=0.368,zoneID=13862}},questType="standard"},
[70754] = {id=70754,name="Extinguishing the Fire Primalists",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.",ends={{npcID=196598,x=0.382,y=0.368,zoneID=13862}},questType="standard"},
[70763] = {id=70763,name="Worldcarver A'tir",level=70,requiredLevel=70,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[70766] = {id=70766,name="The Fractured Flame",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="The gorloc clutches a journal, its cover marred by moisture and lack of care. The faded symbol of the Sundered Flame peeks proudly from behind the tears and discoloration. If you find the missing pages, perhaps you can gain insight into Reclaimer Makko and the madness that has fractured her mind.",ends={{npcID=191159,x=0.4,y=0.674,zoneID=13645}},questType="standard"},
[70779] = {id=70779,name="Tarjin's Tales",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,description="You think yourself worthy of the incredible legends and histories of the djaradin? You, who are hardly the size of one of our weapons? Pfft. I doubt you have the stomach to carry the legacy of my people. Prove me wrong, if you can. Seek out dragons, the only worthy rival on these isles. Bring me trophies of your victory over their strongest.",starts={{npcID=196214,x=0.16,y=0.626,mapID=2022}},ends={{npcID=196214,x=0.16,y=0.626,mapID=2022}},coords={x=0.16,y=0.626,source="quest_giver",mapID=2022},questType="standard"},
[70781] = {id=70781,name="Out of the Blue",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,mapID=2025,description="Did you see that?! This winged creature just fell from the sky! I don't know what sort of being it is, but it certainly isn't native to the Isles. Wait... I do remember a punchy little goblin asking for directions to the Bluefeather Cliffs just above us. You think she would know anything about it?",starts={{npcID=196392,x=0.504,y=0.674,mapID=2025}},ends={{npcID=183912,x=0.5,y=0.698,mapID=2025}},coords={x=0.504,y=0.674,source="quest_giver",mapID=2025},questType="standard"},
[70783] = {id=70783,name="Skaara",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[70784] = {id=70784,name="The Abandoned Outpost",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="From what you mentioned, it appears the stone of Vigilance can be found at an abandoned station northeast of the Azure Archives. That must be Zelthrak Outpost. Meet up with me when you arrive, , and we can find the stone together.",starts={{npcID=186870,x=0.544,y=0.556,zoneID=13647}},ends={{npcID=193350,x=0.538,y=0.506,zoneID=13646}},coords={x=0.544,y=0.556,source="quest_giver",zoneID=13647},questType="standard"},
[70785] = {id=70785,name="The City of the Dead",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,description="An ancient city of the dead can only mean one thing. The Veiled Ossuary off the coast of northern Thaldraszus. It's extensive, remote, and hard to approach. The perfect place to hide something. I'm not sure what we'll find there, . But you can bet that it won't appreciate our presence.",starts={{npcID=186870,x=0.544,y=0.556,zoneID=13647}},ends={{npcID=190855,x=0.622,y=0.182,zoneID=13647}},coords={x=0.544,y=0.556,source="quest_giver",zoneID=13647},questType="standard"},
[70787] = {id=70787,name="Caught In a Dusk Storm",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="world"},
