[70835] = {id=70835,name="Sturdy Expedition Shovel",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=189065,x=0.47,y=0.828,mapID=2022}},ends={{npcID=189065,x=0.47,y=0.828,mapID=2022}},coords={x=0.47,y=0.828,source="quest_giver",mapID=2022},questType="standard"},
[70837] = {id=70837,name="Follow the Clues",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Investigator Erima reviews the map.> It is clear what the X scrawled over the Seat of the Aspects represents. But there is also a circle drawn around the Misty Vale. Perhaps this is the rebels' next target? Or a base of operations. Only one way to find out. Meet me at the Vale.",starts={{npcID=196984,x=0.564,y=0.44,zoneID=13862}},ends={{npcID=196416,x=0.426,y=0.818,zoneID=13647}},coords={x=0.564,y=0.44,source="quest_giver",zoneID=13862},questType="standard"},
[70838] = {id=70838,name="Rebels With a Cause",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The rebel staging ground... we have been looking for this very place. How fortunate for us that their saboteur's carelessness led us here. I cannot believe my brethren would stoop to working with the Primalists. We cannot let this stand. Take out the rebels and their Primalist friends before they can cause any further chaos.",starts={{npcID=196416,x=0.426,y=0.818,zoneID=13647}},ends={{npcID=196432,x=0.426,y=0.788,zoneID=13647}},coords={x=0.426,y=0.818,source="quest_giver",zoneID=13647},questType="standard"},
[70839] = {id=70839,name="The Search for Titan Relics",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=195768,x=0.258,y=0.4,mapID=2112}},ends={{npcID=195768,x=0.258,y=0.4,mapID=2112}},coords={x=0.258,y=0.4,source="quest_giver",mapID=2112},questType="standard"},
[70840] = {id=70840,name="A Titan Relic",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,starts={{npcID=195768,x=0.258,y=0.4,zoneID=13862}},ends={{npcID=195768,x=0.258,y=0.4,zoneID=13862}},coords={x=0.258,y=0.4,source="quest_giver",zoneID=13862},questType="standard"},
[70841] = {id=70841,name="More Titan Relics",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,starts={{npcID=195768,x=0.258,y=0.4,zoneID=13862}},ends={{npcID=195768,x=0.258,y=0.4,zoneID=13862}},coords={x=0.258,y=0.4,source="quest_giver",zoneID=13862},questType="standard"},
[70842] = {id=70842,name="Detonation Locations",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="I am sure that the rebels are documenting their plans for future attacks. We must find out what they are attempting to do before it happens. Search their camp for any marked maps like the one we found in Valdrakken.",starts={{npcID=196416,x=0.426,y=0.818,zoneID=13647}},ends={{npcID=196432,x=0.426,y=0.788,zoneID=13647}},coords={x=0.426,y=0.818,source="quest_giver",zoneID=13647},questType="standard"},
[70843] = {id=70843,name="Ruin the Runestones",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,starts={{npcID=196464,x=0.436,y=0.81,zoneID=13647}},ends={{npcID=196432,x=0.426,y=0.788,zoneID=13647}},coords={x=0.436,y=0.81,source="quest_giver",zoneID=13647},questType="standard"},
[70845] = {id=70845,name="In Tyr's Footsteps",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13646,description="Keeper Tyr planned for all eventualities. He suspected there would be a need to empower the craftspeople of the realm some day, thus he created the Engine of Innovation. It possesses the ability to create a unique material that can help an item achieve expertise beyond that of mortal ability. To ensure his engine would not be misused he created me to oversee any who sought its power. Only those worthy will be able to unlock the engine's full potential. Are you equal to the challenge?",starts={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},ends={{npcID=379290,x=0.672,y=0.308,zoneID=13646}},coords={x=0.838,y=0.536,source="quest_giver",zoneID=13862},questType="standard"},
[70847] = {id=70847,name="Ancient Obsidian Charm",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Talonstalker Kavia might want this.>",ends={{npcID=190899,x=0.266,y=0.624,zoneID=13644}},questType="standard"},
[70848] = {id=70848,name="Forgotten Dragon Crest",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Exadria might want this.>",ends={{npcID=191193,x=0.276,y=0.564,zoneID=13644}},questType="standard"},
[70849] = {id=70849,name="This Calls for a Specialist",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13644,description="Lubbins is doing lots better now, but I think he still needs some more help. A little bit ago I met a super smart Dragonscale Expedition explorer named Haniko who works with proto-drakes all the time. She's a pet trainer, too. I bet she could help Lubbins more! I think she was going to the Waking Shores. I bet if you go there you'll find her. I'm so happy I was able to help you! Goodbye! Good luck, Lubbins.",starts={{npcID=196069,x=0.138,y=0.498,zoneID=13646}},ends={{npcID=196264,x=0.62,y=0.496,zoneID=440},{npcID=196264,x=0.388,y=0.832,zoneID=13644}},coords={x=0.138,y=0.498,source="quest_giver",zoneID=13646},questType="standard"},
[70850] = {id=70850,name="Maldra's in Hot Water",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Excellent work. While you were off disrupting things I was scouting the camp. I did not expect to find my old friend Maldra Flametongue. I knew she was missing, but the rumors said she had joined the rebels. From what I could see, though, she is their captive! We cannot leave her here. Rescue her from the dragonspawn holding her captive!",starts={{npcID=196432,x=0.426,y=0.788,zoneID=13647}},ends={{npcID=196432,x=0.426,y=0.788,zoneID=13647}},coords={x=0.426,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[70851] = {id=70851,name="Born to Be Wilder",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13644,description="There's a lot of information you need to know. Let's have a talk and then we can decide what's best for Lubbins.",starts={{npcID=196264,x=0.62,y=0.496,zoneID=440},{npcID=196264,x=0.388,y=0.832,zoneID=13644}},ends={{npcID=196264,x=0.62,y=0.496,zoneID=440},{npcID=196264,x=0.388,y=0.832,zoneID=13644}},coords={x=0.62,y=0.496,source="quest_giver",zoneID=440},questType="standard"},
[70853] = {id=70853,name="A Friend for Lubbins",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13644,description="Like we talked about, Lubbins needs two things: a buddy and a battle. I think we can get him both at the same time. This area is a prime mating ground for Shyflys. If you look around a bit, you're sure to find a bunch. Remember, you need to weaken it before you can capture it with your trap. Come back when you have one. It might be a bit bruised after your battle, but I've got some battle-training stones that will fix 'em right up!",starts={{npcID=196264,x=0.62,y=0.496,zoneID=440},{npcID=196264,x=0.388,y=0.832,zoneID=13644}},ends={{npcID=196264,x=0.62,y=0.496,zoneID=440},{npcID=196264,x=0.388,y=0.832,zoneID=13644}},coords={x=0.62,y=0.496,source="quest_giver",zoneID=440},questType="standard"},
[70854] = {id=70854,name="So How Did It Go?",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13862,description="You've done well, . Lubbins is doing much better and is in excellent spirits. Jyhanna will want to know, so go back and give her the good news!",starts={{npcID=196264,x=0.62,y=0.496,zoneID=440},{npcID=196264,x=0.388,y=0.832,zoneID=13644}},ends={{npcID=185563,x=0.106,y=0.582,zoneID=13862}},coords={x=0.62,y=0.496,source="quest_giver",zoneID=440},questType="standard"},
[70856] = {id=70856,name="Kill it with Fire",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="These vile spiders lay their eggs in corpses. And sometimes the living. We've seen several bodies of Sundered Flame who have fallen victim to them. We can't let those eggs hatch if we want to survive here and defeat the Sundered Flame. Take this torch. It is imbued with the power of air and fire. Point it in the direction of what you want scorched, and it will do the rest. The Tuskarr don't mess around with spiders. I came prepared.",starts={{npcID=191715,x=0.672,y=0.444,zoneID=13646}},ends={{npcID=191715,x=0.672,y=0.444,zoneID=13646}},coords={x=0.672,y=0.444,source="quest_giver",zoneID=13646},questType="standard"},
[70858] = {id=70858,name="Back into the Action",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="All right, the antidote is ready. I'll keep Alia steady. You pour what's in the vial into her mouth. I hope she will live... we'll need her magic to track down this artifact.",starts={{npcID=196254,x=0.672,y=0.444,zoneID=13646}},ends={{npcID=196501,x=0.672,y=0.444,zoneID=13646}},coords={x=0.672,y=0.444,source="quest_giver",zoneID=13646},questType="standard"},
[70859] = {id=70859,name="What the Guardian Beholds",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I appreciate your aid, . I was the Kirin Tor mage who first discovered this artifact, Valthrux, and the Sundered Flame's plans. The retrieval and study of this supposedly sentient and powerful artifact is of the utmost importance, and mark my word, I shall be the one to do it. The Sundered Flame guess at its location, but I've used my magic to find a path for us. There is a corrupted guardian nearby that holds a magic shard connected to Valthrux. I can use it to find the rest of the artifact.",starts={{npcID=196501,x=0.672,y=0.444,zoneID=13646}},ends={{npcID=196501,x=0.672,y=0.444,zoneID=13646}},coords={x=0.672,y=0.444,source="quest_giver",zoneID=13646},questType="standard"},
[70871] = {id=70871,name="Iskaaran Fishing Net",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,description="I see you're getting along with the villagers. You seek to learn more about our ways of fishing you say? Well, first of all no one fishes with their bare hands. I can craft you a good, strong net worthy of an Iskaaran.",starts={{npcID=195935,x=0.128,y=0.492,zoneID=13646}},ends={{npcID=195935,x=0.128,y=0.492,zoneID=13646}},coords={x=0.128,y=0.492,source="quest_giver",zoneID=13646},questType="standard"},
[70873] = {id=70873,name="Chasing Waterfalls",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The real threat lies in the Emberslate Cavern. This is where they carve those runestones and infuse them with primal fire. No doubt you noticed the blazing wall of flame that blocks the entrance. I cannot dispel it, however I may be able to do something to help. I believe that with the proper application of Fallingwater, we can pass through it safely. Harvest water motes from the nearby elementals.",starts={{npcID=196562,x=0.426,y=0.788,zoneID=13647}},ends={{npcID=196562,x=0.426,y=0.788,zoneID=13647}},coords={x=0.426,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[70874] = {id=70874,name="To Breach a Fire Wall",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The rebels inside the cavern have been imbued with an elemental blessing, allowing them to safely pass through the wall of flame. I can grant you that same boon. Do not worry; I have seen the blessing granted many times. It shouldn't be any problem to recreate it effectively.",starts={{npcID=196562,x=0.426,y=0.788,zoneID=13647}},ends={{npcID=196608,x=0.424,y=0.788,zoneID=13647}},coords={x=0.426,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[70875] = {id=70875,name="Worst of the Worst",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The rebels in the Emberslate Cavern have an unflinching loyalty to the Primalists, and are therefore the greatest threat to Valdrakken. Eliminate them, and any elementals they have unleashed.",starts={{npcID=196566,x=0.424,y=0.788,zoneID=13647}},ends={{npcID=196566,x=0.424,y=0.788,zoneID=13647}},coords={x=0.424,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[70876] = {id=70876,name="Fracture the Foci",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="If Maldra speaks the truth, the rebels are creating the runestones in the Emberslate Cavern. Given the nature of these devices, we know there must be Primalist foci involved. Destroy the foci. You will know them when you see them. The rebels cannot be allowed to create any more weapons of destruction.",starts={{npcID=196566,x=0.424,y=0.788,zoneID=13647}},ends={{npcID=196566,x=0.424,y=0.788,zoneID=13647}},coords={x=0.424,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[70877] = {id=70877,name="A Quack in Time",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,starts={{npcID=196744,x=0.8,y=0.398,zoneID=13644}},ends={{npcID=186428,x=0.744,y=0.42,zoneID=13644}},coords={x=0.8,y=0.398,source="quest_giver",zoneID=13644},questType="standard"},
[70878] = {id=70878,name="Ring of Fire",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="In the deepest recesses of the Emberslate Cavern, the Primalists erected a fiery portal from which they unleash elementals. I can seal it, but my actions will draw the ire of whatever is on the other side. Including the revenant Magmaticus the Primalists have been aiding. I will need your protection if we are to stop them.",starts={{npcID=196608,x=0.424,y=0.788,zoneID=13647}},ends={{npcID=196566,x=0.424,y=0.788,zoneID=13647}},coords={x=0.424,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[70879] = {id=70879,name="Report on the Rebels",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="I am impressed with what you have accomplished today. I hope you agree, . We have successfully shut down the nefarious activities of these Primalist-allied rebels. For now at least. We will need to keep a close watch on any dissent going forward. Return to Captain Drine at your earliest convenience. She will want our full report.",starts={{npcID=196566,x=0.424,y=0.788,zoneID=13647}},ends={{npcID=189842,x=0.56,y=0.402,zoneID=13862}},coords={x=0.424,y=0.788,source="quest_giver",zoneID=13647},questType="standard"},
[70880] = {id=70880,name="To Cook With Finery",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=185556,x=0.466,y=0.464,mapID=2112}},ends={{npcID=185556,x=0.466,y=0.464,mapID=2112}},coords={x=0.466,y=0.464,source="quest_giver",mapID=2112},questType="standard"},
[70881] = {id=70881,name="Fourth Challenge of Tyr: Resourcefulness",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=14082,description="The engine is close to reaching its full potential. All it requires now is a power core to process any essence put into it more efficiently. Tyr left the knowledge of such devices with Watcher Irideus. Go into the Halls of Infusion and find him. I am sure he will help you with whatever you need.",starts={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},ends={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},coords={x=0.838,y=0.536,source="quest_giver",zoneID=13862},questType="dungeon"},
[70882] = {id=70882,name="Renown Supplies",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=193015,x=0.58,y=0.356,mapID=2112}},ends={{npcID=193015,x=0.58,y=0.356,mapID=2112}},coords={x=0.58,y=0.356,source="quest_giver",mapID=2112},questType="standard"},
[70883] = {id=70883,name="A Hand in Cultivation",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13647,description="Greetings mortal, I have word from our Head Gardener Gryrmpech . The word is that the gardens are in a state of chaos, but I don't know if that is abnormal. They assured me that they have it in hand--actually, 'in shovel' is the phrase they used. I am not sure what they are meaning; I am sure they will fill you in. Please, seek them out and they will outfit you appropriately for the situation.",starts={{npcID=193015,x=0.58,y=0.356,zoneID=13862}},ends={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},coords={x=0.58,y=0.356,source="quest_giver",zoneID=13862},questType="standard"},
[70884] = {id=70884,name="Taking Back",level=10,requiredLevel=10,faction="none",expansion=9,questType="standard"},
