[70893] = {id=70893,name="Community Feast",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13646,description="Our community feast is happening RIGHT NOW! This is when everyone pitches in and makes the best soup we can. You should join us!",starts={{npcID=196620,x=0.134,y=0.484,zoneID=13646}},ends={{npcID=196620,x=0.134,y=0.484,zoneID=13646}},coords={x=0.134,y=0.484,source="quest_giver",zoneID=13646},questType="standard"},
[70895] = {id=70895,name="Soaring in Style",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=185561,x=0.468,y=0.788,mapID=2112}},ends={{npcID=185561,x=0.468,y=0.788,mapID=2112}},coords={x=0.468,y=0.788,source="quest_giver",mapID=2112},questType="standard"},
