[70897] = {id=70897,name="A Coming of Age",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=195770,x=0.362,y=0.496,mapID=2112}},ends={{npcID=195770,x=0.362,y=0.496,mapID=2112}},coords={x=0.362,y=0.496,source="quest_giver",mapID=2112},questType="standard"},
[70899] = {id=70899,name="Fifth Challenge of Tyr: Ingenuity",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="As this was not how the Power Core was supposed to be obtained, it requires a re-attunement to the energies of the Engine. The resonance frequencies of the denizens of Tyrhold should bring the core to its full potential once more. Though I do not wish to sacrifice more of my brethren, I believe this is the only way this challenge may be completed.",starts={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},ends={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},coords={x=0.838,y=0.536,source="quest_giver",zoneID=13862},questType="standard"},
[70900] = {id=70900,name="Innovating the Engine",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Tyr believed that the Engine of Innovation would be necessary for the battles to come. You have proven yourself worthy and overcome all the challenges set before you. You may now unlock the Engine's full potential.",starts={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},ends={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},coords={x=0.838,y=0.536,source="quest_giver",zoneID=13862},questType="standard"},
[70901] = {id=70901,name="A Collection of Creatures",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=189197,x=0.742,y=0.632,mapID=2112}},ends={{npcID=189197,x=0.742,y=0.632,mapID=2112}},coords={x=0.742,y=0.632,source="quest_giver",mapID=2112},questType="standard"},
