[70929] = {id=70929,name="More Hunting Trophies",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,starts={{npcID=195454,x=0.64,y=0.41,zoneID=13645}},ends={{npcID=195454,x=0.64,y=0.41,zoneID=13645}},coords={x=0.64,y=0.41,source="quest_giver",zoneID=13645},questType="standard"},
[70930] = {id=70930,name="All Tea, No Shadeleaf",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,description="Today is a celebration of tea - brewed, iced, and otherwise! Extravagant little cakes and biscuits too. But there is a rare ingredient of the Isles I feel could add a whole new dimension of flavor! Deep within the crawler-infested domain of the Shiverweb Vale is a bush laden with the most wondrously uplifting leaf: Coldsnap Sagittate. The Dragonscale Expedition was exploring that area recently. Perhaps one of them could assist?",starts={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},ends={{npcID=185778,x=0.516,y=0.62,zoneID=13646}},coords={x=0.614,y=0.118,source="quest_giver",zoneID=13862},questType="standard"},
[70931] = {id=70931,name="Whispered Fragments",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="I believe Valthrux is trying to communicate to us through the shard we recovered. We can use this to our advantage as long as we keep our minds guarded from the artifact's influence. I was wrong about the Sundered Flame. They have unfortunately collected several shard fragments already. Valthrux's whispers claim they're close to finding its location. Go and recover the shards from the Sundered Flame before they reach the artifact!",starts={{npcID=196501,x=0.672,y=0.444,zoneID=13646}},ends={{npcID=196501,x=0.672,y=0.444,zoneID=13646}},coords={x=0.672,y=0.444,source="quest_giver",zoneID=13646},questType="standard"},
[70932] = {id=70932,name="The Life of Spice",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="To many, meat is essential for any true meal. But what is the essential for any true meat dish? Spice!! A spice that surpasses all others in terms of flavor, texture, and rarity lies within these Isles. Unfortunately, it can only be found on elementals that dwell in the depths of the Obsidian Stronghold. It's an area currently occupied by the Djaradin. Perhaps you can consult with a peculiar troll I met while passing through there. I believe his name was... Griftah .",starts={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},ends={{npcID=189207,x=0.254,y=0.542,zoneID=13644}},coords={x=0.614,y=0.118,source="quest_giver",zoneID=13862},questType="standard"},
[70935] = {id=70935,name="Catch and Release: Islefin Dorado",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=197645,x=0.336,y=0.642,mapID=2022},{npcID=197645,x=0.814,y=0.784,mapID=2023},{npcID=197645,x=0.568,y=0.648,mapID=2025},{npcID=197645,x=0.742,y=0.414,mapID=2151}},ends={{npcID=194584,x=0.632,y=0.758,mapID=2022},{npcID=197645,x=0.336,y=0.642,mapID=2022},{npcID=197645,x=0.814,y=0.784,mapID=2023},{npcID=197645,x=0.568,y=0.648,mapID=2025},{npcID=197645,x=0.742,y=0.414,mapID=2151},{npcID=196840,x=0.588,y=0.348,mapID=2024}},coords={x=0.336,y=0.642,source="quest_giver",mapID=2112},questType="standard"},
[70936] = {id=70936,name="Stolen Tuskarr Totems",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=186448,x=0.124,y=0.492,mapID=2024}},ends={{npcID=186448,x=0.124,y=0.492,mapID=2024}},coords={x=0.124,y=0.492,source="quest_giver",mapID=2024},questType="standard"},
[70937] = {id=70937,name="What Valthrux Once Was",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="To'tik whispers to you.> I don't like this. Mysterious artifacts whispering promises of greatness does not sound good. But we can't just walk away... otherwise the Sundered Flame will get their hands on it. Whatever \"it\" is... I'm familiar with ruins like this. The blue dragons often left behind notes on their work. Keep your eyes open, and you may find some around. We can use whatever evidence you find to warn Alia and Kattigat.",starts={{npcID=191715,x=0.672,y=0.444,zoneID=13646}},ends={{npcID=191715,x=0.672,y=0.444,zoneID=13646}},coords={x=0.672,y=0.444,source="quest_giver",zoneID=13646},questType="standard"},
[70938] = {id=70938,name="Community Feasts",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,description="There you are, ! The soup's on! You better hurry up and get to Iskaara. Big Kinook has been looking for you. One time he told me to get a slimy, icky spinefish for the soup and I didn't want to, so I yelled: \"No, chef!\" He was so mad I thought he was going to throw me in the soup!",starts={{npcID=197631,x=0.456,y=0.554,zoneID=13862}},ends={{npcID=186126,x=0.134,y=0.486,zoneID=13646}},coords={x=0.456,y=0.554,source="quest_giver",zoneID=13862},questType="standard"},
[70939] = {id=70939,name="Cooking Utensils",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=186547,x=0.136,y=0.486,mapID=2024}},ends={{npcID=186547,x=0.136,y=0.486,mapID=2024}},coords={x=0.136,y=0.486,source="quest_giver",mapID=2024},questType="standard"},
[70940] = {id=70940,name="Tuskarr Champion's Tales",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=186448,x=0.124,y=0.492,mapID=2024}},ends={{npcID=186448,x=0.124,y=0.492,mapID=2024}},coords={x=0.124,y=0.492,source="quest_giver",mapID=2024},questType="standard"},
[70941] = {id=70941,name="Fishing Holes",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,description="Hello again! Did you know I'm gonna be the bestest fisherman in the village? I caught a giant piranha once. It tried to eat my face! Rowie looks around distractedly.> Oh yeah! I have a message for you. Nunvuq , back in Iskaara, wants to tell you about fishing holes .",starts={{npcID=197631,x=0.456,y=0.554,zoneID=13862}},ends={{npcID=186554,x=0.138,y=0.492,zoneID=13646}},coords={x=0.456,y=0.554,source="quest_giver",zoneID=13862},questType="standard"},
