[70946] = {id=70946,name="No One May Wield It",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="What you found makes it sound like the artifact's power has doomed everyone who has used it so far. The dragonspawn who lived here killed each other over it. The Sundered Flame seem like they're also getting corrupted by its influence too. This isn't an artifact we need to recover. It's one that needs to be destroyed before it can harm anyone else. We must convince Alia and Kattigat.",starts={{npcID=191715,x=0.672,y=0.444,zoneID=13646}},ends={{npcID=191715,x=0.672,y=0.444,zoneID=13646}},coords={x=0.672,y=0.444,source="quest_giver",zoneID=13646},questType="standard"},
