[70957] = {id=70957,name="The Sea Out West",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,description="Enjoying the greenery around our little scenery, ? It reminds me of a dish I once tasted from a pair of dryad sisters and their kind treant friend. Sugarbough was their name! A resident of Shady Sanctuary on the western coast of the Plains. It was a medley of fresh herbs, veggies, and spices. At the heart of this dish was the most delicious layer of sea kelp you have ever tasted! What? Never tasted sea kelp before? Well you simply must seek some out. And bring back enough to share, please!",starts={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},ends={{npcID=186502,x=0.286,y=0.604,zoneID=13645}},coords={x=0.614,y=0.118,source="quest_giver",zoneID=13862},questType="standard"},
[70958] = {id=70958,name="Finest Fungi at the Feast",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13647,description="Fine dining is all about using the finest techniques on the finest ingredients, naturally. The food composed for fine dining is oft locked behind wealth and means, but we would never allow that at The Ruby Feast! Morsel has informed me of a perfect ingredient for today's theme. One so rare, so exquisite, that it... does not exist yet! Tantalizing, no? The bronze have uncovered a portal to a dangerous future. One where a black truffle with untold flavor exists! You must go!",starts={{npcID=189479,x=0.614,y=0.118,zoneID=13862}},ends={{npcID=187025,x=0.602,y=0.822,zoneID=13647}},coords={x=0.614,y=0.118,source="quest_giver",zoneID=13862},questType="standard"},
[70959] = {id=70959,name="Cute and Cuddly",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=186564,x=0.134,y=0.49,mapID=2024}},ends={{npcID=186564,x=0.134,y=0.49,mapID=2024}},coords={x=0.134,y=0.49,source="quest_giver",mapID=2024},questType="standard"},
