[70965] = {id=70965,name="Wanted: Watcher's Golden Girdle",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The archivists humbly request that all expedition members seek out the Watcher's Golden Girdle for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. You may wish to start your search at our northern dig site, where Elementalist Taiyang has reported a malfunctioning Watcher causing trouble.",starts={{npcID=381579,x=0.475,y=0.835,zoneID=13644}},ends={{npcID=189226,x=0.47,y=0.826,zoneID=13644}},coords={x=0.475,y=0.835,source="quest_giver",zoneID=13644},questType="standard"},
[70966] = {id=70966,name="Trading Made Easier",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=187869,x=0.126,y=0.502,mapID=2024}},ends={{npcID=187869,x=0.126,y=0.502,mapID=2024}},coords={x=0.126,y=0.502,source="quest_giver",mapID=2024},questType="standard"},
