[72063] = {id=72063,name="Return Yennu's Toy Boat",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,description="Yennu , the young Tuskarr, was musing about a boat, it must belong to him>",ends={{npcID=195252,x=0.524,y=0.61,zoneID=13645}},questType="standard"},
[72067] = {id=72067,name="Relaxation Time!",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="You there! You look exhausted. Worn down. In extreme need of some R&R. I have just the thing! The Serene Dreams Spa is the place for you! Enjoy our new you-ga classes, they are AMAZING! Or perhaps a mud mask facial treatment is more your speed? I recommend both! To get to the spa, head north just out of the city!",starts={{npcID=197986,x=0.48,y=0.598,zoneID=13862}},ends={{npcID=197670,x=0.404,y=0.494,zoneID=13647}},coords={x=0.48,y=0.598,source="quest_giver",zoneID=13862},questType="standard"},
[72069] = {id=72069,name="Subglacial Refill",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,description="The fish could be biting better, don't you think? You know, that gives me an idea. Seems we have caught almost all the fish under the ice. Could you catch some more from the Timbertooth Trail downstream, bring it here, and drop it into an ice hole?",starts={{npcID=197700,x=0.586,y=0.344,zoneID=13646}},ends={{npcID=197700,x=0.586,y=0.344,zoneID=13646}},coords={x=0.586,y=0.344,source="quest_giver",zoneID=13646},questType="standard"},
[72071] = {id=72071,name="Round Two, Fish!",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="How do you feel about doing a little fishing, then, ? There's a school of bait fish just offshore that the dumb beast attacks whenever they gather, forgetting that it's already dead. Swim out there and wave that lure around, maybe do your best impression of a wounded seal, and it won't be able to resist.",starts={{npcID=197979,x=0.812,y=0.572,zoneID=13646}},ends={{npcID=197979,x=0.812,y=0.572,zoneID=13646}},coords={x=0.812,y=0.572,source="quest_giver",zoneID=13646},questType="standard"},
[72072] = {id=72072,name="Dragonsprings Drop",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,description="The fish could be biting better, don't you think? You know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it? Maybe you and your drake could give it a try?",starts={{npcID=198766,x=0.808,y=0.784,zoneID=13645}},ends={{npcID=198766,x=0.808,y=0.784,zoneID=13645}},coords={x=0.808,y=0.784,source="quest_giver",zoneID=13645},questType="standard"},
[72074] = {id=72074,name="Highland Habitat",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13647,description="The fish could be biting better, don't you think? You know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it? Maybe you and your drake could give it a try?",starts={{npcID=197597,x=0.572,y=0.652,zoneID=13647}},ends={{npcID=197597,x=0.572,y=0.652,zoneID=13647}},coords={x=0.572,y=0.652,source="quest_giver",zoneID=13647},questType="standard"},
[72075] = {id=72075,name="Hot Stock",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The fish could be biting better, don't you think? You know, that gives me an idea. Legend says these lava lakes are not always abundant with hot-loving fish. They say, pools were stocked with fish when the dragons soaring overhead dropped them! Can you believe it? Maybe you and your drake could give it a try?",starts={{npcID=198767,x=0.344,y=0.65,zoneID=13644}},ends={{npcID=198767,x=0.344,y=0.65,zoneID=13644}},coords={x=0.344,y=0.65,source="quest_giver",zoneID=13644},questType="standard"},
[72079] = {id=72079,name="Community Feast",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[72083] = {id=72083,name="Me Lucky Lure",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description="Ya find me in a low place, , and it's not because I'm dead. I died on the hunt, making sure the beast that killed me crew wouldn't live to kill again. There's nothing wrong with that, it's what me Pa would have wanted. No, the problem is that the fight was a draw! The beast's spirit is still out there, as sure as I stand here before ya. But, being a ghost, I can't even reclaim me lucky lure from the critters that picked me body clean to have another go! Would ya mind helping me out?",starts={{npcID=197979,x=0.812,y=0.572,zoneID=13646}},ends={{npcID=197979,x=0.812,y=0.572,zoneID=13646}},coords={x=0.812,y=0.572,source="quest_giver",zoneID=13646},questType="standard"},
[72113] = {id=72113,name="Shapes Beyond the Veil",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,starts={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},coords={x=0.38,y=0.254,source="quest_giver",mapID=1565},questType="standard"},
