[72116] = {id=72116,name="Liskron the Dazzling",level=40,requiredLevel=40,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[72117] = {id=72117,name="Cultural Exchange",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,mapID=2023,starts={{npcID=196707,x=0.604,y=0.376,mapID=2023}},ends={{npcID=196707,x=0.604,y=0.376,mapID=2023}},coords={x=0.604,y=0.376,source="quest_giver",mapID=2023},questType="standard"},
[72121] = {id=72121,name="The Great Shellkhan",level=40,requiredLevel=40,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[72122] = {id=72122,name="Erstwhile Ecologists",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The wounded are stabilized, but something still troubles me, . A pair of dragonspawn ecologists had come to the outpost to study the wetlands. I haven't seen scale nor claw of them since the attack, and it's become worrisome. If you're venturing out, would you mind keeping an eye out, and making sure they're safe? And do take care. Rumor has it those wetlands are gorloc-infested.",starts={{npcID=195303,x=0.712,y=0.404,zoneID=13644}},ends={{npcID=186410,x=0.744,y=0.42,zoneID=13644}},coords={x=0.712,y=0.404,source="quest_giver",zoneID=13644},questType="standard"},
[72126] = {id=72126,name="Slurpo, the Incredible Snail",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[72127] = {id=72127,name="Captain Lancer",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[72130] = {id=72130,name="Forgotten Gryphon",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[72131] = {id=72131,name="Overstocking",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,mapID=2023,starts={{npcID=196707,x=0.604,y=0.376,mapID=2023}},ends={{npcID=196707,x=0.604,y=0.376,mapID=2023}},coords={x=0.604,y=0.376,source="quest_giver",mapID=2023},questType="standard"},
[72135] = {id=72135,name="Neltharus: Secrets Within",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14011,description="We have a problem, traveler. The djaradin first emerged from within Neltharus, which means they must be ransacking the halls! Neltharus contains many treasures. But more importantly, it contains knowledge: the history of our flight and its fall from grace. Both Sabellian and Wrathion have been looking for more information regarding Neltharion's life and work. Go! See what you can recover before the djaradin plunder it all!",starts={{npcID=193456,x=0.25,y=0.562,zoneID=13644},{npcID=205781,zoneID=14011}},ends={{npcID=193456,x=0.25,y=0.562,zoneID=13644},{npcID=205781,zoneID=14011}},coords={x=0.25,y=0.562,source="quest_giver",zoneID=13644},questType="dungeon"},
[72137] = {id=72137,name="Hatchling Plans",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,mapID=2023,starts={{npcID=196707,x=0.604,y=0.376,mapID=2023}},ends={{npcID=196707,x=0.604,y=0.376,mapID=2023}},coords={x=0.604,y=0.376,source="quest_giver",mapID=2023},questType="standard"},
[72154] = {id=72154,name="Skag the Thrower",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[72155] = {id=72155,name="Spread the Enchantment",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Algeth'ar Academy has put in an order for more enchanting rods. We need everyone to pitch in if we are going to fill the order on time. Could you be of assistance?",starts={{npcID=193744,x=0.308,y=0.614,zoneID=13862}},ends={{npcID=193744,x=0.308,y=0.614,zoneID=13862}},coords={x=0.308,y=0.614,source="quest_giver",zoneID=13862},questType="standard"},
[72156] = {id=72156,name="A Fiery Flight",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The forge is cooling! Quick, can you help me? Bring me some Rousing Fire . Perhaps it will help!",starts={{npcID=185553,x=0.39,y=0.512,zoneID=13862}},ends={{npcID=185553,x=0.39,y=0.512,zoneID=13862}},coords={x=0.39,y=0.512,source="quest_giver",zoneID=13862},questType="standard"},
[72157] = {id=72157,name="The Weight of Earth",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="I have an order for several hundred tons of Primal Molten Alloy, but I have run out of Rousing Earth . I know it's a heavy ask, but I can make it worth your while!",starts={{npcID=185553,x=0.39,y=0.512,zoneID=13862}},ends={{npcID=185553,x=0.39,y=0.512,zoneID=13862}},coords={x=0.39,y=0.512,source="quest_giver",zoneID=13862},questType="standard"},
[72158] = {id=72158,name="A Dense Delivery",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Our scales are tough, but we can always use more protection. Only the densest of hides will do for our armor--a challenge to gather, but perhaps one you are up to? I've seen your skills. Go and gather some hides for our stores.",starts={{npcID=193846,x=0.288,y=0.604,zoneID=13862}},ends={{npcID=193846,x=0.288,y=0.604,zoneID=13862}},coords={x=0.288,y=0.604,source="quest_giver",zoneID=13862},questType="standard"},
[72159] = {id=72159,name="Scaling Down",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Scales have a multitude of purposes--they offer protection, but in some cases, they also offer a keen reflective surface. Many of our finest mirrors are in fact scales. Those mirrors also happen to be in high demand. Gather some scaled hides for me, and I'll share some of my crafting secrets.",starts={{npcID=193846,x=0.288,y=0.604,zoneID=13862}},ends={{npcID=193846,x=0.288,y=0.604,zoneID=13862}},coords={x=0.288,y=0.604,source="quest_giver",zoneID=13862},questType="standard"},
[72172] = {id=72172,name="Essence, Shards, and Chromatic Dust",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="We seem to be in constant need of basic components. Essence, shards... and our stock of Chromatic Dust is almost always depleted. If you wouldn't mind helping us stock up, perhaps we can make it more than a day into the week without needing to replenish our supply.",starts={{npcID=193744,x=0.308,y=0.614,zoneID=13862}},ends={{npcID=193744,x=0.308,y=0.614,zoneID=13862}},coords={x=0.308,y=0.614,source="quest_giver",zoneID=13862},questType="standard"},
[72173] = {id=72173,name="Braced for Enchantment",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="The Dragonscale Expedition has requested some enchantments for their gear. The Dragon Isles can be a treacherous place. I don't blame them for needing some bracer upgrades.",starts={{npcID=193744,x=0.308,y=0.614,zoneID=13862}},ends={{npcID=193744,x=0.308,y=0.614,zoneID=13862}},coords={x=0.308,y=0.614,source="quest_giver",zoneID=13862},questType="standard"},
[72175] = {id=72175,name="A Scept-acular Time",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="There are some exciting orders to fill this week! The students at Algeth'ar Academy have been going horns over heels for these fun scepters. Why don't you assist with some of the scepters?",starts={{npcID=193744,x=0.308,y=0.614,zoneID=13862}},ends={{npcID=193744,x=0.308,y=0.614,zoneID=13862}},coords={x=0.308,y=0.614,source="quest_giver",zoneID=13862},questType="standard"},
[72181] = {id=72181,name="LFGDungeons - DF - Normal Random - 1st",level=10,requiredLevel=10,faction="none",expansion=9,questType="standard"},
[72184] = {id=72184,name="LFGDungeons - DF - Raid Finder - 1st",level=70,requiredLevel=70,faction="none",expansion=9,questType="standard"},
[72187] = {id=72187,name="LFGDungeons - DF - Heroic Random - 1st",level=70,requiredLevel=70,faction="none",expansion=9,questType="standard"},
[72189] = {id=72189,name="Garden Variety",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Are you enjoying the butterfly garden? You know, there's a much larger garden just to the south of here. An older drakonid by the name of Gryrmpech tends to it. He could always use an extra pair of hands. He has an 'assistant', but I've never actually seen him. I can't imagine he's of much help. If you stop by, be sure to let him know that Xina sent you.",starts={{npcID=189364,x=0.772,y=0.67,zoneID=13862}},ends={{npcID=187300,x=0.378,y=0.754,zoneID=13647}},coords={x=0.772,y=0.67,source="quest_giver",zoneID=13862},questType="standard"},
[72190] = {id=72190,name="Reservoir Reservations",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13802,description="! I know someone who is in dire need of your skills. Tyrhold Reservoir has just been attacked by Primalists. I was lucky to make my escape when I did. I fear the others may not be so lucky. It's just to the north of here. Find Zuttiki , she'll be able to fill you in on the details. If she's still alive, that is.",starts={{npcID=198349,x=0.256,y=0.406,zoneID=13862}},ends={{npcID=190527,x=0.496,y=0.588,zoneID=13647},{npcID=190527,x=0.528,y=0.532,zoneID=13802}},coords={x=0.256,y=0.406,source="quest_giver",zoneID=13862},questType="standard"},
[72191] = {id=72191,name="Short-Supply Reward",level=70,requiredLevel=70,faction="none",expansion=9,questType="standard"},
[72192] = {id=72192,name="Halls of Infusion: Entropy to Order",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=14082,description="The Primalists wish to bring elemental chaos back to this world and will stop at nothing to see their goal accomplished. I have received disturbing news that they have infiltrated the Halls of Infusion deep below Tyrhold. They attempt to disrupt the works of Keeper Tyr for their own nefarious purposes. Please, you must put an end to any Primalist threat within those sacred halls, .",starts={{npcID=191369,x=0.546,y=0.41,zoneID=13862},{npcID=197206,x=0.588,y=0.428,zoneID=13862},{npcID=205774,zoneID=14082}},ends={{npcID=191369,x=0.546,y=0.41,zoneID=13862},{npcID=205774,zoneID=14082}},coords={x=0.546,y=0.41,source="quest_giver",zoneID=13862},questType="dungeon"},
[72193] = {id=72193,name="The Algeth'ar Academy",level=45,requiredLevel=45,faction="both",expansion=9,zoneID=14032,description="I understand that the Algeth'ar Academy is open to the world once more. Long ago, its sacred halls were only open to dragons, but in the years that have passed the Headteacher has seen the wisdom of welcoming any who wish to learn. She has asked for my recommendation on any promising new students. As a great ally to dragonkind, it would be an honor to have you attend our great academy. I leave the decision to enroll up to you, but I am sure Doragosa would love to at least give you a tour.",starts={{npcID=187676,x=0.612,y=0.364,zoneID=13862},{npcID=205772,zoneID=14032}},ends={{npcID=187676,x=0.612,y=0.364,zoneID=13862},{npcID=205772,zoneID=14032}},coords={x=0.612,y=0.364,source="quest_giver",zoneID=13862},questType="dungeon"},
[72240] = {id=72240,name="The Obsidian Warders",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,description="This Toddy's enthusiasm is admirable. But I hope it does not blind her to the dangers awaiting us in the Dragon Isles . Regardless, the Obsidian Warders are duty-bound to protect the expedition. I must speak with Wrathion and the Lord Commander about the mission ahead. My fellow dracthyr are exploring the city. Seek out Dervishian, my trusted lieutenant, and inform her that we are to rally at the docks. She will relay my orders to the rest.",starts={{npcID=189603,x=0.798,y=0.272,zoneID=1519}},ends={{npcID=189077,x=0.228,y=0.556,zoneID=1519}},coords={x=0.798,y=0.272,source="quest_giver",zoneID=1519},questType="standard"},
[72241] = {id=72241,name="Lessons From Our Past",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="I am Emberthal, a scalecommander of the dracthyr. Wrathion aided us after we awakened from our long stasis, and now it is my turn to help him. No doubt you have questions about my people and our history. Until recently, I did as well. But Nozdormu, the Timeless One, has revealed lost truths about the dracthyr. He granted me a vision of our origins... and why we were locked away. Let me tell you of the things I have seen.",starts={{npcID=192795,x=0.424,y=0.668,zoneID=13644}},ends={{npcID=192795,x=0.424,y=0.668,zoneID=13644}},coords={x=0.424,y=0.668,source="quest_giver",zoneID=13644},questType="standard"},
[72242] = {id=72242,name="Dragon Isles Engineering",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=190535,x=0.76,y=0.332,mapID=2022}},ends={{npcID=190535,x=0.76,y=0.332,mapID=2022}},coords={x=0.76,y=0.332,source="quest_giver",mapID=2022},questType="standard"},
