[72244] = {id=72244,name="Dragon Isles Inscription",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=198380,x=0.762,y=0.356,mapID=2022}},ends={{npcID=198380,x=0.762,y=0.356,mapID=2022}},coords={x=0.762,y=0.356,source="quest_giver",mapID=2022},questType="standard"},
