[72246] = {id=72246,name="Serene Dreams",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Welcome to the Serene Dreams Spa! I must apologize. We are not able to admit new guests at this time due to circumstances beyond our control. Let me refer you to the Spa Manager, Xijan Thornpaw . He is qualified to answer all your questions.",starts={{npcID=197670,x=0.404,y=0.494,zoneID=13647}},ends={{npcID=194717,x=0.404,y=0.49,zoneID=13647}},coords={x=0.404,y=0.494,source="quest_giver",zoneID=13647},questType="standard"},
[72247] = {id=72247,name="Dragon Isles Jewelcrafting",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=198398,x=0.762,y=0.336,mapID=2022}},ends={{npcID=198398,x=0.762,y=0.336,mapID=2022}},coords={x=0.762,y=0.336,source="quest_giver",mapID=2022},questType="standard"},
