[72254] = {id=72254,name="Fisherman Tinnak's Ghost",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[72256] = {id=72256,name="The Dark Talons",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=14,description="Naleidea is enthusiastic, but she's a historian, not a soldier. She knows nothing of the dangers we'll face in the Dragon Isles . Not that anyone needs to worry. After all, the Dark Talons will be protecting the expedition. I'm going to discuss mission logistics with Ebyssian and your Horde leaders. My lieutenant, Kodethi, is exploring the city along with the other dracthyr. Be a good soldier and let him know we are going to rally at the zeppelin tower. He'll relay my orders to the others.",starts={{npcID=184786,x=0.442,y=0.382,zoneID=1637}},ends={{npcID=197279,x=0.558,y=0.126,zoneID=14}},coords={x=0.442,y=0.382,source="quest_giver",zoneID=1637},questType="standard"},
[72259] = {id=72259,name="Vault Artifacts",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,starts={{npcID=197095,x=0.35,y=0.25,zoneID=13862}},ends={{npcID=197095,x=0.35,y=0.25,zoneID=13862}},coords={x=0.35,y=0.25,source="quest_giver",zoneID=13862},questType="raid"},
[72260] = {id=72260,name="Vault Artifacts",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,starts={{npcID=197095,x=0.35,y=0.25,zoneID=13862}},ends={{npcID=197095,x=0.35,y=0.25,zoneID=13862}},coords={x=0.35,y=0.25,source="quest_giver",zoneID=13862},questType="raid"},
[72261] = {id=72261,name="More Than a Prison?",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13862,description="Lillian Brightmoon in Valdrakken might be able to tell more.>",ends={{npcID=197095,x=0.35,y=0.25,zoneID=13862}},questType="raid"},
[72263] = {id=72263,name="Cavalry Has Its Place",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="Evoker! This place still has herds of vorquin! I managed to round a few up that could be used as mounts for when your wings are tired. Remember how to ride? This one is to be issued to you as the scalecommanders are ordering you all over the place. Please take good care of it.",ends={{npcID=198429,x=0.452,y=0.612,mapID=85}},questType="standard"},
[72266] = {id=72266,name="The Waking Shores",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The drakonid Sendrax is looking for help in aiding all of the newcomers within the Waking Shores .",ends={{npcID=193362,x=0.766,y=0.336,zoneID=13644}},questType="standard"},
[72267] = {id=72267,name="Ohn'ahran Plains",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="The green dragonflight needs the aid of adventurers. To do so, you must ally with the centaur of the plains. Ambassador Taurasza can be of aid.",ends={{npcID=185878,x=0.482,y=0.886,zoneID=13644}},questType="standard"},
[72268] = {id=72268,name="Azure Span",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,description="The Kirin Tor need all the help they can get tracking down the Blue Dragon Oathstone. Some of their mages have been spotted in the Ohn'ahran Plains looking for help.",ends={{npcID=185599,x=0.716,y=0.806,zoneID=13645}},questType="standard"},
[72269] = {id=72269,name="Thaldraszus",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Alexstrasza the Life-Binder is arranging a meeting of the Seat of the Aspects to discuss the threat of the Primalists. She has put out a call for any willing adventurers to come help.",ends={{npcID=187678,x=0.58,y=0.358,zoneID=13862}},questType="standard"},
[72279] = {id=72279,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=193006,x=0.13,y=0.492,mapID=2024}},ends={{npcID=193006,x=0.13,y=0.492,mapID=2024}},coords={x=0.13,y=0.492,source="quest_giver",mapID=2024},questType="standard"},
