[72291] = {id=72291,name="Story of a Memorable Victory",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13647,description="That was a good fight! Elder Poa in Iskaara will be interested in listening to the story of that victory.",ends={{npcID=186448,x=0.124,y=0.492,zoneID=13646}},questType="standard"},
[72292] = {id=72292,name="Story of a Spectacular Victory",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13647,description="That was a majestic fight! Elder Poa in Iskaara will be interested in listening to the story of that impressive victory.",ends={{npcID=186448,x=0.124,y=0.492,zoneID=13646}},questType="standard"},
[72293] = {id=72293,name="Adventuring in the Dragon Isles",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,description="Oh, I know what you can do! The Dragonscale Expedition has posted a very fine looking map of the Dragon Isles nearby. Their drawings are quite accurate and detailed, if I do say so myself. Sorry, you're not here for an art review. You should go check it out to see what areas of the Dragon Isles could use your help!",starts={{npcID=193362,x=0.766,y=0.336,zoneID=13644}},ends={{npcID=193362,x=0.766,y=0.336,zoneID=13644}},coords={x=0.766,y=0.336,source="quest_giver",zoneID=13644},questType="standard"},
[72294] = {id=72294,name="Expedition Crafting Knowledge",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=189065,x=0.47,y=0.828,mapID=2022}},ends={{npcID=189065,x=0.47,y=0.828,mapID=2022}},coords={x=0.47,y=0.828,source="quest_giver",mapID=2022},questType="standard"},
