[72339] = {id=72339,name="Engine of Innovation",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,description="Tyr believed that the Engine of Innovation would be necessary for the battles to come. You have proven yourself worthy and overcome all the challenges set before you. You may now unlock Engine's full potential.",ends={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},questType="standard"},
[72354] = {id=72354,name="The Great Vault",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13644,description="Over the years, the Aspects and their kin acquired many remarkable artifacts and armaments. The Aspects ordered the construction of an enchanted vault where they could be stored for safe-keeping until such a time as a worthy soul came in search of that which lay within. You will find this Great Vault within the walls of the bank. Perhaps, if you prove your mettle, it will grant you a piece of the Aspects' ancient hoard.",starts={{npcID=196499,x=0.502,y=0.56,zoneID=13862},{npcID=213930,x=0.48,y=0.584,zoneID=13862},{npcID=199336,x=0.764,y=0.342,zoneID=13644}},ends={{npcID=196499,x=0.502,y=0.56,zoneID=13862},{npcID=213930,x=0.48,y=0.584,zoneID=13862}},coords={x=0.502,y=0.56,source="quest_giver",zoneID=13862},questType="standard"},
