[72773] = {id=72773,name="Learning Ingenuity",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13644,description="There are some goblins within Valdrakken that are investigating an abandoned titan device. Honestly, they're causing quite a disturbance. Some are concerned their investigation could cause more harm than good. The denizens of Valdrakken would appreciate you meeting these goblins to see if you can find a solution to their investigation. Without destroying part of our city.",starts={{npcID=196499,x=0.502,y=0.56,zoneID=13862},{npcID=213930,x=0.48,y=0.584,zoneID=13862},{npcID=199336,x=0.764,y=0.342,zoneID=13644}},ends={{npcID=196066,x=0.84,y=0.542,zoneID=13862}},coords={x=0.502,y=0.56,source="quest_giver",zoneID=13862},questType="standard"},
[72784] = {id=72784,name="Supporting the Cobalt Assembly",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,description=", excellent timing. Have you heard of the Cobalt Assembly? It was once a wondrous place where most of my kin lived. The Sundered Flame forced us out and have taken it over. There was a hope that we could take it from them, but the latest information from there shows we are fighting a losing battle. Can you lend us your support? Meet Venthi within the Cobalt Assembly if you can.",starts={{npcID=192222,x=0.466,y=0.398,zoneID=13646}},ends={{npcID=194680,x=0.49,y=0.23,zoneID=13646}},coords={x=0.466,y=0.398,source="quest_giver",zoneID=13646},questType="standard"},
