[73393] = {id=73393,name="Gain Even Newer Look: Whelp Egg",level=0,requiredLevel=0,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=384744,x=0.287,y=0.412,mapID=84},{npcID=384744,x=0.506,y=0.822,mapID=85},{npcID=384744,x=0.48,y=0.466,mapID=2112}},ends={{npcID=384744,x=0.287,y=0.412,mapID=84},{npcID=384744,x=0.506,y=0.822,mapID=85},{npcID=384744,x=0.48,y=0.466,mapID=2112}},coords={x=0.287,y=0.412,source="quest_giver",mapID=2112},questType="standard"},
[73398] = {id=73398,name="Too Far Forward",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Our forward forces pressed too aggressively into a Sundered Flame stronghold. Now they need help. We really need to send you in to extract them. Help them get out of there. You can use your own magic or these healing draughts from Viridia. And while you're there? Put some hurt on the Sundered Flame. They certainly deserve it.",starts={{npcID=199204,x=0.354,y=0.586,mapID=2151}},ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},coords={x=0.354,y=0.586,source="quest_giver",mapID=2151},questType="standard"},
[73399] = {id=73399,name="The Search for Blue Dragons",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="Thank you for your help so far, . We've still got more blue dragons to track down. I'll give you the honors of choosing where to go next.",starts={{npcID=190000,x=0.394,y=0.63,zoneID=13646}},coords={x=0.394,y=0.63,source="quest_giver",zoneID=13646},questType="standard"},
[73404] = {id=73404,name="Lost Blue Dragons",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="The Azure Archives are starting to feel much more lively, thanks to your help. Choose which location you'd like to investigate next.",starts={{npcID=190000,x=0.394,y=0.63,zoneID=13646}},coords={x=0.394,y=0.63,source="quest_giver",zoneID=13646},questType="standard"},
[73405] = {id=73405,name="A Pair of Blue Dragons",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="I appreciate your aid so far, . Where would you like to look next?",starts={{npcID=190000,x=0.394,y=0.63,zoneID=13646}},coords={x=0.394,y=0.63,source="quest_giver",zoneID=13646},questType="standard"},
[73406] = {id=73406,name="The Last Missing Blue Dragon",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="We've only one more blue dragon to locate now, . Let's finish this, shall we?",starts={{npcID=190000,x=0.394,y=0.63,zoneID=13646}},coords={x=0.394,y=0.63,source="quest_giver",zoneID=13646},questType="standard"},
[73550] = {id=73550,name="Honeyfreeze Mead",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="Right, so now that we've established somewhat friendlier relations and learned a wee bit of Winterpelt, it's about time tae make friends in the proper dwarf manner. What gesture of friendship is better than a stiff drink tae ward off tae cold? Both dwarves and furbolgs have a long history of brewin', so we can call it somethin' of a cultural exchange too! I saw some hearty lookin' bees a bit south of here. And where there's bees, there's honey. And where there's honey, there could be mead.",starts={{npcID=201065,x=0.668,y=0.126,mapID=2024}},ends={{npcID=201065,x=0.668,y=0.126,mapID=2024}},coords={x=0.668,y=0.126,source="quest_giver",mapID=2024},questType="standard"},
[73692] = {id=73692,name="Hive Maintenance",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="It wouldn't do tae steal a hive's honey without ensurin' they have enough food tae make it through the cold. Especially if we might want more down the line. Frostbell pollen's sticky stuff an' a wee bit fragile. But if ye run through some of the bloomin' plants, it'll be on ye like fleas on a kobold. Then, all ye have to do is bring it back tae a bee afore it blows away--they'll lick it right off ye! Tickles a bit too!",starts={{npcID=201065,x=0.668,y=0.126,mapID=2024}},ends={{npcID=201065,x=0.668,y=0.126,mapID=2024}},coords={x=0.668,y=0.126,source="quest_giver",mapID=2024},questType="standard"},
[73694] = {id=73694,name="Stuck in Stasis",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13642,mapID=2151,description="When the first dracthyr awakened from millennia of slumber, we left the Forbidden Reach for the Dragon Isles. Yet not all of the dracthyr are free. Some are still in stasis, hidden deep within their creches. We need your help. Travel to Froststone Vault. See if you can find more of our friends. One of my Healing Wings would be glad to accompany you. Choose someone who best suits your need. It is time for all dracthyr to rejoin the world as we have.",starts={{npcID=199201,x=0.346,y=0.576,mapID=2151}},ends={{npcID=199201,x=0.346,y=0.576,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[73703] = {id=73703,name="A Summon to Orgrimmar",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=1637,mapID=85,description=", Eitrigg has requested your presence in Grommash Hold. He seemed like he had much to tell you.",ends={{npcID=3144,x=0.49,y=0.722,mapID=85}},questType="standard"},
[73704] = {id=73704,name="Local Flavors",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="Now that we have the base o' the brew figured out, we need tae add the spice. Put that rudimentary Winterpelt I taught ye tae use and ask around for local ingredients tae blend into the flavor profile. Try talkin' with Kazzi. From what I gather she's somethin' of a trader. The finished brew will be a mix of dwarven and Winterpelt traditions which seems appropriate for the circumstances. An' if we're lucky, it won't taste half bad!",starts={{npcID=201065,x=0.668,y=0.126,mapID=2024}},ends={{npcID=201065,x=0.668,y=0.126,mapID=2024}},coords={x=0.668,y=0.126,source="quest_giver",mapID=2024},questType="standard"},
[73707] = {id=73707,name="TICKET: Glimmerogg Games",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="CONGRATULATIONS, LOAMM VISITOR! YOU'VE FOUND A TICKET TO THE BEST COMPETITION IN ZARALEK CAVERN : THE GLIMMEROGG GAMES! You'll find the games in the south of ZARALEK CAVERN . Just look for a bunch of happy drogbar! Don't miss our fun activities like...",starts={{npcID=387520,x=0.556,y=0.546,zoneID=14022}},ends={{npcID=201098,x=0.438,y=0.83,zoneID=14022}},coords={x=0.556,y=0.546,source="quest_giver",zoneID=14022},questType="standard"},
[73708] = {id=73708,name="Pay to Play",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="It doesn't matter if you were invited or if you just showed up. Drogbar, niffen, or , everyone pays for the Glimmerogg Games! Even I did, and I'm runnin' this show! I know you can't pay in drogdollars, but you can pay in snacks for everyone. And we love mushrooms and fish! Bring Brogg some food, and we're square, okay?",starts={{npcID=201098,x=0.438,y=0.83,zoneID=14022}},ends={{npcID=201098,x=0.438,y=0.83,zoneID=14022}},coords={x=0.438,y=0.83,source="quest_giver",zoneID=14022},questType="standard"},
[73709] = {id=73709,name="Favor on the Side",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Brogg counts more people than fees today. It's not sitting well with me neither. I'm gonna blow my top! Sure, Glimmerogg is popular, but it's not all fun and games. We have rules and everyone must follow them. You look like someone who can read fine print and follow rules. If you get rid of the intruders that are cheating Brogg, I may have something for you.",starts={{npcID=201098,x=0.438,y=0.83,zoneID=14022}},ends={{npcID=201098,x=0.438,y=0.83,zoneID=14022}},coords={x=0.438,y=0.83,source="quest_giver",zoneID=14022},questType="standard"},
[73710] = {id=73710,name="Rock By Rock",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Ah, a challenger! So, you think you can defeat Storul Heavystone in his famous rock-lifting marathon challenge? HA! Silly uplander. No one can compare to Storul! No one has EVER matched my strength. But maybe you try. Defeat will teach you a valuable lesson: true strength comes from struggle! Or, Storul will have a new friend to spot him at the gym! Get it, brul!",starts={{npcID=201100,x=0.45,y=0.832,zoneID=14022}},ends={{npcID=201100,x=0.45,y=0.832,zoneID=14022}},coords={x=0.45,y=0.832,source="quest_giver",zoneID=14022},questType="standard"},
[73711] = {id=73711,name="Marked Champion",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="You did good on Storul's challenge, but that does not make you a champion like him. To get on my level, you have to lift the greatest rock--not a real rock, a spirit one. You must face what every drogbar fears... and venerates! You must be blessed by the Carcaxas , The Great Daughter-Worm. But Carcaxas only bestow her mark on those who are DETERMINED and don't FEAR SMELLING BAD! Are you ready to take on this challenge? CAN YOU DO IT, BRUL!?",starts={{npcID=201100,x=0.45,y=0.832,zoneID=14022}},ends={{npcID=201100,x=0.45,y=0.832,zoneID=14022}},coords={x=0.45,y=0.832,source="quest_giver",zoneID=14022},questType="standard"},
[73715] = {id=73715,name="Driftwood Derby",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="One of the challenges of any new village is finding enough raw building materials. Fortunately, the ocean often brings us exactly what we need. Take my boat and sail around the island. Along the way, you can collect driftwood in nets. But be wary. You may attract some unwanted attention!",starts={{npcID=200558,x=0.344,y=0.586,mapID=2151}},ends={{npcID=200558,x=0.344,y=0.586,mapID=2151}},coords={x=0.344,y=0.586,source="quest_giver",mapID=2151},questType="standard"},
[73716] = {id=73716,name="Aylaag Elder",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=201129,x=0.442,y=0.638,mapID=2022}},ends={{npcID=201129,x=0.442,y=0.638,mapID=2022}},coords={x=0.442,y=0.638,source="quest_giver",mapID=2022},questType="standard"},
[73717] = {id=73717,name="Ohn'ir Elder",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13645,mapID=2023,starts={{npcID=201132,x=0.584,y=0.314,mapID=2023}},ends={{npcID=201132,x=0.584,y=0.314,mapID=2023}},coords={x=0.584,y=0.314,source="quest_giver",mapID=2023},questType="standard"},
[73848] = {id=73848,name="Iskaara Elder Shomkol",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=201137,x=0.466,y=0.312,mapID=2022}},ends={{npcID=201137,x=0.466,y=0.312,mapID=2022}},coords={x=0.466,y=0.312,source="quest_giver",mapID=2022},questType="standard"},
[73858] = {id=73858,name="Iskaara Elder Nemaglek",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=201139,x=0.128,y=0.49,mapID=2024}},ends={{npcID=201139,x=0.128,y=0.49,mapID=2024}},coords={x=0.128,y=0.49,source="quest_giver",mapID=2024},questType="standard"},
[73859] = {id=73859,name="Iskaara Elder Sik'ek",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13647,mapID=2025,starts={{npcID=201140,x=0.548,y=0.434,mapID=2025}},ends={{npcID=201140,x=0.548,y=0.434,mapID=2025}},coords={x=0.548,y=0.434,source="quest_giver",mapID=2025},questType="standard"},
[73860] = {id=73860,name="Elder Dekidig",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=201141,x=0.674,y=0.494,mapID=2024}},ends={{npcID=201141,x=0.674,y=0.494,mapID=2024}},coords={x=0.674,y=0.494,source="quest_giver",mapID=2024},questType="standard"},
[73861] = {id=73861,name="Elder Razlok",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13647,mapID=2025,starts={{npcID=201143,x=0.5,y=0.664,mapID=2025}},ends={{npcID=201143,x=0.5,y=0.664,mapID=2025}},coords={x=0.5,y=0.664,source="quest_giver",mapID=2025},questType="standard"},
[74117] = {id=74117,name="Rare Prey",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13642,mapID=2151,description="Rare and dangerous creatures lurk around the creches of the Forbidden Reach . If you and your allies want to stay safe, you should hunt down these threats.",starts={{npcID=200564,x=0.34,y=0.598,mapID=2151}},ends={{npcID=200564,x=0.34,y=0.598,mapID=2151}},coords={x=0.34,y=0.598,source="quest_giver",mapID=2151},questType="standard"},
[74118] = {id=74118,name="Spelunking the Den",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Did you have a chance to visit the Skyfox Den? A very exciting place, from what I've heard. Expedition's spelunkers started surveying the cave and even installed a few grappling hooks on the ceiling, but they were scared away by violent slyverns. Can you do me a favor? Get inside the Skyfox Den, grab the abandoned gear, and check the ceiling for any hidden crevices. Who knows what could be hidden inside?",starts={{npcID=200566,x=0.342,y=0.598,mapID=2151}},ends={{npcID=200566,x=0.342,y=0.598,mapID=2151}},coords={x=0.342,y=0.598,source="quest_giver",mapID=2151},questType="standard"},
[74119] = {id=74119,name="Angler's Challenge",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots to cast a line. Why don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.",starts={{npcID=200562,x=0.342,y=0.6,mapID=2151}},ends={{npcID=200562,x=0.342,y=0.6,mapID=2151}},coords={x=0.342,y=0.6,source="quest_giver",mapID=2151},questType="standard"},
[74282] = {id=74282,name="Authentic Authorization",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course! If I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans! If you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!",starts={{npcID=201180,x=0.292,y=0.528,mapID=2151}},ends={{npcID=201180,x=0.292,y=0.528,mapID=2151}},coords={x=0.292,y=0.528,source="quest_giver",mapID=2151},questType="standard"},
[74291] = {id=74291,name="Blue is My Favorite Color",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="Oh, Kiry's here! I wonder if she has made her decision. Please ask her for thoughts, $p.",starts={{npcID=201019,x=0.458,y=0.436,zoneID=5785}},ends={{npcID=190000,x=0.394,y=0.63,zoneID=13646}},coords={x=0.458,y=0.436,source="quest_giver",zoneID=5785},questType="standard"},
[74293] = {id=74293,name="Not Forgotten",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Viridia is confident that more dracthyr may slumber in these chambers, long forgotten amongst Neltharion's relics.",starts={{npcID=201240,x=0.288,y=0.522,mapID=2151}},ends={{npcID=199201,x=0.346,y=0.576,mapID=2151}},coords={x=0.288,y=0.522,source="quest_giver",mapID=2151},questType="standard"},
[74294] = {id=74294,name="The Keys You Need",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Can I trust you? These are the only keys we have. If we lose them, we can't open any locked doors. Here. Take them. Use them on the doors within this chamber. You look like a hero. Be bold! Throw those doors wide! You'll find glory or... um... something that is not glory but is still amazing! Just don't die. We might find more, but we'll have to search the island to find them.",starts={{npcID=200041,x=0.292,y=0.53,mapID=2151}},ends={{npcID=200041,x=0.292,y=0.53,mapID=2151}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2151},questType="standard"},
[74300] = {id=74300,name="Tectonus",level=70,requiredLevel=70,faction="none",expansion=9,zoneID=14433,mapID=2151,questType="standard"},
[74334] = {id=74334,name="Future Aspects",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,description="My brothers are not interested in investigating the Sundered Flame or helping Emberthal. It worries me that we are dividing our efforts, but I understand their motivation in considering our next steps against Fyrakk immediately. I will aid Emberthal as I promised, but perhaps we should ask for help from the local niffen...",starts={{npcID=201366,x=0.546,y=0.546,zoneID=14022}},ends={{npcID=201236,x=0.594,y=0.688,zoneID=14022}},coords={x=0.546,y=0.546,source="quest_giver",zoneID=14022},questType="standard"},
[74335] = {id=74335,name="A Moment of Reflection",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="I do not understand what would drive Turi Flickerflame and her band of mages to attempt what they have done here today. But I do understand the pain of losing family. I understand the fear and regret that follows you wherever you go. I have much to think about. I imagine Kalecgos has much yet to do in the Dragon Isles--return there with him. I will follow soon... I need some time to think upon what happened here today.",starts={{npcID=199736,x=0.67,y=0.546,zoneID=15}},ends={{npcID=190000,x=0.394,y=0.63,zoneID=13646}},coords={x=0.67,y=0.546,source="quest_giver",zoneID=15},questType="standard"},
[74354] = {id=74354,name="Artifacts Abound",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=618,description="It is... certainly bizarre to see Sindragosa, real in all but the flesh. Look, I appreciate that you have both come all this way for me. The Isles sounds delightful, but I have dedicated many years to cleaning up Winterspring . I am not about to leave a job unfinished. Magic is abound and unfortunately not all good. If you would like to help, The Hidden Grove is next on my list. Therein lie ruins of totems that still emanate with some sort of magic. Will you collect pieces of them?",starts={{npcID=199370,x=0.48,y=0.59,zoneID=618}},ends={{npcID=199370,x=0.48,y=0.59,zoneID=618}},coords={x=0.48,y=0.59,source="quest_giver",zoneID=618},questType="standard"},
[74355] = {id=74355,name="Primordial Embellishment",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="How remarkable! You can affix such a variety of special gems to enhance its power! You should journey back into the Zskera Vaults and locate a Primordial Jeweler's Kit . Yes, that's what you'll need. Crafting gems of this type requires specialized tools. Once we have them, we can fully explore the ring's power! The mind reels with limitless possibilities...",starts={{npcID=200724,x=0.35,y=0.576,mapID=2151}},ends={{npcID=200724,x=0.35,y=0.576,mapID=2151}},coords={x=0.35,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[74356] = {id=74356,name="Back with the Blues",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="It seems I had a good idea. Now let us hope we can broach the subject of the Isles again. I am glad to see Haleh relaxed. She deserves it.",starts={{npcID=199404,x=0.474,y=0.602,zoneID=618}},ends={{npcID=186188,x=0.394,y=0.63,zoneID=13646}},coords={x=0.474,y=0.602,source="quest_giver",zoneID=618},questType="standard"},
[74359] = {id=74359,name="Plunder Siege",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="We're not the only ones to have noticed the storms abating over the Forbidden Reach . Other interested parties have arrived too, looting everything they can and storing their spoils in chests. If they use Neltharion's old hoard chests, they're in for a surprise when the chests' enchantments lock them out. We'll need to clear out surrounding looters to break the chests' enchantments. See if you can recover a stolen item, specifically my old journal. It's nowhere to be found.",starts={{npcID=200010,x=0.346,y=0.576,mapID=2151}},ends={{npcID=200010,x=0.346,y=0.576,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[74374] = {id=74374,name="An Important Heirloom",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="I can guide you in crafting your offering to the ancestors, but you will need two things: First, you need to know the basics! Arugi here can teach you how to cook if you don't already know. Second, I need my old cookbook. We're going to make something truly special, a fusion of old Draenor and Azeroth, and I'm going to need it for reference. Go fetch my book from the inn, and we can get started.",starts={{npcID=199383,x=0.508,y=0.428,mapID=1}},ends={{npcID=199383,x=0.508,y=0.428,mapID=1}},coords={x=0.508,y=0.428,source="quest_giver",mapID=1},questType="standard"},
[74375] = {id=74375,name="Collating Their Research",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,description="It no longer matters how the Sundered Flame got here; now we need to know why. What is in this vault that Sarkareth is after? , while you are in their camp, look for notes, research papers, journals--anything you can find that might reveal their intentions. Please bring whatever you find to me.",starts={{npcID=200049,x=0.594,y=0.688,zoneID=14022}},ends={{npcID=200049,x=0.594,y=0.688,zoneID=14022}},coords={x=0.594,y=0.688,source="quest_giver",zoneID=14022},questType="standard"},
[74376] = {id=74376,name="Coalesced Storm Remnants",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13992,mapID=2085,description="The Primalist Researchers in the area will be interested in this for further study.",ends={{npcID=199425,x=0.612,y=0.47,mapID=2085}},questType="standard"},
[74379] = {id=74379,name="Still Within Reach",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="While we dracthyr were kept in stasis, the Spellsworn, ancient servants of Malygos the Spellweaver, were our wardens. However, despite being slain years ago, the late Aspect's forces are still loyal to him and his lasting directive to keep this island contained. They present a danger to any dracthyr still lost, wounded, or otherwise unaccounted for. Scouts have reported the sighting of a rather large Spellsworn brute hunting for escaped dracthyr. This deadly pursuer must be dealt with.",starts={{npcID=200559,x=0.356,y=0.594,mapID=2151}},ends={{npcID=200559,x=0.356,y=0.594,mapID=2151}},coords={x=0.356,y=0.594,source="quest_giver",mapID=2151},questType="group"},
[74381] = {id=74381,name="Hidden Legacies",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Raszageth and her storms are gone, but our troubles are far from over. The way to the Reach is clear again, and some of our allies have returned to establish a base camp. However, Sarkareth and the Sundered Flame have begun making their way there as well. We need to secure the island. We would appreciate your aid.",starts={{npcID=201398,x=0.61,y=0.264,mapID=2112}},ends={{npcID=201398,x=0.61,y=0.264,mapID=2112}},coords={x=0.61,y=0.264,source="quest_giver",mapID=2112},questType="standard"},
[74382] = {id=74382,name="Community Feast",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[74389] = {id=74389,name="Filming the Caldera",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The arthropods in Caldera of the Menders are truly vicious. One of our gyrocopters went missing there! Our expedition sent a unmanned surveillance aircraft there, but it hasn't returned. Can you find the gyrocopter? You could use it to capture the Caldera's wildlife on camera?",starts={{npcID=200566,x=0.342,y=0.598,mapID=2151}},ends={{npcID=200566,x=0.342,y=0.598,mapID=2151}},coords={x=0.342,y=0.598,source="quest_giver",mapID=2151},questType="standard"},
[74390] = {id=74390,name="Brutal Prey",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13642,mapID=2151,description="This land is crawling with opportunities for a skilled hunter. We want you to join the hunt. Some threats are feral. Dare I say it, some are greatest threats are sentient and malevolent. If we all work together, we can make the Reach a safe haven, as it used to be.",starts={{npcID=200564,x=0.34,y=0.598,mapID=2151}},ends={{npcID=200564,x=0.34,y=0.598,mapID=2151}},coords={x=0.34,y=0.598,source="quest_giver",mapID=2151},questType="standard"},
[74391] = {id=74391,name="Harpooner's Challenge",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14022,mapID=2133,description="Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots. Why don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.",starts={{npcID=200562,x=0.342,y=0.6,mapID=2151}},ends={{npcID=200562,x=0.342,y=0.6,mapID=2151}},coords={x=0.342,y=0.6,source="quest_giver",mapID=2133},questType="standard"},
[74393] = {id=74393,name="Report: Battlefield Ruins",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,description="Our situation is worse than we thought. Their dominance of the air keeps us at a disadvantage. They plan on freeing their powerful Elder from Aberrus. Allowing them to accomplish this could result in us permanently forfeiting control of this area. Seek out Field Commander Ignax in the Battlefield Ruins and see what can be done to turn the tide of this battle. We will join you shortly.",starts={{npcID=200046,x=0.5,y=0.276,zoneID=14022}},ends={{npcID=200051,x=0.466,y=0.296,zoneID=14022}},coords={x=0.5,y=0.276,source="quest_giver",zoneID=14022},questType="standard"},
[74415] = {id=74415,name="A Worthy Offering",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="Now that we have everything on the list, you just have to put it all together, right? How hard could it be? Umm... I'm going to let you handle it, though. I'll watch.",ends={{npcID=199148,x=0.522,y=0.43,mapID=1}},questType="standard"},
[74433] = {id=74433,name="Returning the Blade",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,ends={{npcID=200206,x=0.668,y=0.13,mapID=2024}},questType="standard"},
[74436] = {id=74436,name="Storm Warning",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="Ah, ! I knew I would find you at the right place at the right time. The elements do not just threaten the Dragon Isles in our current time, but also from beyond. Go to the Temporal Conflux and travel through the rift into the future the primalists have overrun. There, speak to Soridormi . She will have more details for you when you arrive.",starts={{npcID=201492,x=0.634,y=0.48,zoneID=13862}},ends={{npcID=183860,x=0.61,y=0.508,zoneID=13992}},coords={x=0.634,y=0.48,source="quest_giver",zoneID=13862},questType="standard"},
[74437] = {id=74437,name="Resisting the Storm",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13992,description="The Primalists are growing in strength in this future timeline, despite our best efforts. If they overrun this valley and threaten the Temporal Conflux, they may become a problem for the rest of the timeways. We are already protecting the timeways from enough threats. Push back on them, . We need to keep this peril in check. Speak to Tarnormu to gather any supplies you might need.",starts={{npcID=183860,x=0.61,y=0.508,zoneID=13992}},ends={{npcID=183860,x=0.61,y=0.508,zoneID=13992}},coords={x=0.61,y=0.508,source="quest_giver",zoneID=13992},questType="standard"},
[74440] = {id=74440,name="Windseeker Avash",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[74442] = {id=74442,name="One Dragon's Junk...",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Greetings! I am looking for items of power from my flight's past. We have a history of great warriors and battle prowess, and I want to recover items that will help us reach that again. I heard you found these vaults. If you see anything of interest inside, could you show it to me?",starts={{npcID=201517,x=0.292,y=0.53,mapID=2151}},ends={{npcID=201517,x=0.292,y=0.53,mapID=2151}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2151},questType="standard"},
[74443] = {id=74443,name="Is Another Dragon's Treasure?",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="I must admit, I am out of my depth here. It is of black dragon make. The decoration on the pommel matches, but I have no idea what it is. Which I suppose is the point. I have heard you have travelled the Isles. Do you have any recommendations on who to talk to?",starts={{npcID=201517,x=0.292,y=0.53,mapID=2151}},ends={{npcID=201517,x=0.292,y=0.53,mapID=2151}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2151},questType="standard"},
[74447] = {id=74447,name="Verbal Archaeology",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Where should we meet this Veritistrasz of yours? Ruby Lifeshrine? Are you sure this is not an attempt to introduce me to Alexstrasza? No? Well then! I shall meet you at the Ruby Lifeshrine!",starts={{npcID=201517,x=0.292,y=0.53,mapID=2151}},ends={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2023},questType="standard"},
[74476] = {id=74476,name="Slime Dies When You're Having Fun",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,description="The investigators here told me that there were some side effects to removing the time anomaly from Eon's Fringe. Seems a bunch of slimes snuck through the timestream in the process. Oh! Oh! Time slimes ! They're Time slimes ! Ha. Anyway, could you take some of them out?",starts={{npcID=204987,x=0.538,y=0.878,zoneID=13647}},ends={{npcID=204987,x=0.538,y=0.878,zoneID=13647}},coords={x=0.538,y=0.878,source="quest_giver",zoneID=13647},questType="standard"},
[74488] = {id=74488,name="Runaway Rusziona",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Black whelps have the agility of a rock, but they try to make up for it with the most impressive top speed. Try to take it easy around those corners! : Dash forward. : Stops forward movement. : Restores all Vigor. Must be grounded.",starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},ends={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[74489] = {id=74489,name="Zhoomsa",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Bronze whelps can be careless when trying to win, so be careful with the timeways! : Transform into an adult and gain improved speed. : Restore 1 Vigor until all Vigor has been recovered. : Resets cooldowns.",starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},ends={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[74490] = {id=74490,name="Zaleth on the Go",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Blue whelps will try to skip ahead where they can, but be careful blinking through rings! : Blink forward and dash. : Increases forward acceleration. : Consumes Arcane Acceleration and restores Vigor.",starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},ends={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[74491] = {id=74491,name="Pole Position Posidriss",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Green whelps have an affinity for short naps and bursts of speed, so do your best to keep pace. : Fly up then restore 1 Vigor. : Adds 5 sec to Winds of Life's duration. : Anytime you restore Vigor, dash forward.",starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},ends={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[74492] = {id=74492,name="Blistering Belastrasza",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Red whelps can be a little out of control, so best of luck! : Consumes all Vigor over time. : Restore all Vigor, boosting forward each time. : Consumes Crimson Flight, resets cooldowns.",starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},ends={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[74493] = {id=74493,name="Second Time Is The Charm",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Voraxian bounces the Odd Round Object in his hands a few times.> Hmm, it lands in the hand well, like it was made for this. Let us talk to Veritistrasz and see if he knows more.",starts={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},ends={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},coords={x=0.578,y=0.67,source="quest_giver",mapID=2023},questType="standard"},
[74494] = {id=74494,name="A Scale for a Scale",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,mapID=2133,description="The elder waking was a threat, certainly. But there is one more mission I must complete before we depart, lest we lose our only chance to complete it at all. However different the Zaqali tribe may be from the Qalashi, they are still dragonslayers. Their implements of war are no less deadly to our kind. I need a spear on par with the one we saw at the elder's side. Find the largest one you can and deliver it to me.",starts={{npcID=201647,x=0.283,y=0.51,mapID=2133}},ends={{npcID=199952,x=0.296,y=0.496,mapID=2133}},coords={x=0.283,y=0.51,source="quest_giver",mapID=2133},questType="standard"},
[74495] = {id=74495,name="The Tale of Hraxian",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Hello , it is good to see you. Would you like to join us around the fire? I think it is time we heard a positive story about the obsidian flight of old. I once promised yourself and Voraxian I would tell you the story from the vase you found in the Zskera Vaults. I believe it is that time.",starts={{npcID=200298,x=0.402,y=0.684,zoneID=14022}},ends={{npcID=200298,x=0.402,y=0.684,zoneID=14022}},coords={x=0.402,y=0.684,source="quest_giver",zoneID=14022},questType="standard"},
[74502] = {id=74502,name="Complimentary Gift",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,starts={{npcID=201714,x=0.282,y=0.568,mapID=2151}},ends={{npcID=201714,x=0.282,y=0.568,mapID=2151}},coords={x=0.282,y=0.568,source="quest_giver",mapID=2151},questType="standard"},
[74503] = {id=74503,name="Another Gift",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,starts={{npcID=201714,x=0.282,y=0.568,mapID=2151}},ends={{npcID=201714,x=0.282,y=0.568,mapID=2151}},coords={x=0.282,y=0.568,source="quest_giver",mapID=2151},questType="standard"},
[74514] = {id=74514,name="The Slowest Fan Club",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Has a crowd ever roared for you? Everyone shouting your name, pushing you on to victory? I want to give that same feeling to Slick. Give him the taste of being a champion. Course, we don't speak snail, so we can only be so useful. Round up some snails that could use purpose in their lives. Slick needs a fan club.",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
[74515] = {id=74515,name="Snail Mail",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Racing snails are all about speed, but riding snails? They need stamina to boot. I owe some supplies to a buddy in Loamm. Why don't you make the delivery for me? Help build Slick's endurance. Oh, and make sure you don't dismount. Not much of a training session if you keep hopping off and on.",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
[74516] = {id=74516,name="A Snail's Pace",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="It's an off day for our local racing track, so I figured we could take the opportunity to build up Slick's speed. Grow some confidence on his home turf, I'm thinking. Take two laps around the track. Let's see how your training is coming along!",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
[74517] = {id=74517,name="All Terrain Snail",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13647,description="While life in these caverns is plenty exciting, Slick has a future in the world above. Namely as your trusty mount. Which means he needs to prepare for all sorts of environments. Luckily, the Dragon Isles has biomes to spare. Why don't you take him for a spin? Give him a taste of what's to come. One lap per location should do the trick.",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
[74518] = {id=74518,name="Resistance Training",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="These caverns aren't easy on my poor snails, which is why I feed them a special crystal diet. Keeps their shells hard and gleaming. Slick eats more than his fair share though, so I'm plumb out. Would you collect some crystals in Zaralek Cavern ? Get a nice mix, too. We need to make sure Slicks ready for every environment.",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
[74519] = {id=74519,name="Good for Goo",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,mapID=2133,description="Every snail trainer knows that it's all about the goo. The slime. The mucus. That's how you turn a speedy snail into a champion. Slick could use a good slather. Go out and collect some goo from the local slime trails to slick him up. Heh.",starts={{npcID=201752,x=0.442,y=0.8,mapID=2133}},ends={{npcID=201752,x=0.442,y=0.8,mapID=2133}},coords={x=0.442,y=0.8,source="quest_giver",mapID=2133},questType="standard"},
[74520] = {id=74520,name="Less Cargo",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Those djaradin think they own these caverns, coming around here and looting our supplies. How am I supposed to train champions under these conditions? Can you do me a favor and get those supplies back? I can't help you train Slick without them. Besides, the big fellow could use a rest day.",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
[74521] = {id=74521,name="A Flame, Extinguished",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Sarkareth is no more. His hubris left him vulnerable to the dark influences that have assaulted our flight for millennia. Just like Neltharion before him. I believe Emberthal seeks more answers than what Wrathion and Sabellian are able to give. She may need some assistance.",starts={{npcID=201727,x=0.48,y=0.118,zoneID=14022}},coords={x=0.48,y=0.118,source="quest_giver",zoneID=14022},questType="standard"},
[74538] = {id=74538,name="Blow It Up",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,description="Make no mistake, the djaradin are experienced dragon killers. But right now their ruthless tactics are overshadowed by the devastating power of their battlefield ballistae, capable of taking out any threat from a long distance. I have lost many good soldiers to these potent weapons. It is essential that we destroy the ballistae if we hope to level the playing field and take to the skies. It is possible that we may even be able to gain the upper hand in this war.",starts={{npcID=200051,x=0.466,y=0.296,zoneID=14022}},ends={{npcID=200051,x=0.466,y=0.296,zoneID=14022}},coords={x=0.466,y=0.296,source="quest_giver",zoneID=14022},questType="standard"},
[74539] = {id=74539,name="Thinning Their Defenses",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,description="The Firecallers are a formidable force. Their powerful, lethal magic allows them to vaporize anything that comes near them. Their strategic positioning on high ledges makes them difficult to reach, but we cannot allow them to continue causing destruction among our forces. The fate of our forces depends on your success. Good luck!",starts={{npcID=200051,x=0.466,y=0.296,zoneID=14022}},ends={{npcID=200051,x=0.466,y=0.296,zoneID=14022}},coords={x=0.466,y=0.296,source="quest_giver",zoneID=14022},questType="standard"},
[74540] = {id=74540,name="Intercepting Communications",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,description=", we need intel, and we need it now. Somewhere within one of the djaradin's encampments, you will find their field general. He is a seasoned and formidable opponent, responsible for many attacks on our forces. According to our field agents, he may possess crucial military orders outlining their next offense and the locations of their new supply lines. It is imperative that we obtain these orders. We cannot allow the djaradin to gain the upper hand.",starts={{npcID=200051,x=0.466,y=0.296,zoneID=14022}},ends={{npcID=200051,x=0.466,y=0.296,zoneID=14022}},coords={x=0.466,y=0.296,source="quest_giver",zoneID=14022},questType="standard"},
[74542] = {id=74542,name="Air Superiority",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,description="Few of my soldiers have experience fighting alongside dragons. What a glorious day. Their presence gives us confidence, . Now we must put an end to the djaradin's advance once and for all.",starts={{npcID=200051,x=0.466,y=0.296,zoneID=14022}},ends={{npcID=202523,x=0.536,y=0.302,zoneID=14022}},coords={x=0.466,y=0.296,source="quest_giver",zoneID=14022},questType="standard"},
[74557] = {id=74557,name="Investigating the Unknown",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,description="We can only assume that something ambushed the marching djaradin. Who could have done this? We should investigate it before we proceed.",starts={{npcID=202523,x=0.536,y=0.302,zoneID=14022}},ends={{npcID=202523,x=0.536,y=0.302,zoneID=14022}},coords={x=0.536,y=0.302,source="quest_giver",zoneID=14022},questType="standard"},
[74562] = {id=74562,name="Break Them Out",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,description="Cages, chains and transportation carts ... I think we all know where this leads. If the drakonids plan on capturing and enslaving the slitherdrakes, then they are no better than the djaradin. See what you can do to thwart their plans.",starts={{npcID=202523,x=0.536,y=0.302,zoneID=14022}},ends={{npcID=202523,x=0.536,y=0.302,zoneID=14022}},coords={x=0.536,y=0.302,source="quest_giver",zoneID=14022},questType="standard"},
[74563] = {id=74563,name="Worst of the Worst",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,description="Everything here suggests this is a well-coordinated effort. These slitherdrakes are almost like wild beasts. They will not stand a chance without our aid. Find whoever is leading their operation and put an end to this.",starts={{npcID=202523,x=0.536,y=0.302,zoneID=14022}},ends={{npcID=202523,x=0.536,y=0.302,zoneID=14022}},coords={x=0.536,y=0.302,source="quest_giver",zoneID=14022},questType="standard"},
[74568] = {id=74568,name="They Who Would Burn Us",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13646,description="The djaradin and their Primalist allies are a stain upon the land, . Wipe them from it.",starts={{npcID=201090,x=0.75,y=0.696,zoneID=13645}},ends={{npcID=201090,x=0.75,y=0.696,zoneID=13645}},coords={x=0.75,y=0.696,source="quest_giver",zoneID=13645},questType="standard"},
[74569] = {id=74569,name="Deny Them Resources",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13645,description="This entire invasion has been carried out with the sole objective of infusing raw materials with elemental power on an unprecedented scale. While we may not know Fyrakk's ultimate goal, frustrating his efforts seems straightforward enough. If he wants these materials, we will deny them to him.",starts={{npcID=201860,x=0.756,y=0.698,zoneID=13645}},ends={{npcID=201860,x=0.756,y=0.698,zoneID=13645}},coords={x=0.756,y=0.698,source="quest_giver",zoneID=13645},questType="standard"},
[74570] = {id=74570,name="Aid Our Wounded",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13645,description=", our forces were not prepared for such an onslaught. These djaradin fight with more furor than the forces we have faced in the past. We have wounded behind enemy lines. If you possess knowledge of how to heal then I ask you employ it. If you do not, we have bandages to aid the wounded with. Please help bring our people out of the fire.",starts={{npcID=201861,x=0.754,y=0.692,zoneID=13645}},ends={{npcID=201861,x=0.754,y=0.692,zoneID=13645}},coords={x=0.754,y=0.692,source="quest_giver",zoneID=13645},questType="standard"},
[74571] = {id=74571,name="Clear a Path",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13645,description="The djaradin are fortifying their beachhead. We cannot allow them to dig in any deeper or we risk their advances becoming permanent. Destroy their barricades before that can happen.",starts={{npcID=201876,x=0.75,y=0.696,zoneID=13645}},ends={{npcID=201876,x=0.75,y=0.696,zoneID=13645}},coords={x=0.75,y=0.696,source="quest_giver",zoneID=13645},questType="standard"},
[74572] = {id=74572,name="Make it Rain",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13645,description="The djaradin are setting the Plains ablaze with the reckless use of fire magic. We must act before these small sparks grow into a raging wildfire. A deep pool of fresh water can be found not far from here. Skim the surface on your drake to collect as much as you can carry, then fly over the djaradin camp to douse any flames beneath you. This won't be enough to put out the larger blazes, but it will buy us time.",starts={{npcID=201861,x=0.754,y=0.692,zoneID=13645}},ends={{npcID=201861,x=0.754,y=0.692,zoneID=13645}},coords={x=0.754,y=0.692,source="quest_giver",zoneID=13645},questType="standard"},
[74573] = {id=74573,name="Aerial Support",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13645,description="The Primalist portals must be destroyed if we are to prevent them from infusing these raw materials with elemental energy. Unfortunately, their structures are too heavily warded for any single attack, whether mortal or draconic, to do lasting harm. Together, though, there is a way. Take this seed. Use it to weaken their defenses and we will be able to strike before they have a chance to react.",starts={{npcID=201648,x=0.752,y=0.692,zoneID=13645}},ends={{npcID=201648,x=0.752,y=0.692,zoneID=13645}},coords={x=0.752,y=0.692,source="quest_giver",zoneID=13645},questType="standard"},
[74581] = {id=74581,name="The Long Knives",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=6451,mapID=1,starts={{npcID=199151,x=0.54,y=0.426,mapID=1},{npcID=199152,x=0.54,y=0.422,mapID=1},{npcID=199154,x=0.542,y=0.424,mapID=1},{npcID=199156,x=0.54,y=0.426,mapID=1},{npcID=199173,x=0.54,y=0.424,mapID=1},{npcID=200616,x=0.522,y=0.428,mapID=1}},ends={{npcID=10176,x=0.432,y=0.688,mapID=1},{npcID=10176,x=0.452,y=0.686,mapID=1}},coords={x=0.54,y=0.426,source="quest_giver",mapID=1},questType="standard"},
[74769] = {id=74769,name="Stemming the Irontide",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Unfortunately, we are not the only ones who took notice of opportunities in the Reach. Our scouts have sent word of pirate vessels moored offshore. The first longboats have apparently come ashore on our northeastern beaches. Our history is not theirs to plunder. If you come across these pirates, send them swimming back to their little boats.",starts={{npcID=199201,x=0.346,y=0.576,mapID=2151}},ends={{npcID=199201,x=0.346,y=0.576,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[74771] = {id=74771,name="Key Hunting",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="My pockets are empty. I have no more vault keys! See if you can find any Zskera Keys, and Jeb and I will see what we can find. If we pool our keys, we can open a lot of doors.",starts={{npcID=200041,x=0.292,y=0.53,mapID=2151}},ends={{npcID=200041,x=0.292,y=0.53,mapID=2151}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2151},questType="standard"},
[74775] = {id=74775,name="Disciple of Fyrakk: Kretchenwrath",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13645,ends={{npcID=181198,x=0.6,y=0.374,zoneID=13645},{npcID=201860,x=0.756,y=0.698,zoneID=13645}},questType="standard"},
[74783] = {id=74783,name="The Sound of Silence",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13646,description="It has been so many years since Shandaral has known true silence. With luck, our actions today will allow the echoes of this cursed place to fade. You are due back in the Isles, no doubt--and I think it is high time I fly there as well.",starts={{npcID=199184,x=0.914,y=0.572,zoneID=2817}},ends={{npcID=190000,x=0.394,y=0.63,zoneID=13646}},coords={x=0.914,y=0.572,source="quest_giver",zoneID=2817},questType="standard"},
[74786] = {id=74786,name="Snailspiration: Shimmershell Snail",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="I smell a snail on you, but it's strange. You holding out on me? Not many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
[74787] = {id=74787,name="Come Snail Away",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Hmm. You ever mount a snail before? I've trained generations of racing snail champions, but now I've come across my toughest case yet. Problem is he's too crokin' big. Straight up barred from competition. It's a shame to keep such a prize specimen stuck in a bucket though. If you can help me train Slick up to be the speedster I know he is, we'll call him yours!",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
[74795] = {id=74795,name="An Odd Round Object",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Voraxian .>",ends={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},questType="standard"},
[74796] = {id=74796,name="A Dusty Vase",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Voraxian is interested in.>",ends={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},questType="standard"},
[74847] = {id=74847,name="Emberthal Awaits",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="We are by no means ready to relax, but at least our encampment here is stable... for the time being. I should be able to handle the rest of our operation from here. Emberthal arrived while you were in the field. She and her allies are surveying the area from the cliffs above. It would be wise to check in with her, I think. We would not want her to attempt taking the Reach alone.",starts={{npcID=199201,x=0.346,y=0.576,mapID=2151}},ends={{npcID=199532,x=0.326,y=0.604,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[74857] = {id=74857,name="Mouse Detective",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Normally I'd chase strangers off my property, but today's an exception. My sniffin' mouse has gone missing. It's not like Persii to ignore me when I call for her... I can't smell as good as other niffen, so I can't tend to the harvest without her help. Poor thing must be so scared, out there all on her own. Please, you gotta find Persii!",starts={{npcID=202597,x=0.51,y=0.74,zoneID=14022}},ends={{npcID=202600,x=0.504,y=0.764,zoneID=14022}},coords={x=0.51,y=0.74,source="quest_giver",zoneID=14022},questType="standard"},
[74858] = {id=74858,name="Agrulculture",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="The niffen say that sniffin' mice have great noses. They can make their way through the caverns and track down the fastest racing snails. Even sniff out glow spores ready for harvest. But I have a good nose, too. Maybe I could even sniff out those glow spores ! Let's collect the harvest for the hermit. That will show him it's okay that his mouse friend isn't here--because I can fill in!",starts={{npcID=202600,x=0.504,y=0.764,zoneID=14022}},ends={{npcID=202600,x=0.504,y=0.764,zoneID=14022}},coords={x=0.504,y=0.764,source="quest_giver",zoneID=14022},questType="standard"},
[74859] = {id=74859,name="Sporemoth Exterminator",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Looks like sporemoths are wrecking these crops. If they keep eating all the spores, the hermit won't have anything to harvest. We need to cull the sporemoths. That should help keep the harvest thriving--and show that I know how to take care of a farm.",starts={{npcID=202600,x=0.504,y=0.764,zoneID=14022},{npcID=204573,x=0.502,y=0.769,zoneID=14022}},ends={{npcID=202600,x=0.504,y=0.764,zoneID=14022},{npcID=204573,x=0.502,y=0.769,zoneID=14022}},coords={x=0.504,y=0.764,source="quest_giver",zoneID=14022},questType="standard"},
[74860] = {id=74860,name="A Friendly Introduction",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="It's time to deliver the harvest to the hermit. When he sees what good work we did, maybe he'll hire me as a farmhand! I, uh... tried talking to him once before. Wanted to ask if he needed a helper. Doesn't seem to like guests, though. Especially drogbar. So I got nervous and ran off. You were looking for his mouse. Could you introduce us?",starts={{npcID=202600,x=0.504,y=0.764,zoneID=14022}},ends={{npcID=202597,x=0.51,y=0.74,zoneID=14022}},coords={x=0.504,y=0.764,source="quest_giver",zoneID=14022},questType="standard"},
[74861] = {id=74861,name="An Unfriendly Confrontation",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,mapID=2133,description="I knew I recognized that drogbar's voice. He probably took Persii. I bet he knows where she is! Please, $p, you gotta track down that big bully. Do whatever it takes to get Persii back!",starts={{npcID=202597,x=0.51,y=0.74,mapID=2133}},ends={{npcID=202600,x=0.504,y=0.764,mapID=2133}},coords={x=0.51,y=0.74,source="quest_giver",mapID=2133},questType="standard"},
[74866] = {id=74866,name="Journal Entry: Experiments",level=70,requiredLevel=70,faction="alliance",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},questType="standard"},
[74869] = {id=74869,name="Primordial Answers",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Revelations await us within this vault. Perhaps we'll find a way to protect ourselves against Primalist magic. The elementals hiding in these vaults are wild, ancient, and free of Primalist control. Perhaps they hold the secret to helping the elementals on the surface. I have an idea. We'll need four primordial cores. Then we can construct a talisman that can purify and remove the influence of Primalist control from the elementals outside. If you help us, I will share what we have found here.",starts={{npcID=202627,x=0.288,y=0.576,mapID=2151}},ends={{npcID=202627,x=0.288,y=0.576,mapID=2151}},coords={x=0.288,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[74876] = {id=74876,name="The Buddy System",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Oh, hello there. Was I speaking my thoughts out loud again? I don't mean to trouble others with my problems, but... I'm a sniffenseeker, you see. We find unique and amazing places all over the cavern! But we have an important rule here in Loamm--we always follow the buddy system. Nobody digs alone! I've had the same buddy since we were pups, but she's too busy to dig anymore. I found this interesting new smell. Before, I had a buddy... Say, how do you feel about being a stand-in dig partner?",starts={{npcID=201426,x=0.556,y=0.574,zoneID=14022}},ends={{npcID=201426,x=0.556,y=0.574,zoneID=14022}},coords={x=0.556,y=0.574,source="quest_giver",zoneID=14022},questType="standard"},
[74877] = {id=74877,name="Best Friends",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Really, I have fun digging with you. I do! Please, don't take this badly, but... I miss my best friend. I don't blame her for being busy. She was kidnapped, and she is the princess! I know she doesn't have lots of time. I just wish... ...I don't know. Maybe I wish things were the way they used to be, when she wanted to dig with me.",starts={{npcID=201426,x=0.556,y=0.574,zoneID=14022}},ends={{npcID=202766,x=0.522,y=0.628,zoneID=14022}},coords={x=0.556,y=0.574,source="quest_giver",zoneID=14022},questType="standard"},
[74878] = {id=74878,name="Old Friends, Dear Friends",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="I don't want to give up on my best friend, but what if she doesn't want to be friends anymore? We've been dig buddies since we were tiny pups. Maybe it matters to me more than it does to her. What do I even say?",starts={{npcID=202766,x=0.522,y=0.628,zoneID=14022}},ends={{npcID=202766,x=0.522,y=0.628,zoneID=14022}},coords={x=0.522,y=0.628,source="quest_giver",zoneID=14022},questType="standard"},
[74880] = {id=74880,name="Journal Entry: Relics",level=70,requiredLevel=70,faction="horde",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},questType="standard"},
[74883] = {id=74883,name="Journal Entry: The Creches",level=70,requiredLevel=70,faction="horde",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},questType="standard"},
[74896] = {id=74896,name="Journal Entry: Silence",level=70,requiredLevel=70,faction="horde",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},questType="standard"},
[74900] = {id=74900,name="Receiving Stone: Final Warning",level=70,requiredLevel=70,faction="horde",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},questType="standard"},
[74901] = {id=74901,name="Sending Stone: Protest",level=70,requiredLevel=70,faction="horde",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},questType="standard"},
[74902] = {id=74902,name="Sending Stone: Initial Report",level=70,requiredLevel=70,faction="horde",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},questType="standard"},
[74903] = {id=74903,name="Sending Stone: The Prisoner",level=70,requiredLevel=70,faction="horde",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},questType="standard"},
[74905] = {id=74905,name="Researchers Under Fire",level=10,requiredLevel=10,faction="none",expansion=9,questType="standard"},
[74906] = {id=74906,name="Researchers Under Fire",level=10,requiredLevel=10,faction="none",expansion=9,questType="standard"},
[74908] = {id=74908,name="New Adventures",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Cataloger Daela is here to investigate places of wonder and mystery. Skyfox Den and Caldera of the Menders look especially promising. Completing her quests will unlock her Envoy Tasks today. You will be able to unlock other factions' Envoy Tasks tomorrow.",ends={{npcID=200566,x=0.342,y=0.598,mapID=2151}},questType="standard"},
[74909] = {id=74909,name="New Catches",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Turik is here to investigate the riches of the sea across the Forbidden Reach on behalf of the Iskaara Tuskarr. Completing this quest will unlock his Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.",ends={{npcID=200562,x=0.342,y=0.6,mapID=2151}},questType="standard"},
[74910] = {id=74910,name="New Foes",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Storykeeper Ashekh is here to scout for enemies of the Maruuk. Completing this quest will unlock her Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.",ends={{npcID=200564,x=0.34,y=0.598,mapID=2151}},questType="standard"},
[74911] = {id=74911,name="New Horizons",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Kraxxus represents the strength of Valdrakken Accord here on Forbidden Reach. Completing this quest will unlock her Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.",ends={{npcID=200563,x=0.34,y=0.598,mapID=2151}},questType="standard"},
[74912] = {id=74912,name="Neltharion's Legacy",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="! This is Nozdormu . The time to redeem the legacy of your creator, Neltharion, is at hand. You hold a vital piece to the artifact Neltharion once used to control you and all of the dracthyr. Meet me in Valdrakken. There is much to discuss.",ends={{npcID=187669,x=0.608,y=0.392,zoneID=13862}},questType="standard"},
[74913] = {id=74913,name="Memories of an Artifact",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="Emberthal aided me in discovering the Oathbinder. This was the artifact Neltharion used to control you all. I have been scouring the timeline to discover how it was made to forge a counterpart to it to protect your kind. This gem you've recovered is just the key I need to move my studies forward. You and I shall next meet within Zaralek Cavern, where you once fought over the broken Oathbinder. It is there we will find the secrets to forge your own weapon to fight against tyranny.",starts={{npcID=187669,x=0.608,y=0.392,zoneID=13862}},ends={{npcID=187669,x=0.608,y=0.392,zoneID=13862}},coords={x=0.608,y=0.392,source="quest_giver",zoneID=13862},questType="standard"},
[74923] = {id=74923,name="It Takes a Village to Make an Artifact",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="You must go now and seek aid to create the key components to forge a new glove. Essence of Order is normally difficult to find, but the memories you have acquired will allow you to recover them at many locations. This new glove will be one to empower your allies and your community... which means you will have to rely on others to aid you in this. Take the memories you've recovered and use them to teach others how to craft these parts.",starts={{npcID=187669,x=0.608,y=0.392,zoneID=13862}},ends={{npcID=187669,x=0.608,y=0.392,zoneID=13862}},coords={x=0.608,y=0.392,source="quest_giver",zoneID=13862},questType="standard"},
[74924] = {id=74924,name="Nasz'uro, the Unbound Legacy",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,description="Through my research, I've uncovered the last piece to make this artifact truly a counter to the Oathbinder. The essence of Neltharion. It is here that I can finally aid the dracthyr. We shall travel to the Maelstrom to see his final moments. With his essence, we shall finish crafting your artifact, Nasz'uro, the Unbound Legacy. Speak to me when you are ready.",starts={{npcID=187669,x=0.608,y=0.392,zoneID=13862}},ends={{npcID=187669,x=0.608,y=0.392,zoneID=13862}},coords={x=0.608,y=0.392,source="quest_giver",zoneID=13862},questType="standard"},
[74942] = {id=74942,name="Grime Lies Where You're Killing Slimes",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13647,description="Did you see that? Some of the slimes are leaving little piles of grime behind. Hmm... Melly makes stuff out of all kinds of things. You think she could use the grime to help out Tempo? I bet she could.",starts={{npcID=204987,x=0.538,y=0.878,zoneID=13647}},ends={{npcID=204987,x=0.538,y=0.878,zoneID=13647}},coords={x=0.538,y=0.878,source="quest_giver",zoneID=13647},questType="standard"},
[74946] = {id=74946,name="A Place of Refuge",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them. This Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. While her reasoning is sound, this is also the perfect location for a trap. , I know you vouch for her, so I will give her the benefit of the doubt. Let us hope your trust in her is not misplaced.",starts={{npcID=202707,x=0.694,y=0.476,mapID=2023}},ends={{npcID=200492,x=0.732,y=0.55,mapID=2023}},coords={x=0.694,y=0.476,source="quest_giver",mapID=2023},questType="standard"},
[74948] = {id=74948,name="Snailspiration: Amethyst Softshell",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="I smell a snail on you, but it's strange. You holding out on me? Not many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
[74949] = {id=74949,name="Snailspiration: Archetype of Vigilance",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="I smell a snail on you, but it's strange. You holding out on me? Not many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
[74950] = {id=74950,name="Snailspiration: Blackchasm Crawler",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="I smell a snail on you, but it's strange. You holding out on me? Not many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
