[74953] = {id=74953,name="The Heavy Crown",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="I was really down when Effervesta didn't come like she said she would. But I understand that she's so busy, what with being kidnapped and all of her duties. I don't blame her. I want to tell her how much that time meant to me when we were pups, though. That I'll be here for her if she ever needs me. Then at least she knows I'm still here. Can you help me get her attention long enough to say what I need to?",starts={{npcID=201426,x=0.556,y=0.574,zoneID=14022}},ends={{npcID=202766,x=0.522,y=0.628,zoneID=14022}},coords={x=0.556,y=0.574,source="quest_giver",zoneID=14022},questType="standard"},
[74959] = {id=74959,name="Snailspiration: Mudshell Conch",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,description="I smell a snail on you, but it's strange. You holding out on me? Not many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.",starts={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},ends={{npcID=201752,x=0.442,y=0.8,zoneID=14022}},coords={x=0.442,y=0.8,source="quest_giver",zoneID=14022},questType="standard"},
